window.COLLECTION = [{"number": "0001", "file": "0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The bedroom is arranged for the river, with a king bed dressed in plain white Egyptian cotton and a low upholstered daybed set along the glazing at its foot, so the view is taken lying down as much as sitting up. Walls and joinery are blonde timber with a fabric shaded wall sconce beside the bedhead, and oatmeal linen Roman blinds soften the black framed floor to ceiling windows and balcony sliders. A black arc floor lamp marks the window corner. To recreate it, keep the palette to warm white, sand and pale oak, furniture low and horizontal, and textiles unpatterned.", "src": "images/Capella Bangkok/0001 - Capella Bangkok - River Suite Premier - bedroom with king bed and river window daybed.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 159483}, {"number": "0002", "file": "0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The separate living room wraps two walls of glass around a corner sofa in oatmeal weave with cushions in sage green and taupe. Two barrel back armchairs in pale leather on dark timber legs face the river, paired with a dark round side table carrying an oversized drum shaded lamp in cream silk on a faceted bronze base. A dark stained desk or console repeats the lamp at smaller scale. Pale carpet, linen Roman blinds and blonde panelling keep the room light. Recreation notes: overscale one lamp, keep upholstery plain, and let green cushions be the only colour accent.", "src": "images/Capella Bangkok/0002 - Capella Bangkok - River Suite Premier - corner living room with sofa and barrel chairs.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 214806}, {"number": "0003", "file": "0003 - Capella Bangkok - River Suite Premier - marble bathroom with oval tub and louvred screens.jpg", "resort": "Capella Bangkok", "space": "River Suite Premier", "description": "The bathroom centres on a sculptural egg shaped freestanding tub in matte white, set against walls and floor in heavily striated warm taupe stone that reads like timber grain. Timber louvred sliding screens flank a glazed opening to the balcony, filtering light and giving privacy without blocking the view, and a timber bath caddy holds a brass lidded jar and folded cloths. Beyond the glass are two balcony chairs and a round pedestal table. For the look, use one stone everywhere, real timber louvres rather than blinds, and a single freestanding form with no visible tap clutter.", "src": "images/Capella Bangkok/0003 - Capella Bangkok - River Suite Premier - marble bathroom with oval tub and louvred screens.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/river-premier-suite", "dimensions": "1296x723", "size": 226271}, {"number": "0004", "file": "0004 - Capella Bangkok - Private Villa - plunge pool and folding doors at dusk.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "Shot at dusk from the garden, this view shows the villa rectangular jacuzzi plunge pool in a pale stone surround edged with black river pebbles, directly in front of full width folding glass doors. Inside, a cream sofa and low round coffee table sit on carpet before the bedroom, with sheer curtains drawn to one side and warm lamplight glowing against the panelling. Bronze framed glazing, stone clad piers and a large stone planter with broad leaf planting complete the threshold. Recreation notes: align pool, doors and sofa on one axis, and light the interior warmer than the garden.", "src": "images/Capella Bangkok/0004 - Capella Bangkok - Private Villa - plunge pool and folding doors at dusk.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/villa", "dimensions": "1296x723", "size": 249312}, {"number": "0005", "file": "0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "From the living area, sliding pocket doors open to the bedroom in one enfilade. Foreground pieces include a dark timber display cabinet with blue and white porcelain jars, art books and a sculptural knot object, a tall floor lamp with a cream drum shade, and a marble topped round table. The bedroom has a king bed in white linen, a striped upholstered bench at its foot, and a geometric gridded fabric panel behind the bedhead flanked by mirrored niches and pendant shades. A dressing area with robes and a stool is visible at right. Keep joinery dark against pale walls and repeat grid patterns quietly.", "src": "images/Capella Bangkok/0005 - Capella Bangkok - Private Villa - living room looking through to bedroom.jpg", "source": "https://capellahotels.com/en/capella-bangkok/accommodation/villa", "dimensions": "1296x723", "size": 289259}, {"number": "0006", "file": "0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The combined living and dining room is anchored by an oval marble dining table with cream leather barrel chairs on dark timber frames, lit by a pair of sculptural hammered metal shell pendants. Behind the sofa, a long dark timber console carries a bonsai and an art book, facing a media wall with open shelving and ceramics. Whitewashed boarded ceilings, a ceiling fan, pale oak floors and full height linen curtains frame folding doors to the garden and plunge pool. Recreation notes: one statement pendant group, low horizontal consoles, and indoor planting at architectural scale, including the large potted palm by the doors.", "src": "images/Capella Bangkok/0006 - Capella Bangkok - Private Villa - dining room with marble table and shell pendant.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1920x1282", "size": 309966}, {"number": "0007", "file": "0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The villa bedroom keeps furniture low and textile led, with two striped chaise longues in beige and brown weave angled towards the garden, small round black side tables between them, and the king bed in plain white in the foreground. Full width sliding doors open to the plunge pool, sun loungers and lawn, while the inner wall is lined with woven grasscloth panels in a pale sand tone that catch raking sunlight. A white ceiling fan, taupe curtains and a muted flatweave rug finish the room. Recreate with natural fibre wallcovering, striped upholstery as the only pattern, and nothing above waist height.", "src": "images/Capella Bangkok/0007 - Capella Bangkok - Private Villa - bedroom with striped chaises and pool doors.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1280x853", "size": 107422}, {"number": "0008", "file": "0008 - Capella Bangkok - Private Villa - window chairs facing the plunge pool.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "From inside the villa, two blackened steel frame chairs with cream upholstered seats and a small round drum side table are silhouetted against open folding doors, looking across the plunge pool to a lawn with two timber garden armchairs and the river beyond. Strong sunlight throws long shadows across a woven sisal look rug and pale curtains. Two bathers in the pool give scale, but the design story is the indoor outdoor chair pairing. To copy it, use identical simple frames inside and out, a tight cream and black palette, and leave the doorway completely uncluttered.", "src": "images/Capella Bangkok/0008 - Capella Bangkok - Private Villa - window chairs facing the plunge pool.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1440x1920", "size": 504867}, {"number": "0009", "file": "0009 - Capella Bangkok - Private Villa - timber garden sala by the river.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "The riverfront garden sala is a freestanding pavilion of vertical timber slats in a warm teak tone, open on all sides and set in dense tropical planting with clipped hedges. Inside are a small dining table and chairs for private outdoor meals, shaded by a mature tree and oriented to sunset over the Chao Phraya. The slatted screen gives privacy while keeping airflow and dappled light, a traditional Thai sala reinterpreted as a crisp modern box. Recreation notes: build the screen from evenly spaced battens, keep planting layered and green only, and furnish simply in dark timber.", "src": "images/Capella Bangkok/0009 - Capella Bangkok - Private Villa - timber garden sala by the river.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "1920x1281", "size": 486266}, {"number": "0010", "file": "0010 - Capella Bangkok - Private Villa - fretwork screen detail with palm shadow.jpg", "resort": "Capella Bangkok", "space": "Private Villa", "description": "A close detail of the carved fretwork screens used through the villas and suites, showing a dark stained timber lattice of interlocking diamonds and crosses set beside a plain panel of natural woven silk in a warm parchment tone. A palm frond shadow falls across the plain panel, demonstrating how the screens are meant to work with daylight to pattern the room. The design team took the motif from traditional Thai and Chinese fretwork and scaled it up to full height joinery. For recreation, pair one ornate dark lattice with a large expanse of plain natural textile so neither overwhelms the other. [below 1200px - best available]", "src": "images/Capella Bangkok/0010 - Capella Bangkok - Private Villa - fretwork screen detail with palm shadow.jpg", "source": "https://capellahotels.com/en/capella-bangkok/private-villa", "dimensions": "960x1280", "size": 146855}, {"number": "0011", "file": "0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "The signature Tea Lounge view pairs two woven rattan armchairs with rolled spiral arms and sage cushions against low dark timber tables and upholstered stools, arranged symmetrically on a patterned carpet over polished stone. Behind them, full height windows look onto the lily pond, divided by dark timber lattice screens in a Thai diamond fretwork, with oversized black ceramic planters holding tall palms at each bay. Arched floor lamps with pink silk shades and a coffered ceiling clad in silk complete the room. This is the clearest statement of the hotel lobby look. [below 1200px - best available]", "src": "images/Capella Bangkok/0011 - Capella Bangkok - Tea Lounge - rattan armchairs and lattice screens by the lily pond.jpg", "source": "https://capellahotels.com/en/capella-bangkok/dining", "dimensions": "968x646", "size": 162644}, {"number": "0012", "file": "0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "This angle of the lobby Tea Lounge shows the deeper seating groups: cream sofas and striped upholstered armchairs around a dark timber coffee table, plus Chinese inspired dark wood armchairs with stone top tables in honey onyx in the foreground. A black lacquer side table with a floral arrangement, drum shaded floor lamps and a display shelf holding a bronze horse sculpture and lacquer boxes add the collected, residential layer. Bronze tinted mirror panels and diamond fretwork screens line the walls, and the lily pond runs outside the glazing. Palette is cream, charcoal, bronze and stone throughout.", "src": "images/Capella Bangkok/0012 - Capella Bangkok - Tea Lounge - lobby lounge sofas and Ming style chairs.jpg", "source": "https://bradajohnson.net/2023/12/16/oltre-review-one-day-in-bangkok-two-worlds-apart/", "dimensions": "2560x1707", "size": 729305}, {"number": "0013", "file": "0013 - Capella Bangkok - Tea Lounge - table for two with white cloth and patterned plates.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "A Tea Lounge table for two is dressed with a crisp white cloth, red patterned porcelain plates, brass cutlery and small glass vases, framed by dark timber spindle back chairs in the Chinese scholar chair tradition. Around it are pale upholstered sofas and a low armchair, with a lattice screen and garden facing windows behind, confirming this is the working afternoon tea setup rather than a styled empty room. Recreation notes: the colour comes entirely from the porcelain and flowers, so keep furniture and linen neutral, chairs dark and linear, and table settings small and precise rather than abundant.", "src": "images/Capella Bangkok/0013 - Capella Bangkok - Tea Lounge - table for two with white cloth and patterned plates.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 537895}, {"number": "0014", "file": "0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "resort": "Capella Bangkok", "space": "Tea Lounge", "description": "Along the Tea Lounge windows, low taupe armchairs with loose cushions are grouped in pairs around small round tables with white cloths, facing the lily pond and the low rise buildings across it. A dark fretwork screen divides the seating from the passage, and a flatweave carpet in mottled grey and cream unifies the groups. Daylight does most of the work, with one shaded lamp for evening. To recreate the feel, set every seat towards water or garden, keep chair backs low so sightlines stay open, and use upholstery in a single warm greige family with cushions a shade darker.", "src": "images/Capella Bangkok/0014 - Capella Bangkok - Tea Lounge - window armchairs overlooking the lily pond.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 731213}, {"number": "0015", "file": "0015 - Capella Bangkok - Phra Nakhon - riverfront terrace with parasols and rattan chairs.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "Phra Nakhon riverfront terrace seats diners at square marble topped tables with woven rattan and black metal chairs under large natural canvas parasols, arranged on a raised deck behind a black river rail. Mature rain trees shade the whole terrace, with clipped hedges and tropical planting softening the edges, and the Chao Phraya and city skyline beyond. The official image carries a small red Michelin 2026 badge in the lower corner. Recreation notes: repeat one chair and one table design across the whole terrace, keep parasols plain canvas on timber poles, and let tree canopy replace a built roof.", "src": "images/Capella Bangkok/0015 - Capella Bangkok - Phra Nakhon - riverfront terrace with parasols and rattan chairs.jpg", "source": "https://capellahotels.com/en/capella-bangkok/dining/phra-nakhon", "dimensions": "1296x723", "size": 187955}, {"number": "0016", "file": "0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "Inside Phra Nakhon, the conservatory dining room runs between glass walls under a coffered ceiling with a central skylight screened by woven cane panels. A long grey upholstered banquette with botanical print cushions faces cane backed chairs with dark timber frames at square marble tables set with green glassware and brass cutlery. Herringbone timber floors, a woven screen divider and a large floral arrangement on a pedestal table structure the depth of the room. Recreation notes: cane, marble and grey upholstery are the three materials, repeated without variation, and planting inside should be oversized and sculptural. Image extracted at native resolution from the official Capella press release PDF.", "src": "images/Capella Bangkok/0016 - Capella Bangkok - Phra Nakhon - conservatory dining room with skylight and banquettes.jpg", "source": "https://capellahotels.com/assets/docs/bangkok/10-2020_Capella_Bangkoks_Phra_Nakhon_Restaurant_ENG.pdf", "dimensions": "1276x852", "size": 188429}, {"number": "0017", "file": "0017 - Capella Bangkok - Phra Nakhon - terrace table for two at the river rail.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "A single terrace table at Phra Nakhon shows the place setting in detail: a white marble top on a black pedestal base, two black woven rattan armchairs with pale seat cushions, amber cut glass tumblers, brass cutlery, white linen napkins and a timber tray of small ceramic condiment pots with a succulent. The black metal river rail and tree canopy frame the Chao Phraya and the opposite skyline. Shot in portrait by the reviewing photographer, it is the best record of the terrace furniture at human scale. Recreate with one amber glass accent per table and nothing else coloured.", "src": "images/Capella Bangkok/0017 - Capella Bangkok - Phra Nakhon - terrace table for two at the river rail.jpg", "source": "https://bradajohnson.net/2023/12/16/oltre-review-one-day-in-bangkok-two-worlds-apart/", "dimensions": "1707x2560", "size": 763043}, {"number": "0018", "file": "0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "This close view of an indoor Phra Nakhon table shows the material palette at full size: a beige marble top with a dark stained timber edge and frame, white paper placemats, black ceramic plates, folded white napkins, green glass tumblers and brass cutlery, lit by a small brass table lamp with a posy of white flowers. The chairs are dark framed with woven backs, glimpsed at the edges. For a home version, the formula is a stone top, black plate, green glass and brass metalwork, with joinery kept dark enough to anchor the pale surfaces around it.", "src": "images/Capella Bangkok/0018 - Capella Bangkok - Phra Nakhon - indoor marble table setting with green glassware.jpg", "source": "https://suiteverdict.com/en/thailand/bangkok/capella-bangkok-verdict", "dimensions": "2560x1707", "size": 623979}, {"number": "0019", "file": "0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "resort": "Capella Bangkok", "space": "Phra Nakhon", "description": "At dusk the Phra Nakhon terrace reads differently, with rows of white marble tables and black rattan chairs lit by small table lamps and the last light on the river, under a heavy tree canopy. The setting is the same furniture as the daytime terrace views but the mood depends on low warm light, dark silhouettes and the reflective water behind the rail. The source review describes vintage style table lamps, gold tinted glasses and brass cutlery in vintage Thai style at these tables. Keep outdoor lighting low, warm and at table height only. [below 1200px - best available]", "src": "images/Capella Bangkok/0019 - Capella Bangkok - Phra Nakhon - terrace at dusk with marble tables.jpg", "source": "https://happyhourasia.com/phra-nakhon-serves-authentic-cuisine-in-capella-bangkoks-relaxing-riverfront-setting/", "dimensions": "1170x780", "size": 490826}, {"number": "0020", "file": "0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A king bed dressed in white linen with a taupe throw sits under a sheer canopy net, facing a wall of dark stained timber panels hand carved with palm frond reliefs. A turquoise glass disc pendant and matching wall disc act as the single colour accent, echoed in the ocean beyond the sliding doors. Note the blush toned flatweave rug with a faded botanical pattern, the woven drum pouf at the bed foot, open shelving with ceramics and books, a television panel painted with a wave motif, wall sconces in aged bronze, and full height sheer curtains softening the vaulted thatch lined ceiling.", "src": "images/Joali Maldives/0020 - Joali Maldives - Luxury Water Villa with Pool - bedroom with canopy net and turquoise pendant.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 309301}, {"number": "0021", "file": "0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "The separate living room pairs two blush pink woven swivel armchairs with a low grey sofa dressed in pink and dove cushions, arranged around a glossy dark wood drum coffee table on a monochrome patterned rug. Behind, a dark timber bar and library unit with brass framing holds glassware, books and small sculptures, flanked by carved palm relief panels and a large turquoise glass disc artwork. Recreating the look needs cane and rattan textures kept tonal, one saturated teal art piece per room, potted palms in woven baskets, and a wall of hat hooks and curated objects by the entry.", "src": "images/Joali Maldives/0021 - Joali Maldives - Luxury Water Villa with Pool - living room with blush woven armchairs and library bar.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 324286}, {"number": "0022", "file": "0022 - Joali Maldives - Luxury Water Villa with Pool - bathroom with freestanding tub and carved wood panels.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A sculptural white freestanding oval tub with a bronze floor mounted filler anchors the bathroom, set on large format stone tiles with dark grout banding. Dark carved timber wardrobe panels with slim brass inlay divide the bath from the bedroom, while a bamboo ladder towel rail holds embroidered white towels beside an oval mirror on a bronze stand. Twin candle style sconces give warm light, and through the opening the turquoise glass disc art and shelving of the living area repeat the villa palette of deep brown, stone grey, white and teal, a useful trick for visual continuity.", "src": "images/Joali Maldives/0022 - Joali Maldives - Luxury Water Villa with Pool - bathroom with freestanding tub and carved wood panels.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 234359}, {"number": "0023", "file": "0023 - Joali Maldives - Luxury Water Villa with Pool - deck with infinity pool and thatched cabana.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "The sundeck runs the full width of the villa in warm timber boards, with a narrow infinity plunge pool tiled in deep teal mosaic reflecting the lagoon. A thatched cabana on chunky turned timber posts shelters a bamboo lattice screen, two low rattan armchairs and a cushioned daybed in rust, ochre and cream stripes. Sliding doors open the interior shelving wall straight onto the deck, blurring inside and out. To copy the scheme, keep outdoor fabrics in faded spice tones, use raw thatch and unfinished wood outdoors, and repeat the lattice screen motif as a privacy device.", "src": "images/Joali Maldives/0023 - Joali Maldives - Luxury Water Villa with Pool - deck with infinity pool and thatched cabana.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 374186}, {"number": "0024", "file": "0024 - Joali Maldives - Luxury Water Villa with Pool - deck daybed with striped cushions.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A close study of the deck daybed: a deep outdoor sofa in weathered timber framing piled with large square cushions in oatmeal linen, one blush pink pillow and one wide striped pillow in grey and taupe ticking. The cushions sit against a simple timber rail with the turquoise lagoon directly behind, and a small round side table with a teal pierced metal base holds coffee and reading material. The lesson for recreation is scale and layering: oversized loose cushions, mixed plain and striped natural fibre fabrics, and a single coloured metal accent table rather than matching outdoor sets.", "src": "images/Joali Maldives/0024 - Joali Maldives - Luxury Water Villa with Pool - deck daybed with striped cushions.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 282899}, {"number": "0025", "file": "0025 - Joali Maldives - Luxury Water Villa with Pool - bamboo sun loungers and overwater net.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "Two sun loungers built from lashed bamboo poles carry thick stone grey mattress cushions, rolled chocolate brown towels and a striped bolster, arranged on the timber deck beside a round wooden tray table and a black framed storm lantern. At the deck edge a white rope net hammock is suspended over the lagoon. The palette is deliberately restful: greys and browns against saturated turquoise water. Recreating it requires natural pole construction rather than aluminium frames, heavy plain weave outdoor fabric, woven fans and dark accessories as styling, and the net hammock as the signature overwater feature.", "src": "images/Joali Maldives/0025 - Joali Maldives - Luxury Water Villa with Pool - bamboo sun loungers and overwater net.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 241887}, {"number": "0026", "file": "0026 - Joali Maldives - Luxury Water Villa with Pool - desk detail with brass lamp and coral sculpture.jpg", "resort": "Joali Maldives", "space": "Luxury Water Villa with Pool", "description": "A styling detail of the villa writing desk, surfaced in dark embossed leather with a crocodile texture. Objects are few and sculptural: a white coral branch on a clear acrylic block, a ribbed amber glass vase with a green stopper, a brass table lamp formed as an inverted U with a sphere detail, printed stationery with botanical borders and a plum coloured resort folder. The arrangement shows the Joali method of decorating with one organic specimen, one coloured glass piece and one metallic lamp per surface, leaving generous negative space so each object reads as art.", "src": "images/Joali Maldives/0026 - Joali Maldives - Luxury Water Villa with Pool - desk detail with brass lamp and coral sculpture.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/luxury-water-villa-with-pool/", "dimensions": "2000x1126", "size": 203993}, {"number": "0027", "file": "0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A ground floor bedroom opens fully to a shaded garden terrace through sliding glass doors with sheer and taupe curtains. The bed carries white linen and a blush throw, matched by a woven blush swivel chair with a slate cushion and two cane terrace armchairs outside around a small table. Two black lattice lantern pendants hang from the thatched terrace roof, and a dark minibar cabinet with brass shelving stands by the wall. The scheme layers cream walls, pale stone floors, woven cane and rattan in honey tones, and soft pink textiles against dense green planting.", "src": "images/Joali Maldives/0027 - Joali Maldives - Four Bedroom Beach Residence with Pool - bedroom opening to garden terrace.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 306820}, {"number": "0028", "file": "0028 - Joali Maldives - Four Bedroom Beach Residence with Pool - pool terrace with cane chairs.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "On the pool terrace, two sculptural cane armchairs with wraparound woven backs face the water across a small three legged wooden drinks table, their round woven seat shadows patterning the pale stone paving. Beyond the infinity pool edge, timber sun loungers and cream umbrellas line the sand in front of palms and a thatched pavilion. Dark cylindrical timber columns with brass collars frame the view from the covered veranda. For recreation, note the contrast of black stained posts against honey cane, the restrained two chair composition, and planting used as the only backdrop decoration.", "src": "images/Joali Maldives/0028 - Joali Maldives - Four Bedroom Beach Residence with Pool - pool terrace with cane chairs.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 541984}, {"number": "0029", "file": "0029 - Joali Maldives - Four Bedroom Beach Residence with Pool - bathroom with stained glass palm window and freestanding tub.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The signature bathroom centres a white freestanding tub on a raised stone plinth before a full height stained glass window of green palm fronds, which floods the room with filtered botanical light. Sliding doors are faced in swirling green marble effect glass with long brass pulls, and dark carved wooden stools and a small sculpture flank the tub. Polished grey stone floors keep the room cool and plain so the green glass dominates. This single architectural artwork, repeated in the dressing room, is the feature to copy: coloured glass foliage panels instead of tiles or wallpaper in the bathroom.", "src": "images/Joali Maldives/0029 - Joali Maldives - Four Bedroom Beach Residence with Pool - bathroom with stained glass palm window and freestanding tub.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 314217}, {"number": "0030", "file": "0030 - Joali Maldives - Four Bedroom Beach Residence with Pool - twin bedroom with cane lattice headboard screen.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The twin bedroom builds its headboard wall in layers: a tall screen of woven cane lattice panels in natural rattan hangs above a dark carved timber headboard with circular medallion details, with small shaded wall lamps between. Two low white upholstered armchairs with pink cushions face the beds across a geometric bordered stone floor, and a pale timber ceiling fan turns overhead. Beds are dressed in white with taupe runners. Recreating the room depends on that stacked headboard composition, cane, carved dark wood and white upholstery in equal thirds, with pink used only as cushion accents.", "src": "images/Joali Maldives/0030 - Joali Maldives - Four Bedroom Beach Residence with Pool - twin bedroom with cane lattice headboard screen.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 333100}, {"number": "0031", "file": "0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The dressing room combines open wardrobe shelving in pale oak with a dark stained vanity desk and woven stool, lit by a mirror framed with globe bulbs in theatrical style. A stained glass door panel of green palm leaves and a full height panel of swirling green marble effect glass carry the bathroom motif through the suite, and a cylindrical rattan stool holds a woven tote. Brass shelf edging and black accessories keep the pale palette grounded. The design lesson is continuity: one coloured glass language links bath, dressing and bedroom, while storage stays open, shallow and hotel style.", "src": "images/Joali Maldives/0031 - Joali Maldives - Four Bedroom Beach Residence with Pool - dressing room with vanity and green marble panels.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 299706}, {"number": "0032", "file": "0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "A double height living room is organised around a full wall of dark timber shelving divided into square compartments displaying ceramics, books and sculpture, with a wave painted television panel at its centre and carved palm relief panels behind. Seating mixes a long blue grey sofa with exposed dark wood frame, woven swivel chairs and a pair of charcoal dining chairs on a blue patterned rug over banded stone floors. Tall sliding doors open to the pool terrace. To recreate, build the shelving as the artwork, keep upholstery in dusty blue and blush, and let one large plant soften the grid.", "src": "images/Joali Maldives/0032 - Joali Maldives - Four Bedroom Beach Residence with Pool - living room with shelving wall and blue sofa.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 316898}, {"number": "0033", "file": "0033 - Joali Maldives - Four Bedroom Beach Residence with Pool - king bedroom with cane screen and curved minibar.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The principal bedroom repeats the cane lattice screen above a dark carved headboard, this time with a king bed and two pale blush swivel armchairs with blue and pink cushions at its foot. To one side a curved dark wood minibar cabinet with brass rails and open shelving forms a small hospitality station, and the stained glass palm panel appears again at the far door. Floors are pale stone with dark border inlay, walls warm cream. The formula to copy is symmetrical soft seating at the bed foot, layered natural screens overhead, and hospitality furniture treated as cabinetry.", "src": "images/Joali Maldives/0033 - Joali Maldives - Four Bedroom Beach Residence with Pool - king bedroom with cane screen and curved minibar.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 334587}, {"number": "0034", "file": "0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The garden shower court is walled in vertically stacked emerald green glazed ceramic tiles with strong colour variation, set between blush plaster pillars and a slatted bamboo privacy screen. A black rain shower on a dark pole, a carved wooden stump side table holding flowers and folded towels, and dense tropical planting in greens complete the space, over pale gravel and stone paving. This is the boldest colour moment in the residence: one saturated tile wall, everything else natural. Recreating it needs handmade look tiles with tonal movement, not flat green, and timber screens left untreated.", "src": "images/Joali Maldives/0034 - Joali Maldives - Four Bedroom Beach Residence with Pool - outdoor shower with emerald tile wall.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 422974}, {"number": "0035", "file": "0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "resort": "Joali Maldives", "space": "Four Bedroom Beach Residence with Pool", "description": "The residence library lines one wall with open dark timber and brass shelving filled with books, coral, ceramics and framed pieces, above a long dark wood desk with bamboo style legs and a brass lamp. Two woven armchairs in blush and cream with pink cushions are grouped with a turned dark wood side table, and carved timber panels and a patterned stair rail close the view. Lighting is warm and low from sconces and desk lamps. For recreation, treat the library as a lived in cabinet of curiosities: mixed natural specimens and books, no matching sets, upholstery kept pale.", "src": "images/Joali Maldives/0035 - Joali Maldives - Four Bedroom Beach Residence with Pool - library with open shelving and woven chairs.jpg", "source": "https://www.joali.com/joali-maldives/villas-and-residences/four-bedroom-beach-residence-with-pool/", "dimensions": "2000x1126", "size": 323834}, {"number": "0036", "file": "0036 - Joali Maldives - Wellness Center - retail reception with timber shelving and Cure signage.jpg", "resort": "Joali Maldives", "space": "Wellness Center", "description": "The Wellness Centre reception and retail wall is built in warm honey timber: vertical slat panelling above open shelves displaying rows of white treatment products, small ceramics and a floral arrangement, with the Cure name in raised letters. In front, a circular sage green pleated fabric planter holds a palm, surrounded by a curved banquette with branded cream cushions. The palette of honey wood, sage and cream with soft cove lighting creates the calm arrival sequence. To recreate, use slatted timber, handleless open shelving, one large planted centrepiece and upholstery in muted green linen. [below 1200px - best available]", "src": "images/Joali Maldives/0036 - Joali Maldives - Wellness Center - retail reception with timber shelving and Cure signage.jpg", "source": "https://www.joali.com/joali-maldives/spa-and-wellness/", "dimensions": "1092x912", "size": 161763}, {"number": "0037", "file": "0037 - Joali Maldives - Wellness Center - relaxation lounge with curved sage sofa.jpg", "resort": "Joali Maldives", "space": "Wellness Center", "description": "In the relaxation lounge, two guests in waffle weave robes sit on a long curved sofa upholstered in pale sage, with a single rust cushion as accent, a black ceramic bowl and folded towels beside them. Through the timber framed opening behind, a treatment room with dressed massage beds is visible, and a dark wood cabinet holds treatment vessels. Warm wood panelling, low lighting and soft grey green textiles define the waiting spaces between treatments. The recreation lesson is the curved sofa plan, robe toned fabrics, and sightlines from lounge to treatment rooms kept open and quiet. [below 1200px - best available]", "src": "images/Joali Maldives/0037 - Joali Maldives - Wellness Center - relaxation lounge with curved sage sofa.jpg", "source": "https://www.joali.com/joali-maldives/spa-and-wellness/", "dimensions": "1092x912", "size": 135900}, {"number": "0038", "file": "0038 - Joali Maldives - Wellness Center - hammam with geometric stone walls.jpg", "resort": "Joali Maldives", "space": "Wellness Center", "description": "The hammam is viewed through a dark timber doorway inlaid with small square bone coloured motifs, past two low armchairs in shadow. Inside, a raised white marble treatment slab centres a chamber whose walls are carved with interlocking geometric fret patterns in pale stone, lit by a glowing circular cove ceiling. The contrast between the near black wood surround and the luminous stone interior is the design device. Recreating a hammam look requires carved or routed geometric stone panels, a single central slab, concealed warm lighting, and dark wood framing to stage the brightness within.", "src": "images/Joali Maldives/0038 - Joali Maldives - Wellness Center - hammam with geometric stone walls.jpg", "source": "https://www.joali.com/joali-maldives/spa-and-wellness/", "dimensions": "2000x1333", "size": 172080}, {"number": "0039", "file": "0039 - Joali Maldives - Wellness Center - ocean treatment suite massage with carved wood screen.jpg", "resort": "Joali Maldives", "space": "Wellness Center", "description": "A massage in progress in the ocean facing treatment suite shows the room dressing that matters for recreation: a treatment bed layered in white towelling and linen, a dark wall of intricately carved timber blocks behind, and soft directional light falling across the bed from the window side. Timber tones are deep walnut brown, textiles are plain white and cream, and decoration is limited to the carved screen itself. The suite demonstrates the Joali spa formula of one richly textured dark wall, plain natural bed linen, and no clutter, letting light and carving carry the atmosphere.", "src": "images/Joali Maldives/0039 - Joali Maldives - Wellness Center - ocean treatment suite massage with carved wood screen.jpg", "source": "https://www.joali.com/joali-maldives/spa-and-wellness/", "dimensions": "2000x1333", "size": 158362}, {"number": "0040", "file": "0040 - Joali Maldives - Wellness Center - overwater yoga pavilion at dusk.jpg", "resort": "Joali Maldives", "space": "Wellness Center", "description": "The overwater yoga pavilion stands at the end of a long timber jetty, its steep thatched roof on dark posts open on all sides to the lagoon. The boardwalk approach is lined with woven lanterns glowing at dusk, white cylindrical planters with flowering shrubs, and low timber rails, while a single practitioner holds a warrior pose on the deck. Materials are entirely natural: thatch, weathered deck boards and dark stained posts. For recreation, the essentials are the symmetrical lantern lit approach, open sided pavilion form, and a completely uncluttered practice deck facing open water.", "src": "images/Joali Maldives/0040 - Joali Maldives - Wellness Center - overwater yoga pavilion at dusk.jpg", "source": "https://www.joali.com/joali-maldives/spa-and-wellness/", "dimensions": "2560x1766", "size": 752984}, {"number": "0041", "file": "0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "The reception pavilion is a vast open sided hall under a steeply pitched thatched roof with exposed dark timber trusses. Massive carved wooden columns stand on black polished terrazzo floors inlaid with teak strips. Low lounge sofas in white canvas with crimson red cushions line both sides, paired with woven rattan tub chairs and low wooden coffee tables on pale rugs. Oversized black wire cage drum pendants with cream shades hang at intervals. Geometric timber lattice screens filter daylight and garden views. A single timber reception desk sits on axis beneath a carved gable panel and patterned feature wall. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0041 - One&Only Reethi Rah - Lobby - wide view of reception pavilion.jpg", "source": "https://theluxurytravelexpert.com/review-one-only-reethi-rah-maldives/", "dimensions": "1000x750", "size": 361590}, {"number": "0042", "file": "0042 - One&Only Reethi Rah - Lobby - corner seating with cage pendant.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "A corner seating bay in the reception pavilion pairs a white upholstered L shaped sofa with bright lime green and natural linen cushions, woven rattan armchairs with timber frames, and a simple rectangular teak coffee table holding a coral sculpture, a book and a vase of orchids. The dominant feature is an oversized cylindrical pendant in black wire mesh over a white diffuser. Behind, geometric dark timber lattice screens open to tropical planting, while a deeply carved column frames the right side. Black polished terrazzo flooring and a woven natural fibre rug ground the palette of dark wood, white and green.", "src": "images/One&Only Reethi Rah/0042 - One&Only Reethi Rah - Lobby - corner seating with cage pendant.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1829x2560", "size": 842211}, {"number": "0043", "file": "0043 - One&Only Reethi Rah - Lobby - carved pillar detail.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "Close detail of one of the reception pavilion columns, hand carved in dark stained hardwood with dense Balinese style relief work. Diamond lozenges frame oval medallions with cross hatched centres, surrounded by scrolling foliage, palmettes and beaded roundels above a band of plain oval panels. The carving is deep cut so light and shadow model the pattern, and the timber shows a warm mid brown patina with lighter rubbed highlights on raised areas. A second carved column blurs behind. To recreate, commission solid timber columns with all over relief carving rather than applied ornament, finished with wax rather than gloss.", "src": "images/One&Only Reethi Rah/0043 - One&Only Reethi Rah - Lobby - carved pillar detail.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1829x2560", "size": 827654}, {"number": "0044", "file": "0044 - One&Only Reethi Rah - Lobby - carved wood panel detail.jpg", "resort": "One&Only Reethi Rah", "space": "Lobby", "description": "Detail of a carved timber screen panel in the reception pavilion, organised as a strict grid of square coffers alternating two motifs: a four petal floral rosette and an oval ring with a central boss. Beside the grid runs a bolder diagonal zigzag fret carved in deeper relief. The wood is dark walnut brown with burnished highlights on the raised carving and shadowed recesses that emphasise the repeat. Smooth stone finished columns in muted grey brown flank the panel. This is the resort pattern language: small scale geometric carving used at architectural scale for screens, doors and dividing panels.", "src": "images/One&Only Reethi Rah/0044 - One&Only Reethi Rah - Lobby - carved wood panel detail.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1829x2560", "size": 458515}, {"number": "0045", "file": "0045 - One&Only Reethi Rah - Botanica restaurant - garden dining terrace.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "Botanica dining terrace spreads across pale sand coloured paving inside the chef garden. Chunky armchairs built from rounded natural teak poles have slatted backs and loose cushions in vivid tangerine orange, grouped around rustic square timber tables set with woven placemats, white napkins with leather rings, green glass tumblers and small black lanterns. A massive shallow stone bowl planter on a pedestal, filled with herbs, anchors the centre on a bed of black pebbles. Behind stands a conical thatched gazebo. Recreate with unfinished teak, one saturated cushion colour, herb planting in oversized stone vessels and dense tropical greenery as walls.", "src": "images/One&Only Reethi Rah/0045 - One&Only Reethi Rah - Botanica restaurant - garden dining terrace.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1314", "size": 750916}, {"number": "0046", "file": "0046 - One&Only Reethi Rah - Botanica restaurant - sacred tree bar and lounge.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "The bar at Botanica sits under a large conical thatched pavilion beside the sacred banyan tree, its counter lined with tall orange timber bar stools. In front, on white sand, heavy lounge furniture is hewn from solid dark timber slabs: low benches and armchairs with tangerine cushions and dark green scatter pillows around plank coffee tables holding candles in glass hurricanes. Small timber lanterns and a woven globe pendant hang from the banyan branches, and orchids grow on its trunk. The palette is dark wood, saturated orange and deep green, with warm low level lantern light planned for evening use.", "src": "images/One&Only Reethi Rah/0046 - One&Only Reethi Rah - Botanica restaurant - sacred tree bar and lounge.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1211", "size": 735079}, {"number": "0047", "file": "0047 - One&Only Reethi Rah - Botanica restaurant - aerial view of garden layout.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "From directly above, Botanica reads as a garden plan: a pale paved dining court dotted with square tables and orange chairs among palm crowns, thatched pavilions at its edges, and a formal kitchen garden laid out as rectangular herb and vegetable beds separated by narrow paths. The orange upholstery is the only strong colour against greens and pale sand paving, showing how the restaurant uses one accent hue to organise a large outdoor room. For recreation, note the geometry: dining on open paving near the pavilions, produce beds in a strict grid behind, and planting density increasing toward the boundaries for privacy.", "src": "images/One&Only Reethi Rah/0047 - One&Only Reethi Rah - Botanica restaurant - aerial view of garden layout.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1226", "size": 756800}, {"number": "0048", "file": "0048 - One&Only Reethi Rah - Botanica restaurant - chefs table pavilion interior.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "Inside the Chefs Table pavilion, a single long dining table seats fourteen on a thick polished live edge timber slab carried by a solid tree trunk pedestal. Rustic armchairs built from natural branches and poles carry rust orange seat cushions. The conical roof reveals its construction: bamboo lattice over thatch, carried on massive dark timber posts whose bases are wrapped in coir rope. The floor is irregular grey stone flags. Black metal candle lanterns line the edges, glassware and white napkins dress the table, and the garden shows on every side. Recreate with raw structural materials left visible and one warm accent colour.", "src": "images/One&Only Reethi Rah/0048 - One&Only Reethi Rah - Botanica restaurant - chefs table pavilion interior.jpg", "source": "https://www.carrier.co.uk/design/hotels/oneonly-reethi-rah/", "dimensions": "1631x1224", "size": 604375}, {"number": "0049", "file": "0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "resort": "One&Only Reethi Rah", "space": "Botanica restaurant", "description": "Dinner inside the Botanica orchid house is served under a high pitched glasshouse roof of black steel trusses and translucent shade panels, with ceiling fans and small star like downlights. Dark stained timber dining tables are paired with formal carved chairs whose shaped splat backs and tan seats recall colonial plantation furniture. Both long walls are tiered planting benches dense with flowering orchids, each tier edged with tiny fairy lights, so guests dine between two banks of blooms. The floor is raked pale sand. Palette: black framework, dark wood, white and magenta orchid flowers, warm pinpoint lighting. [below 1200px - best available]", "src": "images/One&Only Reethi Rah/0049 - One&Only Reethi Rah - Botanica restaurant - orchid house dining room.jpg", "source": "https://www.purelymaldives.co.uk/resorts/view/one-only-reethi-rah", "dimensions": "850x638", "size": 335958}, {"number": "0050", "file": "0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa living room runs under a soaring pitched ceiling of dark timber boards crossed by lashed bamboo poles in a diamond lattice. Freestanding screen walls alternate cream panels with dark woven coconut shell mosaic, separating living, sleeping and bathing zones without doors. A long oatmeal linen sofa and chaise carry cushions in cream, sage and a red medallion print, arranged around a round white coffee table and timber armchairs with woven backs. Polished terrazzo floors with dark inlay bands, a patterned rust toned rug, and full height sliding doors open to a canopied daybed, plunge pool and beach beyond.", "src": "images/One&Only Reethi Rah/0050 - One&Only Reethi Rah - Beach Villas - living room with lattice ceiling.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1324", "size": 583154}, {"number": "0051", "file": "0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The master bedroom is arranged symmetrically on the ocean view, the king bed centred on a wide timber framed window with white linen, taupe cushions and a mustard yellow bolster. At its foot, two pale upholstered timber armchairs with red medallion print cushions flank a round drum pedestal table in warm wood with a dark woven top. Round timber bedside cabinets carry square white pendant lamps. To one side, a black framed minibar cabinet combines mirror, glass shelves and drawers faced in coconut shell and woven fibre; opposite stands a matching luggage cabinet on X frame legs. Woven mosaic wall panels and lashed bamboo ceiling beams complete the scheme.", "src": "images/One&Only Reethi Rah/0051 - One&Only Reethi Rah - Beach Villas - master bedroom with ocean view.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1150", "size": 758992}, {"number": "0052", "file": "0052 - One&Only Reethi Rah - Beach Villas - bedroom seating with pool view.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "Shot from the bedroom toward the living area and pool, this view shows the villa open plan sequence divided by freestanding woven mosaic screen panels. Two woven back armchairs and an oval drum table sit on a mottled mauve rug at the foot of the bed. Beyond the screens, the oatmeal sofa of the living zone is visible on axis. Full width sliding doors open to the plunge pool, where a white curtained canopy daybed stands on a raised platform under a thatched veranda. Framed black and white photographs, a black metal console with a ring sculpture, and the lashed bamboo cathedral ceiling tie the zones together.", "src": "images/One&Only Reethi Rah/0052 - One&Only Reethi Rah - Beach Villas - bedroom seating with pool view.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1380", "size": 789122}, {"number": "0053", "file": "0053 - One&Only Reethi Rah - Beach Villas - bedroom with window seat and bolster.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "Looking along the length of the villa, the bed sits centre frame with crisp white linen, grey cushions piped in red and a long mustard bolster, flanked by a cylindrical timber nightstand with a stone top and a cube lamp in natural linen on a black frame. Behind the bed, a built in window seat with beige cushions faces garden windows fitted with timber blinds. Woven coconut shell screen panels mark the passage to the bathroom vanity visible in the distance. Lashed bamboo trusses form a continuous diamond lattice in the vaulted ceiling, and polished terrazzo with dark wood inlay strips runs the full length.", "src": "images/One&Only Reethi Rah/0053 - One&Only Reethi Rah - Beach Villas - bedroom with window seat and bolster.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1526", "size": 519378}, {"number": "0054", "file": "0054 - One&Only Reethi Rah - Beach Villas - bedroom view to beach with twin desks.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "From behind the bed, the room opens through full height sliding doors to a thatched veranda, white sand, a fringed hammock strung between palms and the turquoise lagoon. Inside, two dark timber writing desks with single drawers line the side walls, topped with books, coral and flowers, and hung above with pairs of framed black and white Maldivian photographs in white mounts. Two pale armchairs with red medallion cushions face the view across a round drum table. The ceiling is dark timber boarding with paired golden bamboo poles tied with rope lashings at each truss, a signature detail worth copying exactly.", "src": "images/One&Only Reethi Rah/0054 - One&Only Reethi Rah - Beach Villas - bedroom view to beach with twin desks.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1489", "size": 619366}, {"number": "0055", "file": "0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The covered veranda lounge is furnished as an outdoor living room: a very long low bench daybed in dark timber with a taupe mattress and a continuous teal bolster back, dressed with teal cushions and leaf patterned pillows in aqua and white. Two barrel back chairs woven in grey cord sit at a round white dining table with a wooden bowl of fruit. Above, the open gable shows thatch laid over bamboo laths and lashed bamboo trusses, framing a wall of tropical planting that acts as the room backdrop. Terrazzo flooring with dark inlay continues outside, blurring the indoor outdoor boundary.", "src": "images/One&Only Reethi Rah/0055 - One&Only Reethi Rah - Beach Villas - veranda lounge with teal daybed.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1551", "size": 706415}, {"number": "0056", "file": "0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The villa dining area centres on a rectangular table whose top is a mosaic of coconut shell pieces in variegated browns, carried on splayed timber legs. Six sculpted dining chairs in warm mid tone wood have curved crest rails, padded grey seats and slender tapered legs. Behind, a pale grey sofa faces the beach through wide sliding doors beneath a thatched veranda. Black metal framed consoles with timber tops hold books, a star sculpture and flowers, and two framed black and white photographs hang above. Polished terrazzo with dark border inlay, woven screen panels and bamboo lashed ceiling beams maintain the villa material palette.", "src": "images/One&Only Reethi Rah/0056 - One&Only Reethi Rah - Beach Villas - dining room with coconut shell table.jpg", "source": "https://www.travoh.com/stays/oneonly-reethi-rah-resort-north-male-atoll-maldives/", "dimensions": "1840x1510", "size": 659432}, {"number": "0057", "file": "0057 - One&Only Reethi Rah - Beach Villas - grand villa secondary bedroom.jpg", "resort": "One&Only Reethi Rah", "space": "Beach Villas", "description": "The Grand Beach Villa secondary bedroom holds two beds dressed in white with mustard yellow bolsters and taupe cushions, lit by square fabric pendant lamps hung either side. A curved chaise longue in oatmeal upholstery with red medallion and grey cushions sits on the mottled mauve rug, with a small round timber side table holding a silver crab sculpture. Louvred mahogany doors flank the opening to the dining room beyond, and folding timber screens open to a terrace with a wicker chair. Dark timber boarded ceilings with lashed bamboo trusses, terrazzo floors and cream walls repeat the main villa palette at a smaller scale.", "src": "images/One&Only Reethi Rah/0057 - One&Only Reethi Rah - Beach Villas - grand villa secondary bedroom.jpg", "source": "https://www.carrier.co.uk/design/hotels/oneonly-reethi-rah/", "dimensions": "1663x1257", "size": 458259}, {"number": "0058", "file": "0058 - The Nautilus Maldives - Beach Residence with Private Pool - two storey residence and oval pool deck.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Elevated view across the private oval pool to the two storey residence, its conical kajan thatch roofs and curved white walls quoting the nautilus shell. A thatched cabana on the pale timber deck holds a suspended swing daybed with cream cushions and a round woven side table, while two white loungers with orange cushions, a small outdoor dining set and black lanterns furnish the pool terrace. Upstairs, a glass balustraded balcony carries a curved daybed piled with orange and patterned cushions. Slatted timber screens, palms and dense planting keep the deck private.", "src": "images/The Nautilus Maldives/0058 - The Nautilus Maldives - Beach Residence with Private Pool - two storey residence and oval pool deck.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 197021}, {"number": "0059", "file": "0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Ground floor living room planned on a curve, with a long low sofa in natural linen following the wall, piled with solid orange cushions and orange and gold ikat cushions. Two round coral orange coffee tables with dark turned legs and patterned tops sit on an orange and ochre abstract rug over pale parquet. Beyond are a slatted timber television console, a table lamp with a stacked openwork rattan base, a woven chandelier over the dining table, and sage woven dining chairs. A cream macrame hanging against a round orange wall disc anchors the bohemian layering, and full height glazing opens to the deck, pool and ocean.", "src": "images/The Nautilus Maldives/0059 - The Nautilus Maldives - Beach Residence with Private Pool - curved living room with orange ikat cushions.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 183062}, {"number": "0060", "file": "0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Close view of the ground floor wet bar and dining corner. Two high stools pair sage green woven wrap around backs with pale timber legs and foot rails, set at a counter fronted in fine vertical strips with a floating shelf holding dark glass vessels above. Matching woven dining chairs with grey seat pads surround a round pale wood table set with turquoise glassware. Oversized ribbed rattan urns, a chevron grooved timber door and a table lamp with three stacked rattan spheres on a round side table complete the scheme, over basketweave parquet in warm oak tones.", "src": "images/The Nautilus Maldives/0060 - The Nautilus Maldives - Beach Residence with Private Pool - wet bar and dining detail with woven stools.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 179464}, {"number": "0061", "file": "0061 - The Nautilus Maldives - Beach Residence with Private Pool - living room in yellow scheme with spiral staircase.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "A second colourway of the ground floor living room, in lemon yellow and cream rather than orange. A curved cream sofa and a grey three seat sofa carry yellow solid and ikat cushions around two round yellow coffee tables with patterned glass tops, on a large yellow and grey abstract rug. A white circular woven wall sculpture hangs above the back sofa, and a tall cream shaded lamp stands beside it. At right, a white spiral staircase climbs to the bedroom floor past a high backed woven chair and a live edge timber console with books. Through the open doors, a macrame swing hangs in the thatched cabana.", "src": "images/The Nautilus Maldives/0061 - The Nautilus Maldives - Beach Residence with Private Pool - living room in yellow scheme with spiral staircase.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x980", "size": 211339}, {"number": "0062", "file": "0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Upstairs king bedroom in white linen, dressed with a central bolster, patterned cushions piped in orange and a painterly bed runner in orange, ochre and taupe stripes. A buttoned grey bench at the foot holds two white and gold lattice cushions, and a round orange and yellow rug softens pale geometric tiled flooring. Timber framed folding doors open to a balcony with wicker armchairs and a round pedestal table under the thatch, facing the ocean. Through the rear doorway, the bathroom shows a round patterned pouffe, a glass shower enclosure and a white robe, linking the sleep and bath zones.", "src": "images/The Nautilus Maldives/0062 - The Nautilus Maldives - Beach Residence with Private Pool - upstairs king bedroom opening to ocean balcony.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 197986}, {"number": "0063", "file": "0063 - The Nautilus Maldives - Beach Residence with Private Pool - circular bathroom with freestanding tub.jpg", "resort": "The Nautilus Maldives", "space": "Beach Residence with Private Pool", "description": "Circular bathroom under a shallow thatched dome, planned around a central round pouffe upholstered in cream pleats with an orange geometric cushion top. A sculptural white freestanding oval tub sits by full height windows with sheer and linen curtains, flanked by two oval vessel basins on pale counters with tall chrome mixers. Curved glass shower enclosures with frosted panels and fine mosaic tiling line the wall, beside a pale timber dressing table with a round mirror and upholstered stool. Geometric cream and taupe floor tiles, a lidded woven basket and an amber glass vessel add pattern and handcrafted texture.", "src": "images/The Nautilus Maldives/0063 - The Nautilus Maldives - Beach Residence with Private Pool - circular bathroom with freestanding tub.jpg", "source": "https://www.thenautilusmaldives.com/houses/beach-residence", "dimensions": "1920x900", "size": 184295}, {"number": "0064", "file": "0064 - The Nautilus Maldives - Nautilus Retreat with Private Pool - aerial view of whole retreat and kidney shaped pool.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Full aerial of the single overwater retreat, five conical thatch roofs stepping across a broad silvered timber deck on stilts above clear turquoise water. The kidney shaped infinity pool wraps the deck edge, reached by a curved stair with a scroll ended handrail descending toward the lagoon. Deck furniture is kept low and pale: two pairs of white loungers with orange cushions under white umbrellas, and a square dining table with four woven chairs and yellow cushions. A small round thatched cabana shelters a daybed at the far end. Use this view to copy the footprint, roof rhythm and deck zoning.", "src": "images/The Nautilus Maldives/0064 - The Nautilus Maldives - Nautilus Retreat with Private Pool - aerial view of whole retreat and kidney shaped pool.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 440815}, {"number": "0065", "file": "0065 - The Nautilus Maldives - Nautilus Retreat with Private Pool - aerial curved deck with thatched cabana and loungers.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Oblique aerial at dusk over the curved end of the deck, where a round thatched cabana holds a cream daybed on the timber boards above the lagoon. Two white loungers with orange patterned cushions share a small side table under a large white umbrella beside the round stepped end of the infinity pool, its handrail finished with a spiral scroll. Black pierced lanterns mark the deck edge, and warm light spills from the glazed doors of the thatched pavilions behind. Weathered grey decking, natural thatch and white textiles keep the palette calm against the turquoise water.", "src": "images/The Nautilus Maldives/0065 - The Nautilus Maldives - Nautilus Retreat with Private Pool - aerial curved deck with thatched cabana and loungers.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 330994}, {"number": "0066", "file": "0066 - The Nautilus Maldives - Nautilus Retreat with Private Pool - sunset deck with infinity pool and outdoor dining.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Ground level view along the curved infinity pool at sunset, its still water merging with the ocean horizon. Pale timber decking carries two white cushioned loungers with rolled towels and orange geometric cushions in the foreground, a rustic timber dining table with woven chairs and yellow cushions mid deck, and a thatched cabana daybed at the far end. Four conical thatch roofs rise behind full height glazed timber doors, through which lamplit interiors and sheer curtains show. The scheme pairs bleached wood, natural thatch and white upholstery with single strong accents of orange and yellow.", "src": "images/The Nautilus Maldives/0066 - The Nautilus Maldives - Nautilus Retreat with Private Pool - sunset deck with infinity pool and outdoor dining.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 137868}, {"number": "0067", "file": "0067 - The Nautilus Maldives - Nautilus Retreat with Private Pool - deck dining table at sunset with wicker chairs.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Close sunset view of outdoor dining on the deck, a weathered rustic timber table set for four with candle lanterns, turquoise glasses and a red patterned textile runner, surrounded by woven rattan barrel chairs with mustard yellow cushions and patterned seat pads. Behind, two white loungers with orange cushions face the curved infinity pool and its spiral scroll handrail, and a round thatched cabana with a draped daybed closes the deck. Warm lamplight glows through the glazed pavilion doors. Recreate with natural weave chairs, one saturated cushion colour, and patterned cloth used only as a runner.", "src": "images/The Nautilus Maldives/0067 - The Nautilus Maldives - Nautilus Retreat with Private Pool - deck dining table at sunset with wicker chairs.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 191237}, {"number": "0068", "file": "0068 - The Nautilus Maldives - Nautilus Retreat with Private Pool - circular living room with glass floor panel.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Circular living room under a domed woven thatch ceiling, centred on an oval glass floor panel looking down to the lagoon. A curved cream sofa with yellow floral and watercolour cushions and a mustard wing chair face two round yellow coffee tables with turned legs, set on a yellow and grey abstract rug. A dark bronze sunburst mirror, a whitewashed console stacked with books and a table lamp with a stacked rattan sphere base dress the walls. A slatted timber television console, full height deck doors and a dining area visible beyond complete the open plan shell form room.", "src": "images/The Nautilus Maldives/0068 - The Nautilus Maldives - Nautilus Retreat with Private Pool - circular living room with glass floor panel.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 197345}, {"number": "0069", "file": "0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Reverse view of the circular living room, taken for its ceiling: a high domed roof of woven panels and exposed rafters, hung with a large hand knotted macrame chandelier with a beaded drop. Below, a high backed mustard wing chair and the curved cream sofa with yellow floral cushions sit around the round yellow coffee table, beside a drum side table carrying the stacked sphere rattan lamp. A cream macrame hanging is mounted on a round yellow wall disc, echoing the motif used in the beach residence, and a chevron grooved timber door closes the wall. Glazed doors run the length of the deck side.", "src": "images/The Nautilus Maldives/0069 - The Nautilus Maldives - Nautilus Retreat with Private Pool - living room under domed thatch ceiling with macrame chandelier.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x980", "size": 211128}, {"number": "0070", "file": "0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Curved bedroom in the yellow colourway, the king bed in white linen with a yellow and taupe painterly runner, lattice patterned cushions and a cylindrical bolster, backed by a pale timber headboard shelf with arched reading lamps. A buttoned cream bench stands at the foot, and a long low slatted timber console holds a turquoise glass bowl. Three tall glazed openings frame the deck and ocean, the middle one open. Through folding doors, the living room shows a rounded mustard chair, yellow tables and a sunburst mirror. Pale parquet in a chevron layout and a yellow abstract rug unify both rooms.", "src": "images/The Nautilus Maldives/0070 - The Nautilus Maldives - Nautilus Retreat with Private Pool - curved bedroom in yellow scheme with deck doors.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 233722}, {"number": "0071", "file": "0071 - The Nautilus Maldives - Nautilus Retreat with Private Pool - bathroom with hexagonal mirrors and oval tub.jpg", "resort": "The Nautilus Maldives", "space": "Nautilus Retreat with Private Pool", "description": "Bathroom opening straight onto the deck and ocean, with a large white oval freestanding tub and a floor standing chrome mixer in the foreground and a curved buttoned bench in a tan leather look finish beside it. Two pale timber vanity consoles carry oval vessel basins beneath tall hexagonal mirrors in timber frames, hung in front of the glazing so the sea stays visible. Blue, grey and cream geometric floor tiles, a cream bath mat, a lidded woven basket and diagonal slatted timber doors add pattern and craft. Through the doors, the bedroom shows the same yellow runner and rug.", "src": "images/The Nautilus Maldives/0071 - The Nautilus Maldives - Nautilus Retreat with Private Pool - bathroom with hexagonal mirrors and oval tub.jpg", "source": "https://www.thenautilusmaldives.com/houses/the-nautilus-retreat", "dimensions": "1920x900", "size": 188324}, {"number": "0072", "file": "0072 - Raffles Bali - Residence - residence exterior and furnished terrace at sunset.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Establishing view of the two storey residence at sunset, built in pale Palimanan limestone below and warm timber above under a steep grey shingle roof. Full height glazing with slim dark wood frames glows amber from inside, signalling the double height living spaces within. The ground floor opens completely to a broad stone paved terrace furnished with low rattan lounge chairs, small round side tables and a dining set, edged by a flowering bougainvillea hedge in magenta. Recreate the look with a strict two material palette, stone and teak toned wood, wide terraces, and planting used as a soft colourful balustrade.", "src": "images/Raffles Bali/0072 - Raffles Bali - Residence - residence exterior and furnished terrace at sunset.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 900770}, {"number": "0073", "file": "0073 - Raffles Bali - Residence - pool terrace and outdoor lounge seating from above.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Elevated view along the 20 metre infinity pool and its wide limestone terrace, showing how outdoor rooms are arranged in loose groups rather than rows. A low lounge cluster of woven rattan armchairs and sofas with oatmeal cushions sits around a round coffee table on the paving, with a second cushioned daybed group at the far end. Slim timber framed glazing runs the length of the house to the left, and a clipped hedge with magenta bougainvillea separates terrace from jungle. The palette is stone cream, weathered teak, sage and one flowering accent, lit by low bollard lamps.", "src": "images/Raffles Bali/0073 - Raffles Bali - Residence - pool terrace and outdoor lounge seating from above.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 870686}, {"number": "0074", "file": "0074 - Raffles Bali - Residence - pool deck sun loungers against stone wall.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Close view of the pool deck furniture against a rusticated limestone wall. Four adjustable sun loungers in pale woven rattan with deep cream mattresses are paired with rolled grey towels and small lumbar cushions in a muted tribal pattern, each pair shaded by a tall cream parasol on a timber pole. The deck is large format pale stone, the planting is architectural, strappy green leaves in raised beds, and sliding timber doors behind lead straight into the bedrooms. To copy the scheme, keep outdoor textiles plain, use pattern only on small cushions, and repeat the same stone inside and out.", "src": "images/Raffles Bali/0074 - Raffles Bali - Residence - pool deck sun loungers against stone wall.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 732143}, {"number": "0075", "file": "0075 - Raffles Bali - Residence - open air living pavilion at dusk.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "The covered outdoor living pavilion at dusk, the key indoor outdoor room of the residence. Two long low sofas in natural woven rattan with cream seats and navy patterned cushions face each other over dark timber coffee tables, flanked by drum shaped side tables with ceramic table lamps. Behind, a bar counter with tall stools serves the terrace. Rough cut limestone piers support a plain plaster ceiling with a dark ceiling fan, and the room frames the pool and the ocean horizon like a picture. Warm lamplight, not overhead light, sets the evening mood.", "src": "images/Raffles Bali/0075 - Raffles Bali - Residence - open air living pavilion at dusk.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 554430}, {"number": "0076", "file": "0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Master bedroom with a coffered, high pitched ceiling in rich teak toned timber and walls panelled in fluted wood and soft taupe fabric. The king bed is dressed in crisp white linen with navy and terracotta cushions, and a dark wood bed bench with navy bolster cushions sits at its foot, a signature Raffles touch. Beside the bed, marble effect stone panels back floating nightstands with box frame lamps. A lounge chair and ottoman sit by full height sliding doors opening to a balcony with garden views. Polished hardwood floors are softened by a plain cream rug.", "src": "images/Raffles Bali/0076 - Raffles Bali - Residence - master bedroom with bed bench and balcony.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 630516}, {"number": "0077", "file": "0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Second bedroom suite arranged as a private apartment, with its own sitting area in the foreground. A cream sofa with navy and woven tan cushions faces a low stone topped coffee table on a blue patterned rug, while the bed sits beyond a carved timber screen panel with a traditional Balinese motif, which zones sleep from sitting without a wall. Fitted wardrobes in warm wood line the far wall, and glazed doors on both sides bring in garden light. The lesson is zoning with screens, rugs and ceiling coffers in one continuous timber and cream scheme.", "src": "images/Raffles Bali/0077 - Raffles Bali - Residence - bedroom suite with sitting area and carved screen.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 587788}, {"number": "0078", "file": "0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Formal dining room for twelve under a soaring pitched ceiling of warm timber boards. One very long, dark stained plank table runs the length of the room, set with white napkins, glassware and a low floral centrepiece. The chairs are the focal craft piece, high backed woven rattan with curved crest rails and plump patterned seat cushions, light in colour against the dark table. Walls of glass on three sides frame jungle and ocean, a carved dark wood screen closes one end, and a single long pendant hangs over the table. Hardwood floors run throughout.", "src": "images/Raffles Bali/0078 - Raffles Bali - Residence - dining room with long dark table and rattan chairs.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 703277}, {"number": "0079", "file": "0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Open plan living and show kitchen in one double height space, designed for entertaining. A long island in warm wood cabinetry with a thick grey veined stone top anchors the room, lit by a cluster of slim black pendant rods at different heights. Beyond it, low cream sofas and armchairs with dark frames group around coffee tables on a pale rug, with a television console against the glass wall. Ceiling fans, cove lit timber ceilings and full height glazing keep the large volume intimate. The scheme mixes stone, teak toned joinery and black metal accents.", "src": "images/Raffles Bali/0079 - Raffles Bali - Residence - open plan living room and stone kitchen island.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 721087}, {"number": "0080", "file": "0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Private study and entertainment room with a dramatic black marble desk slab in the foreground, paired with sculptural grey upholstered desk chairs. Behind, a full wall of open display shelving in warm timber is backlit and styled with Balinese artefacts, a carved gold toned plaque, masks, ceramics, books and framed photographs, with a wall mounted television at its centre. A black multi disc chandelier adds a modern note against a dark woven ceiling panel. Glazed doors open to the pool terrace. The takeaway is museum style shelving, objects in ones and twos, and generous spacing.", "src": "images/Raffles Bali/0080 - Raffles Bali - Residence - study with marble desk and display shelving.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 654096}, {"number": "0081", "file": "0081 - Raffles Bali - Residence - private spa room with treatment bed and pool view.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Private spa treatment room within the residence, furnished simply so the view does the work. A single treatment bed dressed in white linen sits on pale flooring facing glass doors to the pool terrace and jungle. Built in dark wood shelving holds rolled white towels, ceramic vessels and carved decorative objects, styled like a small apothecary. The palette is the calmest in the house, white, warm wood and green from the planting outside, with soft daylight and no pattern. For recreation, keep wellness rooms uncluttered, use closed and open storage in one joinery wall, and frame a green view.", "src": "images/Raffles Bali/0081 - Raffles Bali - Residence - private spa room with treatment bed and pool view.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1708", "size": 520825}, {"number": "0082", "file": "0082 - Raffles Bali - Residence - bathroom with freestanding tub and double vanity.jpg", "resort": "Raffles Bali", "space": "Residence", "description": "Spa bathroom in stone and timber with a garden outlook. A sculptural oval freestanding tub in matt white sits on dark stone floor tiles beside a full height window looking into tropical planting and a stone wall. The double vanity is a long floating stone counter with two rectangular vessel basins, timber drawer fronts below holding folded white towels, and brass toned taps. Twin mirrors are flanked by carved timber panels and warm vertical pendant lights with a batik like pattern. White bath mats soften the stone. The mix of dark floor, pale stone and warm wood is the template.", "src": "images/Raffles Bali/0082 - Raffles Bali - Residence - bathroom with freestanding tub and double vanity.jpg", "source": "https://www.raffles.com/bali/residence/", "dimensions": "2560x1707", "size": 682265}, {"number": "0083", "file": "0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Open sided living room in dark stained timber centred on a woven rattan sofa dressed with ivory cushions and patterned throw pillows in grey, gold and cream. A round black pedestal coffee table carries a tea set and a small floral arrangement, balanced by a cylindrical dark wood cabinet at the side. Behind the sofa, tall hand painted wall panels in muted gold and sage show delicate botanical motifs, the signature art treatment of the villas. Full height glass doors open to a planted terrace, and a pale woven rug softens the polished timber floor.", "src": "images/Mandapa/0083 - Mandapa - Riverfront Pool Villa - living room with hand painted panels.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 771740}, {"number": "0084", "file": "0084 - Mandapa - Riverfront Pool Villa - living pavilion with botanical panels.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Long living pavilion under a steep thatched roof with exposed woven ceiling panels and dark timber trusses. One wall is lined with a run of framed botanical paintings in sage green and gold, each panel showing a single tropical plant study. Low rattan seating with cream upholstery and brown patterned cushions faces a round dark wood coffee table, while a small dining set for two stands by the open glass wall. Polished wood floors, a flat woven jute rug and filtered jungle light give the room its calm, earthy register. Recreate with repeated framed panels and honest natural fibres.", "src": "images/Mandapa/0084 - Mandapa - Riverfront Pool Villa - living pavilion with botanical panels.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1440", "size": 595502}, {"number": "0085", "file": "0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Wide bedroom view showing how the villa layers art, textile and timber. Large hand painted murals of Balinese landscape and flora cover the wall panels around a window seat dressed in cream with ochre cushions. A green upholstered lounge chair and small black side table sit beside folding glass doors that open to a furnished terrace. The bed, partly seen, carries a vivid floral patterned throw in coral and blue over white linen. A woven ceiling pendant, natural fibre rug and dark wood framing complete a rich but restful scheme.", "src": "images/Mandapa/0085 - Mandapa - Riverfront Pool Villa - bedroom with murals and terrace doors.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 928792}, {"number": "0086", "file": "0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "King bedroom arranged symmetrically in dark stained wood, the bed dressed in crisp white linen with a low black bench at its foot holding folded books. Behind the bed, a tall window frames tropical planting, flanked by a large colourful mural panel with peacock and floral detailing. To the left, a built in daybed with cream cushions and a coral throw sits under a second garden window, with a small round black table in front. Stone sculpture on a floating shelf, hanging lantern pendants and a pale woven rug finish the composition.", "src": "images/Mandapa/0086 - Mandapa - Riverfront Pool Villa - king bedroom with mural panel and daybed.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 953519}, {"number": "0087", "file": "0087 - Mandapa - Riverfront Pool Villa - bathroom with rattan wrapped soaking tub.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Bathroom designed as an indoor garden room. A deep oval soaking tub wrapped in woven rattan stands on a raised pale stone plinth in front of floor to ceiling glass filled with banana leaves and tropical planting. Brass floor mounted tapware with a hand shower keeps the rim clean and sculptural. To the right, a dark timber vanity area is lit by teardrop glass pendants, with woven baskets and folded white towels stored below. The lesson is contrast: warm basket weave and dark wood against stone, glass and living green.", "src": "images/Mandapa/0087 - Mandapa - Riverfront Pool Villa - bathroom with rattan wrapped soaking tub.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 952963}, {"number": "0088", "file": "0088 - Mandapa - Riverfront Pool Villa - bathroom with oval tub and dark vanity.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Second bathroom angle showing the vanity wall of the villa bathroom. A smooth white oval freestanding tub sits before full height windows onto a private planted courtyard, served by a tall arched brass mixer. The double vanity is built in dark stained timber with a stone top, twin vessels and a large round mirror that reflects the garden light. Glass teardrop pendants hang at different heights, and frosted glass doors in black frames separate the shower and WC. Rolled white towels, dark accessories and warm wood keep the palette grounded and spa like.", "src": "images/Mandapa/0088 - Mandapa - Riverfront Pool Villa - bathroom with oval tub and dark vanity.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 727756}, {"number": "0089", "file": "0089 - Mandapa - Riverfront Pool Villa - private pool and bedroom pavilion.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "View across the private plunge pool to the bedroom pavilion, showing how the villa presents itself from the garden. The still, dark tiled pool reflects the thatched roof and the warmly lit bedroom beyond its folding glass doors, where the dressed bed is visible. Frangipani trees, clipped planting and a carved stone planter soften the architecture, and a timber deck pavilion with a green ceramic feature wall stands to the right. Use this as the model for indoor outdoor flow: low rooflines, deep eaves, dark timber and planting threaded between buildings.", "src": "images/Mandapa/0089 - Mandapa - Riverfront Pool Villa - private pool and bedroom pavilion.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 1126695}, {"number": "0090", "file": "0090 - Mandapa - Riverfront Pool Villa - pool and pavilion at dusk.jpg", "resort": "Mandapa", "space": "Riverfront Pool Villa", "description": "Twilight view along the private pool toward the open living pavilion, the interiors glowing amber against deep blue evening sky. The long rectangular pool is edged in dark stone with a narrow timber deck, lawn and stepping stones beside it. Inside the pavilion, low sofas and warm lamplight show the outdoor living arrangement, while the separate bedroom wing glows through its glass wall in the foreground. Thatched roofs, frangipani and dense tropical planting frame the scene. The design takeaway is layered warm lighting at low level, never a single bright source.", "src": "images/Mandapa/0090 - Mandapa - Riverfront Pool Villa - pool and pavilion at dusk.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 780732}, {"number": "0091", "file": "0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Spa relaxation lounge arranged along a glass wall above the Ayung River. A curved low sofa in pale upholstery carries cushions in leaf green and terracotta, facing the water through full height sliding glass. Beside it stands a sculptural round side table in dark turned wood, set with a tea service and a bowl of fruit. Polished timber floors reflect the daylight, and carved wooden screens partly divide the seating bays. The recipe to copy is simple: one strong sculptural table, plain upholstery, two saturated cushion colours and an uninterrupted view.", "src": "images/Mandapa/0091 - Mandapa - Mandapa Spa - relaxation lounge with river view.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 872199}, {"number": "0092", "file": "0092 - Mandapa - Mandapa Spa - reception with carved guardian statues.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Spa reception conceived as a gallery of Balinese craft. Tall carved and painted guardian figures in green and gold flank a slatted timber screen, standing on dark plinths like museum pieces. Behind them, a formal arrangement of wooden desks and chairs with woven cane backs sits on stone and timber flooring, lit by angular brass pendants and table lamps with cream shades. Wood panelling, framed artwork and orchid arrangements complete the room. For a designer, the key move is treating ritual sculpture as the room dividing, wayfinding element rather than decoration added later.", "src": "images/Mandapa/0092 - Mandapa - Mandapa Spa - reception with carved guardian statues.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 749147}, {"number": "0093", "file": "0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Long reception and retail gallery in the spa, lined on one side with dark timber display shelving holding ceramics, oils and treatment products under warm picture lighting. A central stone topped consultation table with a carved geometric base is paired with leather and wood chairs, while a low credenza in matching dark wood carries table lamps and a tall arrangement of red tropical flowers. Coffered ceilings, travertine style stone floors and brass pendants give the space a calm, residential formality quite different from a typical hotel spa desk.", "src": "images/Mandapa/0093 - Mandapa - Mandapa Spa - reception and retail gallery.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1302", "size": 368899}, {"number": "0094", "file": "0094 - Mandapa - Mandapa Spa - couples treatment room with timber wardrobe.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Couples treatment room with two dressed massage beds in the foreground, each with rolled towels and a gold patterned runner. The room is anchored by a full height dark timber wardrobe wall and a curved ceiling soffit in warm wood tones. Sliding glass doors open to a private terrace where a daybed faces the jungle, and a low round side table and treatment trolley stand ready between the beds. Soft uplighting, plain plaster walls and uncluttered surfaces keep attention on texture: linen, timber, stone and leaf green outside.", "src": "images/Mandapa/0094 - Mandapa - Mandapa Spa - couples treatment room with timber wardrobe.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "2560x1440", "size": 639232}, {"number": "0095", "file": "0095 - Mandapa - Mandapa Spa - couples treatment room with daybed terrace.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Evening toned couples treatment room photographed from behind the two massage beds, looking toward a private daybed terrace. The beds carry sage grey covers and gold runners, and a woven rattan lounge chair with a small round table sits inside by the window. Through the open glass wall, a cushioned daybed with striped bolsters waits on the deck above the river greenery. Dark timber joinery, a circular recessed ceiling and low warm light make the room feel cocoon like. Note the restraint: no clutter, every object either woven, wooden or linen.", "src": "images/Mandapa/0095 - Mandapa - Mandapa Spa - couples treatment room with daybed terrace.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1281", "size": 262364}, {"number": "0096", "file": "0096 - Mandapa - Mandapa Spa - treatment room with twin beds and garden glass.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Bright treatment room for two, its pair of massage beds dressed in white linen with bolstered headrests and set side by side on a polished timber floor. Dark stained cabinetry runs along one wall, with woven ceiling panels and a slow ceiling fan above. Two walls of sliding glass open the room completely to a private garden of banana leaves and palms, so the treatment happens effectively outdoors while remaining shaded and private. A small woven basket and folded towels are the only props. Copy the black framed glazing against pale bedding and rich wood.", "src": "images/Mandapa/0096 - Mandapa - Mandapa Spa - treatment room with twin beds and garden glass.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1440", "size": 471411}, {"number": "0097", "file": "0097 - Mandapa - Mandapa Spa - single treatment room with textured wall.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Single treatment room with one white dressed massage bed placed against a full height textured grey stone wall. A woven roman blind filters light above sliding doors that open to a narrow balcony with a lounge chair and dense tropical planting. Dark timber floors and joinery frame the pale bed linen, and a small wooden stool holds treatment vessels beside the bed. The composition shows how a single rough material, used at full wall scale, can carry an otherwise minimal room. Keep furniture counts low and let the garden provide the colour.", "src": "images/Mandapa/0097 - Mandapa - Mandapa Spa - single treatment room with textured wall.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1440", "size": 486533}, {"number": "0098", "file": "0098 - Mandapa - Mandapa Spa - relaxation pavilion with carved screen.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Corner relaxation pavilion in the spa, open on two sides to palms and river greenery. A curved sofa in cream upholstery with blush and ochre cushions wraps around a dark turned wood side table set with tea things. Behind the sofa stands an ornate carved timber screen, dark against the bright garden, and the pitched ceiling is lined in woven panels with exposed dark beams. Polished wood floors and low planting at the deck edge blur the boundary with the jungle. It is a useful model for a small, high impact reading or tea corner.", "src": "images/Mandapa/0098 - Mandapa - Mandapa Spa - relaxation pavilion with carved screen.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1440", "size": 491947}, {"number": "0099", "file": "0099 - Mandapa - Mandapa Spa - vitality pool with loungers.jpg", "resort": "Mandapa", "space": "Mandapa Spa", "description": "Outdoor vitality pool at the spa, its curved stone edged basin set into a dark timber deck with two cushioned loungers dressed with rolled white towels. Rough stone side tables and a thatched shade pavilion sit at the pool edge, backed by stone retaining walls, palms and dense hillside jungle. A guest floats in the water, small in the frame, which keeps the focus on the setting. The design points are the organic pool outline, honest stone and timber materials, and loungers oriented to the forest rather than to each other.", "src": "images/Mandapa/0099 - Mandapa - Mandapa Spa - vitality pool with loungers.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/photos/", "dimensions": "1920x1281", "size": 509774}, {"number": "0100", "file": "0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "resort": "Mandapa", "space": "Library", "description": "The Library is an open sided timber pavilion lounge beside the main pool, furnished for afternoon tea and quiet reading. Round dark wood tables are paired with armchairs that combine curved timber frames with woven cane style backs and patterned upholstery. Large woven rattan pendants hang from the high pitched, raftered ceiling, and patterned stone tiles in grey and terracotta run across the floor. Dark wood bookcases and cabinets line the inner wall, while the open sides frame the pool, rice fields and forest. Official resort photograph, the only Library image the resort itself publishes.", "src": "images/Mandapa/0100 - Mandapa - Library - open pavilion lounge with woven pendants.jpg", "source": "https://www.ritzcarlton.com/en/hotels/dpsub-mandapa-a-ritz-carlton-reserve/dining/", "dimensions": "1920x1280", "size": 472846}, {"number": "0101", "file": "0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "resort": "Mandapa", "space": "Library", "description": "Second verified view of The Library, captioned as The Library in the gallery of a UK luxury travel specialist. A large gilt framed Balinese painting of a multi armed deity dominates the dark timber wall above a painted storage chest with gold detailing and a row of small candles. In front, steam bent style wooden armchairs with navy cushions surround a round table laid for the signature afternoon tea, with a tiered stand and teapot. A woven globe pendant hangs overhead, and folding doors open to the veranda, pool and gardens beyond. [below 1200px - best available]", "src": "images/Mandapa/0101 - Mandapa - Library - afternoon tea setting with framed deity painting.jpg", "source": "https://prestburytravel.co.uk/hotels/8374/mandapa-a-ritz-carlton-reserve", "dimensions": "900x600", "size": 251255}, {"number": "0102", "file": "0102 - Amanoi - Amanoi Ocean Pool Villa - living room with red lanterns and cream sofa.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Evening view of the open plan living room, arranged symmetrically around a low round timber coffee table on a dark polished floor. A cream upholstered sofa with loose ivory cushions faces two broad wooden lounge chairs with cream seat pads, flanked by small round side tables. Tall cylindrical red lantern pendants hang beside grey structural columns, giving the palette its only strong colour accent. Behind, latticed timber screens and folding glazed doors filter light, while a slatted timber ceiling and exposed beams keep the long, low room calm, ordered and unmistakably Vietnamese in character.", "src": "images/Amanoi/0102 - Amanoi - Amanoi Ocean Pool Villa - living room with red lanterns and cream sofa.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2000x1235", "size": 491646}, {"number": "0103", "file": "0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Daytime living room photographed from inside looking straight out to the sea, so the furniture reads as a layered foreground to the view. A grey upholstered sofa with rounded cushions sits left, paired with low slung timber armchairs with dark seat pads around a round pedestal coffee table holding a fruit bowl. Narrow side tables carry books and a small lantern. Red cylindrical lanterns hang either side of full height folding doors that open completely onto a terrace with two further armchairs and a table, demonstrating the seamless indoor outdoor plan, pale neutral textiles and dark timber contrast used throughout the villa.", "src": "images/Amanoi/0103 - Amanoi - Amanoi Ocean Pool Villa - living room opening to sea view terrace.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2560x1580", "size": 632650}, {"number": "0104", "file": "0104 - Amanoi - Amanoi Ocean Pool Villa - bathroom with soaking tub at dusk.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Bathroom at dusk with a deep rectangular soaking tub set in the foreground, fitted with a modern chrome filler and a timber bath caddy. Behind it, a low timber vanity unit with stone top runs along a wall of rough stone, lit by two slender cylindrical pendant lights. To the left, open fronted blonde timber wardrobes and shelving form the dressing area, with a white robe hanging against a plain plaster wall. A glazed door at the far end frames a pink sunset over the bay, and the slatted timber ceiling, dark floor and warm low lighting keep the space spa like and restful.", "src": "images/Amanoi/0104 - Amanoi - Amanoi Ocean Pool Villa - bathroom with soaking tub at dusk.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2000x1235", "size": 296312}, {"number": "0105", "file": "0105 - Amanoi - Amanoi Ocean Pool Villa - pool deck dining table beside granite boulders.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Sunlit corner of the private timber sundeck where the infinity pool edge meets a small outdoor dining setting, a round dark topped table with two simple wooden chairs with woven seats. Wide bleached timber deck boards run to a slim metal railing, beyond which huge weathered granite boulders and the rocky headland dominate the view over a turquoise sea. The lesson for recreation is restraint outdoors: one small dining set, no clutter, natural timber left to silver, and the geology and water supplying all colour and ornament instead of applied decoration or accessories.", "src": "images/Amanoi/0105 - Amanoi - Amanoi Ocean Pool Villa - pool deck dining table beside granite boulders.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2000x1235", "size": 611905}, {"number": "0106", "file": "0106 - Amanoi - Amanoi Ocean Pool Villa - timber sundeck with loungers at dusk.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Dusk view across the villa sundeck, with the still private pool reflecting trees in the lower left and a broad expanse of silvered timber boarding stretching toward the bay. Two low wooden sun loungers with dark cushions sit under a mature tree, beside a small round dining table with two chairs. Dry stone walling and dense planting edge the deck, softening the transition to the landscape. The composition shows how the villa furnishes its large deck with only two functional groupings, keeping sightlines open and using twilight, water reflection and foliage as the decorative elements.", "src": "images/Amanoi/0106 - Amanoi - Amanoi Ocean Pool Villa - timber sundeck with loungers at dusk.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2560x1580", "size": 764010}, {"number": "0107", "file": "0107 - Amanoi - Amanoi Ocean Pool Villa - wide timber deck with sun loungers and dining set.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Elevated view over the full width of the sundeck at sunset, showing the zoning of the outdoor room clearly. Two adjustable timber sun loungers with cream pads and a small side table occupy the centre, while a round dining table with two wooden chairs sits to the right, all on wide horizontal timber boards. A low dry stone retaining wall and clipped planting separate deck from hillside, and the dark edge of the private pool enters the frame at lower left. Pale evening light, muted textiles and unadorned wood keep the large terrace feeling private rather than resort like.", "src": "images/Amanoi/0107 - Amanoi - Amanoi Ocean Pool Villa - wide timber deck with sun loungers and dining set.jpg", "source": "https://www.aman.com/resorts/amanoi/gallery", "dimensions": "2560x2560", "size": 1334450}, {"number": "0108", "file": "0108 - Amanoi - Amanoi Ocean Pool Villa - private pool with wooden loungers under trees.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Square format view looking down the length of the private pool, framed by mature trees and granite boulders. In the foreground, two chunky timber sun loungers with stone coloured pads and rolled white towels rest on the boarded deck beside a small wooden stool, with dry stone walling behind them. At the far end of the turquoise pool a small dining table and chairs sit in shade. The image is useful for its material palette: warm mid tone timber, rough grey stone, deep green foliage and clear blue water, with no pattern or bright colour anywhere in the furnishing scheme.", "src": "images/Amanoi/0108 - Amanoi - Amanoi Ocean Pool Villa - private pool with wooden loungers under trees.jpg", "source": "https://www.aman.com/resorts/amanoi/gallery", "dimensions": "1601x1601", "size": 3012028}, {"number": "0109", "file": "0109 - Amanoi - Amanoi Ocean Pool Villa - aerial view of pavilion roof pool and deck.jpg", "resort": "Amanoi", "space": "Amanoi Ocean Pool Villa", "description": "Aerial view that explains the villa plan and its signature roof: a single low pavilion with a sweeping grey tiled roof, its eaves lifting slightly at the corners in traditional Vietnamese fashion, sits in dense forest above the coast. A dark rectangular private pool runs along the front of the pavilion, edged by a timber deck furnished with sun loungers and a shaded dining set under an umbrella. Full height glazing opens the interior to the deck. For recreation, note the hierarchy: one strong architectural gesture, a horizontal pool line, and minimal outdoor furniture set well back into planting.", "src": "images/Amanoi/0109 - Amanoi - Amanoi Ocean Pool Villa - aerial view of pavilion roof pool and deck.jpg", "source": "https://www.aman.com/resorts/amanoi/accommodation/pavilions-villas/amanoi-ocean-pool-villa", "dimensions": "2560x1580", "size": 1121076}, {"number": "0110", "file": "0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Wide interior of the main dining room, set for service with rectangular tables dressed in crisp white linen, glassware and folded napkins, surrounded by wooden framed chairs with dark woven backs and cream seats. A cream banquette runs along one side. Behind the tables, tall illuminated timber display cabinets hold large black lacquered urns and vessels, matched by oversized black table lamps with drum shades on side consoles. Dark ceilings, warm backlighting and restrained black, cream and honey timber tones give the formal room its evening mood, a useful template for quiet, layered restaurant lighting and display shelving.", "src": "images/Amanoi/0110 - Amanoi - The Restaurant - dining room with white linen and black lamps.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2000x1235", "size": 478574}, {"number": "0111", "file": "0111 - Amanoi - The Restaurant - dining detail with illuminated timber cabinets.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Portrait detail of the dining room that isolates the design elements a recreation would need: a white clothed table set with wine glasses, cutlery and a small green plant in the foreground, and behind it a pair of tall, open fronted timber cabinets, backlit in warm amber, each displaying a single large black lacquered urn. A black table lamp with a wide drum shade and a candlestick sit on the console below. The formula is symmetrical display niches, one sculptural dark object per shelf, and warm concealed lighting against dark walls and a slatted timber ceiling.", "src": "images/Amanoi/0111 - Amanoi - The Restaurant - dining detail with illuminated timber cabinets.jpg", "source": "https://www.aman.com/resorts/amanoi/dining/restaurant", "dimensions": "1946x2560", "size": 647961}, {"number": "0112", "file": "0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Long view through the Central Pavilion interior toward full height latticed timber screens, showing the restaurant lounge area furnished with grouped wooden armchairs, cushioned seats and low tables on a highly polished dark floor that mirrors the columns. Massive round grey columns carry the high pitched timber ceiling, and carved dark figures and a large floral arrangement on plinths provide the only ornament. Warm light glows through the lattice at the far end. The scale lesson is clear: very tall, simple architecture, furniture kept low and sparse, and screens used instead of solid walls to divide the space.", "src": "images/Amanoi/0112 - Amanoi - The Restaurant - pavilion interior with lattice screens and columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 537736}, {"number": "0113", "file": "0113 - Amanoi - The Restaurant - terrace dining with orange cushions and sea view.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Terrace dining in full daylight, with round tables in white cloths set with glassware in the foreground and a long built in banquette behind them, piled with cushions in orange, rust red and cream. Slatted timber dining chairs with cream seat pads complete each setting. Dark stone paving, a low hedge and an uninterrupted sea and headland view form the backdrop. This is the one place in the collection where colour is used boldly, through replaceable cushion textiles in warm spice tones against neutral wood, stone and white linen, an easy device to copy for seasonal change.", "src": "images/Amanoi/0113 - Amanoi - The Restaurant - terrace dining with orange cushions and sea view.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 455127}, {"number": "0114", "file": "0114 - Amanoi - The Restaurant - terrace with dark tables and coastal view.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Wide morning view of the restaurant terrace before service, showing three round dark topped pedestal tables, each with a pair of slatted timber armchairs with cream pads, arranged in front of a continuous built in bench seat with pale cushions. A staff member crosses the dark stone paved terrace, which is edged only by a clipped green hedge before the land falls to the sea and rocky headland. Without table linen the furniture forms read more clearly here: chunky timber frames, woven style backs, and a strict, evenly spaced layout that keeps the horizon as the focal point.", "src": "images/Amanoi/0114 - Amanoi - The Restaurant - terrace with dark tables and coastal view.jpg", "source": "https://www.aman.com/resorts/amanoi/dining/restaurant", "dimensions": "2560x1580", "size": 511818}, {"number": "0115", "file": "0115 - Amanoi - The Restaurant - terrace table for two in portrait view.jpg", "resort": "Amanoi", "space": "The Restaurant", "description": "Portrait view of a single terrace table for two, a small round dark table with two matching slatted timber chairs with light cushions, set on dark stone paving in front of a long low banquette. A plain hedge band and a calm, empty sea fill the upper half of the frame. The image distils the Amanoi terrace formula to its essentials: one table, two well proportioned timber chairs, no table dressing, and maximum negative space. It is a strong reference for scaling outdoor dining furniture down and letting proportion, horizon and light carry the sense of luxury.", "src": "images/Amanoi/0115 - Amanoi - The Restaurant - terrace table for two in portrait view.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "1946x2560", "size": 546685}, {"number": "0116", "file": "0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Wide evening view along the Bar, centred on a very long, low timber bar counter with a dark top, fronted by a row of tan leather bar chairs. Massive pale columns divide the counter from a lounge area of low sofas and small round tables to the left, all under a high pitched timber ceiling with exposed structure. Warm light glows from latticed timber screens and glass cabinets behind the counter, where a bartender works. The design takeaway is length and repetition: one continuous counter, identical seating, and amber backlighting creating atmosphere without decoration or clutter.", "src": "images/Amanoi/0116 - Amanoi - The Bar - long timber bar counter with columns.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "2560x1580", "size": 536606}, {"number": "0117", "file": "0117 - Amanoi - The Bar - bar counter detail with table lamps in portrait view.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Portrait detail taken along the Bar counter, showing a receding row of small table lamps with cream shades glowing on the dark counter surface, with tan leather bar chairs tucked beneath it in the foreground. Behind, tall timber panels and doors are lit in deep red tones, echoing the red lantern accents used in the villas. The shallow depth of field makes this a study in bar lighting: repeated low lamps at seat height, warm timber, and dark reflective surfaces, producing intimacy in a very large, high ceilinged pavilion that would otherwise feel exposed.", "src": "images/Amanoi/0117 - Amanoi - The Bar - bar counter detail with table lamps in portrait view.jpg", "source": "https://www.aman.com/resorts/amanoi/dining/bar", "dimensions": "1946x2560", "size": 543781}, {"number": "0118", "file": "0118 - Amanoi - The Bar - leather armchairs with framed art wall.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Intimate corner of the Bar dominated by a dark gallery wall of framed black and white photography and one colourful abstract painting in a gilt frame, exactly the local art and photography the Bar is known for. Below the pictures, deep brown leather club armchairs are grouped around a dark bar table set with bottles and glassware, lit by two small shaded table lamps. Slate grey walls, dark timber and worn leather create a moodier, more urban contrast to the pale pavilion spaces, showing how one dark feature wall can anchor a drinks space.", "src": "images/Amanoi/0118 - Amanoi - The Bar - leather armchairs with framed art wall.jpg", "source": "https://www.aman.com/resorts/amanoi/dining", "dimensions": "1946x2560", "size": 701412}, {"number": "0119", "file": "0119 - Amanoi - The Bar - art and timber console detail.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Close detail of a Bar seating corner, with a round light timber table in the foreground holding a small black lacquered bowl and a closed book, and a slatted wooden chair with a cream cushion beside it. Behind, a low timber console with a woven dark front carries turned wooden vessels and candlesticks, set against tall marbled panels in grey and cream. A large framed black and white photographic portrait hangs above a smaller framed print. The grouping shows the decorative recipe clearly: one hero photograph, natural wood vessels, lacquer, and plain textiles, nothing else.", "src": "images/Amanoi/0119 - Amanoi - The Bar - art and timber console detail.jpg", "source": "https://www.foraytravels.com.sg/post/amanoi", "dimensions": "1706x1280", "size": 234853}, {"number": "0120", "file": "0120 - Amanoi - The Bar - terrace lounge seating with orange cushions.jpg", "resort": "Amanoi", "space": "The Bar", "description": "Terrace lounge seating used for drinks, photographed in soft late light: a long built in banquette runs across the frame, dressed with cushions in burnt orange, deep red and cream, with groups of slatted timber armchairs and small round dark tables arranged on dark stone paving in front of it. A low hedge separates the terrace from a wide sea and headland view. Compared with the set dining terrace, the lower tables and relaxed cushion colours signal drinks rather than dinner, and the image shows how one terrace furniture set serves both venues through textiles alone.", "src": "images/Amanoi/0120 - Amanoi - The Bar - terrace lounge seating with orange cushions.jpg", "source": "https://www.foraytravels.com.sg/post/amanoi", "dimensions": "2560x1340", "size": 227464}, {"number": "0121", "file": "0121 - Four Seasons Resort Koh Samui - Specialty Villas - Residence Villa thatched dining sala over the sea.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "A residence dining sala raised on dark timber stilts above the sea, reached by a railed wooden walkway deck. The steep thatched roof shelters a round dining table with woven chairs and patterned cushions, arranged for open air meals over the water. Slender coconut palms frame the pavilion, and a small freeform plunge pool sits on the adjoining deck beside the villa. The palette is natural and restrained: weathered teak tones, straw thatch, cream upholstery and turquoise sea, a model of southern Thai pavilion living that dissolves the line between room and landscape.", "src": "images/Four Seasons Resort Koh Samui/0121 - Four Seasons Resort Koh Samui - Specialty Villas - Residence Villa thatched dining sala over the sea.jpg", "source": "https://www.fourseasons.com/kohsamui/privateretreats/", "dimensions": "1600x900", "size": 634175}, {"number": "0122", "file": "0122 - Four Seasons Resort Koh Samui - Specialty Villas - Private Residence open air dining pavilion.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "Inside a private residence dining pavilion, a long solid timber table is set for a group meal beneath a high pitched roof of dark stained wood. Slatted back dining chairs with woven seats line both sides, and low lounge seating with pale cushions waits behind. Full height folding glass and timber doors open the room on two sides to the garden, the pool and the sea beyond, so the pavilion reads as a shaded outdoor room. Brass and glass tableware, small flower arrangements and polished hardwood floors keep the mood refined rather than rustic.", "src": "images/Four Seasons Resort Koh Samui/0122 - Four Seasons Resort Koh Samui - Specialty Villas - Private Residence open air dining pavilion.jpg", "source": "https://www.fourseasons.com/kohsamui/privateretreats/", "dimensions": "2560x1518", "size": 1139461}, {"number": "0123", "file": "0123 - Four Seasons Resort Koh Samui - Specialty Villas - Three-Bedroom Residence Villa long pool with loungers.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "The long lap style pool of a three bedroom residence villa stretches toward the Gulf between dark timber decks furnished with white cushioned sun loungers and wide teal umbrellas. Behind the pool, steep pitched Thai pavilion roofs in dark shingle rise among coconut palms and clipped hedges, each pavilion a separate bedroom or living sala. Stone coping and a pale pool edge keep the waterline crisp against the deep green planting. The composition is symmetrical and calm, with the pool as a reflecting axis that organises the whole residence garden.", "src": "images/Four Seasons Resort Koh Samui/0123 - Four Seasons Resort Koh Samui - Specialty Villas - Three-Bedroom Residence Villa long pool with loungers.jpg", "source": "https://www.fourseasons.com/kohsamui/accommodations/private_residences/three_bedroom_residence_villa_with_pool/", "dimensions": "2048x1365", "size": 1330569}, {"number": "0124", "file": "0124 - Four Seasons Resort Koh Samui - Specialty Villas - Beach Villa with Pool freeform pool and timber deck.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "A beach villa freeform pool curves from a raised timber deck down toward the sand, its turquoise water edged in pale stone. A wooden staircase and railed balcony connect the pool level to the villa above, where an open veranda holds loungers and a shaded sitting area. Leaning coconut palms cross the frame and the beach and sea begin immediately beyond the deck, so the pool works as a private lagoon between house and shore. Materials stay natural: oiled deck boards, rough stone and woven outdoor furniture in dark tones. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0124 - Four Seasons Resort Koh Samui - Specialty Villas - Beach Villa with Pool freeform pool and timber deck.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 256593}, {"number": "0125", "file": "0125 - Four Seasons Resort Koh Samui - Specialty Villas - Beach Villa with Pool canopy bed with teal cushions.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "A beach villa bedroom centred on a tall four poster bed dressed in white linen, teal silk cushions and a green patterned throw, with sheer mosquito drapes gathered at the posts. Dark timber framing and a woven ceiling panel contrast with the pale walls, while matching table lamps with striated shades sit on low bedside cabinets. A floral arrangement and folded towels add soft colour, and daylight enters through louvred openings on both sides. The effect is cool, shaded and tailored, with the saturated teal and green accents carried through every textile. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0125 - Four Seasons Resort Koh Samui - Specialty Villas - Beach Villa with Pool canopy bed with teal cushions.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 106381}, {"number": "0126", "file": "0126 - Four Seasons Resort Koh Samui - Specialty Villas - Five-Bedroom Residence Villa private wine cellar.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "The private wine cellar of the five bedroom residence villa is lined floor to ceiling with dark stained timber racking, its cubbies filled with bottles and lit by small candles in glass holders. A central tasting counter displays stemware, a cheese board and a framed coral artwork in red and white, giving the room a collected, club like feel. Through the open doorway at the far end, the blue of the pool and sea is visible, a reminder that this indoor, almost European room sits inside a Thai beach house. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0126 - Four Seasons Resort Koh Samui - Specialty Villas - Five-Bedroom Residence Villa private wine cellar.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 174003}, {"number": "0127", "file": "0127 - Four Seasons Resort Koh Samui - Specialty Villas - Four-Bedroom Residence Villa timber sun deck.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "A broad timber sun deck at a four bedroom residence villa, furnished with two adjustable loungers in weathered wood with grey cushions and folded white towels. A rustic railed balustrade in uneven natural poles edges the deck, and a thatched shade roof covers one corner. Planters with broad leaf tropical plants soften the boards, and the turquoise sea fills the background below a single palm. The detailing is deliberately simple, almost beach house in character, letting proportion, shadow and the horizon do the decorative work. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0127 - Four Seasons Resort Koh Samui - Specialty Villas - Four-Bedroom Residence Villa timber sun deck.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 212637}, {"number": "0128", "file": "0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "The living and dining room of the one bedroom Island Residence combines polished hardwood floors with a high open ceiling and full height glass doors. Two woven armchairs with cream and patterned cushions face a pale upholstered sofa across paired drum side tables in natural wood, stacked with books and ceramics. Behind, a timber dining table with six woven chairs and turquoise cushions stands ready for indoor meals, lit by daylight from three sides. Tall potted palms, carved details and a muted palette of cream, sand and sea green complete a calm, collected interior. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0128 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence living and dining room.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 263986}, {"number": "0129", "file": "0129 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence carved pillars and infinity pool.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "From inside the Island Residence, the view is framed by two massive carved timber pillars with pierced, temple like detailing, opening onto an infinity pool that merges with the Gulf of Thailand. A small stone statue and low planters mark the threshold between the shaded interior and the bright terrace, and red stemmed palms punctuate the planting on either side. The architecture borrows the language of a Thai sala, using overscaled dark wood posts to create a picture frame for water, sky and distant islands. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0129 - Four Seasons Resort Koh Samui - Specialty Villas - Island Residence carved pillars and infinity pool.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 235696}, {"number": "0130", "file": "0130 - Four Seasons Resort Koh Samui - Specialty Villas - Three-Bedroom Residence Villa thatched pool sala.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "Specialty Villas", "description": "A thatched dining sala stands in the middle of the three bedroom residence pool, its open sides furnished with a round table, bench seating and cream and patterned cushions at water level. Dark timber posts and a thick straw roof give the pavilion a rustic silhouette against clipped hedges, palms and the sea beyond. Wooden decking wraps the pool, with loungers placed for sun at the far end. Dining in the sala means sitting almost in the pool itself, a playful, distinctly Thai idea executed with simple natural materials. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0130 - Four Seasons Resort Koh Samui - Specialty Villas - Three-Bedroom Residence Villa thatched pool sala.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 216676}, {"number": "0131", "file": "0131 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Open kitchen chef counter with copper pendants.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "The open kitchen at KOH Thai Kitchen is arranged around a wide timber chef counter where a chef prepares southern Thai dishes in front of guests. Copper pendant lights hang in a row above the counter, warming the dark stained cabinetry, stone worktops and built in ovens behind. Market produce, herbs, chillies and small bowls of prepared ingredients are laid out along the counter as both mise en place and decoration, and a large botanical artwork in green and red hangs on the rear wall. The mood is intimate and theatrical, part kitchen, part stage.", "src": "images/Four Seasons Resort Koh Samui/0131 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Open kitchen chef counter with copper pendants.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/", "dimensions": "2560x1707", "size": 619154}, {"number": "0132", "file": "0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "The main dining hall at KOH Thai Kitchen is a grand open pavilion with a steeply pitched timber ceiling, exposed trusses and slowly turning ceiling fans. Rows of square wooden tables are set with glassware and folded napkins, surrounded by woven rattan armchairs with patterned seat cushions in cream and soft blue. Dark hardwood floors reflect the warm late light, and the open sides frame jungle and sea views between massive round columns. Botanical artworks and low planting complete a room that feels both ceremonial and relaxed, unmistakably southern Thai in spirit.", "src": "images/Four Seasons Resort Koh Samui/0132 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Main dining hall with woven chairs.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/restaurants/koh/", "dimensions": "2560x1642", "size": 1125546}, {"number": "0133", "file": "0133 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Terrace dining at dusk.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "At dusk the KOH Thai Kitchen terrace becomes a candlelit dining room open to the sea, with set tables arranged along a glass balustrade under a deep timber roof. Woven armchairs with pale cushions face outward toward the darkening Gulf, while small lamps and glassware catch the last blue light. Coconut palms rise through and beside the terrace, and the roofline of round dark columns recedes in perspective, giving the space a rhythmic, colonnaded feel. It is the resort at its most atmospheric, built on contrast between warm interior glow and tropical twilight.", "src": "images/Four Seasons Resort Koh Samui/0133 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Terrace dining at dusk.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/restaurants/koh/", "dimensions": "2560x1707", "size": 500749}, {"number": "0134", "file": "0134 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Terrace edge with rattan dining chairs.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "A daylight view along the edge of the KOH Thai Kitchen terrace shows woven rattan dining chairs with cream patterned cushions pulled up to set tables beside a glass and dark post balustrade. Above, a slatted timber ceiling shades the deck, carried on polished round columns in a deep brown finish. Beyond the railing, coconut palms and dense green canopy drop away to the Gulf of Thailand, so every seat feels suspended between jungle and sea. The furniture is light and low, keeping the horizon uninterrupted and the architecture quietly recessive.", "src": "images/Four Seasons Resort Koh Samui/0134 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Terrace edge with rattan dining chairs.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/restaurants/koh/", "dimensions": "2560x1605", "size": 1266879}, {"number": "0135", "file": "0135 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Sunset terrace table for two.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Thai Kitchen", "description": "A single terrace table for two at KOH Thai Kitchen is set with glassware and candles on the open deck at sunset, attended by a server, with the sky turning orange and violet over the Gulf. Two woven lounge chairs with pale cushions angle toward the view, and the dark silhouette of the balustrade and palm trunks separates the intimate setting from the wide seascape. The photograph captures the restaurant in private dining mode, where minimal furniture, generous spacing and the natural spectacle of the sunset provide all the decoration required.", "src": "images/Four Seasons Resort Koh Samui/0135 - Four Seasons Resort Koh Samui - KOH Thai Kitchen - Sunset terrace table for two.jpg", "source": "https://press.fourseasons.com/kohsamui/hotel-news/2025/culinary-artistry-female-chefs/", "dimensions": "1600x900", "size": 280975}, {"number": "0136", "file": "0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Bar", "description": "The KOH Bar lounge fills a high timber pavilion with blocky woven rattan armchairs, oversized daybed sofas and low square coffee tables. Cushions mix burnt orange solids with cream and rust geometric patterns, warming the dark hardwood floor and the massive round columns. Rope wrapped beam joints, a woven ceiling, pierced friezes and clusters of woven pendant lights add crafted Thai detail overhead, while folding glass doors open one whole side to the terrace and trees. Staff serve wine and cocktails at the tables, underlining that this is a drinking lounge, not a dining room.", "src": "images/Four Seasons Resort Koh Samui/0136 - Four Seasons Resort Koh Samui - KOH Bar - Lounge pavilion with rattan armchairs and oversized sofas.jpg", "source": "https://www.fourseasons.com/kohsamui/dining/", "dimensions": "2560x1707", "size": 1055413}, {"number": "0137", "file": "0137 - Four Seasons Resort Koh Samui - KOH Bar - Outdoor lounge sofas at dusk.jpg", "resort": "Four Seasons Resort Koh Samui", "space": "KOH Bar", "description": "The outdoor seating of KOH Bar at dusk is a row of long striped daybed sofas with deep seat cushions and large loose pillows in cream and gold, set along the timber and glass wall of the pavilion. Small wooden side trays hold pierced metal candle lanterns that cast patterned light across the upholstery, and a flat roofed canopy extends over the deck toward the palm silhouettes and the violet sunset sky. The arrangement is linear and calm, designed for lingering over wine while the light fades over the Gulf. [below 1200px - best available]", "src": "images/Four Seasons Resort Koh Samui/0137 - Four Seasons Resort Koh Samui - KOH Bar - Outdoor lounge sofas at dusk.jpg", "source": "https://hurlinghamtravel.co.uk/hotel/four-seasons-resort-koh-samui", "dimensions": "1100x671", "size": 95986}, {"number": "0138", "file": "0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "resort": "Amanpuri", "space": "Pavilion", "description": "A symmetrical pavilion bedroom built around a full height lattice headboard wall of dark stained timber framing lighter wood panels in a strict grid. The low platform king bed in white striped cotton sits on chunky round timber legs, flanked by oval dark wood side tables, black swing arm reading lamps and tall carved wooden paddle sculptures mounted on the cream walls. Polished teak floorboards, a black vase of white orchids and lotus bud dishes complete the restrained palette. To recreate it, pair geometric timber screening with sculptural tribal art, low rounded furniture and warm uplighting.", "src": "images/Amanpuri/0138 - Amanpuri - Pavilion - bedroom with lattice timber headboard wall.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 306989}, {"number": "0139", "file": "0139 - Amanpuri - Pavilion - bathroom with sunken tub open to sea view.jpg", "resort": "Amanpuri", "space": "Pavilion", "description": "The pavilion bathroom centres on a deep oval soaking tub set into a curved polished timber surround, positioned before folding shutter doors that open completely to palms, rooftops and the Andaman Sea. Square chrome deck mounted taps and controls line the tub rim like objects on a shelf, beside folded white towels, a black Aman candle and small dark ceramic toiletry vessels. The design lesson is the framed view: keep the rim low and uncluttered, use rich warm wood against white porcelain, and let daylight and landscape act as the decoration in an otherwise minimal room.", "src": "images/Amanpuri/0139 - Amanpuri - Pavilion - bathroom with sunken tub open to sea view.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "1946x2560", "size": 421873}, {"number": "0140", "file": "0140 - Amanpuri - Pavilion - bathroom vanity with backlit screens and orchid.jpg", "resort": "Amanpuri", "space": "Pavilion", "description": "A detail view across the pavilion bathroom vanity, where a wide white tub edge and angular chrome fittings sit before a mirror framed by backlit timber lattice screens in the same grid pattern as the bedroom headboard. Reflected behind a tall stand holding a pot of white orchids is the bedroom itself, tying the two rooms together. Black pump bottles on a dark tray and a single lotus bud on a pedestal dish provide the only styling. Recreate the look with shoji style glowing panels, dark wood framing, orchids and strictly monochrome accessories. [below 1200px - best available]", "src": "images/Amanpuri/0140 - Amanpuri - Pavilion - bathroom vanity with backlit screens and orchid.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/pavilions", "dimensions": "900x900", "size": 119385}, {"number": "0141", "file": "0141 - Amanpuri - Premium Ocean Pool Pavilion - terrace with teak loungers and daybed sala.jpg", "resort": "Amanpuri", "space": "Premium Ocean Pool Pavilion", "description": "The pool terrace of a Premium Ocean Pool Pavilion shows Amanpuri at its most architectural: a steep Thai gable with grey shingle tiles, red brown fascia boards and a flame like chofa finial shelters a raised daybed platform. In front, two slatted teak sun loungers with charcoal cushions stand under a large canvas parasol beside the still infinity pool edge, with a woven planter of pink bougainvillea at the side. Warm sand toned stone paving, mature trees and the sea complete the composition. Recreate it with slatted hardwood loungers, taupe fabrics, oversized parasols and one strong roof silhouette.", "src": "images/Amanpuri/0141 - Amanpuri - Premium Ocean Pool Pavilion - terrace with teak loungers and daybed sala.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/pavilions", "dimensions": "1280x1280", "size": 2076539}, {"number": "0142", "file": "0142 - Amanpuri - Villa 47 - media room with floor cushions and cane chairs.jpg", "resort": "Amanpuri", "space": "Villa 47", "description": "Villa 47's media and living room layers Thai floor culture with contemporary comfort: low platform daybeds carry ribbed triangular Thai cushions in charcoal, a built in timber bench runs under a lattice panelled wood wall dressed with rust cushions, a blue and white porcelain vase and a red lacquer cabinet. Silvered bamboo and cane webbing armchairs face a large screen set in a grey stone wall, while a burl wood dining table fills the foreground. Tongue and groove timber ceilings, round hardwood columns, stone walls and full height glass to the pool terrace keep the palette warm, earthy and ordered.", "src": "images/Amanpuri/0142 - Amanpuri - Villa 47 - media room with floor cushions and cane chairs.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 634286}, {"number": "0143", "file": "0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "resort": "Amanpuri", "space": "Eight-Bedroom Ocean Villa", "description": "A grand open lounge under a high timber roof, where rows of polished round columns and diagonal braces frame glass walls looking to the sea. Seating is low and generous: taupe leather armchairs, leather daybeds with bolster arms and a long sofa grouped around oversized dark wood coffee tables on a muted rug. A tripod telescope, a bronze figure sculpture on a stone plinth and a carved wooden orb act as focal objects, with a rubble stone wall behind. To recreate it, use leather in warm greys, very large low tables, ceiling fans and museum scale art against the view.", "src": "images/Amanpuri/0143 - Amanpuri - Eight-Bedroom Ocean Villa - lounge with leather armchairs and ocean view.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "1600x988", "size": 1543163}, {"number": "0144", "file": "0144 - Amanpuri - Villas - living sala with charcoal sofas and rust cushions.jpg", "resort": "Amanpuri", "space": "Villas", "description": "An open sided villa living sala defined by massive polished timber posts, angled struts and a slatted wood ceiling with a ceiling fan. Long charcoal grey sofas and matching armchairs with woven panel backs are sharpened by rust orange cushions, arranged around a square glass topped timber coffee table holding a celadon tea set. Black stone floor tiles reflect the palms and sea beyond the terrace, where loungers and a parasol wait. The recipe is simple: dark upholstery, one warm accent colour, glossy black stone, honest teak structure and an orchid arrangement as the only ornament.", "src": "images/Amanpuri/0144 - Amanpuri - Villas - living sala with charcoal sofas and rust cushions.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "2560x2560", "size": 1553528}, {"number": "0145", "file": "0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "resort": "Amanpuri", "space": "Villas", "description": "A formal villa living room arranged with strict symmetry around a round burl wood pedestal table with a stepped, stacked base. Pale celadon daybed platforms with Thai triangular cushions face each other across dark stone tiles, fronted by a low lacquered tea tray. Behind, glazed timber doors and lattice screens reveal display cabinets of ceramics and a media room, flanked by Buddha head sculptures on plinths and silvered bamboo armchairs. The timber boarded ceiling and restrained green, brown and cream palette show how to use symmetry, collectable objects and one statement table to anchor a large room.", "src": "images/Amanpuri/0145 - Amanpuri - Villas - living room with celadon daybeds and pedestal table.jpg", "source": "https://www.aman.com/resorts/amanpuri/accommodation/villas", "dimensions": "2560x2560", "size": 1114382}, {"number": "0146", "file": "0146 - Amanpuri - Buabok - terrace with cane chairs and white linen tables.jpg", "resort": "Amanpuri", "space": "Buabok", "description": "Buabok, the resort's Thai restaurant, spills onto a stone terrace beneath the pavilion roofs, where tables dressed in crisp white linen are surrounded by high backed rattan cane armchairs with sage seat pads. Brass and glass hurricane candle lanterns and single stem flowers form a repeated centrepiece, and warm evening light catches the timber posts, diagonal braces and grey shingle roofs behind. A palm trunk grows straight through the terrace in its own stone planter. To recreate the look, mix woven cane seating, white cloths, brass lanterns and one tree kept inside the seating plan. [below 1200px - best available]", "src": "images/Amanpuri/0146 - Amanpuri - Buabok - terrace with cane chairs and white linen tables.jpg", "source": "https://www.aman.com/resorts/amanpuri/dining", "dimensions": "1068x1068", "size": 1204557}, {"number": "0147", "file": "0147 - Amanpuri - Arva - table for two in open pavilion with sea view.jpg", "resort": "Amanpuri", "space": "Arva", "description": "Arva, the Italian restaurant, is shown as a single table for two set in the corner of an open timber pavilion, proof of how little Amanpuri needs to furnish a room. A white cloth, plain ceramic plates, folded napkins, wine glasses and a glass hurricane candle are arranged between two high backed chairs with vertical timber slats and upholstered panels. Slatted wood ceiling boards, two dark round columns and a low rail frame palms and the turquoise sea. Recreate it with one perfectly set table, generous space around it and the view doing the decorative work.", "src": "images/Amanpuri/0147 - Amanpuri - Arva - table for two in open pavilion with sea view.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1580", "size": 515325}, {"number": "0148", "file": "0148 - Amanpuri - Nama - sake bar with woven wall and bottle shelves.jpg", "resort": "Amanpuri", "space": "Nama", "description": "Nama, the Japanese restaurant designed with Kengo Kuma, pairs Thai timber structure with Japanese detail: a sake bar with a glowing red orange lacquered front and tall stools faces shelves of sake bottles mounted on a wall of fine woven string art. Dining tables in warm wood carry low armchairs with charcoal cushions, while a partition wall of small stone tiles in a brick pattern divides the space. Heavy teak beams, columns and diagonal braces remain from the pavilion structure, and glass walls open to the sea. Combine woven screens, lacquer, stone mosaic and bottle display as art.", "src": "images/Amanpuri/0148 - Amanpuri - Nama - sake bar with woven wall and bottle shelves.jpg", "source": "https://www.aman.com/resorts/amanpuri/dining", "dimensions": "2560x1582", "size": 587732}, {"number": "0149", "file": "0149 - Amanpuri - Sunset Terrace - lounge seating on stone terrace above beach.jpg", "resort": "Amanpuri", "space": "Sunset Terrace", "description": "The Sunset Terrace lines a row of slatted teak lounge armchairs and love seats with thick cream cushions along a sand toned stone terrace above Pansea Beach, each pair angled to the water and the setting sun. Dry stone retaining walls, clipped hedges and tall coconut palms growing through the deck give the furniture its setting, with the resort's stone staircase rising behind. Nothing is styled beyond the seating itself. To recreate the effect, repeat one well made hardwood lounge chair in a disciplined row, keep cushions pale and plain, and let stone, palms and horizon supply the colour.", "src": "images/Amanpuri/0149 - Amanpuri - Sunset Terrace - lounge seating on stone terrace above beach.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 903860}, {"number": "0150", "file": "0150 - Amanpuri - The Spa House - double treatment room with two massage beds.jpg", "resort": "Amanpuri", "space": "The Spa House", "description": "The Spa House double treatment room is a study in symmetry: two massage beds dressed in white linen with dark patterned runners and orchid blooms face frosted, backlit screen doors framed in dark timber. A single orchid plant on a tall wooden stool stands centred between them, and a dark cabinet with a small oil burner sits to one side. Timber boarded ceilings, polished columns and pale stone floor tiles keep the room warm but clinical in its calm. Recreate it with paired beds, one central floral gesture, glowing screens and all clutter hidden in dark wood cabinetry.", "src": "images/Amanpuri/0150 - Amanpuri - The Spa House - double treatment room with two massage beds.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1582", "size": 370826}, {"number": "0151", "file": "0151 - Amanpuri - The Spa House - banya sauna with pine benches and wooden bucket.jpg", "resort": "Amanpuri", "space": "The Spa House", "description": "Inside the Spa House banya sauna, every surface is pale pine: vertical tongue and groove wall boards, slatted bench backs and two broad bench levels lit from beneath for a soft glow. The styling is purely functional and beautiful, a dark stained wooden soaking bucket with a long handled ladle, a hanging whisk of dried leaves and a neat stack of white towels with a felt sauna hat. To recreate a home sauna in this spirit, use one light wood throughout, hide the lighting under the benches, and limit objects to crafted timber vessels and plain white textiles.", "src": "images/Amanpuri/0151 - Amanpuri - The Spa House - banya sauna with pine benches and wooden bucket.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "1946x2560", "size": 524089}, {"number": "0152", "file": "0152 - Amanpuri - Main Pavilion - main pool front with layered Thai roofs and loungers.jpg", "resort": "Amanpuri", "space": "Main Pavilion", "description": "The resort's main pavilion, housing the open reception and lobby behind glass, presents its famous elevation across the midnight blue main pool: layered Thai roofs with grey fish scale shingles, red brown bargeboards and tall pointed gables with chofa finials above walls of pale timber boarding. On the stone terrace, pairs of low teak loungers with grey cushions and small slatted side tables face the water in strict symmetry, with rubble stone walls and palm planting softening the base. It is the template image for the whole collection: monumental roof forms, disciplined furniture pairs and a restrained grey, rust and teak palette.", "src": "images/Amanpuri/0152 - Amanpuri - Main Pavilion - main pool front with layered Thai roofs and loungers.jpg", "source": "https://www.aman.com/resorts/amanpuri/gallery", "dimensions": "2560x1580", "size": 1151663}, {"number": "0153", "file": "0153 - Trisara - Ocean Front Pool Villa - bedroom with pitched teak ceiling and king bed.jpg", "resort": "Trisara", "space": "Ocean Front Pool Villa", "description": "A long, calm bedroom pavilion built around the sea view, with a steeply pitched ceiling panelled in warm teak boards and exposed rafters over polished hardwood floors. The king bed is dressed in plain white linen with a bank of cream and bronze silk cushions, backed by a carved timber headboard panel with a gilded Thai motif. Low dark wood nightstands carry boxy white table lamps. At the far end a writing desk and chair sit between curtained windows, while sliding glass doors open to the terrace. The palette is honey, cream and deep brown, quiet and architectural.", "src": "images/Trisara Phuket/0153 - Trisara - Ocean Front Pool Villa - bedroom with pitched teak ceiling and king bed.jpg", "source": "https://trisara.com/suite/ocean-front-pool-villa/", "dimensions": "2560x1707", "size": 784484}, {"number": "0154", "file": "0154 - Trisara - Ocean Front Pool Villa - bathroom with soaking tub and built in daybed.jpg", "resort": "Trisara", "space": "Ocean Front Pool Villa", "description": "The villa bathroom runs as a long gallery in travertine and dark stained timber, combining bathing and lounging in one space. A deep white built-in soaking tub sits in a raised stone surround beside louvred windows and a garden window, with chrome deck fittings. Along the opposite wall a cream upholstered daybed with olive and cream cushions faces a dark wood vanity with twin basins, wall sconces and a stool. Cove lighting washes the ceiling in amber, and stone tiles underfoot keep the room cool. It reads as a private spa room rather than a conventional bathroom.", "src": "images/Trisara Phuket/0154 - Trisara - Ocean Front Pool Villa - bathroom with soaking tub and built in daybed.jpg", "source": "https://trisara.com/suite/ocean-front-pool-villa/", "dimensions": "2560x2022", "size": 1018979}, {"number": "0155", "file": "0155 - Trisara - Ocean Front Pool Villa - pool deck with dining table and sun loungers.jpg", "resort": "Trisara", "space": "Ocean Front Pool Villa", "description": "A panoramic view across the villa pool deck, furnished as an outdoor room. On bleached teak decking, a slatted timber dining table with four woven seat chairs sits under a large canvas umbrella at one end, while two padded sun loungers with a second umbrella face the infinity pool at the other. Grey green slate pool water mirrors the sea and headland beyond, framed by mature trees. The furniture is simple, low and weathered silver brown, chosen to disappear into the landscape. It shows how Trisara pushes living space outdoors, with dining, lounging and swimming on one continuous deck.", "src": "images/Trisara Phuket/0155 - Trisara - Ocean Front Pool Villa - pool deck with dining table and sun loungers.jpg", "source": "https://trisara.com/suite/ocean-front-pool-villa/", "dimensions": "2560x930", "size": 511310}, {"number": "0156", "file": "0156 - Trisara - Signature Ocean View Pool Suite - bedroom opening to living room.jpg", "resort": "Trisara", "space": "Signature Ocean View Pool Suite", "description": "The suite bedroom is a wide, light panorama in white plaster, pale oak and bleached teak. A low platform king bed in crisp white linen faces the glass wall and pool deck, with a single dark timber cabinet and a shaded table lamp as accents. Through a broad timber framed opening, the separate living room is visible with its sofa, coffee table and garden windows, giving the suite its apartment-like depth. Sheer curtains soften the daylight. For a designer, the lesson is restraint: few pieces, generous spacing, natural fibres and one dark wood note against an otherwise pale scheme.", "src": "images/Trisara Phuket/0156 - Trisara - Signature Ocean View Pool Suite - bedroom opening to living room.jpg", "source": "https://trisara.com/suite/signature-ocean-view-pool-suite/", "dimensions": "1600x600", "size": 142036}, {"number": "0157", "file": "0157 - Trisara - Signature Ocean View Pool Suite - living room with long sofa and stone coffee table.jpg", "resort": "Trisara", "space": "Signature Ocean View Pool Suite", "description": "The separate living room of the suite is arranged for slow daytime use, with a long low sofa in natural linen piled with cream and pale aqua cushions, a solid stone topped coffee table, and a woven rug over pale timber floors. A lounge chair and side table complete the seating, and a carved mirror panel and black wall sconce add the only ornament. Sliding doors connect the room to the bedroom behind and the pool deck in front, so the space works as a shaded retreat between the two. Textiles stay plain, letting weave and texture carry the interest.", "src": "images/Trisara Phuket/0157 - Trisara - Signature Ocean View Pool Suite - living room with long sofa and stone coffee table.jpg", "source": "https://trisara.com/suite/signature-ocean-view-pool-suite/", "dimensions": "1600x600", "size": 168607}, {"number": "0158", "file": "0158 - Trisara - Villa No. 9 - living room with carved wall panels and Buddha alcove.jpg", "resort": "Trisara", "space": "Villa No. 9", "description": "Villa No. 9 has the richest traditional interiors in this set: a formal living room with polished teak floors and white walls, furnished with a cream L-shaped sofa and armchair loaded with tangerine and lime silk cushions. A dark wood coffee table centres the group, and the end wall is built as a shrine-like alcove with a Buddha figure, flowers and carved panels. Lattice fronted teak cabinets and wardrobes line the walls, woven wall panels hang as art, and table lamps with cream shades warm the corners. It is classic Thai residential styling, layered, symmetrical and colour led by silk.", "src": "images/Trisara Phuket/0158 - Trisara - Villa No. 9 - living room with carved wall panels and Buddha alcove.jpg", "source": "https://trisara.com/residence/2-bedroom-ocean-view-residence/villa-no-9/", "dimensions": "1600x600", "size": 143394}, {"number": "0159", "file": "0159 - Trisara - Villa No. 9 - bathroom and dressing room with granite vanity.jpg", "resort": "Trisara", "space": "Villa No. 9", "description": "The bathroom and dressing area of Villa No. 9 is finished in speckled grey granite and honey teak. A long granite vanity with an undermount basin and tall mirror is lit by vertical tube sconces, and a separate timber dressing table with stool sits beneath a second mirror. Louvred teak wardrobe doors conceal hanging space for robes, shown open with white spa robes. Stone, wood and brushed metal are the whole material story, kept practical for a tropical climate. The design takeaway is the hotel bathroom planned as a dressing room, with grooming, storage and bathing given separate stations.", "src": "images/Trisara Phuket/0159 - Trisara - Villa No. 9 - bathroom and dressing room with granite vanity.jpg", "source": "https://trisara.com/residence/2-bedroom-ocean-view-residence/villa-no-9/", "dimensions": "1600x600", "size": 197220}, {"number": "0160", "file": "0160 - Trisara - Villa No. 9 - bedroom with louvred doors and reading chair.jpg", "resort": "Trisara", "space": "Villa No. 9", "description": "A garden bedroom in Villa No. 9 wrapped in warm timber, with louvred teak doors and window shutters that filter the green light from the planting outside. The bed carries white linen and a vivid row of cushions in coral pink, lime and tangerine silk, the colour accent used across the villa. Beside it, a cream reading armchair with an orange cushion sits under paired wall lamps with rectangular shades. Polished wood floors, woven wall panels and low timber furniture keep the room grounded and traditional. It shows Thai silk used as the single, changeable colour system in a neutral wood interior.", "src": "images/Trisara Phuket/0160 - Trisara - Villa No. 9 - bedroom with louvred doors and reading chair.jpg", "source": "https://trisara.com/residence/2-bedroom-ocean-view-residence/villa-no-9/", "dimensions": "1600x600", "size": 142366}, {"number": "0161", "file": "0161 - Trisara - Villa No. 20 - dining room with cane chairs and gilded carving.jpg", "resort": "Trisara", "space": "Villa No. 20", "description": "Villa No. 20 takes the opposite approach to No. 9: a pale, bleached scheme in limewashed timber, cream walls and linen curtains. The dining room seats six at a long pale wood table on cane backed chairs, centred by a dark ceramic bowl. On the sideboard behind, an ornate gilded Thai wood carving with elephant figures is displayed as the room's single artwork, flanked by garden windows. Woven blinds, cane and raw linen provide the texture. For recreation, note how one strong carved piece can carry a whole room when everything else is deliberately quiet and light.", "src": "images/Trisara Phuket/0161 - Trisara - Villa No. 20 - dining room with cane chairs and gilded carving.jpg", "source": "https://trisara.com/residence/2-bedroom-signature-villa/villa-no-20/", "dimensions": "1600x600", "size": 134711}, {"number": "0162", "file": "0162 - Trisara - Villa No. 20 - living room opening to pool terrace.jpg", "resort": "Trisara", "space": "Villa No. 20", "description": "The living room of Villa No. 20 is a long, low space in bleached wood and off-white upholstery, arranged symmetrically around a pale coffee table with a bowl of orchids. Armchairs and sofas in natural linen face inward, while full height glass doors at the far end open to the pool terrace and dining pavilion, pulling the sea breeze through. Oversized drum table lamps frame the foreground, and taupe curtains dress the side windows. The effect is coastal and serene rather than ornate, a useful counterpoint within Trisara to the darker, silk rich traditional villas elsewhere in this collection.", "src": "images/Trisara Phuket/0162 - Trisara - Villa No. 20 - living room opening to pool terrace.jpg", "source": "https://trisara.com/residence/2-bedroom-signature-villa/villa-no-20/", "dimensions": "1600x600", "size": 102547}, {"number": "0163", "file": "0163 - Trisara - Private Pool Residences - residence pavilion and pool terrace at dusk.jpg", "resort": "Trisara", "space": "Private Pool Residences", "description": "A residence pavilion photographed at dusk, when the design reads most clearly. A broad, low Thai roof with a central spire shelters an open fronted living and dining pavilion in dark stained timber, its interior glowing amber through glass doors, with a dining table and chairs visible inside. In front, the private infinity pool reflects the roofline, flanked by sun loungers, canvas umbrellas and two giant glazed ceramic urns used as sculpture. Carved stone door panels and planters of pink bougainvillea complete the scene. It captures the residence formula: pavilion living, water in front, ornament kept to a few oversized pieces.", "src": "images/Trisara Phuket/0163 - Trisara - Private Pool Residences - residence pavilion and pool terrace at dusk.jpg", "source": "https://trisara.com/residences/", "dimensions": "2560x1707", "size": 631019}, {"number": "0164", "file": "0164 - Trisara - Private Pool Residences - pool facade with oversized blue porcelain vases.jpg", "resort": "Trisara", "space": "Private Pool Residences", "description": "This residence facade shows the playful end of the Trisara style. A white pavilion with an orange tiled Thai roof and ceiling fans opens fully to a turquoise pool terrace furnished with white sun loungers, a small dining set and pale blue loungers. The bold gesture is a pair of oversized blue and white porcelain vases planted with greenery, standing in the pool shallows as pure decoration, with a carved stone figure between them. Timber cladding warms the rear wall. The lesson for a designer is scale: two very large ceramic pieces do the work of a whole scheme of small accessories.", "src": "images/Trisara Phuket/0164 - Trisara - Private Pool Residences - pool facade with oversized blue porcelain vases.jpg", "source": "https://trisara.com/residences/", "dimensions": "2560x1707", "size": 849698}, {"number": "0165", "file": "0165 - Trisara - PRU - open kitchen counter with sunset windows.jpg", "resort": "Trisara", "space": "PRU", "description": "PRU's dining room is built around its open kitchen, photographed here at sunset. A long dark timber counter with ten low backed counter chairs faces the chefs' station, backed by deep blue tiles, stainless steel and a fabric wrapped extraction hood. Behind the cooks, a wall of windows frames the Andaman sunset, so the view becomes the room's artwork. Round dining tables edge the foreground, and the ceiling is kept plain with recessed lighting and linear slots. Materials are limited to dark wood, blue tile, steel and glass. It is a chef's counter format translated into a calm, residential luxury language.", "src": "images/Trisara Phuket/0165 - Trisara - PRU - open kitchen counter with sunset windows.jpg", "source": "https://trisara.com/dining/pru/", "dimensions": "2560x1067", "size": 337689}, {"number": "0166", "file": "0166 - Trisara - Cielo & Spice - dining room with marble tables and candle chandelier.jpg", "resort": "Trisara", "space": "Cielo & Spice", "description": "Cielo & Spice is the resort's grand dining room, a high pavilion with a pitched teak ceiling, clerestory windows and a ring chandelier of candle-like glass shades over the tables. Dining tables are thick pale marble slabs on dark pedestal bases, set with woven placemats, ceramic and glass, and surrounded by curved back chairs in tan leather and pale upholstery. Full height glass walls open the room to the palm court and sea light. The mix to note is weight and airiness: heavy stone tables and a dark chandelier grounded by glass, rattan textures and daylight on every side.", "src": "images/Trisara Phuket/0166 - Trisara - Cielo & Spice - dining room with marble tables and candle chandelier.jpg", "source": "https://trisara.com/dining/cielospice/", "dimensions": "2560x1707", "size": 941444}, {"number": "0167", "file": "0167 - Trisara - Thai Library - dining room with wicker chairs and slatted screens.jpg", "resort": "Trisara", "space": "Thai Library", "description": "The Thai Library dining room is a relaxed pavilion room in white, rattan and dark timber. Square tables are dressed in white cloths with gold rimmed chargers, folded napkins and small orchid arrangements, surrounded by woven wicker armchairs with cushions in burnt orange Thai patterned fabric. A slatted timber screen wall divides the space, and a pitched ceiling with exposed beams and a ceiling fan keeps the room airy. At the back, an oversized ceramic urn and garden doors connect the room to the beachfront planting. It is homestyle Southern Thai dining presented with formal table dressing and resort polish.", "src": "images/Trisara Phuket/0167 - Trisara - Thai Library - dining room with wicker chairs and slatted screens.jpg", "source": "https://trisara.com/dining/thai-library/", "dimensions": "2560x1706", "size": 851209}, {"number": "0168", "file": "0168 - Six Senses Yao Noi - Ocean Pool Villa - Open bedroom pavilion from pool.jpg", "resort": "Six Senses Yao Noi", "space": "Ocean Pool Villa", "description": "Shot from the private infinity pool toward the fully open bedroom pavilion, this view captures the villa formula: a steep thatched roof over dark stained timber walls and decking, folding glass doors retracted so the bed platform sits almost outdoors. The bed is dressed in white linen under a sheer mosquito net draped from a natural branch. A built-in daybed niche with ochre cushions, a ceramic table lamp and a woven wall sconce warm the shadowed interior, while the pool edge and timber balustrade frame the sea beyond. Recreate with dark hardwoods, thatch, white bedding and one saturated cushion colour.", "src": "images/Six Senses Yao Noi/0168 - Six Senses Yao Noi - Ocean Pool Villa - Open bedroom pavilion from pool.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1707", "size": 843121}, {"number": "0169", "file": "0169 - Six Senses Yao Noi - Ocean Pool Villa - Sala terrace with table and pool.jpg", "resort": "Six Senses Yao Noi", "space": "Ocean Pool Villa", "description": "From inside the open sala, the camera looks across the pool to the bedroom pavilion. Overhead, a vaulted ceiling of woven bamboo strips on dark rafters carries a cylindrical parchment pendant. The sala is furnished simply: a chunky teak table with an inset tray top and a wooden fruit bowl, low lounge chairs with mustard cushions, and a round pedestal dining table shaded by a canvas umbrella at the deck edge. Pale weathered deck boards contrast with the dark timber structure, and the draped bed net and yellow daybed cushions repeat across the water. The palette is timber brown, canvas cream and turquoise.", "src": "images/Six Senses Yao Noi/0169 - Six Senses Yao Noi - Ocean Pool Villa - Sala terrace with table and pool.jpg", "source": "https://www.sixsenses.com/es/hotels-resorts/asia-the-pacific/thailand/yao-noi/", "dimensions": "2560x1708", "size": 957292}, {"number": "0170", "file": "0170 - Six Senses Yao Noi - Ocean Panorama Pool Villa - Pool terrace and sala at dusk.jpg", "resort": "Six Senses Yao Noi", "space": "Ocean Panorama Pool Villa", "description": "At dusk the pool terrace glows against the darkening bay. Two teak sun loungers with burnt orange mattresses face the infinity edge, flanked by hurricane lanterns, while behind them the open sala holds a deep daybed piled with cream and rust cushions under a pitched thatch roof lined with woven bamboo. Through the fully opened bedroom doors the white dressed bed and its branch hung mosquito net are visible, lit by a fabric wall sconce. Dark timber decking and posts, warm lamplight and the violet sea give the rustic scheme its evening richness. A model for layering one warm accent colour through outdoor upholstery.", "src": "images/Six Senses Yao Noi/0170 - Six Senses Yao Noi - Ocean Panorama Pool Villa - Pool terrace and sala at dusk.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1705", "size": 1527701}, {"number": "0171", "file": "0171 - Six Senses Yao Noi - Beachfront Pool Villa - Bedroom with branch canopy and window seat.jpg", "resort": "Six Senses Yao Noi", "space": "Beachfront Pool Villa", "description": "A true interior: the bedroom fills a pitched pavilion whose ceiling is woven bamboo over dark trusses. The white bed sits beneath a mosquito net swagged from a gnarled natural branch suspended on ropes, the resort's signature gesture. Along the full height glazing runs a long built-in window seat in dark timber with ochre, rust and mustard cushions, turning the karst view into the room's artwork. Beyond the open wall lie the private pool and a sala with a yellow cushioned daybed. Ceramic lamps with parchment shades, wide plank floors and canvas blinds complete the layered, tactile scheme.", "src": "images/Six Senses Yao Noi/0171 - Six Senses Yao Noi - Beachfront Pool Villa - Bedroom with branch canopy and window seat.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1708", "size": 743052}, {"number": "0172", "file": "0172 - Six Senses Yao Noi - Hideaway Pool Villa - Bedroom looking to pool and sala.jpg", "resort": "Six Senses Yao Noi", "space": "Hideaway Pool Villa", "description": "From the foot of the bed, the room reads as one continuous indoor outdoor space: white linen bedding, a branch suspended mosquito net overhead, and ceramic table lamps with stitched parchment shades on rough timber nightstands. Canvas roller blinds top the glazed wall. The eye travels past the plunge pool to the sala, where a long daybed carries a row of yellow cushions against woven bamboo screens, with a small dining set and umbrella on the deck. Dark stained floors and posts, woven ceiling panels and jungle greenery kept close give the garden villa its cocooned, private character.", "src": "images/Six Senses Yao Noi/0172 - Six Senses Yao Noi - Hideaway Pool Villa - Bedroom looking to pool and sala.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1708", "size": 670767}, {"number": "0173", "file": "0173 - Six Senses Yao Noi - The View - Double height bedroom with mezzanine.jpg", "resort": "Six Senses Yao Noi", "space": "The View", "description": "The showpiece one bedroom villa at blue hour: a double height timber pavilion with a mezzanine gallery reached by a spiral stair, its balustrade made of slender spindles. The bed, dressed in white with ochre cushions, sits beside a glass floor panel revealing the waterfall below, under a sheer net draped from a suspended branch. Pale timber armchairs and a small round table face the glass wall and the karst silhouettes, and two oversized canvas poufs soften the polished dark floor. Cylindrical paper lanterns and a ceramic lamp on the timber headboard unit supply the warm points of light.", "src": "images/Six Senses Yao Noi/0173 - Six Senses Yao Noi - The View - Double height bedroom with mezzanine.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1708", "size": 551912}, {"number": "0174", "file": "0174 - Six Senses Yao Noi - The View - Trampoline net daybed with ochre cushions.jpg", "resort": "Six Senses Yao Noi", "space": "The View", "description": "A detail of the villa's most playful feature: a tensioned rope net daybed projecting from the deck, loaded with oversized scatter cushions in ochre, sand and cream canvas. The coarse white mesh, laced to a dark timber frame with rope, contrasts with the smooth plank deck and the single rough bark post beside it. Nothing else competes: palms, turquoise water and the distant karst islands form the backdrop. For recreating the look, note the cushion scale, the deliberately slouchy fills, and the restrained two tone palette that lets texture, net, canvas and timber, do all the work.", "src": "images/Six Senses Yao Noi/0174 - Six Senses Yao Noi - The View - Trampoline net daybed with ochre cushions.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/gallery/", "dimensions": "2560x1717", "size": 553712}, {"number": "0175", "file": "0175 - Six Senses Yao Noi - The Ocean Retreat - Pool deck with daybed wall and sala.jpg", "resort": "Six Senses Yao Noi", "space": "The Ocean Retreat", "description": "The resort's largest residence reads as a two storey Thai long house in dark timber, its upper balcony railed with slim spindles above a woven bamboo screen wall. Along the shaded ground floor runs a very long built-in daybed dressed in lime green cushions, echoed by four teak loungers with green pads at the pool edge. A thatched sala at the far end holds a second green daybed, and the wide infinity pool is tiled in deep green stone. A white canvas umbrella, pale deck boards and cylinder wall lights keep the strong single colour scheme crisp.", "src": "images/Six Senses Yao Noi/0175 - Six Senses Yao Noi - The Ocean Retreat - Pool deck with daybed wall and sala.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/accommodation/", "dimensions": "2560x1708", "size": 1172788}, {"number": "0176", "file": "0176 - Six Senses Yao Noi - The Living Room - Terrace dining tables at dusk.jpg", "resort": "Six Senses Yao Noi", "space": "The Living Room", "description": "Alfresco tables on the beachside terrace at last light: solid teak tables and sculptural high back timber chairs with curved top rails, set with woven placemats in rust red, folded ochre napkins and tall glass hurricane candle lanterns. A glowing bark textured wall sconce is fixed to the dark round post, and coral and orange cushions soften the nearest chair. The setting is deliberately simple, heavy timber, natural fibre and candlelight, so the blue bay and karst islands beyond the planting act as the decoration. Ideal reference for rustic coastal restaurant styling with a controlled warm palette.", "src": "images/Six Senses Yao Noi/0176 - Six Senses Yao Noi - The Living Room - Terrace dining tables at dusk.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/dining/", "dimensions": "2560x1921", "size": 687728}, {"number": "0177", "file": "0177 - Six Senses Yao Noi - The Living Room - Breakfast buffet counter with copper pendants.jpg", "resort": "Six Senses Yao Noi", "space": "The Living Room", "description": "The breakfast buffet is a study in crafted service design: a curved rendered counter in pale plaster, topped with a thick timber worktop carrying grey clay pot warmers on iron stands, stacks of square white plates and small handwritten chalkboards. Above hang enormous hammered copper pendant hoods and smaller copper cones, their warm metal the room's jewellery against a woven bamboo ceiling and dark beams. A branch and twig stand displays cups beside the glass wall. One chef works behind the counter, and dense palm planting presses against the open side, merging kitchen garden and dining room.", "src": "images/Six Senses Yao Noi/0177 - Six Senses Yao Noi - The Living Room - Breakfast buffet counter with copper pendants.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/gallery/", "dimensions": "2560x1709", "size": 659224}, {"number": "0178", "file": "0178 - Six Senses Yao Noi - Nithan & Chef's Table - Dining pavilion with glass floor stream.jpg", "resort": "Six Senses Yao Noi", "space": "Nithan & Chef's Table", "description": "The lower dining pavilion is built around water and trees: massive unpeeled trunk columns support a coffered timber ceiling, and a glass floor panel runs through the deck revealing the stream and rocks below, edged with candle lanterns. Banquette daybeds in pale timber carry lime green cushions, paired with simple square dining tables set for dinner, and a staircase climbs to the Chef's Table and wine display above. Uplighting washes the trunks amber while the garden waterfall glows beyond the railing. The lesson is structural honesty: raw trunks, plain joinery and one vivid cushion colour.", "src": "images/Six Senses Yao Noi/0178 - Six Senses Yao Noi - Nithan & Chef's Table - Dining pavilion with glass floor stream.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/dining/", "dimensions": "2560x1703", "size": 695612}, {"number": "0179", "file": "0179 - Six Senses Yao Noi - The Hilltop - Bar with sculpted counter and lounge daybeds.jpg", "resort": "Six Senses Yao Noi", "space": "The Hilltop", "description": "Inside the hilltop pavilion bar, a sculptural white rendered counter curves like a wave, fronted by turned timber stools with hourglass profiles and pale upholstered tops. Bottles hang above on a suspended circular timber rack. The lounge side is all softness: oversized low daybeds in off white with rounded bolster cushions, and small drum side tables in warm wood, each carrying a globe light. A steep thatched ceiling lined with woven strips and dark beams caps the space, polished dark floorboards reflect the light, and the infinity pool and bay open at the far end.", "src": "images/Six Senses Yao Noi/0179 - Six Senses Yao Noi - The Hilltop - Bar with sculpted counter and lounge daybeds.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/dining/", "dimensions": "2560x1708", "size": 853858}, {"number": "0180", "file": "0180 - Six Senses Yao Noi - The Hilltop - Crescent pool pavilion and netted decks.jpg", "resort": "Six Senses Yao Noi", "space": "The Hilltop", "description": "An elevated view explains the whole venue: a great crescent infinity pool wrapped by a cream render wall clad in vertical bamboo, a steep thatched pavilion housing the bar, and tiered timber decks stepping down the hillside. The lower decks carry the signature netted lounge platforms and daybeds scattered with round cushions in ochre, rust and cream, like pebbles. Teak loungers line the pool, stairs and spindle railings are all dark timber, and two small figures at a poolside table give scale. It is rustic luxury organised as landscape architecture, furniture and planting planned as one composition.", "src": "images/Six Senses Yao Noi/0180 - Six Senses Yao Noi - The Hilltop - Crescent pool pavilion and netted decks.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/dining/", "dimensions": "2560x1705", "size": 1156145}, {"number": "0181", "file": "0181 - Six Senses Yao Noi - The Den - Sunken lily pond lounge at dusk.jpg", "resort": "Six Senses Yao Noi", "space": "The Den", "description": "The bar's sunken lounge sits in a lily pond: stone platforms at water level carry deep purple cushions and low rustic slab tables, each with a single candle, while the still water mirrors the karst islands beyond. A large woven paper lantern hangs from a tree branch, uplighters wash the trunks, and a thatched roof peeks through the planting behind. The saturated violet upholstery is the boldest colour note in the resort, proof that the natural palette can carry one jewel tone. Twilight timing, water, candlelight and minimal furniture make the scene; the furniture itself is deliberately almost nothing.", "src": "images/Six Senses Yao Noi/0181 - Six Senses Yao Noi - The Den - Sunken lily pond lounge at dusk.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/gallery/", "dimensions": "2560x1707", "size": 940630}, {"number": "0182", "file": "0182 - Six Senses Yao Noi - Six Senses Spa - Twin treatment room opening to lily pond.jpg", "resort": "Six Senses Yao Noi", "space": "Six Senses Spa", "description": "A twin treatment room in the spa village: two massage beds in crisp white face full height glazing opened to a private garden with a lily pond and a small waterfall among the rocks. Woven bamboo blinds roll across the top of the windows, tree trunk columns stand inside the glass line, and cylindrical parchment sconces glow at their sides. A bronze singing bowl rests on each bed. Through the side glass, a green cushioned daybed waits on the veranda. Pale plaster floors, thatch overhead and controlled views of water and planting create complete calm.", "src": "images/Six Senses Yao Noi/0182 - Six Senses Yao Noi - Six Senses Spa - Twin treatment room opening to lily pond.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/wellness-spa/", "dimensions": "2560x1708", "size": 978244}, {"number": "0183", "file": "0183 - Six Senses Yao Noi - Alchemy Bar - Workshop with live edge timber table.jpg", "resort": "Six Senses Yao Noi", "space": "Alchemy Bar", "description": "The spa's apothecary workshop is built almost entirely from raw timber: a huge live edge slab table on root bases, surrounded by stump stools, with stone mortars, herb bundles and apothecary jars as the working decor. Branch framed open shelves hold bottles and coconuts, a carved wooden bowl sink sits on a plank counter, and exposed Edison bulbs hang in a cluster. Dark plank walls and tree trunk posts frame the garden views, and a small chalkboard lists the workshop menu. Every surface keeps its grain, edge and imperfection, the clearest statement of the resort's natural material philosophy.", "src": "images/Six Senses Yao Noi/0183 - Six Senses Yao Noi - Alchemy Bar - Workshop with live edge timber table.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/asia-the-pacific/thailand/yao-noi/wellness-spa/", "dimensions": "2560x1708", "size": 971873}, {"number": "0184", "file": "0184 - Four Seasons Resort Bali at Sayan - Lobby - rooftop lotus pond arrival at sunrise.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Lobby", "description": "The resort arrival unfolds across an elliptical rooftop lotus pond that mirrors the rice bowl form of the main building, its still water planted with lily pads and lotus and edged in a burnished metal rim. A timber deck platform carries a simple bench and a thatched bale pavilion, lit by sculptural white globe lamp posts on slender curved stems. Recreating the look means treating water as the primary surface material, keeping furniture minimal and low, and letting the curved pond edge, warm timber decking and layered jungle canopy supply all the ornament. It is architecture as landscape, serene and theatrical at once.", "src": "images/Four Seasons Resort Bali at Sayan/0184 - Four Seasons Resort Bali at Sayan - Lobby - rooftop lotus pond arrival at sunrise.jpg", "source": "https://www.fourseasons.com/sayan/photos-and-videos/", "dimensions": "2000x1500", "size": 1737292}, {"number": "0185", "file": "0185 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - bedroom with carved floral screen wall and terrace doors.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A king bedroom backed by a full height wall of dark stained teak screen panels, each pierced and carved with dense floral relief that filters light like a textile. Crisp white bedding is paired with a pale upholstered bench at the foot, low timber nightstands and slender cylindrical pendant lights in place of table lamps. Louvered teak doors open to a furnished terrace with daybed and chairs over the valley. To recreate it, anchor the room with one carved timber feature wall, keep every other surface quiet, and repeat the dark teak in floors, doors and ceiling fan.", "src": "images/Four Seasons Resort Bali at Sayan/0185 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - bedroom with carved floral screen wall and terrace doors.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1011866}, {"number": "0186", "file": "0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A detail study of the suite headboard wall, where framed teak panels carved with scrolling foliage run floor to ceiling behind the bed, their openwork backed so the pattern reads as shadow and texture. A single fabric shaded cylindrical pendant drops beside the pillow, and the low nightstand is woven cane fronted timber. In a wall niche sits a small stone guardian statue, spotlit like gallery art, while a pale lounge chair with a patterned cushion waits in the corner. The lesson for recreation is layering: carved wood, woven cane, stone sculpture and plain linen in one restrained palette.", "src": "images/Four Seasons Resort Bali at Sayan/0186 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - carved screen headboard wall detail with bedside pendant.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 885109}, {"number": "0187", "file": "0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "The upper living level of the duplex suite pairs a pale grey sofa with low woven rattan armchairs and a green upholstered bench, arranged around the stair rail so the seating group floats above the floor below. A tall floor lamp with a stacked, textured column base and drum shade anchors one corner, and louvered teak shutters frame floor to ceiling windows over the river valley. Beyond glazed doors a dining nook repeats the palette. Recreating it requires furniture kept low and leggy, natural fibre upholstery, dark timber trim throughout, and pattern confined to a few cushions and the woven chair backs.", "src": "images/Four Seasons Resort Bali at Sayan/0187 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - mezzanine living room with woven armchairs and valley windows.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 963596}, {"number": "0188", "file": "0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A corner reading nook wrapped in teak louvered shutters and tall windows, furnished with a pale sofa dressed in oversized green floral cushions and a round swivel chair in bent rattan with floral upholstery. A small dark timber side table carries a sculptural lamp and a vase of white flowers, and the polished timber floor is left bare to show its grain. The design move to copy is the shuttered window wall itself: adjustable louvres replace curtains, controlling light and privacy while adding strong vertical rhythm, and one bold floral textile repeated on chair and cushions ties the whole corner together.", "src": "images/Four Seasons Resort Bali at Sayan/0188 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - window reading corner with louvered shutters and rattan chair.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1056774}, {"number": "0189", "file": "0189 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - sun terrace with woven lounge chair and carved timber table.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "The private sun terrace is paved in pale stone and furnished sparely: a woven lounge chair with thick cream and olive cushions, and a round side table whose solid teak pedestal is carved with vertical fluting, topped with a small offering tray. Slender palms and dense tropical planting form the walls of the room, and the suite glazing in dark timber frames one side. For recreation, the formula is one sculptural timber table, one generously cushioned woven chair, pale stone underfoot, and planting used as architecture. Nothing else is needed, and the restraint is the luxury.", "src": "images/Four Seasons Resort Bali at Sayan/0189 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - sun terrace with woven lounge chair and carved timber table.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1205720}, {"number": "0190", "file": "0190 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - bathroom with green patterned tiles and carved vanity.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Premier Duplex Suite", "description": "A bathroom built around a deep green patterned tile wall in the shower, its geometric motif recalling woven songket cloth, set against a carved dark timber vanity console with black stone vessel basins and brass fittings. Glass pendant lanterns hang before tall mirrors, and a freestanding oval tub sits in a window bay screened by teak louvres, with marble flooring striped in dark stone. To recreate the look, commit to one saturated patterned tile as the single colour statement, then layer carved timber, black stone and aged brass, keeping towels and accessories strictly neutral.", "src": "images/Four Seasons Resort Bali at Sayan/0190 - Four Seasons Resort Bali at Sayan - Premier Duplex Suite - bathroom with green patterned tiles and carved vanity.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/riverside-suites/", "dimensions": "2560x1920", "size": 1144020}, {"number": "0191", "file": "0191 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to plunge pool deck with canopy daybed.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "One-Bedroom Villa", "description": "The classic villa bedroom in teak and cream: a dressed bed in the foreground, a writing desk whose front is inlaid with shimmering shell and stone mosaic, and framed textile art above it. Louvered teak screens and full height sliding doors open the whole wall to a timber deck with a private plunge pool and a canopied daybed, so the room reads as one indoor outdoor pavilion. A ceiling fan, sheer canopy curtain and warm timber floorboards complete the scheme. Recreation notes: use shell mosaic as a single accent surface, match desk, doors and screens in one teak tone, and keep bedding plain white with mauve cushions.", "src": "images/Four Seasons Resort Bali at Sayan/0191 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to plunge pool deck with canopy daybed.jpg", "source": "https://www.fourseasons.com/sayan/photos-and-videos/", "dimensions": "2560x1465", "size": 853475}, {"number": "0192", "file": "0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "One-Bedroom Villa", "description": "A second angle on the villa bedroom showing its full indoor outdoor plan: bed with plum cushions and a woven bench, a stone deity statue set into a lit wall niche, framed Balinese artwork, and a low carved cabinet beneath it. Teak folding louvered doors open to a covered terrace set with a dining table and timber chairs above the valley, while a separate desk sits by shuttered windows. The palette is cream plaster, warm teak and deep plum accents. To copy it, treat the niche statue and artwork as the room art programme and let one accent colour carry cushions and upholstery.", "src": "images/Four Seasons Resort Bali at Sayan/0192 - Four Seasons Resort Bali at Sayan - One-Bedroom Villa - bedroom opening to terrace dining with statue niche.jpg", "source": "https://www.fourseasons.com/sayan/photos-and-videos/", "dimensions": "2560x1568", "size": 893384}, {"number": "0193", "file": "0193 - Four Seasons Resort Bali at Sayan - Ayung Terrace - dining room with grey curved chairs and marble topped tables.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Ayung Terrace", "description": "The restyled Ayung Terrace dining room curves along the valley edge under a dark timber coffered ceiling hung with ceiling fans, its round columns wrapped in pale plaster. Plush grey curved lounge chairs and grey upholstered dining chairs gather around round marble topped tables on timber pedestal bases, exactly the new scheme the resort describes. Tall black ribbed ceramic vases punctuate the banquettes, and the open side frames palms and jungle. Recreating it means committing to the curve: crescent seating, round tables, a coffered dark ceiling overhead, and a strict palette of grey upholstery, pale stone and black accents.", "src": "images/Four Seasons Resort Bali at Sayan/0193 - Four Seasons Resort Bali at Sayan - Ayung Terrace - dining room with grey curved chairs and marble topped tables.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/bali_at_sayan_renova/", "dimensions": "2560x1708", "size": 1029141}, {"number": "0194", "file": "0194 - Four Seasons Resort Bali at Sayan - Ayung Terrace - curved treetop deck with banquette seating.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Ayung Terrace", "description": "On the Ayung Terrace deck, a sweeping curve of teak decking follows the gorge, edged by a timber balustrade and shaded by the coffered soffit of the restaurant roof. Set dining tables pair woven back and timber framed chairs with a continuous cushioned banquette in grey, dressed with patterned throw cushions. The furniture is deliberately lightweight in profile so the palm canopy and river valley stay dominant. For recreation, build the terrace as one long curve, repeat a single chair model throughout, keep table settings minimal, and use banquette cushions in one muted tone with pattern only on the scatter cushions.", "src": "images/Four Seasons Resort Bali at Sayan/0194 - Four Seasons Resort Bali at Sayan - Ayung Terrace - curved treetop deck with banquette seating.jpg", "source": "https://press.fourseasons.com/sayan/hotel-news/2026/bali_at_sayan_renova/", "dimensions": "2560x1708", "size": 1155590}, {"number": "0195", "file": "0195 - Four Seasons Resort Bali at Sayan - Ayung Terrace - terrace tables with orchids and valley view.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Ayung Terrace", "description": "An earlier styling of the Ayung Terrace in daylight, with tables dressed in white cloths and high back dining chairs upholstered in a pale patterned fabric with dark timber arms. A large potted white phalaenopsis orchid serves as the room centrepiece on a stone plinth, glassware is kept crystal clear and minimal, and a server in Balinese dress carries a tray along the railing above the misty valley. The design lesson is the contrast: formal white linen and patterned upholstery against raw jungle. It shows how the same terrace takes a more classical, ceremonial register with textiles alone.", "src": "images/Four Seasons Resort Bali at Sayan/0195 - Four Seasons Resort Bali at Sayan - Ayung Terrace - terrace tables with orchids and valley view.jpg", "source": "https://baliexpertguide.com/four-seasons-resort-bali-at-sayan-a-sacred-sanctuary-in-the-heart-of-ubud/", "dimensions": "2560x1706", "size": 658993}, {"number": "0196", "file": "0196 - Four Seasons Resort Bali at Sayan - Sacred River Spa - spa pavilions across lily pond with island daybeds.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "The Sacred River Spa is arranged as thatched pavilions across a lily pond, reached by a timber boardwalk, with circular stone platforms floating in the water as islands for mint green daybed sofas and low round tables. River stones edge the pond, and the pavilion interiors glow behind glass with lamps and lounge seating. Dense jungle planting encloses the whole composition. To recreate the feel, build outdoor rooms as islands in shallow water, use alang alang thatch over dark timber posts, keep outdoor upholstery in one pale green, and let rough river stone and smooth cut stone play against each other.", "src": "images/Four Seasons Resort Bali at Sayan/0196 - Four Seasons Resort Bali at Sayan - Sacred River Spa - spa pavilions across lily pond with island daybeds.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1534496}, {"number": "0197", "file": "0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "Inside the spa relaxation lounge, barrel back lounge chairs upholstered in blue grey patterned fabric face each other across small sculptural black side tables, under a pitched ceiling of bamboo and dark rafters. One wall is screened with vertical bamboo poles of varied tone, another is a long honed timber counter with orchids and ceramics, and the floor is large format grey stone tile. A therapist kneels in a tea service ritual at the centre. Recreation notes: pattern belongs on the chair fabric alone, structure stays dark timber and bamboo, and fresh orchids plus handmade ceramics provide the only decoration needed.", "src": "images/Four Seasons Resort Bali at Sayan/0197 - Four Seasons Resort Bali at Sayan - Sacred River Spa - relaxation lounge with patterned chairs and bamboo screens.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1217560}, {"number": "0198", "file": "0198 - Four Seasons Resort Bali at Sayan - Sacred River Spa - treatment villa with twin beds and bamboo blinds.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "A spa treatment villa set up for two, with parallel treatment beds dressed in sage green covers and folded stone trays of treatment stones, beneath a high pitched bamboo ceiling. Woven bamboo roller blinds screen the glazed walls, filtering jungle light to a soft glow, while rattan chairs wait on the terrace beyond the open doors. A carved mirror frame, potted orchids and a floor lamp with a woven shade add the decorative layer. To copy the room, match bed linens to the surrounding foliage greens, use bamboo in three forms, blinds, ceiling and screens, and keep all furniture low and horizontal.", "src": "images/Four Seasons Resort Bali at Sayan/0198 - Four Seasons Resort Bali at Sayan - Sacred River Spa - treatment villa with twin beds and bamboo blinds.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1236495}, {"number": "0199", "file": "0199 - Four Seasons Resort Bali at Sayan - Sacred River Spa - outdoor bathing pavilion with stone tub and rain showers.jpg", "resort": "Four Seasons Resort Bali at Sayan", "space": "Sacred River Spa", "description": "The spa outdoor bathing pavilion centres on a monumental hand chiselled Indonesian stone tub filled with water and floating lotus, flanked by two curved timber shower tables beneath arcing multi jet rain shower fixtures in brushed metal. Flagstone paving, banana leaves and a carved stone relief wall with inscribed panels form the enclosure, so bathing reads as a temple ritual. Guests recline on the shower tables during the treatment, but the design subject is the stonework. Recreation requires real weight: one carved stone vessel, honest flagstones, oversized modern shower hardware, and tropical planting at architectural scale.", "src": "images/Four Seasons Resort Bali at Sayan/0199 - Four Seasons Resort Bali at Sayan - Sacred River Spa - outdoor bathing pavilion with stone tub and rain showers.jpg", "source": "https://press.fourseasons.com/content/fourseasons_pressroom/printView.html?pageToPrint=%2Fcontent%2Ffourseasons_pressroom%2Fen%2Fnews%2Fsayan%2F2024%2Fsacred_river_spa_rel", "dimensions": "2560x1707", "size": 1085751}, {"number": "0200", "file": "0200 - Alila Villas Uluwatu - One-Bedroom Pool Villa - private pool courtyard facing open living pavilion.jpg", "resort": "Alila Villas Uluwatu", "space": "One-Bedroom Pool Villa", "description": "Viewed across its private plunge pool, the villa reads as a garden room rather than a sealed box. A deep overhanging flat roof with a lava stone edge shades a fully open living pavilion, its built in daybed dressed with taupe cushions and rust patterned batik pillows. Walls are pale Palimanan limestone block, contrasted with a slatted dark timber screen wall in offset horizontal bands. To the left, glass reveals the stone bathroom with a freestanding tub. Frangipani trees, clipped green planting and pale stone decking soften the geometry, while blue mosaic pool tiles supply the only strong colour.", "src": "images/Alila Villas Uluwatu/0200 - Alila Villas Uluwatu - One-Bedroom Pool Villa - private pool courtyard facing open living pavilion.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 834657}, {"number": "0201", "file": "0201 - Alila Villas Uluwatu - One-Bedroom Pool Villa - bedroom with rattan panelled media wall.jpg", "resort": "Alila Villas Uluwatu", "space": "One-Bedroom Pool Villa", "description": "The bedroom pairs a low platform king bed in crisp white linen with a full height dark timber media and storage wall, its sliding doors faced in fine woven rattan and topped with a louvred ventilation band. A sculptural black pedestal table with a ribbed conical base anchors two mid century style armchairs in taupe leather and dark wood. Pale limestone walls, large format cream floor tiles and a ribbed bamboo ceiling keep the room light, while full height glazing behind the bed opens the sleeping area to a planted courtyard wall.", "src": "images/Alila Villas Uluwatu/0201 - Alila Villas Uluwatu - One-Bedroom Pool Villa - bedroom with rattan panelled media wall.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 499618}, {"number": "0202", "file": "0202 - Alila Villas Uluwatu - One-Bedroom Pool Villa - living space opening to pool and cabana.jpg", "resort": "Alila Villas Uluwatu", "space": "One-Bedroom Pool Villa", "description": "From the villa living area, sliding glass walls retract completely so the room, pool and private cabana read as one pavilion sequence. A built in taupe daybed with a cylindrical bolster runs along the stone pier, lit by a black framed table lamp with a ribbed cylindrical shade. In the foreground, a dark timber armchair and round black pedestal table are set with a black iron teapot and cups beside a white orchid. Beyond the narrow pool, the cabana repeats the resort language of horizontal timber slats and turned bamboo uprights, framing frangipani trees and the sea.", "src": "images/Alila Villas Uluwatu/0202 - Alila Villas Uluwatu - One-Bedroom Pool Villa - living space opening to pool and cabana.jpg", "source": "https://bawa.de/accommodations/alila-uluwatu/", "dimensions": "1800x1200", "size": 1465566}, {"number": "0203", "file": "0203 - Alila Villas Uluwatu - One-Bedroom Pool Villa - window daybed and stone bathroom view.jpg", "resort": "Alila Villas Uluwatu", "space": "One-Bedroom Pool Villa", "description": "Shot from the living end, this reverse view shows the villa planning clearly: a window daybed with bolster and gold brown ikat cushions is built into the glass wall, the dark rattan faced media cabinet stands as a freestanding divider, and the open bathroom beyond has a floating stone vanity, backlit mirror and dark timber paneling. Two splayed leg armchairs in taupe upholstery sit at the round black pedestal table. The ribbed bamboo ceiling, pale stone tiles and cream limestone walls create the calm neutral ground against which the dark wood furniture reads almost as sculpture.", "src": "images/Alila Villas Uluwatu/0203 - Alila Villas Uluwatu - One-Bedroom Pool Villa - window daybed and stone bathroom view.jpg", "source": "https://suitesmile.com/blog/2021/08/19/review-alila-villas-uluwatu-1-bedroom-pool-villa/", "dimensions": "1500x1000", "size": 165382}, {"number": "0204", "file": "0204 - Alila Villas Uluwatu - Three-Bedroom Cliff Edge Villa - infinity pool deck with loungers and cabana.jpg", "resort": "Alila Villas Uluwatu", "space": "Three-Bedroom Cliff Edge Villa", "description": "The cliff edge villa terrace is arranged as a single calm plane of pale stone running from the glass living pavilion to the infinity pool edge. Four low taupe sun loungers with rolled white towels line the water, and at the far end the signature private cabana stands as a cube of horizontal dark timber slats and turned bamboo spindles, its daybeds shaded from the low sun. A recessed strip of black lava rock, manicured lawn and frangipani trees mediate between architecture and cliff vegetation, and the flat lava stone roof edge keeps every line emphatically horizontal.", "src": "images/Alila Villas Uluwatu/0204 - Alila Villas Uluwatu - Three-Bedroom Cliff Edge Villa - infinity pool deck with loungers and cabana.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1440", "size": 630638}, {"number": "0205", "file": "0205 - Alila Villas Uluwatu - Three-Bedroom Cliff Edge Villa - courtyard lounge deck with reflection pond.jpg", "resort": "Alila Villas Uluwatu", "space": "Three-Bedroom Cliff Edge Villa", "description": "An internal courtyard deck in weathered grey timber planks is furnished as an outdoor living room, with two long low taupe sofas, patterned gold cushions and small black pedestal tables facing each other across the boards. A still black reflection pond edges the deck in the foreground. Around it, cream walls carry the resort signature ribbed stone relief panels beside near black timber doors, and slim black columns support deep flat overhangs with open skylight slots above the deck, so sun and breeze reach the seating while the perimeter stays shaded and private.", "src": "images/Alila Villas Uluwatu/0205 - Alila Villas Uluwatu - Three-Bedroom Cliff Edge Villa - courtyard lounge deck with reflection pond.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 514947}, {"number": "0206", "file": "0206 - Alila Villas Uluwatu - CIRE - terrace dining with rattan chairs and lime cushions.jpg", "resort": "Alila Villas Uluwatu", "space": "CIRE", "description": "CIRE dining spills onto an open terrace under a flat white canopy on slim black steel columns. Square marble topped tables on dark timber A frame bases are paired with round pedestal tables, and the chairs are a resort signature: woven dark rattan backs and arms on teak legs, with chartreuse green back cushions and oatmeal seat pads. Green glass tumblers and earthenware plates dress each table. At the right edge, a large driftwood root sculpture is mounted as wall art, and beyond the lawn the slatted timber cabana and a small Balinese shrine frame the ocean view.", "src": "images/Alila Villas Uluwatu/0206 - Alila Villas Uluwatu - CIRE - terrace dining with rattan chairs and lime cushions.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 908286}, {"number": "0207", "file": "0207 - Alila Villas Uluwatu - CIRE - batik stamp wall detail.jpg", "resort": "Alila Villas Uluwatu", "space": "CIRE", "description": "A full wall of antique copper batik stamps, the tjap used to hot wax cloth, is gridded in blackened metal frames as the defining artwork of CIRE, whose name refers to the waxing and polishing process. Each square holds a different hand cut pattern, florals, geometry and figurative motifs in warm bronze and brass tones that glow under raking light. For a designer, the lesson is in the repetition: hundreds of small crafted objects become one architectural surface, marrying Indonesian textile heritage to a stark modern dining room without a single framed picture. [below 1200px - best available]", "src": "images/Alila Villas Uluwatu/0207 - Alila Villas Uluwatu - CIRE - batik stamp wall detail.jpg", "source": "https://www.archdaily.com/59740/alila-villas-uluwatu-woha", "dimensions": "887x585", "size": 475075}, {"number": "0208", "file": "0208 - Alila Villas Uluwatu - The Warung - ocean facing terrace dining with marble tables.jpg", "resort": "Alila Villas Uluwatu", "space": "The Warung", "description": "The Warung terrace looks straight to the ocean through slim black columns, its marble topped tables set with green glass tumblers, stoneware plates and batik patterned napkins. The same woven rattan and teak chairs used across the resort dining rooms appear here with lime green cushions, tying the Indonesian restaurant to the wider design language. To the left, the slatted timber screen wall of the adjacent cabana filters light into horizontal stripes. Pale stone paving, a strip of lawn and dense green planting form a deliberately simple foreground, keeping attention on horizon, table and craft detail.", "src": "images/Alila Villas Uluwatu/0208 - Alila Villas Uluwatu - The Warung - ocean facing terrace dining with marble tables.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 701882}, {"number": "0209", "file": "0209 - Alila Villas Uluwatu - The Warung - communal table and open kitchen with timber screens.jpg", "resort": "Alila Villas Uluwatu", "space": "The Warung", "description": "Inside The Warung, a single massive live edge communal table runs in front of the open kitchen, flanked by benches and woven rattan chairs with pale cushions, exactly the convivial arrangement the restaurant is known for. Above and around it, walls of mosaic screens are built from thousands of small recycled timber blocks in honey, bronze and charcoal, dappling the polished stone floor with patterned sunlight. A long black linear pendant hangs over the table, ceramic bowls and produce are displayed on open kitchen shelving, and two chefs at work give the otherwise architectural space its working, hospitable scale. [below 1200px - best available]", "src": "images/Alila Villas Uluwatu/0209 - Alila Villas Uluwatu - The Warung - communal table and open kitchen with timber screens.jpg", "source": "https://www.archdaily.com/59740/alila-villas-uluwatu-woha", "dimensions": "817x1100", "size": 394447}, {"number": "0210", "file": "0210 - Alila Villas Uluwatu - Sunset Cabana Bar - slatted lounge interior with batik cushions.jpg", "resort": "Alila Villas Uluwatu", "space": "Sunset Cabana Bar", "description": "Inside the cliff edge Sunset Cabana, everything is built from one kit of parts: horizontal recycled timber slats and turned bamboo spindles form the walls and ceiling grid, throwing striped shadows across the weathered deck boards. Low modular sofas in warm taupe canvas are grouped around stump like petrified wood side tables, each holding a white orchid, and the only colour comes from gold and rust batik cushions. A server crosses with a tray, giving scale to the cliff drop beyond the screen. The effect is luxurious shade and breeze, not enclosure, with the ocean as the fourth wall.", "src": "images/Alila Villas Uluwatu/0210 - Alila Villas Uluwatu - Sunset Cabana Bar - slatted lounge interior with batik cushions.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 701793}, {"number": "0211", "file": "0211 - Alila Villas Uluwatu - Sunset Cabana Bar - lounge at dusk with candle lanterns.jpg", "resort": "Alila Villas Uluwatu", "space": "Sunset Cabana Bar", "description": "At dusk the Sunset Cabana changes character without changing a single piece of furniture. The same low taupe modular sofas and petrified wood stump tables now carry glass hurricane lanterns with candles, recessed spots in the slatted timber ceiling pick out each seating group, and the bamboo spindle screens turn deep blue against the afterglow over the ocean. Bolster cushions and patterned throw pillows in earth tones soften the boxy upholstery. For recreation, note the layering: the daylight design is all slat, shadow and view, while evening atmosphere is added purely through low warm light points at table height.", "src": "images/Alila Villas Uluwatu/0211 - Alila Villas Uluwatu - Sunset Cabana Bar - lounge at dusk with candle lanterns.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 539709}, {"number": "0212", "file": "0212 - Alila Villas Uluwatu - Lobby - lounge interior with ribbed stone walls.jpg", "resort": "Alila Villas Uluwatu", "space": "Lobby", "description": "The lobby pavilion is a long gallery like lounge, one side a full height glass wall over a black reflection pond and gardens, the other clad in vertically ribbed pale stone relief panels with inset bands of dark stacked slate. Low taupe sofas with ikat patterned cushions face paired black slatted timber coffee tables, one inset with a games board, on a woven bamboo runner. At the far end a book lined library wall sits under a rattan louvre, and a slim desk serves guests beside splayed leg timber armchairs. Twin tracks of ceiling spotlights keep the space evenly and quietly lit.", "src": "images/Alila Villas Uluwatu/0212 - Alila Villas Uluwatu - Lobby - lounge interior with ribbed stone walls.jpg", "source": "https://www.travelplatinum.nl/indonesie/bali/alila-villas-uluwatu-bali", "dimensions": "2560x1536", "size": 806053}, {"number": "0213", "file": "0213 - Alila Villas Uluwatu - Lobby - open pavilion overlooking main pool.jpg", "resort": "Alila Villas Uluwatu", "space": "Lobby", "description": "From within the shaded lobby pavilion, dark timber armchairs with taupe cushions face out across mirror still reflection ponds to the 50 metre main pool and the ocean horizon. Low black counters flank the seating, tall palms punctuate the axis, and the flanking pavilions repeat the resort vocabulary of white ribbed stone walls, dark slate panels and slatted timber cabana cubes. The design move to copy is restraint: a symmetrical water axis, a limited palette of black, white and taupe, and furniture kept low so nothing interrupts the horizontal line where pool meets sea. [below 1200px - best available]", "src": "images/Alila Villas Uluwatu/0213 - Alila Villas Uluwatu - Lobby - open pavilion overlooking main pool.jpg", "source": "https://www.archdaily.com/59740/alila-villas-uluwatu-woha", "dimensions": "1100x446", "size": 262433}, {"number": "0214", "file": "0214 - Alila Villas Uluwatu - Cliff Edge Spa Cabana - treatment pavilion with ocean view.jpg", "resort": "Alila Villas Uluwatu", "space": "Cliff Edge Spa Cabana", "description": "The Cliff Edge Spa Cabana is a small open pavilion hung on the cliff face, furnished simply with two massage beds dressed in white linen with woven brown and grey runner throws and face cradle covers. A low taupe sofa with sage cushions, a robe on a stand, a ceramic stool and a dark bladed ceiling fan complete the room, and slatted timber balustrades keep the ocean view open while screening the drop. Spa photography for this resort is scarce at high resolution, and this verified view is the best available. [below 1200px - best available]", "src": "images/Alila Villas Uluwatu/0214 - Alila Villas Uluwatu - Cliff Edge Spa Cabana - treatment pavilion with ocean view.jpg", "source": "https://www.forbestravelguide.com/hotels/bali-indonesia/alila-villas-uluwatu", "dimensions": "760x425", "size": 144627}, {"number": "0215", "file": "0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "resort": "The Datai Langkawi", "space": "Canopy Suite", "description": "Open plan living and dining room in the main building, defined by a continuous slatted timber cornice at ceiling level. Curved barrel armchairs in cream fabric with dark timber side panels face grey sofas dressed with mustard yellow, charcoal and black and white patterned cushions. Two low black oval coffee tables carry glass hurricane candles, and a tall dark timber minibar cabinet with folding doors and warm internal lighting stands on legs against the wall. Beyond, an oval timber dining table with cream upholstered chairs sits under a large pleated white pendant, with torch style floor lamps, mirrored panelling and polished timber floors.", "src": "images/The Datai Langkawi/0215 - The Datai Langkawi - Canopy Suite - living and dining room with slatted timber cornice.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/canopy-suite/", "dimensions": "2448x1633", "size": 496682}, {"number": "0216", "file": "0216 - The Datai Langkawi - Canopy Suite - bedroom with timber plank headboard wall.jpg", "resort": "The Datai Langkawi", "space": "Canopy Suite", "description": "Bedroom centred on a full height headboard wall of horizontal timber planks with darker rails and round brass studs, lit by a concealed strip above. The king bed is dressed plainly in white Egyptian cotton with a small monogrammed cushion and a black swing arm reading lamp. A tall torch style sconce with a flared cream shade is mounted on a mirrored panel beside the bed, a signature fitting repeated through the resort. Open double doors frame the living and dining area beyond, with its patterned rug, black oval table and timber framed glass doors to the rainforest facing veranda.", "src": "images/The Datai Langkawi/0216 - The Datai Langkawi - Canopy Suite - bedroom with timber plank headboard wall.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/canopy-suite/", "dimensions": "2447x1633", "size": 373762}, {"number": "0217", "file": "0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "resort": "The Datai Langkawi", "space": "The Datai Suite", "description": "Dining and living space divided by round dark timber columns under a coffered timber ceiling panel with cove lighting. Six dining chairs with tightly woven basketweave backs, cream seat pads and loose white cushions surround a round polished timber table with a raised fruit compote. On the white wall hangs a large circular sunburst disc in dark patinated metal, spotlit from above. A timber desk with an orchid and a black ceramic urn separates the dining area from a grey sofa lounge with a low timber coffee table. Torch style floor lamps, textured grey rugs and dark timber floors hold the calm, earthy palette together.", "src": "images/The Datai Langkawi/0217 - The Datai Langkawi - The Datai Suite - dining room with woven chairs and sunburst wall disc.jpg", "source": "https://www.thedatai.com/accommodation/the-canopy-collection/the-datai-suite/", "dimensions": "2448x1633", "size": 511984}, {"number": "0218", "file": "0218 - The Datai Langkawi - Rainforest Villa - bedroom with draped canopy bed and window daybed.jpg", "resort": "The Datai Langkawi", "space": "Rainforest Villa", "description": "Villa bedroom under a high pitched ceiling of exposed timber boards and rafters. The king bed sits inside a four post canopy frame hung with sheer white curtains and lit by a white paper lantern pendant. Along the louvred windows runs a long daybed with bolster ends and cushions in mustard, deep green, charcoal and patterned neutrals, flanked by torch style floor lamps. Two cream barrel armchairs with dark side panels face a black oval coffee table on a blue grey patterned rug. Slatted timber screens, a writing desk and polished timber floors complete a room designed to open to the surrounding rainforest.", "src": "images/The Datai Langkawi/0218 - The Datai Langkawi - Rainforest Villa - bedroom with draped canopy bed and window daybed.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 730450}, {"number": "0219", "file": "0219 - The Datai Langkawi - Rainforest Villa - bathroom with twin vanities and central soaking tub.jpg", "resort": "The Datai Langkawi", "space": "Rainforest Villa", "description": "Symmetrical bathroom in warm timber, viewed from the doorway. Two long floating vanities in white stone with dark frames and open towel shelves face each other across a pale marble floor, each with a tall mirror, a suspended linear light and chrome fittings. Between them, on the room axis, stands a sculptural white soaking tub with a flared rim beneath a wide window of timber louvres filtering the rainforest greenery. A tan leather bench sits in front of the tub. Horizontal timber plank walls with brass studs, a pitched boarded ceiling, orchids and candle hurricanes give the space a crafted, lodge like quality.", "src": "images/The Datai Langkawi/0219 - The Datai Langkawi - Rainforest Villa - bathroom with twin vanities and central soaking tub.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1709", "size": 638970}, {"number": "0220", "file": "0220 - The Datai Langkawi - Rainforest Pool Villa - timber pool deck with loungers and rope railing.jpg", "resort": "The Datai Langkawi", "space": "Rainforest Pool Villa", "description": "Private pool deck deep in the rainforest, built in warm timber planks around existing trees that rise straight through the deck. A rectangular plunge pool with a dark stone surround and steel handrail occupies one side. On the other, two timber armchairs with pale cushions and woven side panels face a round dark table, with cushioned sun loungers and rolled blue towels behind. The deck edge is fenced with thick rope strung between timber posts, a deliberately rustic detail. Dappled sunlight, dense green planting and the stream below the deck make the furnishings feel like a clearing in the jungle rather than a terrace.", "src": "images/The Datai Langkawi/0220 - The Datai Langkawi - Rainforest Pool Villa - timber pool deck with loungers and rope railing.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1709", "size": 1356615}, {"number": "0221", "file": "0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "resort": "The Datai Langkawi", "space": "One-Bedroom Beach Villa", "description": "Open sided living pavilion with a high pitched raftered timber ceiling and full height glass doors. In the foreground, a massive single slab timber coffee table on black block legs holds black and gold ceramic vessels and a book, over a grey rug with a raised organic pattern. Cane backed armchairs with deep cream cushions group around it, and a timber dining table with matching woven cane chairs stands by the glass wall. Beyond the sliding doors, sun loungers and an umbrella sit beside the private pool against a wall of rough grey rubble stone, the resort signature boundary treatment.", "src": "images/The Datai Langkawi/0221 - The Datai Langkawi - One-Bedroom Beach Villa - living pavilion opening to courtyard pool.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1361931}, {"number": "0222", "file": "0222 - The Datai Langkawi - One-Bedroom Beach Villa - bedroom with woven lattice ceiling and textile art.jpg", "resort": "The Datai Langkawi", "space": "One-Bedroom Beach Villa", "description": "Bedroom that opens directly to the private pool along one side. The ceiling is a woven timber lattice in a grid pattern, and the walls are lined with woven grasscloth panels and carved lattice screens. The low platform bed in crisp white linen faces a framed antique ikat textile in gold, rust and black hung on the grasscloth wall, with a carved timber artefact displayed on a shelf nearby. Black floating nightstands carry a clock and telephone, lit by tall rectangular box sconces with warm shades. A cream upholstered bench sits at the foot of the bed, over a grey patterned rug and dark timber floors.", "src": "images/The Datai Langkawi/0222 - The Datai Langkawi - One-Bedroom Beach Villa - bedroom with woven lattice ceiling and textile art.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1709", "size": 1059691}, {"number": "0223", "file": "0223 - The Datai Langkawi - One-Bedroom Beach Villa - bathroom with stone walls and egg shaped tub.jpg", "resort": "The Datai Langkawi", "space": "One-Bedroom Beach Villa", "description": "Monumental bathroom lined floor to ceiling in horizontally striated grey stone. At its centre sits a smooth egg shaped freestanding tub in pale stone on the polished black floor, with a timber tray trolley of candles and amenities beside it and rolled towels on a black pedestal stand. Two solid stone pedestal vanities with integrated basins stand under tall mirrors beside the garden facing glass, lit by a vertical lantern sconce and a white orchid. Exposed timber rafters cross the woven ceiling panel above, and at the far end a glass door opens to a planted outdoor shower court enclosed by a timber fence.", "src": "images/The Datai Langkawi/0223 - The Datai Langkawi - One-Bedroom Beach Villa - bathroom with stone walls and egg shaped tub.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1709", "size": 1129522}, {"number": "0224", "file": "0224 - The Datai Langkawi - The Datai Estate Villa - Meranti master bedroom with sitting area.jpg", "resort": "The Datai Langkawi", "space": "The Datai Estate Villa", "description": "Vast master bedroom in the Meranti house of the estate villa, under a soaring pitched roof of exposed timber trusses and boarded ceilings with ceiling fans. The king bed is framed by a canopy with gathered sheer white curtains tied with dark rosettes and a woven pendant above the pillows. In front, a sitting area of two dark barrel armchairs and a cream sofa with red and black patterned cushions groups around a black oval coffee table on a cream and olive wave patterned rug, lit by angled floor lamps with rectangular shades. The bathroom, with its own freestanding tub, is visible through the opening beyond.", "src": "images/The Datai Langkawi/0224 - The Datai Langkawi - The Datai Estate Villa - Meranti master bedroom with sitting area.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2491x1605", "size": 590023}, {"number": "0225", "file": "0225 - The Datai Langkawi - The Datai Estate Villa - Seraya dining room with woven pendant lights.jpg", "resort": "The Datai Langkawi", "space": "The Datai Estate Villa", "description": "Dining room in the Seraya house under a steep pitched timber roof. Three oversized cloud like pendants in natural woven fibre hang over a long dark timber dining table with a black and cream patterned runner and curved timber armchairs with pale cushions. Against the far wall, a low timber credenza with cane panelled doors holds books, twin box lantern lamps, orchids and an antique carved chest, flanked by tall carved green panels and a torch style sconce. Glass doors open to a wraparound veranda lounge with wicker seating, so dining, living and rainforest views flow into one continuous timber interior.", "src": "images/The Datai Langkawi/0225 - The Datai Langkawi - The Datai Estate Villa - Seraya dining room with woven pendant lights.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1709", "size": 946256}, {"number": "0226", "file": "0226 - The Datai Langkawi - The Gulai House - kampung house dining room with rattan pendants.jpg", "resort": "The Datai Langkawi", "space": "The Gulai House", "description": "Traditional Malay kampung house dining room built entirely in timber, with vertical plank walls, a woven ceiling and dark plank floors. Rows of woven rattan dome pendants light rustic square timber tables set with white plates, amber glasses and small black ceramic oil lamp centrepieces, surrounded by simple timber chairs with woven seats. Sheer white curtains divide the room into intimate sections, including a raised floor seating area behind an ornately carved screen. Antique cabinets with green painted carved panels display earthenware jars and vessels, and a green carved lattice screen adds the strongest colour accent in an otherwise warm brown palette.", "src": "images/The Datai Langkawi/0226 - The Datai Langkawi - The Gulai House - kampung house dining room with rattan pendants.jpg", "source": "https://www.thedatai.com/dining/the-gulai-house/", "dimensions": "2560x1709", "size": 895822}, {"number": "0227", "file": "0227 - The Datai Langkawi - The Pavilion - open air dining pavilion with globe lanterns and bar.jpg", "resort": "The Datai Langkawi", "space": "The Pavilion", "description": "Open air Thai restaurant pavilion raised on tall angled timber stilts above the rainforest canopy. A dramatic pitched roof of layered timber planes is carried on splayed columns that fan out across the dining floor. Large spherical lanterns with dark ribbed frames hang in rows over square timber tables set with candles, orchids and white napkins, with tan leather sling back dining chairs. At the centre, a long bar glows warmly behind a criss cross timber lattice front with bottle shelving above. The palette is dark timber, tan leather and warm amber light against the deep green of the surrounding forest.", "src": "images/The Datai Langkawi/0227 - The Datai Langkawi - The Pavilion - open air dining pavilion with globe lanterns and bar.jpg", "source": "https://www.thedatai.com/dining/the-pavilion/", "dimensions": "2560x1709", "size": 911259}, {"number": "0228", "file": "0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "resort": "The Datai Langkawi", "space": "The Dining Room", "description": "Terrace seating of the main restaurant under a slatted timber canopy carried on slender angled columns, overlooking the main pool. Square white topped tables on fluted dark timber pedestal bases are set for breakfast with white ceramics and small stone vases of flowers. The chairs are the design focus: curved timber armchairs with wraparound arms and cream upholstered backs and seats, repeated in rows across the pale stone tiles. Cylindrical cream pendants hang from the canopy. Beyond the pool, sun loungers with white umbrellas and a shingled pavilion roof sit against dense rainforest, in a palette of cream, pale stone and warm timber.", "src": "images/The Datai Langkawi/0228 - The Datai Langkawi - The Dining Room - poolside terrace with curved armchairs.jpg", "source": "https://www.thedatai.com/gallery/", "dimensions": "2560x1708", "size": 1025101}, {"number": "0229", "file": "0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "resort": "The Datai Langkawi", "space": "The Lobby Lounge", "description": "Grand open lounge pavilion under a soaring pitched timber roof with exposed rafters, ceiling fans and warm uplighting along the beams. In the foreground, a sunken seating pit of long cream banquettes is dressed with black and white geometric patterned cushions and deep green and ochre accents, grouped around round hammered metal drum tables with candle votives and low cream swivel lounge chairs. To the left, a long black stone bar with patterned seat stools runs towards a raised deck with a grand piano, armchairs and torch style lamps, all facing the open side and its view over the rainforest canopy to the sea.", "src": "images/The Datai Langkawi/0229 - The Datai Langkawi - The Lobby Lounge - lounge pavilion with sunken seating and bar.jpg", "source": "https://www.thedatai.com/dining/the-lobby-lounge/", "dimensions": "2560x1709", "size": 1035139}, {"number": "0230", "file": "0230 - The Datai Langkawi - The Spa - open air treatment villa with flower bath.jpg", "resort": "The Datai Langkawi", "space": "The Spa", "description": "Open air spa treatment villa beside the rainforest stream, under a pitched timber roof with a fringe of palm thatch. In the foreground, a square white soaking bath is filled with water, red petals and green leaves, with a small brass gong and candle holder on its rim. Two timber treatment beds with white linen and rust coloured runners stand beside a timber storage cabinet and a small vanity. On the deck, woven rattan armchairs with slate blue cushions and a matching two seat sofa face a black ribbed drum table, with a woven water bowl and foot bath completing the ritual setting.", "src": "images/The Datai Langkawi/0230 - The Datai Langkawi - The Spa - open air treatment villa with flower bath.jpg", "source": "https://www.thedatai.com/spa-and-well-being/the-spa/", "dimensions": "2560x1704", "size": 1257678}, {"number": "0231", "file": "0231 - Song Saa Private Island - One Bed Overwater Villa - pool terrace daybed under driftwood pergola.jpg", "resort": "Song Saa Private Island", "space": "One Bed Overwater Villa", "description": "The private pool terrace is organised around a deep platform daybed in natural cotton with charcoal cushions, sheltered by a pergola of rough driftwood poles and tangled root wood that casts patterned shade. Silvered bamboo fencing screens the deck from neighbouring villas, while the infinity pool runs flush with the timber boards so the sea reads as a continuation of the pool. A woven seagrass basket, a low painted tea tray table and a pierced metal lantern on a whitewashed trestle stool complete the styling. To recreate it, pair bleached, weathered timber with raw bamboo, keep textiles plain and matte, and let one sculptural piece of driftwood carry the whole composition.", "src": "images/Song Saa Private Island/0231 - Song Saa Private Island - One Bed Overwater Villa - pool terrace daybed under driftwood pergola.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-overwater-villa", "dimensions": "1920x1080", "size": 762281}, {"number": "0232", "file": "0232 - Song Saa Private Island - One Bed Overwater Villa - canopy bedroom with glass floor panel.jpg", "resort": "Song Saa Private Island", "space": "One Bed Overwater Villa", "description": "A soaring thatched roof on dark stained rafters crowns the bedroom, where a four poster bed is draped in sheer white muslin curtains tied back at the posts. In front of the bed, a long low daybed with white cushions doubles as a room divider, and a glass floor panel set into the boards looks straight down to the reef water below. Rubble stone cladding, a large framed monochrome botanical print, oversized metal lanterns and polished dark timber floors ground the pale textiles. Recreate the look with a muslin canopy, one statement stone wall, oversized lanterns at floor level and a strict palette of white, stone and dark wood. [below 1200px - best available]", "src": "images/Song Saa Private Island/0232 - Song Saa Private Island - One Bed Overwater Villa - canopy bedroom with glass floor panel.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-overwater-villa", "dimensions": "596x844", "size": 204176}, {"number": "0233", "file": "0233 - Song Saa Private Island - One Bed Overwater Villa - sunken bathroom with sea view and round mirrors.jpg", "resort": "Song Saa Private Island", "space": "One Bed Overwater Villa", "description": "The bathroom is built around a wide sunken bath in smooth white render, set into a raised platform with vintage style crosshead taps and a slatted timber bath tray. A corner of full height glass and a large open picture window frame the sea, so bathing faces the horizon. Three small circular mirrors in chunky hand carved timber rings hang asymmetrically on the plaster wall, and a whole tree trunk column marks the shower zone. The palette is quiet plaster white, pale stone and warm wood. To copy it, keep fittings minimal, repeat one organic shape, here the rough timber circle, and let the view supply the colour. [below 1200px - best available]", "src": "images/Song Saa Private Island/0233 - Song Saa Private Island - One Bed Overwater Villa - sunken bathroom with sea view and round mirrors.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-overwater-villa", "dimensions": "846x598", "size": 95610}, {"number": "0234", "file": "0234 - Song Saa Private Island - One Bed Overwater Villa - entrance hall with stone pillar and carved lintel.jpg", "resort": "Song Saa Private Island", "space": "One Bed Overwater Villa", "description": "The entrance hall shows the villa material palette in one view: a structural pillar clad in irregular rubble stone, wide plank doors in dark timber, and a doorway framed by a deep, hand carved timber lintel in a scrolling floral pattern drawn from Khmer craft. On the facing wall, a backlit panel of reclaimed boat planks in faded turquoise, teal and rust acts as artwork, proof that salvaged fishing boat timber is used as a decorative finish throughout the resort. Polished dark hardwood floors, a woven thatch ceiling and a simple bronze wall sconce finish the space. Recreate it by mixing one carved antique element with plain modern joinery. [below 1200px - best available]", "src": "images/Song Saa Private Island/0234 - Song Saa Private Island - One Bed Overwater Villa - entrance hall with stone pillar and carved lintel.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-overwater-villa", "dimensions": "846x598", "size": 176586}, {"number": "0235", "file": "0235 - Song Saa Private Island - One Bed Jungle Villa - aerial terrace view with daybed cabana and pool.jpg", "resort": "Song Saa Private Island", "space": "One Bed Jungle Villa", "description": "Seen from above through the rainforest canopy, the Jungle Villa wraps its terrace around mature trees, with a steep thatched roof over glass sliding doors and sheer curtains. A timber framed cabana holds a wide daybed dressed in white with black cushions and a low tray table, beside a small rustic stool carrying a metal lantern. The narrow plunge pool runs along the deck edge in dark mosaic, reflecting the foliage. A single guest sits at the pool edge, small within the frame. The design lesson is restraint: weathered decking, one thatched shelter, plain textiles, and planting allowed to close in until the architecture nearly disappears into the jungle.", "src": "images/Song Saa Private Island/0235 - Song Saa Private Island - One Bed Jungle Villa - aerial terrace view with daybed cabana and pool.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-jungle-villa", "dimensions": "1920x1080", "size": 1006335}, {"number": "0236", "file": "0236 - Song Saa Private Island - One Bed Jungle Villa - bedroom with canopy bed and log pedestal desk.jpg", "resort": "Song Saa Private Island", "space": "One Bed Jungle Villa", "description": "A workspace is built into the foot of the canopy bed: a single thick timber slab desk rests on two solid log pedestals, paired with a scrolled armchair upholstered in white with stud detailing, a black stem table lamp and an oil drum style candle lamp on a stump side table. Behind it, the four poster bed carries knotted muslin drapes. The vaulted ceiling is lined with woven thatch panels between dark rafters, one wall is rubble stone with a framed reclaimed plank panel, and the floors are polished dark hardwood. To recreate it, use furniture with visible mass and grain, log and slab forms, and keep every textile white. [below 1200px - best available]", "src": "images/Song Saa Private Island/0236 - Song Saa Private Island - One Bed Jungle Villa - bedroom with canopy bed and log pedestal desk.jpg", "source": "https://www.songsaa-privateisland.com/villas/one-bed-jungle-villa", "dimensions": "846x598", "size": 203687}, {"number": "0237", "file": "0237 - Song Saa Private Island - Ocean View Villa - beach terrace daybed cabana and mosaic pool.jpg", "resort": "Song Saa Private Island", "space": "Ocean View Villa", "description": "The shoreline terrace layers three places to recline: a raised cabana daybed in white with black cushions under a driftwood and root pergola, a pair of dark timber sun loungers with striped mattresses on the sand, and a tall white parasol on a bamboo pole. Silvered bamboo fencing and a dry stone retaining wall separate the villa from the beach, while the plunge pool is lined in variegated stone mosaic in teal, ochre and slate that mimics the reef shallows. Planting is left loose and tropical. Recreate the effect with bleached fencing, mosaic rather than plain pool tiles, and black, white and natural fibre as the only textile colours.", "src": "images/Song Saa Private Island/0237 - Song Saa Private Island - Ocean View Villa - beach terrace daybed cabana and mosaic pool.jpg", "source": "https://www.songsaa-privateisland.com/villas/ocean-view-villa", "dimensions": "1920x1080", "size": 896511}, {"number": "0238", "file": "0238 - Song Saa Private Island - Ocean View Villa - deck with thatched dining gazebo and daybed.jpg", "resort": "Song Saa Private Island", "space": "Ocean View Villa", "description": "A second terrace view shows the villa outdoor dining arrangement: a small open gazebo with a conical thatched roof on whole trunk posts shelters a rustic table and folding timber chairs at the waters edge, while a shaded daybed piled with charcoal cushions sits under a pergola of twisted driftwood roots. Ferns and palms grow through and around the deck, a woven basket of rolled towels rests on a low stool, and the bleached plank decking runs in long lines toward the sea. The lesson for recreation is to mix one formal thatched shelter with very informal furniture, worn timber, slubby natural fabrics and planting that is never clipped. [below 1200px - best available]", "src": "images/Song Saa Private Island/0238 - Song Saa Private Island - Ocean View Villa - deck with thatched dining gazebo and daybed.jpg", "source": "https://www.songsaa-privateisland.com/villas/ocean-view-villa", "dimensions": "846x598", "size": 296202}, {"number": "0239", "file": "0239 - Song Saa Private Island - Two Bed Jungle Villa - pool deck with round daybed and log table.jpg", "resort": "Song Saa Private Island", "space": "Two Bed Jungle Villa", "description": "The two bedroom villa deck is planned around existing trees, which rise straight through the boardwalk beside the infinity pool. A circular white daybed with pale grey cushions forms the centrepiece, matched by a rustic dining table on log legs with stump stools and a carved timber armchair with a scrolled arm in the foreground. A large terracotta water jar with a wooden dipper sits at the pool edge, a detail borrowed from Cambodian village life, and the thatched roof, bamboo screening and dark framed glazing keep the building recessive. Copy it with round, low, soft furniture against angular decking, and authentic village objects used as working pieces, not ornaments.", "src": "images/Song Saa Private Island/0239 - Song Saa Private Island - Two Bed Jungle Villa - pool deck with round daybed and log table.jpg", "source": "https://www.songsaa-privateisland.com/villas/two-bed-jungle-villa", "dimensions": "1920x1080", "size": 977335}, {"number": "0240", "file": "0240 - Song Saa Private Island - The Royal Villa - living room with slab bench and wood bowl.jpg", "resort": "Song Saa Private Island", "space": "The Royal Villa", "description": "This detail of the Royal Villa living area shows the resort at its most refined: a long live edge timber slab bench on block feet carries a single large turned wooden bowl, and an L shaped white sofa is piled with slate grey cushions. Floor to ceiling glass doors open to the deck, where a bleached driftwood stool with a round stone top stands by a timber table, and sheer linen curtains soften the light. A pierced metal lantern, an orchid planter and dark polished floors complete the scene. To recreate it, invest in one exceptional slab of wood, keep upholstery plain, and use a narrow palette of white, grey, teak and stone.", "src": "images/Song Saa Private Island/0240 - Song Saa Private Island - The Royal Villa - living room with slab bench and wood bowl.jpg", "source": "https://www.songsaa-privateisland.com/villas/the-royal-villa", "dimensions": "1920x1080", "size": 507487}, {"number": "0241", "file": "0241 - Song Saa Private Island - The Royal Villa - open plan kitchen with stone island.jpg", "resort": "Song Saa Private Island", "space": "The Royal Villa", "description": "The Royal Villa open plan living space pairs a contemporary kitchen, flat white cabinetry and a steel extractor, with an island fully clad in rough white rubble stone, a deliberate clash of modern and primitive. Whole tree trunk columns carry the vaulted woven thatch ceiling, and the entertaining level is defined by wide dark floorboards, a petal filled stone bowl, oversized pierced metal floor lanterns and a long planter trough of greenery dividing the seating zone. Wall lights in dark bronze and sheer curtains keep it calm. The transferable idea is contrast: one raw stone mass and raw trunks set against clean lined joinery and appliances. [below 1200px - best available]", "src": "images/Song Saa Private Island/0241 - Song Saa Private Island - The Royal Villa - open plan kitchen with stone island.jpg", "source": "https://www.songsaa-privateisland.com/villas/the-royal-villa", "dimensions": "846x598", "size": 219699}, {"number": "0242", "file": "0242 - Song Saa Private Island - Vista Bar and Restaurant - swinging daybeds with painted wall panels.jpg", "resort": "Song Saa Private Island", "space": "Vista Bar and Restaurant", "description": "Vista signature seating is a row of full size daybeds suspended on chains from the pavilion beams, each dressed in white with natural linen cushions and a round timber tray holding an amber glass candle. Rough whole trunk columns divide the open side, which looks over the water and the jetty, and the back wall carries large abstract paintings in sea green, sand and rust that echo the reclaimed plank panels used in the villas. The ceiling is plain boarded timber. For recreation, the formula is simple: hanging bed swings instead of sofas, one large piece of weathered abstract art per bay, and candlelight in coloured glass rather than bright fittings. [below 1200px - best available]", "src": "images/Song Saa Private Island/0242 - Song Saa Private Island - Vista Bar and Restaurant - swinging daybeds with painted wall panels.jpg", "source": "https://www.songsaa-privateisland.com/dining", "dimensions": "1048x1050", "size": 372523}, {"number": "0243", "file": "0243 - Song Saa Private Island - Vista Bar and Restaurant - overwater dining deck with scrolled chairs.jpg", "resort": "Song Saa Private Island", "space": "Vista Bar and Restaurant", "description": "The Vista dining deck projects over the sea on stout weathered posts, its edge fenced only by a low rail so tables sit directly above the water. Dining chairs are the resort signature piece: a carved timber frame with a scrolled arm and crest, upholstered in white with visible studding, around plain rustic timber tables. Above, a deep thatched roof with fabric blinds rolled at the edge gives shade, and the deck boards and fascia are silvered driftwood tones. In the foreground, grey cushions of the lounge seating soften the geometry. Recreate it with one distinctive chair design repeated throughout, natural thatch overhead and absolutely plain table settings. [below 1200px - best available]", "src": "images/Song Saa Private Island/0243 - Song Saa Private Island - Vista Bar and Restaurant - overwater dining deck with scrolled chairs.jpg", "source": "https://www.songsaa-privateisland.com/dining", "dimensions": "1048x1050", "size": 469940}, {"number": "0244", "file": "0244 - Song Saa Private Island - Driftwood - beach bar pavilion with beanbag loungers.jpg", "resort": "Song Saa Private Island", "space": "Driftwood", "description": "Driftwood, the beach bar, is a thatched pavilion held up by unpeeled tree trunk posts wrapped at the eaves with tangled driftwood, so the structure looks grown rather than built. Inside, a bar counter is faced in rough stone with a warm under counter glow, backed by open bottle shelving, and two stone chimney stacks rise behind the roofline from the pizza oven. Seating mixes long slab tables with benches, simple cafe chairs, and oversized grey beanbag loungers arranged on the sand around a stump table with a glowing cube lantern. Copy the mood with sand as the floor finish, low warm light and furniture that can be dragged into new groups. [below 1200px - best available]", "src": "images/Song Saa Private Island/0244 - Song Saa Private Island - Driftwood - beach bar pavilion with beanbag loungers.jpg", "source": "https://www.songsaa-privateisland.com/dining", "dimensions": "1048x1050", "size": 455628}, {"number": "0245", "file": "0245 - Song Saa Private Island - Saraan Sanctuaries - overwater treatment sala with sheer curtains.jpg", "resort": "Song Saa Private Island", "space": "Saraan Sanctuaries", "description": "The Saraan Sanctuaries treatment sala is an open pavilion on a timber platform over the water: a steep thatched roof on rough posts, with long sheer white curtains tied back at each corner to move in the breeze. A single massage table dressed in white linen stands at the centre, with stone bowls of flower petals placed at the platform edge and potted plants in rustic timber planters screening the sides. A therapist prepares the table, small within the composition. The design content is the architecture of calm: one bed, white fabric, thatch and water on every side. Recreate it by stripping a treatment space to a platform, a roof and curtains, with every object natural and handmade. [below 1200px - best available]", "src": "images/Song Saa Private Island/0245 - Song Saa Private Island - Saraan Sanctuaries - overwater treatment sala with sheer curtains.jpg", "source": "https://www.songsaa-privateisland.com/saraan-sanctuaries", "dimensions": "595x845", "size": 288585}, {"number": "0246", "file": "0246 - Song Saa Private Island - Saraan Sanctuaries - salt brick wall with slab table and bell.jpg", "resort": "Song Saa Private Island", "space": "Saraan Sanctuaries", "description": "A detail from the sanctuaries salt room shows a full wall built from translucent Himalayan salt bricks in blush, amber and cream, laid in a stretcher bond and glowing softly from behind. Against it stands a small altar like table, a single live edge timber slab on plain legs, holding a shallow carved wooden bowl with white blossom and a dark bronze ritual bell with a vajra handle, a nod to the Buddhist metta principle behind the spa programme. Nothing else is in the frame. The recreation lesson is the power of one luminous natural material used wall to wall, paired with a single piece of dark carved wood and one ceremonial object. [below 1200px - best available]", "src": "images/Song Saa Private Island/0246 - Song Saa Private Island - Saraan Sanctuaries - salt brick wall with slab table and bell.jpg", "source": "https://www.songsaa-privateisland.com/saraan-sanctuaries", "dimensions": "594x858", "size": 131553}, {"number": "0247", "file": "0247 - Six Senses Ninh Van Bay - Water Pool Villa - bedroom with draped mosquito canopy and sea view.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Water Pool Villa", "description": "A low teak platform bed dressed in crisp white linen anchors the room, its sheer mosquito canopy draped from a frame of lashed bamboo poles hung from the pitched timber ceiling. Walls and wide plank floors are warm honey toned wood, with woven rattan sliding screens and natural canvas roll up blinds softening the glass wall. A green upholstered window bench holds a wooden tray and woven fan, while a cylindrical paper floor lamp gives a soft glow. To recreate the look, pair raw teak furniture, bamboo pole detailing, cane webbing panels and one vivid textile accent against an all white bed.", "src": "images/Six Senses Ninh Van Bay/0247 - Six Senses Ninh Van Bay - Water Pool Villa - bedroom with draped mosquito canopy and sea view.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 273886}, {"number": "0248", "file": "0248 - Six Senses Ninh Van Bay - Water Pool Villa - living room daybed with round woven window.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Water Pool Villa", "description": "The split level living space is built around a broad timber platform daybed with a cream mattress, rust orange and white cushions and a low wooden tea tray. Woven cane panels line the walls as screens and shutters, filtering sunset light into a fine pattern, and a large round window with a woven centre acts as functional art on the plank wall. A solid wood cabinet, a chunky timber armchair and a small coir mat complete the scheme. Recreate it with cane webbing, unfinished teak, a platform daybed form and sunset toned cushions in orange, rust and lime.", "src": "images/Six Senses Ninh Van Bay/0248 - Six Senses Ninh Van Bay - Water Pool Villa - living room daybed with round woven window.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 380905}, {"number": "0249", "file": "0249 - Six Senses Ninh Van Bay - Rock Pool Villa - bedroom with rope handled glass door and canopy bed.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Rock Pool Villa", "description": "Seen through a glass door whose handle is a thick knotted rope, the bedroom runs long and narrow under a steep pitched roof of exposed rafters and a ceiling fan. The low platform bed in dark stained wood carries white linen and a tied sheer canopy on a bamboo rail. Plank floors and vertical board walls are deep warm brown, lit by a parchment cylinder floor lamp and a small wall sconce. Glazing reflects the thatched roof and granite boulders outside. Key recreation notes: rope door pulls, bamboo canopy rails, dark oiled timber everywhere and minimal, almost monastic furnishing.", "src": "images/Six Senses Ninh Van Bay/0249 - Six Senses Ninh Van Bay - Rock Pool Villa - bedroom with rope handled glass door and canopy bed.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 313117}, {"number": "0250", "file": "0250 - Six Senses Ninh Van Bay - Rock Pool Villa - open air bathroom with handcrafted wooden soaking tub.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Rock Pool Villa", "description": "The signature handcrafted wooden soaking tub, coopered like a barrel with dark metal banding, sits centre stage on wide plank decking in a fully open air bathroom. Behind it a rustic timber vanity bench holds a hammered dark stone vessel basin under a round mirror, flanked by tall conical shades. Canvas blinds roll up to reveal the sea and granite boulders, and a woven rattan pendant hangs from the thatched ceiling. A conical Vietnamese hat used as a wall light adds local character. Recreate with a wooden ofuro style tub, iron taps, stone basins and thatch overhead.", "src": "images/Six Senses Ninh Van Bay/0250 - Six Senses Ninh Van Bay - Rock Pool Villa - open air bathroom with handcrafted wooden soaking tub.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 324297}, {"number": "0251", "file": "0251 - Six Senses Ninh Van Bay - Beachfront Pool Villa - bedroom with bamboo canopy frame and whitewashed plaster walls.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Beachfront Pool Villa", "description": "This bedroom contrasts hand trowelled whitewashed plaster walls with a warm beamed timber ceiling and pale polished concrete floor. The chunky low bed frame in weathered wood is dressed all in white, with a sheer canopy cascading from a bamboo pole frame suspended overhead. An angled floor lamp with a long cylindrical paper shade stands on a low wooden tray table set into a plaster plinth. A woven fibre mat with sandals, slatted timber shutters and a glimpse through to the bamboo fenced garden bathroom complete the calm, tactile palette of plaster, bamboo, cane and raw wood.", "src": "images/Six Senses Ninh Van Bay/0251 - Six Senses Ninh Van Bay - Beachfront Pool Villa - bedroom with bamboo canopy frame and whitewashed plaster walls.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 256652}, {"number": "0252", "file": "0252 - Six Senses Ninh Van Bay - Beachfront Pool Villa - living pavilion with hanging rattan chair and daybed sofa.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Beachfront Pool Villa", "description": "The upper living pavilion is an open sided sala under a woven thatch ceiling on heavy timber trusses. A long built in daybed sofa in pale green is piled with cushions in magenta, lime, yellow and pink, facing a low teak coffee table. The hero piece is a teardrop hanging chair in bent rattan with deep cushions, suspended from the roof beam. Woven bamboo blinds screen one side, parchment cylinder lamps hang at the posts, and a coconut shell ornament sits on the sideboard. Recreate with a rattan pod chair, a platform daybed and saturated silk look cushions on green.", "src": "images/Six Senses Ninh Van Bay/0252 - Six Senses Ninh Van Bay - Beachfront Pool Villa - living pavilion with hanging rattan chair and daybed sofa.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 406939}, {"number": "0253", "file": "0253 - Six Senses Ninh Van Bay - Beachfront Pool Villa - bathroom with wooden soaking tub and garden shower.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Beachfront Pool Villa", "description": "A vast open plan bathroom pairs a handcrafted wooden soaking tub, complete with timber bath caddy and a wooden bucket and stool beside it, with a lime green upholstered daybed bench for lounging. The vanity is a rustic open timber bench with a black stone vessel basin, round mirror and twin conical parchment sconces, set against whitewashed plaster. Above, vertical bamboo poles clad the gable under the pitched board ceiling, and a woven rattan drum pendant hangs from bamboo rails. Full height glass opens to the private garden shower court, enclosed by a bamboo fence and stone wall.", "src": "images/Six Senses Ninh Van Bay/0253 - Six Senses Ninh Van Bay - Beachfront Pool Villa - bathroom with wooden soaking tub and garden shower.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 360225}, {"number": "0254", "file": "0254 - Six Senses Ninh Van Bay - Hill Top Pool Villa - bedroom daybed with bright cushions and plunge pool deck view.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Hill Top Pool Villa", "description": "Inside the bedroom, a low timber daybed with a green mattress and big square cushions in pink, lime and yellow sits in the corner where full height sliding glass doors meet, framing the bay and the villa plunge pool deck with its sun loungers and white umbrella. The bed, corner visible, wears white linen under a corner of sheer canopy netting. Vertical teak boards line the walls, the floor is wide dark planks, and natural canvas blinds roll up above the glass. The recipe is simple: one green daybed, three saturated cushion colours, raw teak and glass on two sides.", "src": "images/Six Senses Ninh Van Bay/0254 - Six Senses Ninh Van Bay - Hill Top Pool Villa - bedroom daybed with bright cushions and plunge pool deck view.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 342546}, {"number": "0255", "file": "0255 - Six Senses Ninh Van Bay - The Rock Retreat - bedroom with granite boulder backdrop at sunset.jpg", "resort": "Six Senses Ninh Van Bay", "space": "The Rock Retreat", "description": "At sunset the master bedroom glows amber, its platform bed in white linen set directly before a wall of glass behind which a huge natural granite boulder forms the headboard backdrop. The sheer canopy is swagged from a horizontal bamboo pole, and canvas blinds are rolled high. A small round timber table with two cushioned armchairs makes a sitting corner by the open deck doors, while a low dresser holds a ceramic lamp and a coconut bowl. Dark plank floors, exposed rafters and woven thatch ceiling panels keep the architecture raw so the rock and sea become the decoration.", "src": "images/Six Senses Ninh Van Bay/0255 - Six Senses Ninh Van Bay - The Rock Retreat - bedroom with granite boulder backdrop at sunset.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 244894}, {"number": "0256", "file": "0256 - Six Senses Ninh Van Bay - The Rock Retreat - outdoor sala with daybed among granite boulders.jpg", "resort": "Six Senses Ninh Van Bay", "space": "The Rock Retreat", "description": "The outdoor sala is a heavy timber pavilion with a deep thatched roof, built on a plank deck threaded between sculptural granite boulders at the water edge. Inside, a wide daybed in natural canvas with orange and cream cushions faces the sea, next to a low wooden cabinet, with a knotted white fabric pendant hanging from the beams as a soft sculpture. Bamboo balustrades and rolled bamboo blinds repeat the villa language outdoors. For recreation, the essential moves are the oversized thatch, the boulder as a design partner, one generous daybed and restrained natural textiles in cream and burnt orange.", "src": "images/Six Senses Ninh Van Bay/0256 - Six Senses Ninh Van Bay - The Rock Retreat - outdoor sala with daybed among granite boulders.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 300395}, {"number": "0257", "file": "0257 - Six Senses Ninh Van Bay - The Rock Retreat - pool deck with sun loungers and rock edged plunge pool.jpg", "resort": "Six Senses Ninh Van Bay", "space": "The Rock Retreat", "description": "A broad weathered timber deck wraps the private plunge pool, which is edged directly against pale granite boulders so the water appears carved from the rock. Four adjustable wooden sun loungers with cream canvas cushions are arranged in pairs around a small round stone side table, with a dark ceramic urn as an accent. The villa veranda runs along one side behind woven cane screens and bamboo railings under the thatch eaves, and wooden steps lead from the deck down to the sea. The palette is decking grey brown, stone, cream canvas and deep blue water.", "src": "images/Six Senses Ninh Van Bay/0257 - Six Senses Ninh Van Bay - The Rock Retreat - pool deck with sun loungers and rock edged plunge pool.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 326274}, {"number": "0258", "file": "0258 - Six Senses Ninh Van Bay - Hill Top Reserve - master bedroom with window daybed and panoramic sea view.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Hill Top Reserve", "description": "The master bedroom is lined in vertical striped teak boards under a high pitched boarded ceiling, with wide glass sliders and woven cane screens opening to a wraparound balcony. Across the window wall runs a full width low daybed in sage green, dressed with triangular bolster cushions and square pillows in magenta, lime and cream, plus a small lacquered tea tray. The white dressed bed carries a ceramic teapot set, and a low timber table holds tropical fruit. Canvas roller blinds, rope tie details and warm parchment wall lights finish a scheme built on teak, cane, sage and jewel bright accents.", "src": "images/Six Senses Ninh Van Bay/0258 - Six Senses Ninh Van Bay - Hill Top Reserve - master bedroom with window daybed and panoramic sea view.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 287400}, {"number": "0259", "file": "0259 - Six Senses Ninh Van Bay - Dining by the Bay - main dining hall with canvas sling chairs.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Dining by the Bay", "description": "The main restaurant is a soaring open pavilion of massive round timber columns and trusses under a woven thatch roof, with ceiling fans and parchment cylinder pendants. Rows of square wooden tables are set with natural linen runners and folded green napkins, surrounded by director style chairs of bamboo like timber frames with cream canvas slings. On one side, cushioned bench seating in yellow and orange runs along the tables. Wide plank floors, bamboo balustrades and an uninterrupted view across the bay complete the design. Recreate with sling chairs, chunky timber tables, green linen accents and oversized natural fibre lighting.", "src": "images/Six Senses Ninh Van Bay/0259 - Six Senses Ninh Van Bay - Dining by the Bay - main dining hall with canvas sling chairs.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 457120}, {"number": "0260", "file": "0260 - Six Senses Ninh Van Bay - Dining by the Bay - terrace dining deck with bamboo framed chairs.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Dining by the Bay", "description": "On the outer terrace deck, pairs of bamboo framed director chairs with cream and tan canvas slings sit at simple wooden tables dressed with rust orange napkins, looking straight across the bay to the beach and forested headland. The decking is weathered grey brown planks, the railing is vertical bamboo poles set in a timber frame, and the thatched roof of the restaurant pavilion overhangs one side with clear roll down weather screens. A carved wooden figure stands by the inner tables. The look to copy is safari camp dining refined: bamboo, canvas, one hot accent colour and a panoramic water view.", "src": "images/Six Senses Ninh Van Bay/0260 - Six Senses Ninh Van Bay - Dining by the Bay - terrace dining deck with bamboo framed chairs.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 401650}, {"number": "0261", "file": "0261 - Six Senses Ninh Van Bay - Dining by the Rocks - hilltop dining deck at dusk with rustic branchwood chairs.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Dining by the Rocks", "description": "The signature hilltop restaurant seats just four small tables on an open wooden deck high above the bay, photographed at dusk. The chairs are handmade from irregular branchwood poles with simple ladder backs and deep red seat cushions, and the tables wear orange runners, green folded napkins and glass hurricane lanterns with candles. Tall slim lantern posts mark the deck edge, and the balustrade is bamboo poles in a timber rail. Everything is deliberately rustic so the sunset seascape dominates. To recreate, use branchwood or faux bois chairs, red cushions, saffron textiles and candlelight only.", "src": "images/Six Senses Ninh Van Bay/0261 - Six Senses Ninh Van Bay - Dining by the Rocks - hilltop dining deck at dusk with rustic branchwood chairs.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 293690}, {"number": "0262", "file": "0262 - Six Senses Ninh Van Bay - Six Senses Spa - spa reception pavilion across stepping stone pond at dusk.jpg", "resort": "Six Senses Ninh Van Bay", "space": "Six Senses Spa", "description": "Arrival at the spa is a procession across oversized organic stepping stones set in a shallow illuminated pond, each stone carrying a glass hurricane candle lantern. Dry stacked stone walls with irregular moon gate style openings frame the path, leading to a thatched reception pavilion in warm timber, its interior glowing with parchment wall lights around a wooden reception desk. The treatment pavilions repeat the thatch and stone language against the forested hillside, seen here at blue hour. Key elements for recreation: rubble stone walls with sculptural openings, water as the floor plane, candle lanterns and a single glowing timber pavilion.", "src": "images/Six Senses Ninh Van Bay/0262 - Six Senses Ninh Van Bay - Six Senses Spa - spa reception pavilion across stepping stone pond at dusk.jpg", "source": "https://www.travelplusstyle.com/hotels/six-senses-ninh-van-nha-trang", "dimensions": "1880x1208", "size": 302112}, {"number": "0263", "file": "0263 - Amanyara - Entrance Pavilion - arrival hall with cathedral timber ceiling and communal table.jpg", "resort": "Amanyara", "space": "Entrance Pavilion", "description": "The arrival hall is a soaring open pavilion with a cathedral ceiling of exposed warm timber rafters and boards, lit by a ceiling fan and low sun through full height openings. A long, low communal timber table runs down the centre on a polished pale stone floor, dressed with books, ceramics and blue patterned floor cushions, with grey upholstered lounge seating and a tall woven cane screen closing the far end. To recreate the look, pair a steep pitched timber ceiling and stone floor with one oversized low table, woven screens, and a restrained palette of honey wood, cream and indigo accents. This is the largest official original served for this view, best available at 912 px wide.", "src": "images/Amanyara/0263 - Amanyara - Entrance Pavilion - arrival hall with cathedral timber ceiling and communal table.jpg", "source": "https://www.aman.com/resorts/amanyara/gallery", "dimensions": "912x1200", "size": 1067867}, {"number": "0264", "file": "0264 - Amanyara - Entrance Pavilion - reflecting pond view to the circular bar pavilion.jpg", "resort": "Amanyara", "space": "Entrance Pavilion", "description": "The view from the arrival pavilion crosses the mirror still central reflecting pond to the circular Bar pavilion, its conical timber shingled roof and slatted teak screens doubled in the water, with the colonnaded Restaurant pavilion to the right and mahogany trees framing both sides. Dark planters and stone edged planting beds sit in the pond itself. To recreate it, build the arrival sequence around a still black pond, a round shingled roof pavilion as the focal point, and symmetrical timber colonnades in warm teak against cream render.", "src": "images/Amanyara/0264 - Amanyara - Entrance Pavilion - reflecting pond view to the circular bar pavilion.jpg", "source": "https://www.aman.com/resorts/amanyara", "dimensions": "2560x1580", "size": 969573}, {"number": "0265", "file": "0265 - Amanyara - Main Pool - black stone pool with central stone bowl.jpg", "resort": "Amanyara", "space": "Main Pool", "description": "The 50 metre main pool is a sheet of dark volcanic stone water stretching to the ocean, with a carved stone bowl fountain on a low plinth at its centre, a timber pergola daybed pavilion to the left and canvas umbrellas with cushioned loungers along the right hand deck. Scrub planting and a single tree soften the horizon line where pool meets sea. To recreate it, use black stone or black tiles for the water, one sculptural stone bowl as the only ornament, and plain timber pergolas with cream canvas shading.", "src": "images/Amanyara/0265 - Amanyara - Main Pool - black stone pool with central stone bowl.jpg", "source": "https://www.aman.com/resorts/amanyara", "dimensions": "2560x1580", "size": 632163}, {"number": "0266", "file": "0266 - Amanyara - The Restaurant - oceanfront terrace dining under the trees.jpg", "resort": "Amanyara", "space": "The Restaurant", "description": "The Restaurant terrace sets square pale timber tables and low armchairs with cream cushions on a stone terrace under mature trees, metres from the ocean hedge. Place settings are minimal, with small ceramic vases, dark napkins and glassware, and the palette is bleached wood, cream and sea green. To recreate it, keep dining furniture low and square in pale teak, upholster seats in plain cream outdoor fabric, and let the tree canopy and ocean provide the decoration.", "src": "images/Amanyara/0266 - Amanyara - The Restaurant - oceanfront terrace dining under the trees.jpg", "source": "https://www.aman.com/resorts/amanyara/dining/restaurant", "dimensions": "1600x988", "size": 1925495}, {"number": "0267", "file": "0267 - Amanyara - The Bar - circular bar with conical timber ceiling.jpg", "resort": "Amanyara", "space": "The Bar", "description": "The circular Bar is the resort signature, a soaring conical timber ceiling over a central round bar counter in dark stone and cream, ringed by oversized daybeds and low lounge chairs in dark woven frames with cream cushions. Tall openings with slatted teak shutters frame ocean views on every side, and the polished terrazzo floor carries dark timber inlay lines radiating from the centre. To recreate it, centre a round bar under a conical boarded ceiling, circle it with deep daybeds, and hold the palette to dark timber, cream and stone.", "src": "images/Amanyara/0267 - Amanyara - The Bar - circular bar with conical timber ceiling.jpg", "source": "https://www.aman.com/resorts/amanyara/dining/bar", "dimensions": "1600x988", "size": 1201039}, {"number": "0268", "file": "0268 - Amanyara - Beach Club - terrace dining at sunset.jpg", "resort": "Amanyara", "space": "Beach Club", "description": "The Beach Club terrace seats diners at glass topped tables with woven back dining chairs and cream cushions under a pitched timber roof on round teak columns, facing the sunset over the ocean hedge. Textured blue green drinking glasses and simple ceramics dress each table. To recreate it, combine glass and teak dining sets, woven chair backs, coloured handmade glassware and an open colonnade that frames the horizon. This is the largest official original served for this view, best available at 1073 px wide.", "src": "images/Amanyara/0268 - Amanyara - Beach Club - terrace dining at sunset.jpg", "source": "https://www.aman.com/resorts/amanyara/dining/beach-club", "dimensions": "1073x1073", "size": 1056929}, {"number": "0269", "file": "0269 - Amanyara - Amanyara Pavilion - T-shaped pool and shingled pavilion.jpg", "resort": "Amanyara", "space": "Amanyara Pavilion", "description": "The Amanyara Pavilion stands behind its private T-shaped pool, a broad timber shingled pyramid roof on cream walls with slatted teak shutters and full height glass. A canvas umbrella shades timber loungers and a cushioned daybed on the deck, with a hammock strung to one side and dense coastal planting enclosing the plot. To recreate it, centre a dark water pool on the pavilion axis, use shingle roofing and teak louvres, and furnish the deck with plain canvas and cream upholstery.", "src": "images/Amanyara/0269 - Amanyara - Amanyara Pavilion - T-shaped pool and shingled pavilion.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilion/amanyara-pavilion", "dimensions": "2560x1580", "size": 821203}, {"number": "0270", "file": "0270 - Amanyara - Amanyara Pavilion - canopy bed bedroom with slatted screens.jpg", "resort": "Amanyara", "space": "Amanyara Pavilion", "description": "The bedroom is arranged on the pavilion axis, a king bed dressed in plain white linen with sheer canopy drapes tied at the posts, facing a window seat with indigo cushions. Walls of vertical teak slats, an exposed rafter ceiling in warm timber and polished sand coloured terrazzo floors with dark wood inlay carry the Aman palette, with a low reading chair and timber side tables. To recreate it, use a draped canopy bed as the single focal point, slatted timber wall panels, sheer white curtains and almost no pattern beyond one indigo textile accent.", "src": "images/Amanyara/0270 - Amanyara - Amanyara Pavilion - canopy bed bedroom with slatted screens.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilion/amanyara-pavilion", "dimensions": "2560x1580", "size": 560989}, {"number": "0271", "file": "0271 - Amanyara - Pool Pavilion - pavilion across the infinity pool.jpg", "resort": "Amanyara", "space": "Pool Pavilion", "description": "The Pool Pavilion is photographed across its private infinity edge pool, the pyramid shingled roof and deep overhanging eaves shading a terrace with two canvas sling loungers and a dining set, the canopy bed visible through open slatted screens. Cream render, teak louvres and the dark pool water form the whole palette against dense green planting. To recreate it, align a black infinity pool on the bedroom, keep eaves deep and low, and furnish with canvas sling chairs and plain teak.", "src": "images/Amanyara/0271 - Amanyara - Pool Pavilion - pavilion across the infinity pool.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilions/pool-pavilion", "dimensions": "2560x2560", "size": 1111654}, {"number": "0272", "file": "0272 - Amanyara - Ocean Cove Pavilion - bedroom opening to ocean terrace.jpg", "resort": "Amanyara", "space": "Ocean Cove Pavilion", "description": "Inside an Ocean Cove Pavilion the combined bedroom and living area faces floor to ceiling glass doors onto a private terrace and the ocean path, with a low cream sofa in the foreground and a timber framed armchair with pale upholstery to the side. The ceiling is boarded timber with exposed beams, sheer curtains soften the glass, and a small terrace table and chairs sit outside. To recreate it, frame the sea with full height sliding glass, board the ceiling in warm wood, and keep furniture low, pale and few.", "src": "images/Amanyara/0272 - Amanyara - Ocean Cove Pavilion - bedroom opening to ocean terrace.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilion/ocean-cove-pavilion", "dimensions": "1600x988", "size": 1388813}, {"number": "0273", "file": "0273 - Amanyara - Tranquility Pavilion - canopy bed bedroom and garden terrace.jpg", "resort": "Amanyara", "space": "Tranquility Pavilion", "description": "A corner view of a Tranquility Pavilion bedroom shows the white draped canopy bed, exposed timber rafter ceiling and polished terrazzo floor, with sliding glass opening to a shaded terrace holding a small round table and two timber armchairs above the pond side garden. Cream sheers, plain white bedding and honey coloured wood do all the work. To recreate it, pair a sheer draped bed with board and rafter ceilings, pale stone floors and a simply furnished garden terrace.", "src": "images/Amanyara/0273 - Amanyara - Tranquility Pavilion - canopy bed bedroom and garden terrace.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilion/tranquility-pavilion", "dimensions": "2560x2560", "size": 720552}, {"number": "0274", "file": "0274 - Amanyara - Tranquility Pavilion - bathroom with freestanding tub and teak screen.jpg", "resort": "Amanyara", "space": "Tranquility Pavilion", "description": "The pavilion bathroom, filed by Aman as the Pond Pavilion bathroom for this same pavilion type, centres a sculptural freestanding oval tub in front of a full height screen of vertical teak slats that filters light from the bedroom beyond. A black tray holds rolled white towels and dark ceramic bottles, and the floor is pale stone with timber inlay. To recreate it, set an oval soaking tub against a slatted timber screen, use black stone accessories, and keep every surface pale and uncluttered.", "src": "images/Amanyara/0274 - Amanyara - Tranquility Pavilion - bathroom with freestanding tub and teak screen.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/pavilion/tranquility-pavilion", "dimensions": "2560x1574", "size": 739122}, {"number": "0275", "file": "0275 - Amanyara - The Artists Villa - living pavilion with stone disc sculpture.jpg", "resort": "Amanyara", "space": "The Artists Villa", "description": "The Artists Villa living pavilion is a double height room with carved and slatted timber wall panels, patterned textile hangings and a vast circular stone disc sculpture as its centrepiece. A long cream sofa with gold patterned cushions faces a low dark timber coffee table, flanked by teak armchairs, on sisal coloured flooring. To recreate it, anchor a neutral cream seating group with one monumental stone disc, carved teak screens and a single gold toned patterned textile.", "src": "images/Amanyara/0275 - Amanyara - The Artists Villa - living pavilion with stone disc sculpture.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/villa/artists-villa", "dimensions": "2560x1580", "size": 572002}, {"number": "0276", "file": "0276 - Amanyara - The Artists Villa - infinity pool running to the ocean.jpg", "resort": "Amanyara", "space": "The Artists Villa", "description": "From the Artists Villa living pavilion the private infinity pool runs in one long black mirror from the timber deck straight to the ocean horizon, lined on one side by a stone walk and on the other by cream cushioned loungers under canvas umbrellas. Timber posts frame the view like a picture. To recreate it, extend a dark infinity pool on the main room axis to the sea, keep deck furniture cream and canvas, and frame the composition with two plain posts.", "src": "images/Amanyara/0276 - Amanyara - The Artists Villa - infinity pool running to the ocean.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/villa/artists-villa", "dimensions": "2560x1580", "size": 473044}, {"number": "0277", "file": "0277 - Amanyara - Five-Bedroom Beach Sala Villa - living pavilion and black pool.jpg", "resort": "Amanyara", "space": "Five-Bedroom Beach Sala Villa", "description": "The Beach Sala Villa living pavilion is a long open fronted hall of round teak columns and full height glass under a shingled roof, fronted by the black infinity pool with white cushioned loungers and a dining set on the stone deck. Interiors visible through the glass repeat the cream sofa and teak theme. To recreate it, build one long colonnaded living pavilion in teak and shingle, run a black pool along its front, and furnish in cream canvas and pale timber.", "src": "images/Amanyara/0277 - Amanyara - Five-Bedroom Beach Sala Villa - living pavilion and black pool.jpg", "source": "https://www.aman.com/resorts/amanyara/accommodation/villas/five-bedroom-beach-sala-villa", "dimensions": "2560x2560", "size": 1165657}, {"number": "0278", "file": "0278 - Amanyara - Spa - double treatment pavilion with louvred screens.jpg", "resort": "Amanyara", "space": "Spa", "description": "A double treatment pavilion at the Aman Spa holds two massage tables dressed in cream woven covers, facing louvred teak screens and glass doors that open toward the spa pool and relaxation pavilion. The pitched ceiling is boarded timber with a ceiling fan, a low lounge chair and wooden bowls sit to one side, and the palette is cream, honey wood and soft green from the planting outside. To recreate it, use louvred timber screens for privacy without darkness, cream textured bed covers, boarded ceilings and a garden or water view at the foot of the tables.", "src": "images/Amanyara/0278 - Amanyara - Spa - double treatment pavilion with louvred screens.jpg", "source": "https://www.aman.com/resorts/amanyara/gallery", "dimensions": "1600x988", "size": 1673892}, {"number": "0279", "file": "0279 - Amanera - Casitas - jungle garden exterior with green roof.jpg", "resort": "Amanera", "space": "Casitas", "description": "A freestanding casita half hidden in layered tropical planting, its thin flat concrete roof carrying a biodiverse green roof that merges with the jungle canopy. Full height teak framed glass walls sit behind deep eaves, and a stepping stone path crosses the lawn to the entrance. To recreate the look, pair raw modernist concrete and warm Asian teak with dense native planting, keep the roofline low and horizontal, and let the building emerge from the garden rather than sit on it.", "src": "images/Amanera/0279 - Amanera - Casitas - jungle garden exterior with green roof.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "2560x2560", "size": 1807168}, {"number": "0280", "file": "0280 - Amanera - Casitas - private pool and shaded terrace.jpg", "resort": "Amanera", "space": "Casitas", "description": "A Pool Casita terrace arranged around a narrow private swimming pool, with cushioned timber sun loungers on a pale stone deck and the flat roofed pavilion opening behind through floor to ceiling glass. Planting is lush and architectural, palms and broadleaf shrubs screening the terrace for privacy. Recreate with a simple rectangular pool hard against the living space, low platform loungers in weathered teak with ecru cushions, and sliding glass walls that erase the threshold between room and terrace.", "src": "images/Amanera/0280 - Amanera - Casitas - private pool and shaded terrace.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1600x988", "size": 2492456}, {"number": "0281", "file": "0281 - Amanera - Casitas - living room with woven armchair and garden doors.jpg", "resort": "Amanera", "space": "Casitas", "description": "The casita living room is wrapped in floor to ceiling teak framed sliding glass doors that open to a private garden court with a coral stone wall and timber louvred shutters. A woven rope armchair with taupe cushions and a faceted solid timber side table sit on a flatweave rug patterned in geometric blocks of sage, ochre, slate blue and cream. Built in teak shelving holds white ceramics and books, and a potted orchid softens the joinery. Recreate with honey toned teak joinery throughout, one patterned flatweave as the only strong textile, and furniture kept low and open framed.", "src": "images/Amanera/0281 - Amanera - Casitas - living room with woven armchair and garden doors.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1200x1200", "size": 1578438}, {"number": "0282", "file": "0282 - Amanera - Casitas - bathroom with garden shower and stone wall.jpg", "resort": "Amanera", "space": "Casitas", "description": "The bathroom opens through teak framed glazing to a private walled garden of local coral stone planted with ferns. In the foreground an inset oval bath with a matte black gooseneck faucet sits in a pale stone counter with a tray of white ceramic amenities, and beyond the glass a walk in rain shower uses black fittings against plaster walls. Handmade Aguayo tiles in a soft geometric pattern pave the floor, and a faceted timber stool holds folded towels. Recreate with stone, plaster and dark bronze or black fittings, a garden outlook from both bath and shower, and one patterned tile used sparingly on the floor. This is the largest official version obtainable and is best available at 1022 px wide.", "src": "images/Amanera/0282 - Amanera - Casitas - bathroom with garden shower and stone wall.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1022x1022", "size": 1005973}, {"number": "0283", "file": "0283 - Amanera - Casitas - bedroom with teak platform bed and sliding panels.jpg", "resort": "Amanera", "space": "Casitas", "description": "A low teak platform bed dressed in plain white linen stands on a woven natural fibre mat, facing full height sliding teak panels that open the bedroom to the living area and the garden court beyond. The joinery is uniformly rich reddish teak, walls are plaster, and a ceiling fan and lattice screened courtyard complete the Far Eastern plan. A low timber media console runs along the side wall. Recreate with a single wood species carried across bed, panels and cabinetry, unpatterned white bedding, woven grass matting underfoot, and rooms that flow into each other through sliding screens rather than doors. This is the largest official version obtainable and is best available at 1166 px wide.", "src": "images/Amanera/0283 - Amanera - Casitas - bedroom with teak platform bed and sliding panels.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1166x1165", "size": 1232677}, {"number": "0284", "file": "0284 - Amanera - Two-Bedroom Bay View Casa - pool frontage with glass pavilion.jpg", "resort": "Amanera", "space": "Two-Bedroom Bay View Casa", "description": "The front elevation of the Bay View Casa across its 20 metre infinity pool: a wafer thin concrete roof slab floats on paired dark columns above a fully glazed living pavilion framed in teak. Built in cream sofas and timber daybeds line the stone terrace between the glass and the water, with a small tree planted in a raised bed as the only ornament. Recreate the effect with an exaggerated thin roof plane, full height glass in warm timber frames, a black edged mirror pool, and terrace furniture kept to low upholstered benches in undyed canvas tones.", "src": "images/Amanera/0284 - Amanera - Two-Bedroom Bay View Casa - pool frontage with glass pavilion.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1200x1200", "size": 1334350}, {"number": "0285", "file": "0285 - Amanera - Two-Bedroom Bay View Casa - living and dining pavilion.jpg", "resort": "Amanera", "space": "Two-Bedroom Bay View Casa", "description": "Inside the casa living pavilion, a long cream sofa faces a black glass topped coffee table on a geometric flatweave rug in sage, indigo and ochre, with a woven rope armchair to one side. Behind the sofa a full width teak shelving partition displays plain white ceramic vessels and separates the sitting area from the dining table and chairs. Clerestory glazing and floor to ceiling glass on both sides wash the space in light. Recreate with a joinery screen wall as the room divider, one patterned rug against plain upholstery, and ceramics in a single colour used as sculpture.", "src": "images/Amanera/0285 - Amanera - Two-Bedroom Bay View Casa - living and dining pavilion.jpg", "source": "https://www.aman.com/resorts/amanera/accommodation", "dimensions": "1200x1200", "size": 1259286}, {"number": "0286", "file": "0286 - Amanera - Casa Grande - arrival pavilion with reflecting pool.jpg", "resort": "Amanera", "space": "Casa Grande", "description": "The Casa Grande arrival pavilion is a vast open sided hall of slender columns and a floating flat roof, furnished with long white upholstered sofas and dark timber lounge chairs around a still reflecting pool. Polished stone floors mirror the roof plane and the jungle beyond, so the architecture reads as a frame for water and greenery. Recreate with an open plan pavilion on slim supports, a shallow rill or reflecting pool as the central feature, and a restrained palette of white upholstery, dark wood and stone.", "src": "images/Amanera/0286 - Amanera - Casa Grande - arrival pavilion with reflecting pool.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "2560x2560", "size": 1165792}, {"number": "0287", "file": "0287 - Amanera - Casa Grande - terraces and main pool at dusk.jpg", "resort": "Amanera", "space": "Casa Grande", "description": "At dusk the Casa Grande terraces step down the cliff in layers of dining tables, cream daybeds and the curved main pool, all under deep overhanging roof planes lit warmly from within. Timber screens and columns structure the levels while the Atlantic and Playa Grande fill the horizon. Recreate with terraced outdoor rooms under one continuous roof language, low modular outdoor sofas and daybeds in ecru canvas, and lighting kept low and amber so the view stays dominant.", "src": "images/Amanera/0287 - Amanera - Casa Grande - terraces and main pool at dusk.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "2000x1235", "size": 480125}, {"number": "0288", "file": "0288 - Amanera - Casa Grande - open air lounge with marble tables.jpg", "resort": "Amanera", "space": "Casa Grande", "description": "A corner of the Casa Grande lounge where living palm trunks rise through the open air seating area. Built in L shaped banquettes in cream canvas wrap around white marble slab tables, each set with a dark bronze sculptural vessel like a split seed pod. The jungle is the wallpaper and the furniture is masonry and stone. Recreate with fixed banquette seating in pale upholstery, heavy marble occasional tables, one dark sculptural object per table, and planting brought inside the architecture.", "src": "images/Amanera/0288 - Amanera - Casa Grande - open air lounge with marble tables.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "1200x1200", "size": 1651178}, {"number": "0289", "file": "0289 - Amanera - Casa Grande - library reading chair by garden windows.jpg", "resort": "Amanera", "space": "Casa Grande", "description": "The library is a glazed teak room looking into palm trunks and jungle, with open shelves of art books, a polished teak floor, and a single A frame timber lounge chair with matching ottoman in sage upholstery angled to the view. A cream daybed runs along the side wall. Recreate with one sculptural reading chair in warm wood and muted green fabric, floor to ceiling garden glazing in dark timber frames, and books treated as the decoration.", "src": "images/Amanera/0289 - Amanera - Casa Grande - library reading chair by garden windows.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "1200x1200", "size": 1584762}, {"number": "0290", "file": "0290 - Amanera - The Restaurant - dining room with marble tables and garden views.jpg", "resort": "Amanera", "space": "The Restaurant", "description": "The main restaurant in Casa Grande is a glass pavilion of teak framed floor to ceiling windows on three sides, so every table faces gardens or the ocean. Dining tables have white marble tops with timber and woven rope chairs in the resort pattern, and the polished floor reflects the greenery. Settings are minimal, white porcelain and a small vase of tropical flowers. Recreate with marble topped tables, cane or rope backed dining chairs with navy and cream cushions, and glazing instead of walls so the landscape does the decorating.", "src": "images/Amanera/0290 - Amanera - The Restaurant - dining room with marble tables and garden views.jpg", "source": "https://www.aman.com/resorts/amanera/dining", "dimensions": "2560x1580", "size": 669659}, {"number": "0291", "file": "0291 - Amanera - Beach Club - dining tables on the sand at dusk.jpg", "resort": "Amanera", "space": "Beach Club", "description": "Beach Club tables stand directly on the sand at dusk, set with glowing cube lanterns and simple glassware, facing the surf and the rocky headland at the end of Playa Grande. The chairs are the resort dining chair in its outdoor form, timber frames with woven rope backs and deep navy seat cushions. Recreate feet in the sand dining with rope weave armchairs, one warm lantern per table, and no decoration beyond the setting. This is the largest official version obtainable and is best available at 929 px wide.", "src": "images/Amanera/0291 - Amanera - Beach Club - dining tables on the sand at dusk.jpg", "source": "https://www.aman.com/resorts/amanera/dining", "dimensions": "929x929", "size": 828869}, {"number": "0292", "file": "0292 - Amanera - Beach Club - dining room with domed white oven.jpg", "resort": "Amanera", "space": "Beach Club", "description": "Inside the Beach Club, meals are cooked in a monumental domed white rendered oven with a steel flue that anchors the dining room like a piece of sculpture. Around it, marble topped tables are set with white porcelain and surrounded by woven rope dining chairs with navy cushions, while chefs in striped aprons work at the open counter. Walls are warm plaster with timber louvred clerestories. Recreate with one oversized rendered masonry feature, plaster walls, and the same rope and navy chair used outdoors for continuity.", "src": "images/Amanera/0292 - Amanera - Beach Club - dining room with domed white oven.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "1200x1200", "size": 1016991}, {"number": "0293", "file": "0293 - Amanera - Wellness Casa - spa pavilion in tropical gardens.jpg", "resort": "Amanera", "space": "Wellness Casa", "description": "The Wellness Casa spa pavilion is a flat roofed glass box in teak frames set on a manicured lawn among palms, its deep concrete roof plane shading full height sliding doors. The building is almost entirely transparent, so treatments and movement classes happen inside the garden rather than beside it. Recreate with a single storey pavilion under an oversized thin roof slab, full glazing in warm timber, and a lawn and palm setting kept immaculate and uncluttered.", "src": "images/Amanera/0293 - Amanera - Wellness Casa - spa pavilion in tropical gardens.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "1600x988", "size": 2827039}, {"number": "0294", "file": "0294 - Amanera - Wellness Casa - treatment room with massage table and candles.jpg", "resort": "Amanera", "space": "Wellness Casa", "description": "A double treatment room in the Wellness Casa, dark and cocooning against the brightness outside: a dressed massage table in grey linen, a therapist in indigo Aman uniform, low candles, and near black timber panelling with pierced lattice ventilation grilles. The mood is created by darkness, candlelight and texture rather than ornament. Recreate with very dark stained timber walls, one lattice detail, plain stone grey textiles, and candlelight as the main light source. This is the largest official version obtainable and is best available at 1000 px wide.", "src": "images/Amanera/0294 - Amanera - Wellness Casa - treatment room with massage table and candles.jpg", "source": "https://www.aman.com/resorts/amanera", "dimensions": "1000x1000", "size": 553411}, {"number": "0295", "file": "0295 - Banyan Tree Mayakoba - Bliss Pool Villa - bedroom and sitting area with carved lattice screen.jpg", "resort": "Banyan Tree Mayakoba", "space": "Bliss Pool Villa", "description": "The renovated Bliss Pool Villa reads as one long, calm room under a soaring pitched ceiling, the king bed and a separate sitting area divided by a freestanding carved lattice screen in pale timber, a signature Asia-Maya gesture that filters light and air. Joinery and wall panelling are warm honey toned wood, the floor is large format charcoal slate, and the palette is cream, sand and pale oak with a single teal accent cushion. Furniture is low and horizontal: a cream upholstered sofa, round pedestal side table, boucle style ottoman stools and a curved timber lounge chair with woven cane back. Full height glazing opens to the garden terrace where a hammock hangs beside the private pool. To recreate it, pair a carved timber screen room divider with cream boucle upholstery, slate floors, woven cane and one muted jewel accent, keeping every line low and the planting always in view.", "src": "images/Banyan Tree Mayakoba/0295 - Banyan Tree Mayakoba - Bliss Pool Villa - bedroom and sitting area with carved lattice screen.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/bliss-pool-villa-0", "dimensions": "2560x1828", "size": 876801}, {"number": "0296", "file": "0296 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - bedroom with perforated timber headboard wall.jpg", "resort": "Banyan Tree Mayakoba", "space": "Serenity Pool Villa with Living Room", "description": "In the renovated Serenity Pool Villa the bed wall is the artwork: a full height perforated timber headboard panel, its grid of small apertures glowing softly and throwing patterned shadow, flanked by plain cream walls and a low platform bed in pale wood dressed in white linen with a single geometric patterned cushion. Dark slate floors ground the room, a wall mounted screen keeps surfaces clear, and sliding glass doors open to the terrace hammock and jungle planting beyond. Bedside tables are simple timber blocks with small shaded lamps. The recreation formula is a statement perforated wood panel behind the bed, an otherwise quiet cream and slate palette, blackout linen curtains in warm white, and furniture kept to a few sculptural, low pieces so the patterned light does the decorating.", "src": "images/Banyan Tree Mayakoba/0296 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - bedroom with perforated timber headboard wall.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/serenity-pool-villa-with-living-room", "dimensions": "2560x1778", "size": 786355}, {"number": "0297", "file": "0297 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - private pool deck with jet pool.jpg", "resort": "Banyan Tree Mayakoba", "space": "Serenity Pool Villa with Living Room", "description": "The Serenity Pool Villa garden is a private outdoor room: a full size turquoise pool edged in stone, a raised timber deck carrying two cushioned sun loungers with teal towels, a separate bubbling jet pool, and a small dining set tucked against the villa wall. The villa itself is warm stucco and terracotta tile with deep eaves, almost hidden by layered tropical planting that guarantees privacy. Materials are honest and weatherproof, ipe style decking, rough stone coping, powder coated frames and outdoor fabrics in white and aqua. To recreate the look, zone a garden into swim, lounge and soak areas on different levels, wrap it in dense green screening, and repeat the interior palette of cream, warm wood and one watery accent colour outdoors.", "src": "images/Banyan Tree Mayakoba/0297 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - private pool deck with jet pool.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/serenity-pool-villa-with-living-room", "dimensions": "2560x1708", "size": 1233247}, {"number": "0298", "file": "0298 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - aerial view of pool garden and hammock terrace.jpg", "resort": "Banyan Tree Mayakoba", "space": "Serenity Pool Villa with Living Room", "description": "From above, the Serenity Pool Villa garden shows its planning clearly: a long rectangular pool in bright turquoise runs the length of the plot, with a stepped timber sun deck at one end, two loungers, a shaded terrace with a strung hammock, and the low stucco villa with terracotta roofs tucked under mature jungle canopy. The contrast of the geometric pool and deck against loose, layered planting is the whole design idea, architecture as a calm frame for wilderness. Colours are saturated green, warm earth and aqua. Recreating it means committing to one strong geometric water element, natural timber decking, and planting in deep layers so the building disappears into green from every upper viewpoint.", "src": "images/Banyan Tree Mayakoba/0298 - Banyan Tree Mayakoba - Serenity Pool Villa with Living Room - aerial view of pool garden and hammock terrace.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/serenity-pool-villa-with-living-room", "dimensions": "2560x1920", "size": 1427376}, {"number": "0299", "file": "0299 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - rooftop solarium with slatted pavilion roof.jpg", "resort": "Banyan Tree Mayakoba", "space": "Lagoon & Sunset Rooftop Pool Villa", "description": "The rooftop solarium of the Lagoon and Sunset Rooftop Pool Villa is a pavilion in the sky: a soaring pitched roof of timber slats throws striped shade over two oversized daybeds in cream canvas with rust orange cushions, beside a dark infinity plunge pool that mirrors the lagoon and mangrove forest below. Wood decking, woven textile flooring and concealed warm uplighting keep the mood intimate at dusk, and an Ixchel dining boat can be seen crossing the water. To recreate it, build a slatted timber pergola roof at a steep pitch, use daybeds scaled almost like beds, choose one burnt orange accent against cream and dark water, and let the view be the only ornament.", "src": "images/Banyan Tree Mayakoba/0299 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - rooftop solarium with slatted pavilion roof.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/lagoon-sunset-rooftop-pool-villa", "dimensions": "2560x1707", "size": 1097620}, {"number": "0300", "file": "0300 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - bedroom with stone headboard wall.jpg", "resort": "Banyan Tree Mayakoba", "space": "Lagoon & Sunset Rooftop Pool Villa", "description": "The lower level bedroom of the rooftop villa is lined almost entirely in warm timber, walls, ceiling and floor, with a feature headboard wall of large, pale Crema Maya style stone slabs behind a low platform king bed. Built in timber shelving displays small carved objects, a woven front panel conceals storage, and floating bedside shelves carry globe wall lights. A small round stone topped table with two woven seat chairs makes a breakfast corner, and a flat woven grey rug softens the wood floor. The palette is amber wood, bone stone and white linen. Recreate it with full timber lining, one pale stone feature wall, platform furniture and woven textures, keeping decoration to a few hand made pieces.", "src": "images/Banyan Tree Mayakoba/0300 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - bedroom with stone headboard wall.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/lagoon-sunset-rooftop-pool-villa", "dimensions": "2560x1706", "size": 596478}, {"number": "0301", "file": "0301 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - living area opening to lagoon balcony at dusk.jpg", "resort": "Banyan Tree Mayakoba", "space": "Lagoon & Sunset Rooftop Pool Villa", "description": "At dusk the rooftop villa living area glows amber: timber lined walls and ceiling, a cream daybed sofa with patterned cushions and a matching ottoman, woven seat chairs around a round marble topped table, and full width sliding doors opening to a balcony over the dark lagoon. Cove lighting washes the wood, a ceiling fan turns overhead, and sheer linen curtains frame the deep blue evening view. The mood depends on warm, layered, indirect light against saturated wood tones, with cream upholstery and pale stone as relief. To recreate it, light timber rooms from concealed coves rather than ceiling points, keep textiles cream and tactile, and open one whole wall to water or garden.", "src": "images/Banyan Tree Mayakoba/0301 - Banyan Tree Mayakoba - Lagoon & Sunset Rooftop Pool Villa - living area opening to lagoon balcony at dusk.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/lagoon-sunset-rooftop-pool-villa", "dimensions": "2560x1706", "size": 621142}, {"number": "0302", "file": "0302 - Banyan Tree Mayakoba - Lobby - main lobby water court with banyan tree at sunset.jpg", "resort": "Banyan Tree Mayakoba", "space": "Lobby", "description": "The main lobby is built around water and one tree: guests arrive between massive rough cut stone walls to a still reflecting court, at its centre a banyan tree growing from a square planted island, with a slatted timber pergola tower rising behind it and the low lobby pavilions reflected in the lagoon at sunset. The design is pure Asia-Maya, monumental stone, dark water, a sacred tree and precise geometry softened by jungle planting at every edge. There is almost no furniture in view; the architecture and the tree are the furnishing. To recreate the effect, frame a single specimen tree with still black water, use large scale rusticated stone, and keep every added element low, symmetrical and quiet.", "src": "images/Banyan Tree Mayakoba/0302 - Banyan Tree Mayakoba - Lobby - main lobby water court with banyan tree at sunset.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/gallery", "dimensions": "2560x1706", "size": 1225284}, {"number": "0303", "file": "0303 - Banyan Tree Mayakoba - Saffron - overwater dining decks on the lagoon at dusk.jpg", "resort": "Banyan Tree Mayakoba", "space": "Saffron", "description": "Saffron, the signature Thai restaurant, is a cluster of open dining pavilions and three decks floating on the dark lagoon, reached by boat and lit at dusk by strings of warm lanterns whose reflections double the scene in the water. Roofs are low and broad on timber posts, tables sit under the sky on wooden decking, and the mangrove forest forms a black green wall around the restaurant, with the Ixchel boat and the stone lobby towers completing the view. The design lesson is atmosphere through restraint: natural deck timber, candle level lighting, and pavilions spaced so each table feels alone on the water. Recreate it with low pavilion roofs, festoon and lantern light only, and furniture kept dark and simple against water.", "src": "images/Banyan Tree Mayakoba/0303 - Banyan Tree Mayakoba - Saffron - overwater dining decks on the lagoon at dusk.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/dining/saffron", "dimensions": "2560x1707", "size": 861259}, {"number": "0304", "file": "0304 - Banyan Tree Mayakoba - The Rainforest - rain walk corridor with stone walls and brass pendants.jpg", "resort": "Banyan Tree Mayakoba", "space": "The Rainforest", "description": "The Rainforest hydrothermal trail begins with a rain walk, a narrow corridor of blackened stone walls down which sheets of warm water fall, lit by small recessed amber lights and oversized brushed brass globe pendants that blur in the foreground. The space is deliberately cave like, wet stone, steam, low golden light, so the body slows before treatment. Materials are the message: rough dark stone kept permanently wet and glossy, brass that will patina, and water used as architecture. To recreate the mood in a home spa, line a shower corridor in dark split face stone, add a rainfall ceiling, keep lighting low and amber, and use one or two large metal globe fittings as the only ornament.", "src": "images/Banyan Tree Mayakoba/0304 - Banyan Tree Mayakoba - The Rainforest - rain walk corridor with stone walls and brass pendants.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/spa/banyan-tree-spa-mayakoba", "dimensions": "2560x1941", "size": 951697}, {"number": "0305", "file": "0305 - Banyan Tree Mayakoba - Banyan Tree Spa - temazcal dome and fire circle in jungle garden.jpg", "resort": "Banyan Tree Mayakoba", "space": "Banyan Tree Spa", "description": "In a clearing in the spa garden stands the temazcal, a smooth white domed sweat lodge of Mayan tradition, fronted by a circular stone table inlaid with colour and ringed with low stools cut from single logs, curved timber benches and a flower filled soaking trough. Everything is hand made and elemental: lime washed masonry, rough stone, raw log sections, sand underfoot and dense jungle planting closing the circle. The palette is white, sand and green with small ritual hits of colour from flowers and textiles. To recreate a temazcal corner, combine one sculptural white dome or curved wall with log stools, a mosaic or inlaid round table, and let tropical planting form the walls of the room.", "src": "images/Banyan Tree Mayakoba/0305 - Banyan Tree Mayakoba - Banyan Tree Spa - temazcal dome and fire circle in jungle garden.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/spa/banyan-tree-spa-mayakoba", "dimensions": "2560x1794", "size": 1480863}, {"number": "0306", "file": "0306 - Banyan Tree Mayakoba - Banyan Tree Spa - treatment still life with tingsha cymbals and herbal scrub.jpg", "resort": "Banyan Tree Mayakoba", "space": "Banyan Tree Spa", "description": "A flat lay of the spa ritual objects on dark stained timber: a wooden bowl of white herbal scrub scattered with rosemary, engraved brass tingsha cymbals with Sanskrit style characters, fresh ginger root, and marigold and gerbera heads in saturated yellow and orange. This is the spa design language in miniature, Asian instruments and Ayurvedic ingredients presented like jewellery on dark wood, colour used sparingly and symbolically. For recreation, the details matter more than furniture: natural scrubs in turned wooden bowls, small brass sound instruments, fresh flowers and herbs, all arranged on dark timber trays or tables against a quiet background.", "src": "images/Banyan Tree Mayakoba/0306 - Banyan Tree Mayakoba - Banyan Tree Spa - treatment still life with tingsha cymbals and herbal scrub.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/spa/banyan-tree-spa-mayakoba", "dimensions": "2000x1332", "size": 988228}, {"number": "0307", "file": "0307 - Banyan Tree Mayakoba - Three-Bedroom Family Residence - living room with live edge timber coffee tables.jpg", "resort": "Banyan Tree Mayakoba", "space": "Three-Bedroom Family Residence", "description": "The renovated Three-Bedroom Family Residence living room is the Asia-Maya fusion at its most domestic: two deep cream sofas face each other across a pair of massive live edge timber coffee tables, on a woven natural fibre rug over dark slate floors. A vast woven rattan disc pendant hangs in the coffered, cove lit ceiling, open timber shelving displays books, coral and ceramics, and the dining area beyond repeats the pale wood and cream scheme. Colour is warm neutral throughout, lifted by texture, cane, weave, grain and matte ceramic, rather than pattern. To recreate it, invest in one or two sculptural solid wood tables, oversized woven lighting, cream upholstery and open shelving styled with natural objects.", "src": "images/Banyan Tree Mayakoba/0307 - Banyan Tree Mayakoba - Three-Bedroom Family Residence - living room with live edge timber coffee tables.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/three-bedroom-family-residence", "dimensions": "2560x1708", "size": 709211}, {"number": "0308", "file": "0308 - Banyan Tree Mayakoba - Three-Bedroom Family Residence - upper terrace pool with pergola and daybeds.jpg", "resort": "Banyan Tree Mayakoba", "space": "Three-Bedroom Family Residence", "description": "The residence upper terrace is a private rooftop world: a rectangular pool with glass balustrade at its edge, a timber sun deck with two cushioned loungers, and a shaded lounge pavilion under a flat pergola of dark posts, its back wall in pale stone with a long cream banquette and cushions. Stucco walls in warm sand enclose the space while jungle canopy fills every outward view. Materials repeat the interior story outdoors, warm timber, pale stone, cream canvas and sand coloured render. To recreate it, treat a terrace as a room: define a shade structure, a water element and a lounging wall, enclose it in warm render, and keep the furniture low, pale and few.", "src": "images/Banyan Tree Mayakoba/0308 - Banyan Tree Mayakoba - Three-Bedroom Family Residence - upper terrace pool with pergola and daybeds.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/accommodation/three-bedroom-family-residence", "dimensions": "2560x1920", "size": 942177}, {"number": "0309", "file": "0309 - Banyan Tree Mayakoba - Beachfront Villas - villa exterior and pool in jungle garden at sunset.jpg", "resort": "Banyan Tree Mayakoba", "space": "Beachfront Villas", "description": "At sunset a beachfront villa shows the resort architecture in one frame: a soaring pitched roof with a decorative lattice gable screen, deep shaded terraces, warm light glowing from full height glazing, and a still private pool laid like a mirror in a jungle garden of palms and layered tropical planting. The lattice gable is the Asia-Maya signature, part Thai roof, part Mayan screen, and the planting is allowed to touch the building on all sides. Colours are coral dusk sky, deep green and warm amber light. To recreate the look, give a garden building one exaggerated pitched roof with a patterned gable, light it warmly from inside, and plant densely right up to the walls.", "src": "images/Banyan Tree Mayakoba/0309 - Banyan Tree Mayakoba - Beachfront Villas - villa exterior and pool in jungle garden at sunset.jpg", "source": "https://www.banyantree.com/mexico/mayakoba/gallery", "dimensions": "2560x1706", "size": 1026961}, {"number": "0310", "file": "0310 - Nayara Bocas del Toro - Overwater Villa - terrace plunge pool and thatched villa at dusk.jpg", "resort": "Nayara Bocas del Toro", "space": "Overwater Villa", "description": "The villa terrace is the design statement: a rectangular stone plunge pool inset into the timber deck, a deep thatched alang roof sheltering an open lounge with daybeds, and the sea on three sides. Villas were crafted in Bali with over 1,000 hours of hand carving per villa, so expect dense teak joinery and carved panels rather than plain millwork. To recreate, pair a steep pitched thatch or shingle roof with wide eaves, dark stained decking, a stone rimmed plunge pool, low teak loungers with ecru cushions, and lantern lighting kept low and warm.", "src": "images/Nayara Bocas del Toro/0310 - Nayara Bocas del Toro - Overwater Villa - terrace plunge pool and thatched villa at dusk.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1920", "size": 469587}, {"number": "0311", "file": "0311 - Nayara Bocas del Toro - Overwater Villa - bedroom with carved Tumpang Sari canopy.jpg", "resort": "Nayara Bocas del Toro", "space": "Overwater Villa", "description": "A wide view across polished hardwood floors to the carved Balinese Tumpang Sari canopy bed, the tiered wooden crown draped with sheer white curtains that is the signature of every villa. A carved storage chest sits at the foot, woven wall discs and rattan shaded sconces warm the white walls, and a small desk and chair fill the window bay. Palette is white linen, honey teak and natural fibre. To recreate, commission or source a four poster with a stepped carved canopy, hang sheer cotton panels, keep bedding plain white, and add one patterned textile, here the batik style cushion, as the single accent.", "src": "images/Nayara Bocas del Toro/0311 - Nayara Bocas del Toro - Overwater Villa - bedroom with carved Tumpang Sari canopy.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1708", "size": 455041}, {"number": "0312", "file": "0312 - Nayara Bocas del Toro - Overwater Villa - bathroom with patterned tiles and double vanity.jpg", "resort": "Nayara Bocas del Toro", "space": "Overwater Villa", "description": "The bathroom mixes Balinese carving with playful pattern: encaustic look patterned tiles in ochre, rust and slate cover the floor and climb the shower wall, against a long double vanity with vessel basins, a timber framed mirror and open shelving stacked with white towels. Louvred timber doors, a carved robe closet and a rustic wooden bench keep the room grounded in craft. To recreate, commit pattern to floor and one wet wall only, balance it with plain white plaster, thick timber shelving, blackened taps, and woven baskets for storage.", "src": "images/Nayara Bocas del Toro/0312 - Nayara Bocas del Toro - Overwater Villa - bathroom with patterned tiles and double vanity.jpg", "source": "https://nayarabocasdeltoro.com/stay/", "dimensions": "2560x1708", "size": 757234}, {"number": "0313", "file": "0313 - Nayara Bocas del Toro - Presidential Overwater Villa - tiered thatch villa over the water.jpg", "resort": "Nayara Bocas del Toro", "space": "Presidential Overwater Villa", "description": "The Presidential Villa reads as a small Balinese compound on stilts: two tiered thatch roofed pavilions in hand worked timber, a broad sun deck with cushioned loungers and a plunge pool, and steps straight down to the sea. Carved fascia boards and woven wall panels show the Bali built construction. To recreate the look at any scale, use layered pitched roofs at different heights, exposed timber framing left natural, deck furniture in teak with canvas cushions, and keep the structure raised so the building floats above the waterline planting.", "src": "images/Nayara Bocas del Toro/0313 - Nayara Bocas del Toro - Presidential Overwater Villa - tiered thatch villa over the water.jpg", "source": "https://nayarabocasdeltoro.com/stay/", "dimensions": "1920x1080", "size": 223395}, {"number": "0314", "file": "0314 - Nayara Bocas del Toro - Presidential Overwater Villa - indoor infinity pool hall with branch chandelier.jpg", "resort": "Nayara Bocas del Toro", "space": "Presidential Overwater Villa", "description": "Inside the Presidential Villa a narrow saltwater infinity pool runs down the centre of the main hall toward the ocean view, flanked by stone columns, daybed platforms with bolster cushions and a sculptural tree branch chandelier overhead. Painted mural panels soften the gable ends and woven rugs warm the timber floor. To recreate, treat the pool as a reflecting rill inside the room, line it with low lounge platforms instead of chairs, use rough stone or plaster columns, and hang one organic branch or root chandelier as the single dramatic light.", "src": "images/Nayara Bocas del Toro/0314 - Nayara Bocas del Toro - Presidential Overwater Villa - indoor infinity pool hall with branch chandelier.jpg", "source": "https://nayarabocasdeltoro.com/stay/", "dimensions": "1920x1080", "size": 548736}, {"number": "0315", "file": "0315 - Nayara Bocas del Toro - Presidential Overwater Villa - living and dining room with carved doors.jpg", "resort": "Nayara Bocas del Toro", "space": "Presidential Overwater Villa", "description": "The living and dining end of the Presidential Villa is anchored by monumental hand carved timber doors and matching carved door surrounds, with a woven pendant cluster over the round dining table, low sofas with loose cushions, a woven floor rug and landscape art in soft greens. Earthy plaster walls and exposed beams keep the carving as the hero. To recreate, invest in one pair of genuinely carved doors or panels, keep upholstery plain linen in sand tones, choose a round table to soften the heavy timber, and light with woven pendants rather than metal fittings.", "src": "images/Nayara Bocas del Toro/0315 - Nayara Bocas del Toro - Presidential Overwater Villa - living and dining room with carved doors.jpg", "source": "https://nayarabocasdeltoro.com/stay/", "dimensions": "1920x1080", "size": 309361}, {"number": "0316", "file": "0316 - Nayara Bocas del Toro - Treehouse - tiered bamboo treehouse above the mangroves.jpg", "resort": "Nayara Bocas del Toro", "space": "Treehouse", "description": "From above, the IBUKU treehouse shows its stacked composition: conical shingled roofs tiered like a pagoda, curved bamboo balconies wrapping each level, and the whole structure lifted fifty feet on slender poles above the mangrove canopy. Designed by Elora Hardy of IBUKU and built from locally harvested bamboo with hardwoods reclaimed from the Panama Canal floor. To recreate the silhouette, stack shrinking roof tiers, curve every balcony rail, keep supports visually light, and let planting grow right up to the structure so it reads as grown rather than built.", "src": "images/Nayara Bocas del Toro/0316 - Nayara Bocas del Toro - Treehouse - tiered bamboo treehouse above the mangroves.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1721", "size": 792343}, {"number": "0317", "file": "0317 - Nayara Bocas del Toro - Treehouse - open air living room with bamboo columns.jpg", "resort": "Nayara Bocas del Toro", "space": "Treehouse", "description": "The top floor living room is a bamboo pavilion in the round: soaring structural bamboo poles, a woven bamboo ceiling, rattan lounge chairs and a curved banquette around a low timber table, with a small kitchen counter tucked behind. Nothing is straight or machined, every member follows the natural taper of the pole. To recreate, use real bamboo or bamboo look poles as structure, not decoration, choose rounded rattan seating with loose ecru cushions, lay a flat weave rug to define the group, and hang clustered woven pendants at varied heights.", "src": "images/Nayara Bocas del Toro/0317 - Nayara Bocas del Toro - Treehouse - open air living room with bamboo columns.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1708", "size": 448794}, {"number": "0318", "file": "0318 - Nayara Bocas del Toro - Treehouse - bedroom with bamboo lattice walls and woven pendant.jpg", "resort": "Nayara Bocas del Toro", "space": "Treehouse", "description": "The treehouse bedroom wraps the bed in woven bamboo lattice screens in a diamond pattern, with terra cotta and sand bedding, a carved timber bench, and a large woven pendant glowing overhead. Floor to ceiling glass and drapes open to the canopy, so the room feels held inside the forest. To recreate, line the bed wall with woven bamboo or rattan lattice panels, keep the palette to bark, clay and flax, add one oversized woven light fitting, and use blackened timber trim to frame the openings.", "src": "images/Nayara Bocas del Toro/0318 - Nayara Bocas del Toro - Treehouse - bedroom with bamboo lattice walls and woven pendant.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1708", "size": 579841}, {"number": "0319", "file": "0319 - Nayara Bocas del Toro - Treehouse - bedroom with woven textile wall hanging.jpeg", "resort": "Nayara Bocas del Toro", "space": "Treehouse", "description": "A second treehouse bedroom in a warmer key: a full width woven textile hanging in black, gold and rust geometry behind the bed, saffron bedding, a round rattan peacock style chair with cushions, and a long timber bench at the foot. Dark stained bamboo and timber walls make the textile glow. To recreate, hang one large woven panel or tapestry as the headboard wall, pick up its colours in the bed cushions only, and furnish with rattan and solid timber pieces kept low so the hanging dominates.", "src": "images/Nayara Bocas del Toro/0319 - Nayara Bocas del Toro - Treehouse - bedroom with woven textile wall hanging.jpeg", "source": "https://nayarabocasdeltoro.com/stay/", "dimensions": "1280x854", "size": 427256}, {"number": "0320", "file": "0320 - Nayara Bocas del Toro - The Elephant House - timber dining hall with patterned tile floor.jpg", "resort": "Nayara Bocas del Toro", "space": "The Elephant House", "description": "The Elephant House interior is a century old Balinese building shipped from Indonesia and rebuilt on its own pier: massive carved timber columns and beams, a patterned tile floor in soft grey and cream geometry, white clothed tables, woven rattan pendants and a long cushioned daybed down the centre. Carved doors close the far wall. To recreate, build the room around reclaimed or carved structural timber, lay a repeating patterned tile across the whole floor, keep table linen white, and use one long central bench or daybed as the spine of the plan.", "src": "images/Nayara Bocas del Toro/0320 - Nayara Bocas del Toro - The Elephant House - timber dining hall with patterned tile floor.jpg", "source": "https://nayarabocasdeltoro.com/eat/", "dimensions": "1773x1182", "size": 515387}, {"number": "0321", "file": "0321 - Nayara Bocas del Toro - The Elephant House - candlelit private dining terrace.jpg", "resort": "Nayara Bocas del Toro", "space": "The Elephant House", "description": "Private dining on the Elephant House terrace at night: a scalloped Balinese arch glowing amber, turned stone balusters lining the pier, a checkerboard tile floor scattered with rose petals and candles, and a single table dressed in gold patterned cloth. The architecture does all the decorating. To recreate, frame one dining position with an arched or carved opening, use balustrade or screen edges to enclose it, lay bold patterned tile, and light only with candles and one warm wash on the arch so the setting reads after dark.", "src": "images/Nayara Bocas del Toro/0321 - Nayara Bocas del Toro - The Elephant House - candlelit private dining terrace.jpg", "source": "https://nayarabocasdeltoro.com/eat/", "dimensions": "1440x960", "size": 284567}, {"number": "0322", "file": "0322 - Nayara Bocas del Toro - Coral Cafe - cafe interior with cloud pendants and mural.jpg", "resort": "Nayara Bocas del Toro", "space": "Coral Cafe", "description": "The Coral Café is a light flooded pavilion of slender timber columns filled with dozens of woven cloud pendants at ceiling height, white cafe tables and rattan chairs, and a full wall mural inlaid with hundreds of hand painted wooden shakes in sea blues, greens and coral. To recreate, cluster many large woven pendants until they form a ceiling canopy, keep furniture white and simple, and make one wall a mosaic of painted timber pieces in an ombre from turquoise to red, with plants used as the only other colour.", "src": "images/Nayara Bocas del Toro/0322 - Nayara Bocas del Toro - Coral Cafe - cafe interior with cloud pendants and mural.jpg", "source": "https://nayarabocasdeltoro.com/eat/", "dimensions": "2560x1708", "size": 927587}, {"number": "0323", "file": "0323 - Nayara Bocas del Toro - Coral Cafe - bar with hand painted wooden shake mural.jpg", "resort": "Nayara Bocas del Toro", "space": "Coral Cafe", "description": "Close on the Coral Café bar: a long timber counter with white bar stools, back bar shelving in dark wood, and the signature mural of hand painted wooden shakes rising behind it in pixel like blocks of blue, green, yellow and red. Oversized woven pendants hang in the foreground and the room opens straight to the garden. To recreate, build the mural from small painted timber offcuts fixed as tiles, keep the counter plain honed timber, choose simple white stools, and let the mural supply every accent colour in the space.", "src": "images/Nayara Bocas del Toro/0323 - Nayara Bocas del Toro - Coral Cafe - bar with hand painted wooden shake mural.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1708", "size": 536024}, {"number": "0324", "file": "0324 - Nayara Bocas del Toro - The Colonnade - clubhouse and freshwater pool at night.jpg", "resort": "Nayara Bocas del Toro", "space": "The Colonnade", "description": "The Colonnade clubhouse at night, the social centre of the island: a low pavilion with a wide hipped roof and green painted pergola framing the seventy foot freshwater infinity pool, loungers lined along the water and the Coral Café glowing behind glass. To recreate the mood, keep the building low and horizontal, mirror it in a long still pool, use pergola shade instead of solid walls at the pool edge, and light from inside the building and under the water so the whole composition glows as one.", "src": "images/Nayara Bocas del Toro/0324 - Nayara Bocas del Toro - The Colonnade - clubhouse and freshwater pool at night.jpg", "source": "https://nayarabocasdeltoro.com/gallery/", "dimensions": "2560x1708", "size": 368188}, {"number": "0325", "file": "0325 - Nayara Bocas del Toro - Spa - open air massage deck beside the pool.jpg", "resort": "Nayara Bocas del Toro", "space": "Spa", "description": "Spa treatments happen in the open air on timber decks like this one, seen from above: a massage table dressed in white and sage beside a dark stone plunge and shower slab, thatch overhead and the sea or pool at the edge of the deck. The palette is pure material, weathered timber, black stone, white linen. To recreate, build treatment spaces as simple deck platforms, use dark stone for the wet zone, dress tables in white with one muted green or sand throw, and keep every fitting timber or stone so the setting stays elemental.", "src": "images/Nayara Bocas del Toro/0325 - Nayara Bocas del Toro - Spa - open air massage deck beside the pool.jpg", "source": "https://nayarabocasdeltoro.com/unwind/", "dimensions": "1920x1079", "size": 915549}, {"number": "0326", "file": "0326 - Six Senses Zil Pasyon - Hideaway Pool Villa - four poster bedroom and living area.jpg", "resort": "Six Senses Zil Pasyon", "space": "Hideaway Pool Villa", "description": "The villa interior is one open timber lined room under a boarded wood ceiling, the black framed four poster bed draped in sheer white mosquito netting and dressed in white linen with a long turquoise upholstered daybed at its foot. Sliding glass walls open to the pool terrace, and the living zone carries a low timber lounge chair with teal cushioning, a drum shaped stone side table and a woven blue grey rug over dark wood floors. To recreate the look, pair warm mid tone timber panelling and ceilings with black metal bed framing, one saturated turquoise textile accent, natural fibre rugs and unlacquered stone accessories, keeping every other fabric white or oatmeal so the vegetation outside supplies the colour.", "src": "images/Six Senses Zil Pasyon/0326 - Six Senses Zil Pasyon - Hideaway Pool Villa - four poster bedroom and living area.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/accommodation/hideaway-pool-villa/", "dimensions": "2560x1708", "size": 949325}, {"number": "0327", "file": "0327 - Six Senses Zil Pasyon - Panorama Pool Villa - four poster bedroom opening to pool deck.jpg", "resort": "Six Senses Zil Pasyon", "space": "Panorama Pool Villa", "description": "The bedroom faces the ocean through a fully glazed wall and opens straight onto the deck and infinity pool, so the black four poster bed with its sheer canopy is read against water and sky. A turquoise bolster daybed runs along the foot of the bed, with a woven indigo rug, a round carved timber stool and a framed botanical print in muted reds on the timber panelled wall behind. Recreate it with a boarded timber ceiling and wall linings, white bed linen, one strong blue green upholstered piece, flatweave rugs in sea colours and artwork kept to a single framed print so the panorama stays dominant.", "src": "images/Six Senses Zil Pasyon/0327 - Six Senses Zil Pasyon - Panorama Pool Villa - four poster bedroom opening to pool deck.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/accommodation/panorama-pool-villa/", "dimensions": "2560x1507", "size": 653252}, {"number": "0328", "file": "0328 - Six Senses Zil Pasyon - Panorama Pool Villa - bathroom with swing seat and freestanding tub.jpg", "resort": "Six Senses Zil Pasyon", "space": "Panorama Pool Villa", "description": "The bathroom is arranged symmetrically around the view, with a freestanding oval soaking tub centred on the window and a cushioned swing seat suspended in front of it, the signature detail the resort itself describes for these villas. Twin timber washstands with drawers flank the tub, carrying stone vessel basins, wall mounted lantern sconces and rolled white towels, all in warm wood against grey green plaster and stone. To recreate it, use paired timber vanities with vessel basins, an oval freestanding tub on the window axis, a hanging daybed or swing bench in pale upholstery, and lantern style lighting in blackened metal, keeping the palette to wood, stone and white.", "src": "images/Six Senses Zil Pasyon/0328 - Six Senses Zil Pasyon - Panorama Pool Villa - bathroom with swing seat and freestanding tub.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/accommodation/panorama-pool-villa/", "dimensions": "2560x1580", "size": 579267}, {"number": "0329", "file": "0329 - Six Senses Zil Pasyon - Oceanfront Pool Villa - pool deck with loungers above the ocean.jpg", "resort": "Six Senses Zil Pasyon", "space": "Oceanfront Pool Villa", "description": "The deck is a study in horizontal timber, with wide plank decking, a rectangular infinity pool edged in dark mosaic and two cushioned timber sun loungers angled to the sea, the villa's shingle roof and timber cladding just visible at the edge of frame. A low blue ceramic garden stool is the single colour accent. Recreate the look with silvered teak decking, simply framed loungers in natural canvas, frameless glass balustrades so nothing interrupts the horizon, and planting kept wild and green around the built edge.", "src": "images/Six Senses Zil Pasyon/0329 - Six Senses Zil Pasyon - Oceanfront Pool Villa - pool deck with loungers above the ocean.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/accommodation/oceanfront-pool-villa/", "dimensions": "2560x1657", "size": 870851}, {"number": "0330", "file": "0330 - Six Senses Zil Pasyon - Two-Bedroom Pool Villa - covered dining deck beside granite boulder.jpg", "resort": "Six Senses Zil Pasyon", "space": "Two-Bedroom Pool Villa", "description": "The covered deck is built around a giant weathered granite boulder that rises straight through the terrace beside the pool, and the design leans into it rather than screening it. A heavy timber dining table with simple slatted chairs sits under the pitched shingle roof, with low lounge seating, round timber stools and a woven jute rug in the foreground. To recreate it, anchor an outdoor room with one oversized natural feature, use chunky unadorned timber furniture, woven fibre rugs and cushions in sand and ochre linen, and keep the roof structure exposed in dark stained wood.", "src": "images/Six Senses Zil Pasyon/0330 - Six Senses Zil Pasyon - Two-Bedroom Pool Villa - covered dining deck beside granite boulder.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/accommodation/two-bedroom-pool-villa/", "dimensions": "2560x1705", "size": 1134671}, {"number": "0331", "file": "0331 - Six Senses Zil Pasyon - Seascape Three-Bedroom Residence - master bedroom with glass walls.jpg", "resort": "Six Senses Zil Pasyon", "space": "Seascape Three-Bedroom Residence", "description": "The Seascape master bedroom is wrapped in glass on three sides, with a slatted timber ceiling, wide plank floors and a low platform bed in white linen facing the ocean, flanked by open timber shelving and a long upholstered bench at its foot. Pale lounge chairs and unadorned joinery keep the room almost monastic so the granite and sea become the decoration, exactly the stealth architecture Studio RHE describes for the residences. Recreate it with full height glazing, warm oak tones throughout, built in open shelving instead of freestanding storage, and textiles limited to white, bone and pale sage.", "src": "images/Six Senses Zil Pasyon/0331 - Six Senses Zil Pasyon - Seascape Three-Bedroom Residence - master bedroom with glass walls.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1707", "size": 917361}, {"number": "0332", "file": "0332 - Six Senses Zil Pasyon - Seascape Three-Bedroom Residence - pool terrace and living room at dusk.jpg", "resort": "Six Senses Zil Pasyon", "space": "Seascape Three-Bedroom Residence", "description": "Shot at dusk as a split view, one half shows the residence's glass bottomed pool glowing above the timber deck with two loungers and an umbrella, the other half the living room behind glass, with a timber lined ceiling, cove lighting, low cream sofas, timber armchairs and a wall mounted screen on a stone clad wall. The blue lit ceiling recess in the living room mirrors the pool water colour. To recreate the evening mood, combine concealed warm cove lighting with one cool blue accent, stone cladding used as a single feature wall, and low horizontal furniture that keeps sightlines under the ceiling line.", "src": "images/Six Senses Zil Pasyon/0332 - Six Senses Zil Pasyon - Seascape Three-Bedroom Residence - pool terrace and living room at dusk.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1709", "size": 694860}, {"number": "0333", "file": "0333 - Six Senses Zil Pasyon - Ocean Sounds Four-Bedroom Residence - living and dining room under glass bottom pool.jpg", "resort": "Six Senses Zil Pasyon", "space": "Ocean Sounds Four-Bedroom Residence", "description": "The great room of Ocean Sounds is roofed by the transparent base of the pool above, so rippled blue light falls across the timber ceiling beams and the whole living and dining space. A long rough sawn timber dining table with curved back dining chairs in pale aqua upholstery runs down one side, while timber framed lounge chairs and a low coffee table face the glass wall and the sea, with granite clad columns grounding the room. Recreate it with exposed stone columns, one very long communal timber table, aqua and sand upholstery, hurricane lanterns as table objects, and as much glazing as the structure allows.", "src": "images/Six Senses Zil Pasyon/0333 - Six Senses Zil Pasyon - Ocean Sounds Four-Bedroom Residence - living and dining room under glass bottom pool.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1707", "size": 909085}, {"number": "0334", "file": "0334 - Six Senses Zil Pasyon - Ocean Sounds Four-Bedroom Residence - master bedroom with glass walls.jpg", "resort": "Six Senses Zil Pasyon", "space": "Ocean Sounds Four-Bedroom Residence", "description": "This panoramic master bedroom sits inside the granite clad residence volume, glass walled to the boulders and the sea, with a slatted timber ceiling, a low timber platform bed dressed in white, open shelving in pale oak behind the bedhead and a pair of cream upholstered lounge chairs. The room is deliberately bare of ornament, letting rock, water and sky act as the art. To recreate it, use a restrained palette of oak, white linen and cream boucle or canvas, platform furniture with no visible legs where possible, and integrated shelving lit softly from within.", "src": "images/Six Senses Zil Pasyon/0334 - Six Senses Zil Pasyon - Ocean Sounds Four-Bedroom Residence - master bedroom with glass walls.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1043", "size": 522926}, {"number": "0335", "file": "0335 - Six Senses Zil Pasyon - Six Senses Spa - elevated saltwater pool among granite boulders.jpg", "resort": "Six Senses Zil Pasyon", "space": "Six Senses Spa", "description": "The spa's elevated saltwater pool is a curved, stone edged pod set directly into the granite outcrop above the sea, reached by a timber boardwalk and edged with a low deck and loungers, so the built form reads as one more boulder in the landscape. The waterline follows the rock, and planting is left as found scrub and palm. To recreate this, shape a small pool organically rather than geometrically, face it in rough stone or stone look render, connect it with simple timber walkways, and let raw rock dominate every sightline.", "src": "images/Six Senses Zil Pasyon/0335 - Six Senses Zil Pasyon - Six Senses Spa - elevated saltwater pool among granite boulders.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1913", "size": 1069916}, {"number": "0336", "file": "0336 - Six Senses Zil Pasyon - Six Senses Spa - Ocean treatment villa among the boulders.jpg", "resort": "Six Senses Zil Pasyon", "space": "Six Senses Spa", "description": "The Ocean treatment villa is a small refined timber pavilion slotted between enormous granite boulders above the water, its louvred and glazed walls opening to a private deck with two treatment beds visible inside, reached through the rock field that the spa was built around without moving a single boulder. A thatched shade pavilion stands on the rocks nearby. Recreate the spa villa look with vertical timber cladding, louvre screens for privacy and air, a simple pitched roof, and furniture limited to treatment beds and a single bench, all in weathered natural finishes.", "src": "images/Six Senses Zil Pasyon/0336 - Six Senses Zil Pasyon - Six Senses Spa - Ocean treatment villa among the boulders.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1919", "size": 882558}, {"number": "0337", "file": "0337 - Six Senses Zil Pasyon - Island Cafe - restaurant interior with stone counter and cane chairs.jpg", "resort": "Six Senses Zil Pasyon", "space": "Island Cafe", "description": "The all day restaurant interior mixes a rough stone faced service counter with a coffered dark timber ceiling, clusters of small exposed bulb pendants on black cords, and cane backed dining chairs with timber tables set for service, one turquoise glass demijohn used as a counter accent. Bar stools in turned wood and blue painted metal sit at the counter. To recreate it, combine one rustic stone element, woven cane chair backs, bare bulb pendant clusters at varied heights, and a single repeated glass colour accent, keeping tableware and linens plain white.", "src": "images/Six Senses Zil Pasyon/0337 - Six Senses Zil Pasyon - Island Cafe - restaurant interior with stone counter and cane chairs.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/dining/island-cafe/", "dimensions": "2560x1920", "size": 1042988}, {"number": "0338", "file": "0338 - Six Senses Zil Pasyon - Ocean Kitchen - bar with woven stools under thatched roof.jpg", "resort": "Six Senses Zil Pasyon", "space": "Ocean Kitchen", "description": "Ocean Kitchen's bar is a curved stone counter under a high radial thatched roof carried on dark timber posts, with a row of high stools whose backs and seats are woven in a green and natural checker weave, and dining tables set on the deck behind facing the sea through the granite boulders. Recreate it with a fan or radial thatch ceiling, a masonry bar front in rough stone, woven panel stools in a two tone check, and dark stained structural timber throughout.", "src": "images/Six Senses Zil Pasyon/0338 - Six Senses Zil Pasyon - Ocean Kitchen - bar with woven stools under thatched roof.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/dining/", "dimensions": "2560x1704", "size": 1043364}, {"number": "0339", "file": "0339 - Six Senses Zil Pasyon - Chef's Kitchen - chefs table counter with canvas director stools.jpg", "resort": "Six Senses Zil Pasyon", "space": "Chef's Kitchen", "description": "The chef's table is a straight timber counter fronted by four folding director style stools with natural canvas seats and backs, set against louvred timber doors and open shelves carrying ceramic bowls, glass jars and produce. Dozens of small pendants on cords hang at different heights above the counter, and the walls are finished in rough grey plaster. To recreate it, line up simple canvas and timber stools at a working counter, use open shelving with honest ceramics and jars as the display, and cluster many small warm pendants rather than one statement fitting.", "src": "images/Six Senses Zil Pasyon/0339 - Six Senses Zil Pasyon - Chef's Kitchen - chefs table counter with canvas director stools.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1842", "size": 848137}, {"number": "0340", "file": "0340 - Six Senses Zil Pasyon - Main Pool - elongated main pool and thatched pavilion.jpg", "resort": "Six Senses Zil Pasyon", "space": "Main Pool", "description": "The main pool is a long still rectangle of water, rebuilt over the old seawall as Hospitality Design records, running towards a thatched roof pavilion on white columns, with timber decking, rows of loungers and the restaurant building under the trees behind. The planting is mature and unmanicured, and the palette is water green, timber and white. To recreate it, keep the pool a simple elongated rectangle with a mirror still surface, use a single open pavilion as the focal point, and frame everything with large existing trees rather than ornamental planting.", "src": "images/Six Senses Zil Pasyon/0340 - Six Senses Zil Pasyon - Main Pool - elongated main pool and thatched pavilion.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1782", "size": 914586}, {"number": "0341", "file": "0341 - Six Senses Zil Pasyon - Library - attic library lounge with woven ceiling.jpg", "resort": "Six Senses Zil Pasyon", "space": "Library", "description": "The library occupies a dramatic attic under a steep pitched roof lined in woven matting between dark timber trusses, with low rattan lounge chairs, round timber side tables, a banquette in cream cushions along one side and shelves of books at the far gable, all lit by table lamps with pale shades. It is the resort's most interior, cocooning space. Recreate it with a woven or rush lined vaulted ceiling, exposed dark trusses, low woven seating, and warm lamp light instead of downlights, keeping fabrics in cream and natural tones.", "src": "images/Six Senses Zil Pasyon/0341 - Six Senses Zil Pasyon - Library - attic library lounge with woven ceiling.jpg", "source": "https://www.sixsenses.com/en/hotels-resorts/middle-east-africa/seychelles/zil-pasyon/gallery/", "dimensions": "2560x1593", "size": 982924}, {"number": "0342", "file": "0342 - COMO Laucala Island - Plantation Residence - aerial view of free form pool among thatched bures.jpg", "resort": "COMO Laucala Island", "space": "Plantation Residence", "description": "Aerial view of a Plantation Residence private pool, a free form lagoon with scalloped stone edging, pebble mosaic bands and carved stone bowls, wrapped by sago palm thatched bures and dense tropical planting. The pool geometry copies natural rock pools rather than a rectangle, and planting is allowed to crowd the water so the residence feels grown rather than built. To recreate the look, pair an irregular stone edged pool with thatched pavilions, local hardwood decking, woven cocoon loungers and a palette drawn from lagoon turquoise, sand and deep foliage green.", "src": "images/COMO Laucala Island/0342 - COMO Laucala Island - Plantation Residence - aerial view of free form pool among thatched bures.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plantation.html", "dimensions": "1920x1011", "size": 581877}, {"number": "0343", "file": "0343 - COMO Laucala Island - Plantation Residence - curved pool deck with cocoon lounger.jpg", "resort": "COMO Laucala Island", "space": "Plantation Residence", "description": "A Plantation Residence at pool level, where a long curving pool with a pebble mosaic edge runs along a wide local timber deck in front of a row of sago thatched bures with full height glass doors. A woven cocoon lounger anchors the deck and a separate thatched pavilion shades outdoor dining. Recreate with horizontal deck boards, free form pool curves, woven outdoor furniture in natural fibre, and restrained planting of grasses and palms against the thatch.", "src": "images/COMO Laucala Island/0343 - COMO Laucala Island - Plantation Residence - curved pool deck with cocoon lounger.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plantation.html", "dimensions": "1920x1080", "size": 543275}, {"number": "0344", "file": "0344 - COMO Laucala Island - Plantation Residence - bathroom with granite tub carved from a single block.jpg", "resort": "COMO Laucala Island", "space": "Plantation Residence", "description": "The Plantation Residence bathroom is built around a freestanding bathtub carved from a single block of granite, its rough natural exterior set against polished stone slab floors and walls. A bamboo ladder serves as the towel rail, stone vessel basins sit on a live edge timber vanity, and louvred doors open to the garden so the room reads as an indoor outdoor pavilion. To recreate it, commission one oversized carved stone piece as the hero and keep every other surface in raw stone, bamboo and dark timber.", "src": "images/COMO Laucala Island/0344 - COMO Laucala Island - Plantation Residence - bathroom with granite tub carved from a single block.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plantation.html", "dimensions": "1920x1080", "size": 379739}, {"number": "0345", "file": "0345 - COMO Laucala Island - Seagrass Residence - bedroom with four poster bed and shell chandelier.jpg", "resort": "COMO Laucala Island", "space": "Seagrass Residence", "description": "A Seagrass Residence bedroom with a four poster bed dressed in white linen and sheer drapes, its posts and the exposed rafters bound with dyed magimagi coconut husk twine under a woven sago thatch ceiling. A chandelier of shells and coconut discs hangs like a jellyfish above fringed cocoon chairs and ottomans in natural fibre, set on a teal wave patterned rug over polished local timber floors. Cream plaster walls and blue green accents taken from the lagoon complete the palette. Recreate with a draped canopy bed, handmade fibre seating, one statement organic pendant and a single coloured rug on dark wood.", "src": "images/COMO Laucala Island/0345 - COMO Laucala Island - Seagrass Residence - bedroom with four poster bed and shell chandelier.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/seagrass.html", "dimensions": "1920x1080", "size": 286984}, {"number": "0346", "file": "0346 - COMO Laucala Island - Seagrass Residence - bathroom with carved timber tub and stone slab walls.jpg", "resort": "COMO Laucala Island", "space": "Seagrass Residence", "description": "The Seagrass Residence bathroom pairs a deep soaking tub hand carved from a single dark timber trunk and shaped like a canoe with walls and floors of large fitted stone slabs. A stone vessel basin rests on a live edge timber vanity lit by cylindrical woven pendants, and glass doors open straight into tropical planting so bathing feels semi alfresco. Recreate with one sculptural carved tub, honest stone surfaces, woven lighting and a strict palette of charcoal, bark brown and leaf green.", "src": "images/COMO Laucala Island/0346 - COMO Laucala Island - Seagrass Residence - bathroom with carved timber tub and stone slab walls.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/seagrass.html", "dimensions": "1920x1080", "size": 418497}, {"number": "0347", "file": "0347 - COMO Laucala Island - Seagrass Residence - thatched pool gazebo with daybed and floor cushions.jpg", "resort": "COMO Laucala Island", "space": "Seagrass Residence", "description": "A Seagrass Residence pool terrace built around a circular thatched gazebo on dark timber posts, sheltering a round daybed piled with slate and sage cushions beside an infinity pool that runs toward the beach. A woven rattan tub chair, swirl patterned floor cushions in lagoon blue, black metal lanterns and a lantern hanging from a tree branch furnish the deck. Recreate with a steep sago thatch canopy, a low round daybed, natural fibre accent chairs and textiles patterned from waves and coral.", "src": "images/COMO Laucala Island/0347 - COMO Laucala Island - Seagrass Residence - thatched pool gazebo with daybed and floor cushions.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/seagrass.html", "dimensions": "1920x1080", "size": 570781}, {"number": "0348", "file": "0348 - COMO Laucala Island - Plateau Residence - pool terrace in hilltop garden.jpg", "resort": "COMO Laucala Island", "space": "Plateau Residence", "description": "A Plateau Residence seen across its private pool, a calm rectangle of mosaic tiled water edged with stone and set in dense hilltop planting below steep sago thatched roofs. A woven cocoon lounger waits on the terrace and the garden is left lush and unstructured so the architecture sits inside the rainforest canopy. Recreate with a simple geometric pool as a quiet counterpoint to wild planting, natural fibre loungers and deep eaves of thatch.", "src": "images/COMO Laucala Island/0348 - COMO Laucala Island - Plateau Residence - pool terrace in hilltop garden.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plateau.html", "dimensions": "1920x1080", "size": 552510}, {"number": "0349", "file": "0349 - COMO Laucala Island - Plateau Residence - free form pool with stone bowl and thatched bures.jpg", "resort": "COMO Laucala Island", "space": "Plateau Residence", "description": "A Plateau Residence arranged behind a free form pool with pebble mosaic walls, a lower plunge basin and a carved stone bowl set on the coping. Three sago thatched bures open onto the deck, the central one showing a curved built in sofa with round cushions, and a woven cocoon daybed sits by the water. Recreate with layered water levels, stone and pebble surfaces, curved plastered seating and thatch roofs of different heights grouped like a village.", "src": "images/COMO Laucala Island/0349 - COMO Laucala Island - Plateau Residence - free form pool with stone bowl and thatched bures.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plateau.html", "dimensions": "1920x1080", "size": 539333}, {"number": "0350", "file": "0350 - COMO Laucala Island - Plateau Residence - living room with curved sofa and shell chandelier.jpg", "resort": "COMO Laucala Island", "space": "Plateau Residence", "description": "The Plateau Residence living room is furnished with a sweeping curved sofa in cream upholstery, a live edge timber coffee table and a woven lounge chair, all on a grey shag rug over local timber boards. A chandelier of shells and coconut discs hangs above, folding doors open to the pool deck, and the view runs through planting to the sea. Recreate with one big sculptural curved sofa, organic timber tables, fibre and shell lighting, and a neutral palette lifted by garden green.", "src": "images/COMO Laucala Island/0350 - COMO Laucala Island - Plateau Residence - living room with curved sofa and shell chandelier.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/plateau.html", "dimensions": "1920x1080", "size": 351260}, {"number": "0351", "file": "0351 - COMO Laucala Island - Overwater Residence - thatched bures on stilts above the lagoon.jpg", "resort": "COMO Laucala Island", "space": "Overwater Residence", "description": "The Wai overwater residence from the lagoon, a linked row of sago thatched bures on timber piles with wraparound decks, stairs down into the water and a jetty deck with loungers and umbrellas. Roofs are steep pitched thatch with carved finials, walls are dark stained timber, and the whole composition floats between the rainforest shore and the reef. Recreate the feel with stilted pavilions, continuous decking, thatch at varied heights and furniture kept to low loungers and woven pieces.", "src": "images/COMO Laucala Island/0351 - COMO Laucala Island - Overwater Residence - thatched bures on stilts above the lagoon.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/wai.html", "dimensions": "1920x1011", "size": 473026}, {"number": "0352", "file": "0352 - COMO Laucala Island - Overwater Residence - bedroom opening to deck above the sea.jpg", "resort": "COMO Laucala Island", "space": "Overwater Residence", "description": "A Wai Residence bedroom under a soaring woven ceiling whose rafters are lashed with magimagi coconut husk twine, lit by woven sphere pendants. The bed faces full width folding doors opening to a deck above the sea, with a cushioned bench seat, woven lounge chairs, a wave patterned rug in lagoon tones and dark polished timber floors. Recreate with exposed lashed beams, a restrained bed wall, natural weave lighting and blue green textiles drawn from the water outside.", "src": "images/COMO Laucala Island/0352 - COMO Laucala Island - Overwater Residence - bedroom opening to deck above the sea.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/wai.html", "dimensions": "1920x1011", "size": 297419}, {"number": "0353", "file": "0353 - COMO Laucala Island - Overwater Residence - bathroom with giant carved timber bowl tub.jpg", "resort": "COMO Laucala Island", "space": "Overwater Residence", "description": "The Wai Residence bathroom centres on an enormous turned timber bowl bathtub, big enough to define the room, set on flagstone floors against fitted stone walls. A natural branch handrail lashed with magimagi runs past folding glass doors to the deck and the open sea, dried grass tassels hang from the thatch ceiling, and a live edge vanity carries a matching timber vessel basin beside a woven basket and a cylindrical rattan wall light. Recreate with one oversized carved timber piece, stone underfoot, lashed branch rails and woven lighting.", "src": "images/COMO Laucala Island/0353 - COMO Laucala Island - Overwater Residence - bathroom with giant carved timber bowl tub.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/wai.html", "dimensions": "1920x1011", "size": 328233}, {"number": "0354", "file": "0354 - COMO Laucala Island - Peninsula Residence - aerial view of cliff top bures and walkways.jpg", "resort": "COMO Laucala Island", "space": "Peninsula Residence", "description": "The Udu Peninsula Residence from the air, a cluster of sago thatched bures linked by raised timber walkways across a rocky headland, with a small pool tucked into the cliff edge and the resort sailing yacht anchored in the bay below. Roofs step down the point at different heights so the residence reads as a small village above the reef, the most secluded setting on the island. Recreate the composition with pavilions raised on posts, connecting boardwalks, and thatch silhouettes kept dominant over any wall surface.", "src": "images/COMO Laucala Island/0354 - COMO Laucala Island - Peninsula Residence - aerial view of cliff top bures and walkways.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/udu.html", "dimensions": "1920x1011", "size": 484338}, {"number": "0355", "file": "0355 - COMO Laucala Island - Peninsula Residence - bedroom with tapa cloth art and curved glass wall.jpg", "resort": "COMO Laucala Island", "space": "Peninsula Residence", "description": "The Udu Residence bedroom curves with the headland, its glass wall following the arc of the coast above the sea. Framed tapa cloth panels with bold geometric patterns hang beside the low timber bed, cushions repeat the same black and cream geometry, and a sculptural live edge desk wraps the window bay over polished local hardwood floors. A woven conical ceiling and stone clad piers ground the room. Recreate with curved glazing, tapa or barkcloth art as the pattern source, and furniture in dark sculptural timber.", "src": "images/COMO Laucala Island/0355 - COMO Laucala Island - Peninsula Residence - bedroom with tapa cloth art and curved glass wall.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/udu.html", "dimensions": "1920x1011", "size": 285410}, {"number": "0356", "file": "0356 - COMO Laucala Island - Peninsula Residence - living room with serpentine sofa and leather dining chairs.jpg", "resort": "COMO Laucala Island", "space": "Peninsula Residence", "description": "The Udu Residence living room is built around a serpentine cream sofa, the seashell curve that organises the whole space, facing the sea through walls of folding glass. A kidney shaped live edge coffee table, a round dining table with tan leather chairs, a carved wooden kava bowl, three flat woven pendants and a ceiling of woven thatch panels lashed with magimagi complete the interior, while flagstone flooring runs out to the wraparound pool. Recreate with one long curved sofa as the organising gesture, organic timber tables, leather accents and pattern kept to cushions and woven pieces.", "src": "images/COMO Laucala Island/0356 - COMO Laucala Island - Peninsula Residence - living room with serpentine sofa and leather dining chairs.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/udu.html", "dimensions": "1920x1011", "size": 326627}, {"number": "0357", "file": "0357 - COMO Laucala Island - Peninsula Residence - bathroom with sunken stone bath and bamboo ladder.jpg", "resort": "COMO Laucala Island", "space": "Peninsula Residence", "description": "The Udu Residence bathroom is lined in large irregular stone slabs, with a sunken plaster bath fed by a waterfall spout beneath a wall of glass looking out to the sea. A bamboo ladder serves as the towel rail, a live edge vanity carries a stone bowl basin, and a small woven stool keeps the fittings handmade and simple. Recreate with full height stone cladding, a built in sunken tub, bamboo accessories and openings framed precisely to the view.", "src": "images/COMO Laucala Island/0357 - COMO Laucala Island - Peninsula Residence - bathroom with sunken stone bath and bamboo ladder.jpg", "source": "https://blueskyluxurytravels.com/villas/fiji/laucala-island/udu.html", "dimensions": "1920x1011", "size": 334596}, {"number": "0358", "file": "0358 - COMO Laucala Island - Hilltop Estate - panoramic pool and loungers above the reef.jpg", "resort": "COMO Laucala Island", "space": "Hilltop Estate", "description": "The Delana Hilltop Estate panoramic pool, a long still sheet of water high on the island with timber loungers on a stone edged terrace island, a thatched shade pavilion and the reef and neighbouring islands spread out below. The design relies on altitude and horizon rather than ornament, with planting kept low so nothing interrupts the view, and it shows how the estate works as a resort within the resort. Note, this is the best available verified image of the Hilltop Estate at 584 px wide, because the Delana Residence is photographed only on request and no larger property supplied file could be verified.", "src": "images/COMO Laucala Island/0358 - COMO Laucala Island - Hilltop Estate - panoramic pool and loungers above the reef.jpg", "source": "http://dgamazingexperiences.com/2017/02/11/special-report-laucala-resort-laucala-island-fiji-february-2017/", "dimensions": "584x438", "size": 56208}, {"number": "0359", "file": "0359 - The Brando - One Bedroom Villa - twilight exterior with plunge pool and dining fare.jpg", "resort": "The Brando", "space": "One Bedroom Villa", "description": "The villa at dusk, a single storey fare with a steeply pitched roof of woven pandanus leaf over timber walls and full height glazed sliding doors glowing amber. In front, a dark stone clad plunge pool sits in white sand, flanked by a round thatched dining fare with white barrel chairs. Palette is sand, palm green and warm honey light. To recreate, pair a thatched pavilion form and low horizontal massing with a stone edged plunge pool, sand instead of paving, and layered warm lighting at deck level.", "src": "images/The Brando/0359 - The Brando - One Bedroom Villa - twilight exterior with plunge pool and dining fare.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "1200x837", "size": 230256}, {"number": "0360", "file": "0360 - The Brando - One Bedroom Villa - king bedroom under woven pandanus vault.jpg", "resort": "The Brando", "space": "One Bedroom Villa", "description": "King bedroom beneath a soaring vaulted ceiling of woven pandanus panels on dark timber rafters. The low platform bed has a woven check timber headboard, white linen, a natural fibre runner, and burnt orange and aubergine cushions as the only saturated colour. Behind the bed, a built in upholstered bench nook with bolster cushions sits in an alcove, flanked by flush wardrobe doors and sliding timber panels. A tall white sculptural floor lamp, a small round timber side table with a drum shade lamp, and honey toned timber floors complete the calm palette. Recreate with a woven ceiling finish, integrated joinery, and one controlled accent colour against neutrals.", "src": "images/The Brando/0360 - The Brando - One Bedroom Villa - king bedroom under woven pandanus vault.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2560x1440", "size": 542667}, {"number": "0361", "file": "0361 - The Brando - One Bedroom Villa - living area with Polynesian artwork and woven wall panels.jpg", "resort": "The Brando", "space": "One Bedroom Villa", "description": "Living area detail showing the material palette at close range: walls panelled in woven natural fibre matting, a wide plank timber floor in weathered mid brown, and a large framed Polynesian figural artwork in rust, black and cream above a dark timber table. The armchair is a clean lined dark timber frame with tailored oatmeal upholstery and loose natural cushions. Through the sliding door, a folding camp style chair and an oval timber desk with a mushroom lamp form a small media room nook, and sheer plus lined curtains soften the full height glazing. Recreate with woven wall cladding, one statement artwork, and restrained tailored upholstery.", "src": "images/The Brando/0361 - The Brando - One Bedroom Villa - living area with Polynesian artwork and woven wall panels.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "1977x1401", "size": 536549}, {"number": "0362", "file": "0362 - The Brando - One Bedroom Villa - bathroom with stacked stone walls and pedestal basins.jpg", "resort": "The Brando", "space": "One Bedroom Villa", "description": "Bathroom with two sculptural white cylindrical pedestal basins set against walls of stacked stone in grey and ochre bands. Oversized round mirrors hang from ceiling rods, lit by small square wall washers, and a pebble mosaic floor in cream and stone tones runs wall to wall, with a dark turned wood bowl placed on it as an object. The wide central opening, framed in timber with cream curtains, looks straight onto palms and pandanus, making the garden part of the room. Bright chartreuse lacquered trays are the single vivid accent. Recreate with rough stacked stone against glossy white sanitaryware, pebble flooring, and a garden facing opening.", "src": "images/The Brando/0362 - The Brando - One Bedroom Villa - bathroom with stacked stone walls and pedestal basins.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2560x1707", "size": 945119}, {"number": "0363", "file": "0363 - The Brando - One Bedroom Villa - garden bathtub behind branch pole screen.jpg", "resort": "The Brando", "space": "One Bedroom Villa", "description": "The signature outdoor bathroom: a deep white rectangular soaking tub on a timber deck in the garden, screened by a wall of horizontal natural branch poles in varied diameters. Chrome deck mounted filler and hand shower, a raw tree stump side table holding a black stone bowl and bath salts, and dense palm planting behind a glass balustrade. The contrast of crisp white ceramic and chrome against rough pole timber and foliage is the whole effect. Recreate with a pole or bamboo privacy screen, a stump or live edge side table, and planting kept close to the deck edge.", "src": "images/The Brando/0363 - The Brando - One Bedroom Villa - garden bathtub behind branch pole screen.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2560x1593", "size": 604075}, {"number": "0364", "file": "0364 - The Brando - Two Bedroom Villa - rear deck with loungers and plunge pool.jpg", "resort": "The Brando", "space": "Two Bedroom Villa", "description": "Rear terrace of the two bedroom villa: broad weathered timber decking with four black framed mesh loungers, rolled natural towels, and large sand coloured umbrellas. A narrow dark plunge pool runs along the deck toward the beach, with a woven pod chair on the sand and the lagoon beyond, and the villa's trunk form post and thatched roof edge framing the right side. Palette is bleached timber, sand, black metal and aquamarine water. Recreate with wide board decking, black minimal loungers, oversized neutral umbrellas, and a linear plunge pool aligned to the view.", "src": "images/The Brando/0364 - The Brando - Two Bedroom Villa - rear deck with loungers and plunge pool.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2560x1918", "size": 1205595}, {"number": "0365", "file": "0365 - The Brando - Two Bedroom Villa - bathroom with pebble floor and garden tub.jpg", "resort": "The Brando", "space": "Two Bedroom Villa", "description": "Wide view of the two bedroom villa bathroom: pebble mosaic floor, stacked stone clad walls, two white pedestal basins with round suspended mirrors, and a woven cane lounge chair with a scarlet cushion used as a dressing chair. At the far end the room opens through full height glass to the outdoor deck, where the white garden tub sits behind a horizontal branch pole screen with palms beyond. Chartreuse amenity boxes repeat the accent colour used across the villas. Recreate by treating the bathroom as a furnished room, with a chair, generous round mirrors, and a direct visual axis to an outdoor tub.", "src": "images/The Brando/0365 - The Brando - Two Bedroom Villa - bathroom with pebble floor and garden tub.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2560x1964", "size": 830908}, {"number": "0366", "file": "0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "resort": "The Brando", "space": "Three Bedroom Villa", "description": "The great room of the three bedroom villa, a double height space under a dramatic woven pandanus vault with exposed timber trusses and ceiling fans. A long marble topped dining table seats eight in textured oatmeal upholstered chairs. A low open timber credenza with ceramic vessels divides dining from the media wall, which is timber panelled with an inset screen. Full height sliding glass and cream curtains open to the pool deck and beach. Recreate with a woven vaulted ceiling as the hero, one long shared dining table, and low horizontal furniture that never competes with the roof.", "src": "images/The Brando/0366 - The Brando - Three Bedroom Villa - living and dining room under pandanus vault.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1879", "size": 997170}, {"number": "0367", "file": "0367 - The Brando - Three Bedroom Villa - exterior with raised stone plunge pool.jpg", "resort": "The Brando", "space": "Three Bedroom Villa", "description": "Day view of the three bedroom villa from the garden: two thatched buildings, the taller carried on massive natural trunk columns with a glass balustraded upper balcony, arranged around a raised plunge pool clad in dark stone with a surrounding overflow rill. White umbrellas, black loungers, and a thatched dining fare with woven chairs complete the arrangement, all set in sand and dense palm planting. Recreate with trunk form columns, a stone clad raised pool treated as a garden object, and buildings kept low and separate under individual thatched roofs.", "src": "images/The Brando/0367 - The Brando - Three Bedroom Villa - exterior with raised stone plunge pool.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1667", "size": 1274936}, {"number": "0368", "file": "0368 - The Brando - Three Bedroom Villa - outdoor dining fare with woven pendant.jpg", "resort": "The Brando", "space": "Three Bedroom Villa", "description": "Inside the round outdoor dining fare: a conical woven pandanus ceiling on radiating timber rafters, a large woven fibre drum pendant over a round timber pedestal table, and six woven rattan barrel chairs with ochre cushions. The fare stands on a dark circular deck in white sand, open on all sides to pandanus and palms, with plain white tableware on natural placemats. Recreate with a circular thatched pavilion, a single oversized woven pendant, and rattan chairs with one warm accent colour in the cushions.", "src": "images/The Brando/0368 - The Brando - Three Bedroom Villa - outdoor dining fare with woven pendant.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1667", "size": 915514}, {"number": "0369", "file": "0369 - The Brando - Teremoana Residence - dining room with carved figure and Polynesian painting.jpg", "resort": "The Brando", "space": "Teremoana Residence", "description": "The Teremoana dining room seats six at a white marble topped table with caramel upholstered chairs on black legs, lit by three white globe pendants in a row. A large framed Polynesian painting in red, black and gold hangs on the wall, a carved wooden fish hook decorates the pillar, and a tall carved wooden figure stands by the sheer curtains. Through the open doorway is the residence kitchen, with a breakfast counter and woven rope chairs. Timber floors and cream walls keep the art as the focus. Recreate with museum scale Polynesian art and carving, globe pendants in a row, and a neutral shell.", "src": "images/The Brando/0369 - The Brando - Teremoana Residence - dining room with carved figure and Polynesian painting.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1667", "size": 458084}, {"number": "0370", "file": "0370 - The Brando - Teremoana Residence - infinity pool terrace with ironwood posts.jpg", "resort": "The Brando", "space": "Teremoana Residence", "description": "Teremoana's pool terrace: a long infinity edge lap pool in turquoise tile with a submerged entry bench, fronting the two storey residence whose upper balcony is carried on massive polished ironwood trunk columns behind a glass balustrade. Six black loungers and sand umbrellas line the bleached timber deck, and a separate thatched fare on a coral stone base houses the outdoor lounge and barbecue area. Recreate with trunk columns as the structural signature, a long lap format pool, and a detached thatched pavilion for outdoor cooking and sitting.", "src": "images/The Brando/0370 - The Brando - Teremoana Residence - infinity pool terrace with ironwood posts.jpg", "source": "https://thebrando.com/accommodations/", "dimensions": "2500x1667", "size": 856202}, {"number": "0371", "file": "0371 - The Brando - Varua Te Ora Polynesian Spa - Fare Manu woven nest cabins.jpg", "resort": "The Brando", "space": "Varua Te Ora Polynesian Spa", "description": "The Fare Manu treatment cabins, domed structures hand woven from branches into bird nest forms, set in a grove of coconut palms and pandanus and reached by timber boardwalks. The weave is deliberately irregular, mixing grey weathered and dark branches, so each cabin reads as a natural object rather than a building. This is the spa's defining design gesture. Recreate with a free form woven branch shell, boardwalk access across planting or water, and no visible conventional wall or roof materials.", "src": "images/The Brando/0371 - The Brando - Varua Te Ora Polynesian Spa - Fare Manu woven nest cabins.jpg", "source": "https://thebrando.com/spa-wellness/", "dimensions": "2560x1200", "size": 847330}, {"number": "0372", "file": "0372 - The Brando - Varua Te Ora Polynesian Spa - open air treatment pavilion.jpg", "resort": "The Brando", "space": "Varua Te Ora Polynesian Spa", "description": "Open air treatment fare inside the spa: a massage table dressed in white linen with a green and black Marquesan motif pareu cloth, a bronze singing bowl, and a woven pandanus floor mat over dark decking. A circular patterned gong on a timber stand stands at the open side, which is fully open to palms and the pond garden, under a thatched roof finished with a fringe of pandanus leaves. Recreate with an open sided thatched pavilion, patterned Polynesian textiles as the colour layer, woven mats underfoot, and ritual objects used as decor.", "src": "images/The Brando/0372 - The Brando - Varua Te Ora Polynesian Spa - open air treatment pavilion.jpg", "source": "https://thebrando.com/spa-wellness/", "dimensions": "2048x1366", "size": 569937}, {"number": "0373", "file": "0373 - The Brando - Les Mutines - arched entrance over water at night.jpg", "resort": "The Brando", "space": "Les Mutines", "description": "Les Mutines at night, approached by a walkway over a lily pond: the restaurant is a tall arched timber structure like an upturned hull, its louvred vault glowing warm against the dark. The entrance frames a vintage Mutiny on the Bounty film poster above a timber host desk, Brando memorabilia used as the room's artwork. Egg shaped path lights and pandanus planting line the bridge. Recreate with an arched louvred timber shell, water at the threshold, and one large framed piece of graphic art as the focal point.", "src": "images/The Brando/0373 - The Brando - Les Mutines - arched entrance over water at night.jpg", "source": "https://thebrando.com/dining/", "dimensions": "2560x1604", "size": 945416}, {"number": "0374", "file": "0374 - The Brando - Les Mutines - dining room with ship chandelier and marble tables.jpg", "resort": "The Brando", "space": "Les Mutines", "description": "Inside Les Mutines, the barrel vaulted ceiling is lined in pale timber louvres on arched ribs. A huge crystal chandelier in the shape of a ship hangs over the central marble topped table, with smaller coral form pendants over the side tables. Dark louvred timber screens divide the room into intimate sections, and the chairs are simple leather and timber campaign style frames over terra cotta toned floor tiles. Recreate with a louvred vault, one theatrical chandelier, louvre screens for zoning, and marble and leather as the luxury layer.", "src": "images/The Brando/0374 - The Brando - Les Mutines - dining room with ship chandelier and marble tables.jpg", "source": "https://thebrando.com/dining/", "dimensions": "2560x1331", "size": 666548}, {"number": "0375", "file": "0375 - Amanwella - Arrival Pavilion - colonnaded pavilion across red pebble courtyard.jpg", "resort": "Amanwella", "space": "Arrival Pavilion", "description": "The arrival court is a study in Bawa tropical modernism as interpreted by Kerry Hill: a broad red pebble courtyard with a striped stone threshold inlay, fronted by a colonnade of slim black columns carrying deep terracotta tiled roofs at two heights. Plastered walls in warm sand tones enclose the court while coconut palms tower behind the roofline. To recreate it, pair a restrained horizontal pavilion form and clay tile roof with dark stained timber or steel posts, gravel and stone paving, and almost no applied ornament, letting proportion, shade and shadow do the work.", "src": "images/Amanwella/0375 - Amanwella - Arrival Pavilion - colonnaded pavilion across red pebble courtyard.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "2560x1580", "size": 1088351}, {"number": "0376", "file": "0376 - Amanwella - Arrival Pavilion - colonnaded walkway with black columns and steps.jpg", "resort": "Amanwella", "space": "Arrival Pavilion", "description": "A covered colonnade walkway of black square columns on a terracotta toned terrazzo floor, rising in shallow steps beside a white plastered wall, with frangipani and lawn glimpsed between the columns. Wall lanterns are slim vertical boxes. The lesson for recreation is rhythm and restraint: repeat one column module at strict intervals, keep the palette to black, white plaster and warm stone, and use planting rather than decoration to soften the geometry.", "src": "images/Amanwella/0376 - Amanwella - Arrival Pavilion - colonnaded walkway with black columns and steps.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "1945x2560", "size": 473450}, {"number": "0377", "file": "0377 - Amanwella - Ocean Pool Suite - living area opening to ocean terrace.jpg", "resort": "Amanwella", "space": "Ocean Pool Suite", "description": "The suite living area seen through floor to ceiling sliding glass and dark timber lattice screens, opening to a stone parapet terrace with a cushioned daybed, a sling back armchair and a small round table, with coconut palms and the Indian Ocean beyond. Terrazzo floors in muted sandy tones run inside and out so the room reads as one shaded loggia. All 28 suites share this identical layout; categories differ only by view. To recreate, use low horizontal furniture in dark kithul or teak tones, oatmeal linen upholstery, and full height screens that slide away completely.", "src": "images/Amanwella/0377 - Amanwella - Ocean Pool Suite - living area opening to ocean terrace.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "2560x1580", "size": 598567}, {"number": "0378", "file": "0378 - Amanwella - Garden Pool Suite - bedroom with woven wall hanging and lattice screens.jpg", "resort": "Amanwella", "space": "Garden Pool Suite", "description": "Principal bedroom with a king bed in white linen and a natural throw, a slatted timber bench seat at its foot, and a long green woven textile wall hanging above the bed in place of a headboard. Dark timber desks with black task lamps flank the bed, a geometric framed armchair with cream cushions sits by a round drum side table, and sliding lattice screens open to the courtyard daybed. Terrazzo floors and a pitched timber lined ceiling keep the palette warm and quiet. Recreate with woven fibre art, low platform furniture and one strong textile accent against neutral plaster.", "src": "images/Amanwella/0378 - Amanwella - Garden Pool Suite - bedroom with woven wall hanging and lattice screens.jpg", "source": "https://www.aman.com/resorts/amanwella/accommodation/suites", "dimensions": "2000x2000", "size": 625400}, {"number": "0379", "file": "0379 - Amanwella - Suite - walled courtyard with plunge pool and banquette.jpg", "resort": "Amanwella", "space": "Suite", "description": "The private entrance courtyard of a suite, enclosed by high hand hewn stone and plastered walls: a six by four metre plunge pool with submerged steps, a built in banquette with grey cushions, a small dining table with two woven seat chairs, and a floating stone stair against the wall. Planting is limited to palms and tropical foliage in the corners. Every suite has this courtyard on its entrance side. To recreate, treat the courtyard as an outdoor room with masonry seating, one timber table set, and shade from the enclosing walls rather than umbrellas.", "src": "images/Amanwella/0379 - Amanwella - Suite - walled courtyard with plunge pool and banquette.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "2560x1580", "size": 1242171}, {"number": "0380", "file": "0380 - Amanwella - Suite - covered ocean terrace with dining table and daybed.jpg", "resort": "Amanwella", "space": "Suite", "description": "The covered ocean terrace on the view side of a suite: a round perforated metal dining table with two slatted timber chairs, a long built in daybed with grey cushions against the hand hewn stone parapet, black square columns and a deep overhanging soffit framing palms and sea. Terrazzo paving continues from inside. The recreating brief is a shaded veranda furnished like a room, with weatherproof slatted timber and metal furniture in black and stone tones, and the view left completely unobstructed.", "src": "images/Amanwella/0380 - Amanwella - Suite - covered ocean terrace with dining table and daybed.jpg", "source": "https://www.aman.com/resorts/amanwella/accommodation/suites", "dimensions": "2560x2560", "size": 957987}, {"number": "0381", "file": "0381 - Amanwella - Suite - geometric armchair and alcove daybed detail.jpg", "resort": "Amanwella", "space": "Suite", "description": "Detail of the suite sitting area: a geometric black framed armchair with slatted back and cream cushion in the foreground, and behind it an alcove daybed with bolster cushions set into a plastered niche beside sliding timber lattice screens. A round dark timber side table carries books and ceramics. Sunlight rakes across sandy terrazzo. This is the furniture language of the whole resort in one frame: strict rectilinear frames in dark wood, loose cushions in undyed linen tones, and woven or latticed timber as the only pattern.", "src": "images/Amanwella/0381 - Amanwella - Suite - geometric armchair and alcove daybed detail.jpg", "source": "https://www.aman.com/resorts/amanwella/accommodation/suites", "dimensions": "2559x2560", "size": 709907}, {"number": "0382", "file": "0382 - Amanwella - Suite - bathroom with freestanding tub and timber vanities.jpg", "resort": "Amanwella", "space": "Suite", "description": "Suite bathroom arranged around a freestanding oval soaking tub in the centre of the room, with a low terrazzo partition behind it carrying wall mounted taps, twin vanity bays lined in horizontal timber panelling with mirrors, and bird of paradise flowers in a glass vase as the single decorative gesture. Terrazzo floors, louvred timber screens and glass to the courtyard keep it light. To recreate, float the tub as furniture, keep fittings minimal and chrome, and use timber panelling rather than tile as the warm surface.", "src": "images/Amanwella/0382 - Amanwella - Suite - bathroom with freestanding tub and timber vanities.jpg", "source": "https://www.aman.com/resorts/amanwella/accommodation/suites", "dimensions": "2558x2560", "size": 864387}, {"number": "0383", "file": "0383 - Amanwella - The Restaurant - dining room with folding glass doors.jpg", "resort": "Amanwella", "space": "The Restaurant", "description": "The Restaurant interior above the main pool: rows of square timber dining tables set for two and four, each with slatted back chairs in dark wood with cream seat pads, on a polished dark terrazzo floor. The seaward wall is a full run of folding glass doors with black frames, opened to the terrace and the ocean view, and daylight stripes the floor through the door frames. Recreate with identical simple table settings repeated in a grid, no tablecloths, and architecture that disappears when the doors fold back.", "src": "images/Amanwella/0383 - Amanwella - The Restaurant - dining room with folding glass doors.jpg", "source": "https://www.aman.com/resorts/amanwella/dining", "dimensions": "2000x1235", "size": 672892}, {"number": "0384", "file": "0384 - Amanwella - The Restaurant - stone terrace dining among tropical planting.jpg", "resort": "Amanwella", "space": "The Restaurant", "description": "Terrace dining outside The Restaurant, with dark metal and slatted timber tables and chairs on stone paving, a hand hewn stone wall behind, and dense tropical planting including palms and potted specimens in black planters closing the space in. Settings are minimal: glassware, folded napkins and small candles. For recreation, this is garden dining defined by enclosure and shade, using the same black and timber furniture family as indoors so terrace and dining room read as one space.", "src": "images/Amanwella/0384 - Amanwella - The Restaurant - stone terrace dining among tropical planting.jpg", "source": "https://www.aman.com/resorts/amanwella/dining", "dimensions": "2000x1235", "size": 603287}, {"number": "0385", "file": "0385 - Amanwella - The Lounge Bar - banquette lounge with low armchairs.jpg", "resort": "Amanwella", "space": "The Lounge Bar", "description": "The lounge sitting area of the main pavilion, furnished as a long room: built in banquettes with cream cushions along one side, low geometric armchairs with slatted timber backs grouped around small round tables, and a dark timber counter run beneath the windows. Folding glass doors open to the courtyard lawn and the restaurant pavilion beyond. The palette is cream, sand and dark wood under a high pitched ceiling. Recreate with banquette seating, repeated low armchairs and drinks tables at knee height, nothing bar like or glossy.", "src": "images/Amanwella/0385 - Amanwella - The Lounge Bar - banquette lounge with low armchairs.jpg", "source": "https://www.aman.com/resorts/amanwella/dining", "dimensions": "2000x1235", "size": 476161}, {"number": "0386", "file": "0386 - Amanwella - Main Pool - elevated view of pool deck with loungers.jpg", "resort": "Amanwella", "space": "Main Pool", "description": "Elevated view along the 47 metre main pool: a terracotta toned stone deck with white cushioned sun loungers and large square umbrellas in taupe canvas, the still green water mirroring the coconut grove, and the surf line of the crescent beach beyond the palms. The pool sits on the landscaped rise below the restaurant terrace. To recreate the mood, use one long rectilinear water plane, warm stone coping, and loungers and umbrellas in a single neutral colour repeated without variation.", "src": "images/Amanwella/0386 - Amanwella - Main Pool - elevated view of pool deck with loungers.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "2560x2560", "size": 1577342}, {"number": "0387", "file": "0387 - Amanwella - Main Pool - pool length with palm reflections.jpg", "resort": "Amanwella", "space": "Main Pool", "description": "Eye level view down the length of the 47 metre pool, its glassy surface reflecting the coconut palms, with a stone deck of adjustable sun loungers and umbrellas to one side and a terracotta roofed pavilion at the far end. Furniture is kept to the deck edge so the water plane stays empty and calm. Recreate with a narrow deck, dense palm planting at the far end, and no pool furniture in the water or on the view axis.", "src": "images/Amanwella/0387 - Amanwella - Main Pool - pool length with palm reflections.jpg", "source": "https://www.aman.com/resorts/amanwella", "dimensions": "1600x988", "size": 2194341}, {"number": "0388", "file": "0388 - Amanwella - Spa Suite - treatment room with massage table.jpg", "resort": "Amanwella", "space": "Spa Suite", "description": "The spa treatment room prepared for a guest: a massage table dressed in white linen with rolled towels and a frangipani flower, a dark timber cabinet with a woven vase of white flowers and treatment oils, and warm taupe plastered walls lit softly from behind a curtain. The room is deliberately plain, with natural fibres and one floral arrangement. Treatments are also offered in the suites. To recreate, use a single dressed table as the only furniture statement, dark wood storage, woven vessels and flowers, and no visible equipment.", "src": "images/Amanwella/0388 - Amanwella - Spa Suite - treatment room with massage table.jpg", "source": "https://www.aman.com/resorts/amanwella/wellness", "dimensions": "1946x2560", "size": 471428}, {"number": "0389", "file": "0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite Beachfront", "description": "Portrait view of the suite bedroom built around a tall carved dark wood poster bed dressed in white linen, a pleated fabric canopy panel and spice toned cushions, with an X frame upholstered bench at its foot. The pitched ceiling is lined in woven rattan under the thatch, floors are warm varnished timber, and a writing desk with an oval mirror and shell toned ceramics sits to one side. To recreate the look, pair a raised four poster bed with cream silk drapes, a cross leg bench, rattan ceiling cladding and bedside lamps with drum shades.", "src": "images/Constance Prince Maurice/0389 - Constance Prince Maurice - Junior Suite Beachfront - bedroom with draped poster bed and X frame bench.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "1771x2560", "size": 751844}, {"number": "0390", "file": "0390 - Constance Prince Maurice - Junior Suite Beachfront - bedroom and sitting area with oval mirror desk.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite Beachfront", "description": "Wide bedroom and sitting area in one open plan, with a dark wood bed, graphic cream and olive cushions and a patterned bed runner facing a curved daybed sofa with rust and sand cushions by the glass doors. Varnished timber floors, an oval mirror over the desk, shuttered windows and the thatched roof outside set the colonial tropical tone. Recreate with a low curved settee, a round pedestal side table, woven blinds and textiles in sand, ochre and burnt orange.", "src": "images/Constance Prince Maurice/0390 - Constance Prince Maurice - Junior Suite Beachfront - bedroom and sitting area with oval mirror desk.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1673", "size": 806361}, {"number": "0391", "file": "0391 - Constance Prince Maurice - Junior Suite on Stilts - bedroom and daybed opening to lagoon deck.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite on Stilts", "description": "Bedroom and sitting room of a suite raised on stilts over the lagoon fish reserve, opening through folding timber doors to a private deck above the water. A window daybed with cream, rust and patterned cushions runs along the glazing, beside a small round table, desk and armchair, all in dark stained wood on polished floorboards under a vaulted rattan lined ceiling. Recreate with full width folding doors, a built in daybed, slatted deck furniture and linen blinds in natural tones.", "src": "images/Constance Prince Maurice/0391 - Constance Prince Maurice - Junior Suite on Stilts - bedroom and daybed opening to lagoon deck.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1707", "size": 707297}, {"number": "0392", "file": "0392 - Constance Prince Maurice - Junior Suite on Stilts - bathroom with marble double vanity and oval tub.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite on Stilts", "description": "Bathroom under a high vaulted rattan ceiling, centred on a marble topped double vanity in dark wood, with an oval inset bath, a glass shower and tall mirrors in timber frames. Warm wood floors and louvred screens keep the wet room inside the suite palette of stone, marble and varnished timber. Recreate with a double console vanity in dark stained wood, polished marble tops, framed mirrors and lantern style wall lights.", "src": "images/Constance Prince Maurice/0392 - Constance Prince Maurice - Junior Suite on Stilts - bathroom with marble double vanity and oval tub.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1707", "size": 763696}, {"number": "0393", "file": "0393 - Constance Prince Maurice - Junior Suite on Stilts - thatched suites on stilts over the fish reserve.jpg", "resort": "Constance Prince Maurice", "space": "Junior Suite on Stilts", "description": "The row of thatched Junior Suites standing on timber stilts over the calm green water of the natural fish reserve, each with a small railed balcony facing the lagoon and the mangroves. Steep pitched roofs in natural thatch, dark timber framing and cream rendered walls define the resort silhouette. To recreate the setting, elevate simple gabled pavilions on posts over still water and keep planting dense and native at the shoreline.", "src": "images/Constance Prince Maurice/0393 - Constance Prince Maurice - Junior Suite on Stilts - thatched suites on stilts over the fish reserve.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1285", "size": 800147}, {"number": "0394", "file": "0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "resort": "Constance Prince Maurice", "space": "Villa on Stilts", "description": "Villa bedroom with a high vaulted ceiling lit by a warm cove, a carved dark wood bed dressed with a brocade style throw and teal cushions over the spice route palette. Louvred timber doors open to the deck, with an armchair, pedestal table and upholstered bench completing the room on polished wood floors. Recreate with teal and sand silk cushions, a patterned throw, shutter doors and a ceiling fan.", "src": "images/Constance Prince Maurice/0394 - Constance Prince Maurice - Villa on Stilts - bedroom with teal cushions and louvred deck doors.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1709", "size": 716631}, {"number": "0395", "file": "0395 - Constance Prince Maurice - Villa on Stilts - bathroom with whirlpool tub and stone garden wall.jpg", "resort": "Constance Prince Maurice", "space": "Villa on Stilts", "description": "Villa bathroom arranged around a deep whirlpool tub set into a marble surround beneath tall windows that look onto a rough stone garden wall and an outdoor shower. A long double vanity with a marble top and timber cabinetry faces a full width mirror, and the floors are pale stone tiles. Recreate with a raised inset tub, a stone feature wall, dark wood vanity units and chrome fittings kept simple.", "src": "images/Constance Prince Maurice/0395 - Constance Prince Maurice - Villa on Stilts - bathroom with whirlpool tub and stone garden wall.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1707", "size": 779440}, {"number": "0396", "file": "0396 - Constance Prince Maurice - Beach Villa with Private Pool - bedroom opening to dining room and pool terrace.jpg", "resort": "Constance Prince Maurice", "space": "Beach Villa with Private Pool", "description": "Beach villa bedroom looking through open double doors into a separate dining room and out to the private pool terrace with its thatched gazebo and loungers. Dark wood furniture, an upholstered armchair, framed prints and polished timber floors run through both rooms, giving one continuous indoor outdoor suite. Recreate with folding internal doors, a small round dining set, a woven pendant light and a shaded pool pavilion.", "src": "images/Constance Prince Maurice/0396 - Constance Prince Maurice - Beach Villa with Private Pool - bedroom opening to dining room and pool terrace.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1707", "size": 670788}, {"number": "0397", "file": "0397 - Constance Prince Maurice - Beach Villa with Private Pool - bathroom with octagonal whirlpool tub and louvred bay.jpg", "resort": "Constance Prince Maurice", "space": "Beach Villa with Private Pool", "description": "Villa bathroom built around an octagonal whirlpool tub set in a marble plinth inside a louvred bay window, with twin marble topped vanities in dark wood on either side. French doors and shuttered windows open to a private stone walled garden, and wall lanterns flank the mirrors. Recreate with a central island tub, louvre shutters all round, stone garden walls and symmetrical vanity runs.", "src": "images/Constance Prince Maurice/0397 - Constance Prince Maurice - Beach Villa with Private Pool - bathroom with octagonal whirlpool tub and louvred bay.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1440", "size": 636216}, {"number": "0398", "file": "0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "resort": "Constance Prince Maurice", "space": "Princely Villa", "description": "The Princely Villa open air dining pavilion, a vast thatched roof on rough timber posts against a dry stone wall, lit by a multi arm chandelier with fabric shades. A long timber dining table set with glassware and a tall floral arrangement faces low grey lounge sofas, with the private pool and sea beyond. Recreate with a stone feature wall, oversized pendant lighting, mixed dining and lounge zones and sand toned upholstery.", "src": "images/Constance Prince Maurice/0398 - Constance Prince Maurice - Princely Villa - thatched dining pavilion with stone wall and chandelier.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1708", "size": 1035646}, {"number": "0399", "file": "0399 - Constance Prince Maurice - Princely Villa - private pool terrace and beach at sunset.jpg", "resort": "Constance Prince Maurice", "space": "Princely Villa", "description": "The Princely Villa private heated pool at golden hour, its still surface running from a timber deck with cushioned loungers and a canvas umbrella to the sand beach and lagoon. A black stone planter lantern and mature palms frame the terrace. Recreate with a simple rectangular pool hard against the deck, oversized lanterns, and planting used as the only ornament.", "src": "images/Constance Prince Maurice/0399 - Constance Prince Maurice - Princely Villa - private pool terrace and beach at sunset.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/accommodation/", "dimensions": "2560x1707", "size": 955543}, {"number": "0400", "file": "0400 - Constance Prince Maurice - Le Barachois - lantern lit pontoon and floating decks at dusk.jpg", "resort": "Constance Prince Maurice", "space": "Le Barachois", "description": "Le Barachois at dusk, reached by a lantern lit timber pontoon with rope rails that crosses the mangrove lagoon to the floating decks, each roofed with a peaked canvas canopy. Wooden tables and folding chairs sit on plank decks above the fish reserve, with mountains on the horizon. Recreate with a boardwalk approach, canvas sail canopies, rope handrails and warm lantern light only.", "src": "images/Constance Prince Maurice/0400 - Constance Prince Maurice - Le Barachois - lantern lit pontoon and floating decks at dusk.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/restaurants-bars/le-barachois/", "dimensions": "2560x1440", "size": 606498}, {"number": "0401", "file": "0401 - Constance Prince Maurice - Le Barachois - floating deck set for dinner under canvas canopy.jpg", "resort": "Constance Prince Maurice", "space": "Le Barachois", "description": "One floating deck of Le Barachois set for dinner, with wooden folding armchairs in rust and natural canvas around linen dressed tables under a taut cream canopy. The deck planks and rope edged rails put the mangrove water at table level on open sides. Recreate with folding timber chairs, spice coloured seat pads, plain cream linen and unobtrusive structure so the water is the backdrop.", "src": "images/Constance Prince Maurice/0401 - Constance Prince Maurice - Le Barachois - floating deck set for dinner under canvas canopy.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/restaurants-bars/le-barachois/", "dimensions": "2560x1920", "size": 758255}, {"number": "0402", "file": "0402 - Constance Prince Maurice - Archipel Restaurant - pool deck dining terrace with white umbrellas.jpg", "resort": "Constance Prince Maurice", "space": "Archipel Restaurant", "description": "Archipel restaurant terrace wrapped around the main pool at sunset, with set tables and woven chairs on broad timber decking shaded by large white umbrellas. Terracotta pots with flowering shrubs and lantern posts divide the dining rows, and the thatched main building sits behind the palms. Recreate with pale deck boards, white canvas umbrellas, woven dining chairs and planting in terracotta.", "src": "images/Constance Prince Maurice/0402 - Constance Prince Maurice - Archipel Restaurant - pool deck dining terrace with white umbrellas.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/restaurants-bars/archipel/", "dimensions": "2560x1649", "size": 1049503}, {"number": "0403", "file": "0403 - Constance Prince Maurice - Constance Spa - open air twin treatment pavilion with thatched roof.jpg", "resort": "Constance Prince Maurice", "space": "Constance Spa", "description": "Open air couples treatment pavilion at Constance Spa, a rustic thatched roof carried on rough hewn poles above twin linen dressed massage beds, with a carved timber bench and black offering bowls on the polished deck. A dry stone wall and layered tropical planting close the space like a Balinese garden room. Recreate with exposed pole construction, white treatment linens, stone walls and dense green screening.", "src": "images/Constance Prince Maurice/0403 - Constance Prince Maurice - Constance Spa - open air twin treatment pavilion with thatched roof.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/", "dimensions": "2560x1707", "size": 1133701}, {"number": "0404", "file": "0404 - Constance Prince Maurice - Main Pool - main pool and thatched Laguna Bar pavilion at dusk.jpg", "resort": "Constance Prince Maurice", "space": "Main Pool", "description": "The main infinity pool at blue hour, reflecting the thatched Laguna Bar pavilion whose open sides glow with table lamps and lantern light behind the bar seating. Palm silhouettes and a still water edge give the pool its mirror finish. Recreate with a dark tiled pool, a thatched open pavilion bar, and layered warm lighting at table height.", "src": "images/Constance Prince Maurice/0404 - Constance Prince Maurice - Main Pool - main pool and thatched Laguna Bar pavilion at dusk.jpg", "source": "https://www.constancehotels.com/en/hotels-resorts/prince-maurice/restaurants-bars/laguna-bar/", "dimensions": "2560x1700", "size": 795102}, {"number": "0405", "file": "0405 - Kokomo Private Island - One Bedroom Sunrise Villa - bedroom with tapa panel and Kenyon painting.jpg", "resort": "Kokomo Private Island", "space": "One Bedroom Sunrise Villa", "description": "King bedroom in the bure tradition, with a dark cinnamon wood headboard unit and crisp white quilted bedding under a vaulted ceiling of woven matting carried on thick natural log beams. A long framed tapa cloth panel runs above the headboard, balanced by a large turquoise and rust abstract by resident artist Chris Kenyon, and the open plan layout looks through to the bathroom, where a shell chandelier hangs over the tub against timber louvre shutters. A black upholstered bench sits at the foot of the bed, with a timber writing desk, woven wicker chair and ceramic table lamp to one side. To recreate the look, pair dark tropical hardwood joinery and exposed pole beams with white walls, woven ceiling matting, tapa cloth art and one bold colour saturated canvas, keeping textiles plain white and oatmeal.", "src": "images/Kokomo Private Island/0405 - Kokomo Private Island - One Bedroom Sunrise Villa - bedroom with tapa panel and Kenyon painting.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/one-bedroom-sunrise-villa", "dimensions": "2048x1365", "size": 1867598}, {"number": "0406", "file": "0406 - Kokomo Private Island - One Bedroom Sunrise Villa - pool deck with stone edged plunge pool.jpg", "resort": "Kokomo Private Island", "space": "One Bedroom Sunrise Villa", "description": "The villa pool deck at sunrise, a wide sweep of weathered timber boards with a rectangular plunge pool edged in pale stone coping. Two rattan loungers with oatmeal cushions sit under a large canvas umbrella, and a stepping stone path crosses the lawn to the beach, framed by leaning coconut palms and dense tropical planting, with the thatched villa eave and magimagi wrapped beam ends visible at frame left. To recreate it, use silvered hardwood decking, stone edged water, woven rattan sun loungers in natural tones and generous palm planting so the architecture stays subordinate to the landscape.", "src": "images/Kokomo Private Island/0406 - Kokomo Private Island - One Bedroom Sunrise Villa - pool deck with stone edged plunge pool.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/one-bedroom-sunrise-villa", "dimensions": "2560x1708", "size": 1113795}, {"number": "0407", "file": "0407 - Kokomo Private Island - One Bedroom Sunset Villa - open plan bathroom and bedroom with ocean view.jpg", "resort": "Kokomo Private Island", "space": "One Bedroom Sunset Villa", "description": "Open plan villa interior photographed from the bathroom, where a sculptural freestanding white tub and a cane and rattan bench with a white cushion stand before full height sliders opening to the garden and ocean. Beyond, the bedroom carries a low timber framed bed in white and sand linens, indigo upholstered armchairs, a round woven wall mirror and a shell chandelier, all under a thatched ceiling on magimagi lashed beams. To recreate the look, zone bath and bed as one flowing space, use a statement soaking tub as furniture, add woven and cane textures against white plaster, and punctuate the calm palette with deep indigo upholstery.", "src": "images/Kokomo Private Island/0407 - Kokomo Private Island - One Bedroom Sunset Villa - open plan bathroom and bedroom with ocean view.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/one-bedroom-sunset-villa", "dimensions": "2560x1708", "size": 894972}, {"number": "0408", "file": "0408 - Kokomo Private Island - Two Bedroom Sunrise Villa - guest bedroom with woven panel headboard.jpg", "resort": "Kokomo Private Island", "space": "Two Bedroom Sunrise Villa", "description": "Guest bedroom with a woven panel headboard in a dark Fijian mahogany frame, flanked by matching dark timber bedside cabinets and a full wall of built in wardrobes with open shelving and a mirrored dressing section. Bedding is ivory waffle weave with stone coloured cushions and a botanical print throw, a green and blue Chris Kenyon diptych hangs beside timber louvre windows, and a ribbed drum side table holds a white coral textured vase of tropical foliage over a natural woven rug. To recreate it, anchor the room with dark stained timber joinery and woven headboard panels, then soften with ivory textiles, one colourful art pair and organic coral and shell objects.", "src": "images/Kokomo Private Island/0408 - Kokomo Private Island - Two Bedroom Sunrise Villa - guest bedroom with woven panel headboard.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/two-bedroom-sunrise-villa", "dimensions": "2560x1707", "size": 590447}, {"number": "0409", "file": "0409 - Kokomo Private Island - Three Bedroom Sunrise Villa - garden bathroom with freestanding tub.jpg", "resort": "Kokomo Private Island", "space": "Three Bedroom Sunrise Villa", "description": "Master ensuite opening to its private walled garden, photographed through the planting so the freestanding white oval tub is glimpsed between ti leaves and hibiscus. Timber framed bifold doors and a slatted louvre screen fold back completely, dissolving the line between bathroom and garden, with a rustic timber stool beside the tub, a shell garland hanging at the doorway and a dry stone garden wall behind. To recreate the look, give the bathroom a fully opening glazed wall, a sculptural tub as the centrepiece, warm timber frames against sage plaster, and lush layered planting kept close enough to brush the threshold.", "src": "images/Kokomo Private Island/0409 - Kokomo Private Island - Three Bedroom Sunrise Villa - garden bathroom with freestanding tub.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/three-bedroom-sunrise-villa", "dimensions": "2560x1707", "size": 674187}, {"number": "0410", "file": "0410 - Kokomo Private Island - Three Bedroom Sunset Villa - bedroom with Kenyon painting and lashed beams.jpg", "resort": "Kokomo Private Island", "space": "Three Bedroom Sunset Villa", "description": "Bedroom under a soaring thatched ceiling carried on massive natural poles lashed with magimagi coconut fibre rope, the signature Kokomo construction detail. The bed is dressed in white diamond quilted linen with a charcoal upholstered bench at its foot, a large coastal abstract by Chris Kenyon hangs beside louvred windows, and a dark timber desk with a woven chair and stone based lamp sits near sheer draped sliders that open to the deck, pool and ocean. Deep indigo armchairs and coral patterned planters add the colour accents. Recreate it with rope lashed pole beams, thatch or woven matting overhead, white bedding, dark timber case goods and one large scale seascape canvas.", "src": "images/Kokomo Private Island/0410 - Kokomo Private Island - Three Bedroom Sunset Villa - bedroom with Kenyon painting and lashed beams.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/three-bedroom-sunset-villa", "dimensions": "2560x1707", "size": 835910}, {"number": "0411", "file": "0411 - Kokomo Private Island - Three Bedroom Sunset Villa - pool terrace on the beach.jpg", "resort": "Kokomo Private Island", "space": "Three Bedroom Sunset Villa", "description": "The villa pool terrace sitting directly on the sand, a long mosaic tiled infinity edge pool running the length of the shaded veranda, where round timber posts wrapped with magimagi support the roof over wicker dining chairs and a timber table. Loungers and a canvas umbrella face the lagoon, a volcanic stone garden wall screens the neighbouring villa, and the beach begins at the pool coping. To recreate it, run the pool hard against the living veranda, use rope wrapped posts and grey shingle or thatch roofing, keep outdoor furniture in woven wicker and weathered timber, and let the sand meet the terrace without a fence.", "src": "images/Kokomo Private Island/0411 - Kokomo Private Island - Three Bedroom Sunset Villa - pool terrace on the beach.jpg", "source": "https://www.kokomoislandfiji.com/stay/beachfront-villas/three-bedroom-sunset-villa", "dimensions": "2560x1707", "size": 1105610}, {"number": "0412", "file": "0412 - Kokomo Private Island - Sunset Residence - living room with vaulted timber ceiling.jpg", "resort": "Kokomo Private Island", "space": "Sunset Residence", "description": "The great room of the six bedroom Sunset Residence, a vast open plan living space under a vaulted ceiling of pale tongue and groove timber boards with oversized paddle ceiling fans. Seating is arranged in conversational groups on a huge natural woven rug, linen sofas and armchairs in white and oatmeal, woven cane wing chairs, a rustic slab timber coffee table and a single burl wood stool used as an accent piece. A deep blue Chris Kenyon seascape anchors the far wall above the dining area and kitchen, and glass sliders open on both sides to terraces and the pool. Recreate it with bleached timber ceilings, oversized woven floor coverings, neutral linen upholstery mixed with cane, and one monumental blue artwork to carry the ocean indoors.", "src": "images/Kokomo Private Island/0412 - Kokomo Private Island - Sunset Residence - living room with vaulted timber ceiling.jpg", "source": "https://www.kokomoislandfiji.com/stay/residences/sunset", "dimensions": "2560x1707", "size": 974193}, {"number": "0413", "file": "0413 - Kokomo Private Island - Sunset Residence - master bedroom with padded headboard wall.jpg", "resort": "Kokomo Private Island", "space": "Sunset Residence", "description": "Master bedroom viewed through its glass sliders, centred on a floor to ceiling padded headboard wall in oatmeal fabric panels set into blonde timber joinery with open display niches holding coral, shell and ceramic pieces. Wall sconces flank the bed, an upholstered linen bench on tapered timber legs sits at its foot, and the palette of stone, sand and white is lifted by black and white geometric cushions. The ceiling is pale boarded timber with a sculptural paddle fan, and large format stone tiles run underfoot. To recreate it, build the headboard as architecture, upholstered panels within a timber grid, keep bedding white with graphic monochrome cushions, and display natural found objects in lit niches.", "src": "images/Kokomo Private Island/0413 - Kokomo Private Island - Sunset Residence - master bedroom with padded headboard wall.jpg", "source": "https://www.kokomoislandfiji.com/stay/residences/sunset", "dimensions": "2560x1707", "size": 392133}, {"number": "0414", "file": "0414 - Kokomo Private Island - Ocean Residence - living area opening to pool.jpg", "resort": "Kokomo Private Island", "space": "Ocean Residence", "description": "Living area of the four bedroom Ocean Residence, a serene sand and ivory room under a pitched pale timber ceiling, opening through full width sliders to the pool terrace. A rustic live edge timber coffee table centres the seating, linen sofas and a woven cane armchair, and holds a giant clam shell as sculpture, while two monumental weathered stone urns filled with bamboo poles frame the doorway like sentries. A woven jute rug warms the stone floor. To recreate the look, keep every textile natural and unbleached, use one oversized raw timber table, and style with collected marine objects, shells, coral and bamboo, at architectural scale.", "src": "images/Kokomo Private Island/0414 - Kokomo Private Island - Ocean Residence - living area opening to pool.jpg", "source": "https://www.kokomoislandfiji.com/stay/residences/ocean", "dimensions": "2200x1467", "size": 2406669}, {"number": "0415", "file": "0415 - Kokomo Private Island - Namara Residence - kitchen with stone island and cane stools.jpg", "resort": "Kokomo Private Island", "space": "Namara Residence", "description": "The Namara Residence kitchen, a monolithic island in honed grey stone with a waterfall end, fronted by three bent cane bar stools with woven backs in dark stained rattan. Cabinetry is flat fronted in warm grey brown timber veneer with crisp white uppers, a stone splashback, and an oversized woven bell pendant over the island, all beneath a pale boarded timber ceiling. Sliders open to the pool deck and garden, and large porcelain tiles keep the floor cool and pale. To recreate it, contrast one heavy stone form with fine cane seating, handleless timber cabinetry and woven lighting, keeping the whole scheme in stone, taupe and honey tones.", "src": "images/Kokomo Private Island/0415 - Kokomo Private Island - Namara Residence - kitchen with stone island and cane stools.jpg", "source": "https://www.kokomoislandfiji.com/stay/residences/namara", "dimensions": "2560x1920", "size": 839624}, {"number": "0416", "file": "0416 - Kokomo Private Island - Dravuni Residence - bathroom with egg tub and cinnamon wood vanity.jpg", "resort": "Kokomo Private Island", "space": "Dravuni Residence", "description": "Portrait view of a Dravuni Residence bathroom, where a sculptural egg shaped freestanding tub in matte white sits before floor to ceiling glass framing the pool and ocean. The vanity wall is built in dark cinnamon wood, with tall framed mirrors, shaded wall sconces, a stone counter and a round white vessel basin, the dark timber partition giving the pale room its warmth and structure. A small round timber stool and folded slippers complete the spa mood. To recreate it, set a curvaceous tub against a full height view window, build the vanity as a dark stained timber wall with framed mirrors, and keep fittings brushed metal and ceramics pure white.", "src": "images/Kokomo Private Island/0416 - Kokomo Private Island - Dravuni Residence - bathroom with egg tub and cinnamon wood vanity.jpg", "source": "https://www.kokomoislandfiji.com/stay/residences/dravuni", "dimensions": "1887x2560", "size": 496513}, {"number": "0417", "file": "0417 - Kokomo Private Island - Beach Shack - deck dining at sunset.jpg", "resort": "Kokomo Private Island", "space": "Beach Shack", "description": "Beach Shack restaurant deck at sunset, white cloth dressed tables set on a weathered timber boardwalk above the lagoon, with high backed woven rattan dining chairs, rope railed balustrades and a single leaning palm framing the view to the reef and islands. The design is deliberately simple, bleached boards, natural wicker and white linen, so the changing light over the water does the decorating. Best available at 1000 px wide, the largest file the official site serves for this photograph. To recreate it, use silvered decking, rope and post railings, woven dining chairs and plain white table linen in an open air room with no walls at all.", "src": "images/Kokomo Private Island/0417 - Kokomo Private Island - Beach Shack - deck dining at sunset.jpg", "source": "https://www.kokomoislandfiji.com/culinary/beach-shack", "dimensions": "1000x667", "size": 730679}, {"number": "0418", "file": "0418 - Kokomo Private Island - Beach Shack - beach bar lounge with wicker seating.jpg", "resort": "Kokomo Private Island", "space": "Beach Shack", "description": "The covered beach bar lounge at Beach Shack, a long open sided pavilion on round timber posts wrapped with patterned magimagi bindings, its ceiling lined in woven matting with a thatch fringe. Deep wicker armchairs and a curved rattan settee are piled with cream and fine stripe cushions around a weathered timber table holding a giant clam shell, and bamboo poles stand in a stone urn as sculpture. Rope railings separate the deck from the sand and jetty beyond. To recreate it, combine woven ceilings, lashed post details, generous low wicker seating in off white cushions and shell and bamboo objects styled at large scale.", "src": "images/Kokomo Private Island/0418 - Kokomo Private Island - Beach Shack - beach bar lounge with wicker seating.jpg", "source": "https://www.kokomoislandfiji.com/culinary/beach-shack", "dimensions": "2048x1365", "size": 2925214}, {"number": "0419", "file": "0419 - Kokomo Private Island - Walker d'Plank - boardwalk approach with rope railings.jpg", "resort": "Kokomo Private Island", "space": "Walker d'Plank", "description": "The approach to Walker d’Plank, the resort’s overwater Asian street food restaurant designed by artist in residence Chris Kenyon from recycled maritime materials. A weathered timber boardwalk on chunky posts runs along the rocky shore, its handrail looped with thick natural rope swags, leading to the small open pavilion tucked under the trees at the cove, with hand painted signage at the entrance. To recreate the look, use reclaimed looking deck boards, heavy rope as a balustrade material, stone edged planting and a deliberately ramshackle fish shack silhouette softened by lush tropical greenery.", "src": "images/Kokomo Private Island/0419 - Kokomo Private Island - Walker d'Plank - boardwalk approach with rope railings.jpg", "source": "https://www.kokomoislandfiji.com/culinary/walker-dplank", "dimensions": "2560x1707", "size": 1558840}, {"number": "0420", "file": "0420 - Kokomo Private Island - Yaukuve Spa Sanctuary - treatment bure with sheer curtains.jpg", "resort": "Kokomo Private Island", "space": "Yaukuve Spa Sanctuary", "description": "Inside an open sided treatment bure at the Yaukuve Spa Sanctuary, where a therapist gives a shoulder massage at a linen dressed treatment bed covered with a grey and white botanical print throw. Sheer white curtains billow between posts wrapped in woven magimagi and tapa patterned bands, with thatch visible above and tropical greenery glowing through the fabric, the whole room softened to a palette of white, grey and leaf green. To recreate it, build treatment rooms as curtained pavilions rather than closed boxes, layer sheer linen drapes over open sides, wrap structural posts in fibre and patterned cloth, and keep bed textiles in muted botanical prints.", "src": "images/Kokomo Private Island/0420 - Kokomo Private Island - Yaukuve Spa Sanctuary - treatment bure with sheer curtains.jpg", "source": "https://www.kokomoislandfiji.com/wellness/yaukuve-spa-sanctuary", "dimensions": "2560x1716", "size": 600927}, {"number": "0421", "file": "0421 - Zuri Zanzibar - Bungalows - bedroom opening to hammock terrace.jpg", "resort": "Zuri Zanzibar", "space": "Bungalows", "description": "Bedroom flowing through full height louvred timber doors onto a private deck. Canopy bed with sheer white drapes, a sculptural olive upholstered lounge chair and footstool, and a slim timber desk set under a large carved lotus leaf wall panel in warm ochre. Polished timber plank floors, taupe linen curtains, a perforated black metal wall lamp, and outside a rope hammock, woven rattan loungers and a pierced drum side table under the exposed thatch roof. Recreate with warm mid tone timber, layered natural textiles and one oversized botanical relief panel as the single art statement.", "src": "images/Zuri Zanzibar/0421 - Zuri Zanzibar - Bungalows - bedroom opening to hammock terrace.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-bungalows/", "dimensions": "2000x1335", "size": 485082}, {"number": "0422", "file": "0422 - Zuri Zanzibar - Bungalows - bathroom with paper bead curtain and stone basins.jpg", "resort": "Zuri Zanzibar", "space": "Bungalows", "description": "Bathroom entered through a handmade paper bead curtain in earthy reds, greens and ochres, the resort signature craft detail made by local women. Twin stone vessel basins sit on a monolithic cement vanity beneath an oversized round timber framed mirror, lit by wire cage pendants hanging from the thatch ceiling. Timber framed glass doors open to the outdoor shower, walled in rough coral stone over a pebble floor. Recreate with cast stone basins, raw cement, coral stone cladding and beadwork used as a soft partition instead of a door.", "src": "images/Zuri Zanzibar/0422 - Zuri Zanzibar - Bungalows - bathroom with paper bead curtain and stone basins.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-bungalows/", "dimensions": "1800x1202", "size": 352825}, {"number": "0423", "file": "0423 - Zuri Zanzibar - Bungalows - bedroom with paper bead curtain partition.jpg", "resort": "Zuri Zanzibar", "space": "Bungalows", "description": "Bedroom divided from its bathroom by a full height curtain of multicoloured paper beads, so the two rooms read as one crafted space. Canopy bed with floating white drapes, woven rattan cage pendant, carved timber drum stools beside the bed, dark timber boards and a glimpse of the stone basin bathroom beyond the beads. Recreate by replacing one internal wall with a bead or textile hanging and keeping every surface natural and handmade.", "src": "images/Zuri Zanzibar/0423 - Zuri Zanzibar - Bungalows - bedroom with paper bead curtain partition.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-bungalows/", "dimensions": "1800x1200", "size": 400549}, {"number": "0424", "file": "0424 - Zuri Zanzibar - Bungalows - raised thatched bungalow with hammock deck.jpg", "resort": "Zuri Zanzibar", "space": "Bungalows", "description": "The bungalow as architecture: raised on a broad timber deck above the garden, deep overhanging coconut thatch roof, louvred timber shutters, hammocks slung across the veranda and dense tropical planting against the facade. It shows the village cluster planning and the raised, naturally ventilated construction Jestico + Whiles designed for the site. Recreate the type with a raised deck, a generous roof overhang and hammock first outdoor living rather than a sealed facade.", "src": "images/Zuri Zanzibar/0424 - Zuri Zanzibar - Bungalows - raised thatched bungalow with hammock deck.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-bungalows/", "dimensions": "1800x1202", "size": 499168}, {"number": "0425", "file": "0425 - Zuri Zanzibar - Suites - living room with blue sofas and carved door.jpg", "resort": "Zuri Zanzibar", "space": "Suites", "description": "Separate suite living room under a cathedral thatch ceiling with radial exposed timber trusses. Two deep sofas in saturated Indian Ocean blue face a reclaimed plank coffee table on dark timber floors. Behind them, stacks of painted clay pots flank a bead curtained doorway, and a heavily carved Zanzibari door with an ornate frame closes the bedroom. Carved lotus leaf panel, low timber cabinetry and wire cage pendants complete the room. Recreate with one bold blue textile note against carved timber, clay and thatch.", "src": "images/Zuri Zanzibar/0425 - Zuri Zanzibar - Suites - living room with blue sofas and carved door.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-suites/", "dimensions": "1800x1200", "size": 258778}, {"number": "0426", "file": "0426 - Zuri Zanzibar - Suites - bedroom seen through louvred timber doors.jpg", "resort": "Zuri Zanzibar", "space": "Suites", "description": "Suite bedroom framed by folding louvred timber doors opened like a proscenium, the canopy bed centred under the pitched thatch roof with exposed trusses. Dark plank floors, a small timber desk and chair to one side, woven textures and white bedding with a single patterned cushion. Recreate by using louvred doors as an internal screen so the bed is revealed in layers rather than all at once.", "src": "images/Zuri Zanzibar/0426 - Zuri Zanzibar - Suites - bedroom seen through louvred timber doors.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-suites/", "dimensions": "1800x1200", "size": 281676}, {"number": "0427", "file": "0427 - Zuri Zanzibar - Suites - ocean front terrace with daybed and jacuzzi.jpg", "resort": "Zuri Zanzibar", "space": "Suites", "description": "Ocean Front Suite terrace: a cushioned timber daybed and the suite private outdoor jacuzzi set on broad timber decking, with pandanus and palms framing the way down to the semi private beach. Louvred screens and the thatch overhang keep the deck shaded. Recreate with a daybed scaled like a second bed outdoors and planting used as the balustrade.", "src": "images/Zuri Zanzibar/0427 - Zuri Zanzibar - Suites - ocean front terrace with daybed and jacuzzi.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-suites/", "dimensions": "1800x1200", "size": 439245}, {"number": "0428", "file": "0428 - Zuri Zanzibar - Two-Bedroom Garden Villa - bedroom with garden mural.jpg", "resort": "Zuri Zanzibar", "space": "Two-Bedroom Garden Villa", "description": "Garden villa bedroom with a canopy bed and sheer white drapes, a hand painted black ink botanical mural covering one wall, polished timber floors and sliding doors opening to the garden terrace. A woven stool holds a tropical flower arrangement, and a timber desk and chair stand against a wood panelled wall. Recreate with a single mural wall, monochrome ink on plaster, against otherwise plain limewashed surfaces and natural timber.", "src": "images/Zuri Zanzibar/0428 - Zuri Zanzibar - Two-Bedroom Garden Villa - bedroom with garden mural.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-villas/", "dimensions": "1800x1200", "size": 245242}, {"number": "0429", "file": "0429 - Zuri Zanzibar - Ocean Front Two-Bedroom Villa - open living pavilion and sectional sofa.jpg", "resort": "Zuri Zanzibar", "space": "Ocean Front Two-Bedroom Villa", "description": "The villa social core is a full timber living pavilion: plank decking throughout, slatted timber screens, louvred shutters and a tasselled fibre chandelier over an L shaped teal sectional loaded with coral orange and patterned cushions. A carved white drum table, woven deck chairs and stools gather around the private jacuzzi, with the dining area and kitchen behind. Recreate with decking run continuously inside and out, one large sectional, and saturated cushions as the only strong colour.", "src": "images/Zuri Zanzibar/0429 - Zuri Zanzibar - Ocean Front Two-Bedroom Villa - open living pavilion and sectional sofa.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-villas/", "dimensions": "1800x1200", "size": 278443}, {"number": "0430", "file": "0430 - Zuri Zanzibar - Ocean Front Two-Bedroom Villa - outdoor shower and tub with coral stone wall.jpg", "resort": "Zuri Zanzibar", "space": "Ocean Front Two-Bedroom Villa", "description": "Outdoor bathroom court: a freestanding oval tub and open rain shower set against a rough coral stone wall, screened by bamboo pole fencing, with black pebble ground cover and round stone stepping pads. It is the tropical outdoor bathroom idea translated into Zanzibari materials. Recreate with coral stone cladding, bamboo screening, matte stoneware and planting at the edges rather than tiles and glass.", "src": "images/Zuri Zanzibar/0430 - Zuri Zanzibar - Ocean Front Two-Bedroom Villa - outdoor shower and tub with coral stone wall.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-villas/", "dimensions": "1800x1200", "size": 445505}, {"number": "0431", "file": "0431 - Zuri Zanzibar - Three-Bedroom Luxury Villa - living room with fabric drum pendants.jpg", "resort": "Zuri Zanzibar", "space": "Three-Bedroom Luxury Villa", "description": "Main living room of the three bedroom villa: a soaring pitched roof with exposed timber trusses and full height louvred shutters opening to the sea. Three large fabric drum pendants hang over low armchairs and teal sofas arranged on polished boards around a central rug, with ceiling fans above. Recreate with oversized soft pendants at low height to humanise a very tall volume, and shutters instead of glazed walls on the view side.", "src": "images/Zuri Zanzibar/0431 - Zuri Zanzibar - Three-Bedroom Luxury Villa - living room with fabric drum pendants.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-villas/", "dimensions": "1800x1200", "size": 331821}, {"number": "0432", "file": "0432 - Zuri Zanzibar - Three-Bedroom Luxury Villa - entertainment room with library wall.jpg", "resort": "Zuri Zanzibar", "space": "Three-Bedroom Luxury Villa", "description": "Entertainment room with a full height timber library wall, a pool table, wraparound blue sofas, a reclaimed plank coffee table and woven pendants under the thatch roof, with a woven hanging chair visible on the terrace beyond. It mixes games room and lounge in one crafted timber interior. Recreate with one entire wall of joinery shelving and durable, deep seated sofas in a single colour family.", "src": "images/Zuri Zanzibar/0432 - Zuri Zanzibar - Three-Bedroom Luxury Villa - entertainment room with library wall.jpg", "source": "https://www.zurizanzibar.com/accommodation/the-villas/", "dimensions": "1800x1138", "size": 299133}, {"number": "0433", "file": "0433 - Zuri Zanzibar - Upendo Restaurant - dining room with timber posts and hanging lamps.jpg", "resort": "Zuri Zanzibar", "space": "Upendo Restaurant", "description": "Upendo, the main restaurant, set for dinner between massive rough timber posts: simple timber tables, curved slat back chairs and clusters of amber hanging lamps overhead, with the open kitchen and live cooking beyond. Mr and Mrs Smith counts hundreds of hanging lamps here and a crocodile shaped communal table at the back. Recreate with heavy structural timber left exposed, low warm lighting in quantity, and plainly set tables.", "src": "images/Zuri Zanzibar/0433 - Zuri Zanzibar - Upendo Restaurant - dining room with timber posts and hanging lamps.jpg", "source": "https://www.zurizanzibar.com/culinary/", "dimensions": "1800x916", "size": 187245}, {"number": "0434", "file": "0434 - Zuri Zanzibar - Bahari Bar - bar with illuminated blue counter and bulb pendants.jpg", "resort": "Zuri Zanzibar", "space": "Bahari Bar", "description": "The Bahari bar at night: a long counter with a luminous blue top, which the resort credits to Czech artist David Cerny, faced in dark vertical slats, with rows of backless stools in black and natural timber. A dense canopy of exposed Edison bulb pendants hangs from the timber roof structure. Recreate with one saturated, almost glowing colour accent held against dark timber, cane and warm filament light.", "src": "images/Zuri Zanzibar/0434 - Zuri Zanzibar - Bahari Bar - bar with illuminated blue counter and bulb pendants.jpg", "source": "https://www.zurizanzibar.com/culinary/", "dimensions": "1800x947", "size": 258463}, {"number": "0435", "file": "0435 - Zuri Zanzibar - Maua Wellness - outdoor treatment pavilion with curtained cabana.jpg", "resort": "Zuri Zanzibar", "space": "Maua Wellness", "description": "Maua Wellness outdoor treatment pavilion: an open timber pergola cabana with flowing white curtains standing on a broad timber deck, treatment beds inside, a small plunge pool at the deck edge and dense tropical planting all around. It is the Southeast Asian spa pavilion type rebuilt in local timber and white cloth. Recreate with a simple post and beam cabana, full length sheer curtains and decking instead of stone floors.", "src": "images/Zuri Zanzibar/0435 - Zuri Zanzibar - Maua Wellness - outdoor treatment pavilion with curtained cabana.jpg", "source": "https://www.zurizanzibar.com/experiences/maua-wellness/", "dimensions": "1800x935", "size": 373725}, {"number": "0436", "file": "0436 - Zuri Zanzibar - Maua Wellness - treatment room with garden view.jpg", "resort": "Zuri Zanzibar", "space": "Maua Wellness", "description": "Maua Wellness treatment room: a single massage table dressed in white linen on a polished timber floor, carved wooden side tables, a woven floor cushion and bowls of petals, with sheer curtains and a full height opening onto dense garden greenery. Recreate with one timber table bed, woven accessories and the garden itself as the decoration.", "src": "images/Zuri Zanzibar/0436 - Zuri Zanzibar - Maua Wellness - treatment room with garden view.jpg", "source": "https://www.zurizanzibar.com/experiences/maua-wellness/", "dimensions": "1800x937", "size": 270159}, {"number": "0437", "file": "0437 - qualia - Windward Pavilion - infinity plunge pool and pavilion exterior.jpg", "resort": "qualia", "space": "Windward Pavilion", "description": "The pavilion reads as a low pitched roof plane in dark stained timber floating over glass, with the private infinity edge plunge pool running along the deck edge so water, timber decking and Coral Sea merge in one horizontal band. Spotted gum decking, a deep shaded veranda and native eucalypt planting frame the view. To recreate the look, pair a simple gabled pavilion form and full height glazing with warm hardwood decking, minimal pool fencing lines and planting kept low so the horizon stays uninterrupted.", "src": "images/qualia Hamilton Island/0437 - qualia - Windward Pavilion - infinity plunge pool and pavilion exterior.jpg", "source": "https://www.qualia.com.au/luxury-accommodation/", "dimensions": "2560x1440", "size": 918358}, {"number": "0438", "file": "0438 - qualia - Windward Pavilion - living room with stone wall and plunge pool view.jpg", "resort": "qualia", "space": "Windward Pavilion", "description": "A vaulted, timber lined ceiling in warm spotted gum soars over an open plan lounge arranged around the view: a low grey upholstered sofa, a round white coffee table, a wall mounted screen and a rubble stone feature wall anchoring the far end beside a small dining setting. Polished hardwood floors run straight out through full height sliding glass to the terrace and plunge pool. Recreate it with a restrained palette of grey linen upholstery, pale stone, oiled timber and black steel accents, keeping furniture low and horizontal so the sea remains the artwork.", "src": "images/qualia Hamilton Island/0438 - qualia - Windward Pavilion - living room with stone wall and plunge pool view.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x800", "size": 821633}, {"number": "0439", "file": "0439 - qualia - Windward Pavilion - bedroom opening to stone bathroom.jpg", "resort": "qualia", "space": "Windward Pavilion", "description": "The king bedroom is dressed in white linen with a grey woven throw, polished hardwood floors and a framed coastal artwork, and it opens through a wide timber trimmed doorway directly into the stone ensuite, where a sculptural freestanding oval bath sits under hanging white towels. Sliding louvred screens and floor to ceiling glass connect both rooms to the terrace and sea. To recreate the look, use one continuous timber floor, en suite planning with no visual barrier, a single statement bath as the focal object and artwork in muted reef tones.", "src": "images/qualia Hamilton Island/0439 - qualia - Windward Pavilion - bedroom opening to stone bathroom.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x800", "size": 439154}, {"number": "0440", "file": "0440 - qualia - Windward Pavilion - freestanding oval bath before louvred windows.jpg", "resort": "qualia", "space": "Windward Pavilion", "description": "A single sculptural, egg shaped freestanding bath in matte white is centred on dark stone tiles before a wall of timber louvre windows opened to the Coral Sea, a folded white towel over its rim the only styling. The composition is pure qualia: one crafted object, natural materials and the view doing the decorating. Recreate it with a stone look floor, operable timber louvres for breeze and privacy, and a bath placed on axis with the outlook. Note: qualia publishes this view only at 542 px wide, the best available official original at 542 px.", "src": "images/qualia Hamilton Island/0440 - qualia - Windward Pavilion - freestanding oval bath before louvred windows.jpg", "source": "https://www.qualia.com.au/", "dimensions": "542x800", "size": 204265}, {"number": "0441", "file": "0441 - qualia - Leeward Pavilion - bedroom and terrace overlooking Dent Passage.jpg", "resort": "qualia", "space": "Leeward Pavilion", "description": "From the foot of the king bed, dressed in white linen with ochre and grey cushions and a textured throw, the eye runs across a black cone table lamp and louvred screen to sliding glass doors and a private terrace set with a round metal table and woven chairs above Dent Passage. Walls are clad in horizontal timber boards and white louvres, the palette warm grey, sand and olive. To recreate the look, frame the bed on the view axis, use low profile terrace furniture in dark metal and weave, and keep textiles to a few earthy accent cushions.", "src": "images/qualia Hamilton Island/0441 - qualia - Leeward Pavilion - bedroom and terrace overlooking Dent Passage.jpg", "source": "https://www.qualia.com.au/luxury-accommodation/leeward-pavilion/", "dimensions": "2560x1440", "size": 2410799}, {"number": "0442", "file": "0442 - qualia - Leeward Pavilion - king bed against timber panel wall.jpg", "resort": "qualia", "space": "Leeward Pavilion", "description": "A detail of the Leeward sleeping space: white bedlinen and an ochre cushion against a full height wall of rich vertical timber panelling, a small round side table in pale wood and metal holding a black cone lamp, and built in timber wardrobes closing the composition. It shows qualia's Queensland craft at close range, joinery as decoration. Recreate it with book matched timber wall panelling, a single sculptural bedside lamp and one warm accent colour repeated sparingly. Note: qualia publishes this view only at 566 px wide, the best available official original at 566 px.", "src": "images/qualia Hamilton Island/0442 - qualia - Leeward Pavilion - king bed against timber panel wall.jpg", "source": "https://www.qualia.com.au/", "dimensions": "566x800", "size": 277273}, {"number": "0443", "file": "0443 - qualia - Leeward Pavilion - stone bathroom vanity with vessel basin.jpg", "resort": "qualia", "space": "Leeward Pavilion", "description": "The Leeward ensuite detail pairs a white oval vessel basin and polished chrome wall mounted taps with a charcoal stone splashback, a vertical spotted gum panel and a round magnifying mirror on an articulated arm, white towels folded beneath. It is a study in contrast, dark stone against warm timber and crisp white ceramics. To recreate the look, wall mount the tapware, float the vanity, and limit materials to stone, timber and white sanitaryware. Note: qualia publishes this view only at 533 px wide, the best available official original at 533 px.", "src": "images/qualia Hamilton Island/0443 - qualia - Leeward Pavilion - stone bathroom vanity with vessel basin.jpg", "source": "https://www.qualia.com.au/", "dimensions": "533x800", "size": 196610}, {"number": "0444", "file": "0444 - qualia - Beach House - pavilion and infinity pool among palms.jpg", "resort": "qualia", "space": "Beach House", "description": "Seen across its own 12 metre infinity pool, the Beach House sits low in a grove of palms and pandanus, a wide deck furnished with sun loungers and a shaded entertaining terrace under a dark pitched roof, lawns running down toward the Coral Sea. The architecture disappears into tropical planting, which is the design lesson: deep eaves, dark roofing, timber decking and layered palm canopy. Recreate it with a pool edge that mirrors the sea horizon, generous deck platforms and furniture in weathered teak tones.", "src": "images/qualia Hamilton Island/0444 - qualia - Beach House - pavilion and infinity pool among palms.jpg", "source": "https://www.qualia.com.au/luxury-accommodation/beach-house/", "dimensions": "2560x1707", "size": 1020673}, {"number": "0445", "file": "0445 - qualia - Beach House - open plan dining room for ten.jpg", "resort": "qualia", "space": "Beach House", "description": "Inside the Beach House, a vaulted spotted gum ceiling with a ceiling fan covers an open plan room where a long dining table seats ten on timber framed chairs with woven seats, a low lounge chair and ottoman in pale upholstery sit in the foreground, and folding doors open the far wall to a daybed terrace in the garden. Polished hardwood floors, a single orchid arrangement and one framed print keep the mood calm. To recreate the look, use one large scaled dining setting in honest timber, loose low lounge pieces and fully retractable door walls. Note: qualia publishes this view only at 671 px wide, the best available official original at 671 px.", "src": "images/qualia Hamilton Island/0445 - qualia - Beach House - open plan dining room for ten.jpg", "source": "https://www.qualia.com.au/luxury-accommodation/beach-house/", "dimensions": "671x800", "size": 437714}, {"number": "0446", "file": "0446 - qualia - Long Pavilion - poolside dining terrace at dusk.jpg", "resort": "qualia", "space": "Long Pavilion", "description": "At dusk the Long Pavilion's dining terrace lines the edge of the resort's long reflecting pool: tables dressed in white linen with dark timber chairs face the Coral Sea, palms silhouette against the evening sky and the water doubles the light. The architecture is a backdrop; the furniture is simple, dark and formal against pale stone paving. To recreate the look, run a still water plane beside the dining terrace, keep chairs dark stained and upright, and light the scene low and warm so the horizon stays the focus.", "src": "images/qualia Hamilton Island/0446 - qualia - Long Pavilion - poolside dining terrace at dusk.jpg", "source": "https://www.qualia.com.au/dining/dinner/", "dimensions": "2560x1440", "size": 2577051}, {"number": "0447", "file": "0447 - qualia - Long Pavilion - lounge with daybeds overlooking the Coral Sea.jpg", "resort": "qualia", "space": "Long Pavilion", "description": "Inside the Long Pavilion, deep daybeds and sofas piled with patterned and plain cushions face full height glass and the infinity edge of the pool beyond, a staff member crossing with a drinks tray giving the room its scale. Dark tiled floors, heavy timber columns and a low shingled roof plane keep the interior shaded and cool against the bright seascape. Recreate it with oversized daybed seating in washable neutral fabrics, a few botanical print cushions as the only pattern, and black or bronze low tables.", "src": "images/qualia Hamilton Island/0447 - qualia - Long Pavilion - lounge with daybeds overlooking the Coral Sea.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x800", "size": 537990}, {"number": "0448", "file": "0448 - qualia - Library - timber lined library with striped armchairs.jpg", "resort": "qualia", "space": "Library", "description": "The qualia library, housed in the Long Pavilion, is a cocoon of dark timber: panelled walls and ceiling, built in shelves of art and design books, and pairs of high backed armchairs upholstered in red, navy and cream stripes around a chess table, with an easel displaying artwork at the far end. It is the resort's most interior room and its richest textile moment. To recreate the look, line the room in one dark timber, choose one bold striped upholstery used in pairs, and layer books and board games as the decoration.", "src": "images/qualia Hamilton Island/0448 - qualia - Library - timber lined library with striped armchairs.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x692", "size": 510619}, {"number": "0449", "file": "0449 - qualia - Pebble Beach - restaurant terrace under louvred roof.jpg", "resort": "qualia", "space": "Pebble Beach", "description": "Pebble Beach restaurant is a simple open pavilion: a slatted timber louvre roof on dark posts shades rows of tables with white cloths and dark chairs, framed by two tall palm trunks and lush green planting, the Coral Sea glittering behind. Nothing competes with the setting, the craft is in the roof carpentry and the spacing. To recreate the look, build a light louvred pergola roof for dappled shade, keep table settings crisp white and let palm trunks act as natural columns. Note: qualia publishes this view only at 524 px wide, the best available official original at 524 px.", "src": "images/qualia Hamilton Island/0449 - qualia - Pebble Beach - restaurant terrace under louvred roof.jpg", "source": "https://www.qualia.com.au/", "dimensions": "524x800", "size": 384884}, {"number": "0450", "file": "0450 - qualia - Pebble Beach - beach pool with sun loungers and umbrellas.jpg", "resort": "qualia", "space": "Pebble Beach", "description": "A long still pool runs along the Pebble Beach lawn toward the sea, its edge lined with teak sun loungers and black market umbrellas on pale stone paving, a single sculptural tree marking the point where lawn meets beach. The geometry is resort classicism in Australian materials: straight lines, honest timber loungers and deep shade. To recreate the look, align the pool on the sea axis, repeat one lounger and umbrella pairing rhythmically and keep planting to lawn, palms and one feature tree.", "src": "images/qualia Hamilton Island/0450 - qualia - Pebble Beach - beach pool with sun loungers and umbrellas.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x800", "size": 756509}, {"number": "0451", "file": "0451 - qualia - Spa qualia - entrance pavilion with reflection pools.jpg", "resort": "qualia", "space": "Spa qualia", "description": "The approach to Spa qualia is a ceremonial open pavilion: massive dark timber posts carry a coffered timber ceiling over a stone walkway flanked by still reflection pools and tropical planting, ending at a framed artwork on a timber panelled wall. Water, shade and symmetry slow the visitor down before any treatment begins. To recreate the look, use paired shallow water rills beside a central stone path, overscale the timber structure and place a single artwork as the terminal focal point.", "src": "images/qualia Hamilton Island/0451 - qualia - Spa qualia - entrance pavilion with reflection pools.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x800", "size": 970165}, {"number": "0452", "file": "0452 - qualia - Spa qualia - treatment room with stone soaking tub.jpg", "resort": "qualia", "space": "Spa qualia", "description": "A Spa qualia treatment room centres on a monumental rectangular soaking tub carved from dark stone, set before bifolding doors opened completely to a private garden of dense tropical foliage, with a pale daybed along the side wall and small bronze vessels as the only objects. Grey stone tiles, a timber ceiling and filtered green light complete the sanctuary mood. Recreate it with one oversized stone bath as the room's sculpture, a garden outlook with total privacy and a palette limited to stone grey, timber and leaf green.", "src": "images/qualia Hamilton Island/0452 - qualia - Spa qualia - treatment room with stone soaking tub.jpg", "source": "https://www.qualia.com.au/", "dimensions": "1230x692", "size": 655988}, {"number": "0453", "file": "0453 - Alila Ubud - The Resort - aerial view of the infinity pool and thatched pavilions in the forest.jpg", "resort": "Alila Ubud", "space": "The Resort", "description": "Aerial view of Kerry Hill's hillside village plan, the thatched pavilions scattered small through dense Ayung valley forest. The long emerald infinity pool is cut into the slope with a single line of white umbrellas along its deck, lawns and gravel paths stepping down the hill below it. Smooth plaster and stone buildings sit under steep alang alang roofs, the whole resort reading as a village folded into the canopy rather than a single hotel block.", "src": "images/Alila Ubud/0453 - Alila Ubud - The Resort - aerial view of the infinity pool and thatched pavilions in the forest.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud", "dimensions": "2560x1440", "size": 463897}, {"number": "0454", "file": "0454 - Alila Ubud - Infinity Pool - pool and stone deck with loungers and umbrellas seen from above.jpg", "resort": "Alila Ubud", "space": "Infinity Pool", "description": "Seen from above, the 30 metre emerald infinity pool floats at the lip of the Ayung valley, its far edge dissolving into forest. A wide stone deck carries two neat rows of dark timber loungers with blue cushions under large white canvas umbrellas, and a low stone platform with a single planter sits in the shallow water at the near end. The composition is pure Kerry Hill restraint, geometry, stone and water against the green ravine.", "src": "images/Alila Ubud/0454 - Alila Ubud - Infinity Pool - pool and stone deck with loungers and umbrellas seen from above.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud", "dimensions": "2560x1440", "size": 465594}, {"number": "0455", "file": "0455 - Alila Ubud - Infinity Pool - pool deck at dusk with timber loungers and glowing lanterns.jpg", "resort": "Alila Ubud", "space": "Infinity Pool", "description": "At dusk the pool deck becomes a furniture study in silhouette, a line of dark timber loungers under oversized white umbrellas, small lanterns glowing amber between them. Palms and dense canopy close in behind, and the still water in the foreground mirrors the last pink light. The mood is the resort's signature, spare, calm and entirely built from timber, canvas and stone.", "src": "images/Alila Ubud/0455 - Alila Ubud - Infinity Pool - pool deck at dusk with timber loungers and glowing lanterns.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud", "dimensions": "2560x1440", "size": 691143}, {"number": "0456", "file": "0456 - Alila Ubud - Superior Room - twin room with louvred wardrobes opening to a balcony daybed.jpg", "resort": "Alila Ubud", "space": "Superior Room", "description": "Upper floor Superior twin room with two beds dressed in white linen, gold patterned batik runners and matching cushions. Polished stone tile floors run to full height sliding doors opening on a covered balcony with a woven bamboo ceiling, where a timber table and chairs and a built in daybed face the forest. Dark timber louvred wardrobes and a writing desk with a woven chair complete the room's quiet, crafted palette.", "src": "images/Alila Ubud/0456 - Alila Ubud - Superior Room - twin room with louvred wardrobes opening to a balcony daybed.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 352756}, {"number": "0457", "file": "0457 - Alila Ubud - Superior Room - king room with sheer draped canopy and covered balcony.jpg", "resort": "Alila Ubud", "space": "Superior Room", "description": "Superior king room centred on a bed hung with sheer white canopy drapes, dressed plainly in white with a single gold batik runner and cushion. A dark timber louvred wardrobe and desk line the wall, and beyond the sliding doors the covered balcony holds a table, chairs and a window daybed under a woven ceiling, with the green valley as the only decoration. Terrazzo toned stone floors keep the room cool and spare.", "src": "images/Alila Ubud/0457 - Alila Ubud - Superior Room - king room with sheer draped canopy and covered balcony.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 279370}, {"number": "0458", "file": "0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "resort": "Alila Ubud", "space": "Deluxe Room", "description": "Ground floor Deluxe twin room in the village blocks, its beds dressed in white with gold patterned runners, a tall louvred timber wardrobe and vanity to one side. Glass doors open fully to a private garden terrace where timber armchairs and a side table sit on stone paving against a low stone wall and lawn, the first step in the resort's indoor outdoor living pattern that the villas take further.", "src": "images/Alila Ubud/0458 - Alila Ubud - Deluxe Room - twin room with garden terrace and outdoor armchairs.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 338493}, {"number": "0459", "file": "0459 - Alila Ubud - Plantation Restaurant - wantilan dining pavilion with alang alang roof on coconut pillars.jpg", "resort": "Alila Ubud", "space": "Plantation Restaurant", "description": "The Plantation Restaurant is a Balinese wantilan, an open pavilion with a soaring alang alang thatched roof carried on towering coconut palm pillars. Timber tables and chairs are set across the shaded terrace for dining above the valley, and in the late afternoon light two Barong figures wait at the steps for the evening's cultural performance. The architecture does the decorating here, thatch, palm trunks and open air.", "src": "images/Alila Ubud/0459 - Alila Ubud - Plantation Restaurant - wantilan dining pavilion with alang alang roof on coconut pillars.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/dining/plantation-restaurant", "dimensions": "2560x1440", "size": 777938}, {"number": "0460", "file": "0460 - Alila Ubud - Spa Alila - open air treatment pavilion with twin massage beds and sunken stone tub.jpg", "resort": "Alila Ubud", "space": "Spa Alila", "description": "Open air spa treatment pavilion under a high pitched roof of woven thatch on dark timber posts. Two massage beds are dressed with striped handwoven textiles, and a square sunken stone soaking tub is set into the stone floor beside them. A low stone wall and dense tropical planting close the space off from the valley beyond, making a private garden room for treatment rituals.", "src": "images/Alila Ubud/0460 - Alila Ubud - Spa Alila - open air treatment pavilion with twin massage beds and sunken stone tub.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud", "dimensions": "2560x1920", "size": 746214}, {"number": "0461", "file": "0461 - Alila Ubud - Spa Alila - treatment room with platform bed, louvre screens and stone soaking tub.jpg", "resort": "Alila Ubud", "space": "Spa Alila", "description": "Interior spa treatment room built around a low platform treatment bed dressed in dark textiles, flanked by a raised stone soaking tub and dark timber louvre screens that filter the daylight. Stone floors, orchids and garden views through the open side keep the room grounded in the resort's material palette of stone, timber and thatch, wellness delivered through architecture rather than ornament.", "src": "images/Alila Ubud/0461 - Alila Ubud - Spa Alila - treatment room with platform bed, louvre screens and stone soaking tub.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud", "dimensions": "2560x1440", "size": 575909}, {"number": "0462", "file": "0462 - Alila Ubud - Pool Villa - open air bathroom with sunken stone tub against a river stone wall.jpg", "resort": "Alila Ubud", "space": "Pool Villa", "description": "The Pool Villa's open air bathroom is the collection's purest material moment, a rectangular sunken stone bathtub set directly before a wall of rounded river stones, with a narrow lotus pond and reeds planted at its base. Rolled white towels stand on a dark timber stool, and timber framed glass doors separate the bath court from the bedroom. Bathing here is framed as a garden ritual.", "src": "images/Alila Ubud/0462 - Alila Ubud - Pool Villa - open air bathroom with sunken stone tub against a river stone wall.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 257478}, {"number": "0463", "file": "0463 - Alila Ubud - Terrace Tree Villa - bedroom with four poster bed, bench and long window daybed.jpg", "resort": "Alila Ubud", "space": "Terrace Tree Villa", "description": "Terrace Tree Villa bedroom with a dark timber four poster bed dressed in white and tied back sheer drapes, a slatted bench at its foot, and a long upholstered daybed running along the window wall with patterned cushions. Stone tile floors, a ceiling fan and sliding glass doors lead to the terrace and the canopy view, the villa perched at the top of the ravine like a tree house.", "src": "images/Alila Ubud/0463 - Alila Ubud - Terrace Tree Villa - bedroom with four poster bed, bench and long window daybed.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 292696}, {"number": "0464", "file": "0464 - Alila Ubud - Terrace Tree Villa - living area with deep daybed opening to the terrace.jpg", "resort": "Alila Ubud", "space": "Terrace Tree Villa", "description": "The Terrace Tree Villa's living space is a deep, low daybed with bolster cushions set against the windows, polished stone tiles underfoot and sheer curtains softening the light. Through the open doors the terrace is set with a small dining table and chairs above the forest, so the room reads as one continuous platform between the draped bed behind and the valley in front.", "src": "images/Alila Ubud/0464 - Alila Ubud - Terrace Tree Villa - living area with deep daybed opening to the terrace.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 387641}, {"number": "0465", "file": "0465 - Alila Ubud - Two-Bedroom Pool Villa - bedroom with four poster bed and rust patterned textile runner.jpg", "resort": "Alila Ubud", "space": "Two-Bedroom Pool Villa", "description": "Bedroom in the Two Bedroom Pool Villa with a dark timber four poster bed dressed in white linen and a rust and gold patterned Balinese textile runner, a woven bench at the foot and a daybed beneath the window. Warm lamplight, stone tile floors and doors opening to the terrace give the room a more intimate, evening register than the resort's paler rooms, with the textile doing the colour work.", "src": "images/Alila Ubud/0465 - Alila Ubud - Two-Bedroom Pool Villa - bedroom with four poster bed and rust patterned textile runner.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 389920}, {"number": "0466", "file": "0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "resort": "Alila Ubud", "space": "Valley Villa", "description": "Valley Villa bedroom photographed from behind its dark timber writing desk, which carries twin shaded lamps and a woven rattan chair. Beyond, the bed is hung with sheer white canopy drapes and faces a full wall of glass over the Ayung valley, with a cushioned window seat built in to one side. The woven thatch ceiling and timber floor keep the open plan room warm despite its size.", "src": "images/Alila Ubud/0466 - Alila Ubud - Valley Villa - open bedroom with timber desk, rattan chair and draped canopy bed.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 446060}, {"number": "0467", "file": "0467 - Alila Ubud - Forest Edge Villa - open plan interior with four poster bed, window seat and timber floors.jpg", "resort": "Alila Ubud", "space": "Forest Edge Villa", "description": "Forest Edge Villa's open plan interior in warm dark timber, a draped four poster bed to one side, a built in window daybed with grey cushions, and polished timber floors running through to the bathroom visible at the far end. A ceiling fan turns under the plain ceiling, framed art hangs at the corridor's end, and floor to ceiling glass keeps the forest pressed against the room on two sides.", "src": "images/Alila Ubud/0467 - Alila Ubud - Forest Edge Villa - open plan interior with four poster bed, window seat and timber floors.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 270310}, {"number": "0468", "file": "0468 - Alila Ubud - Forest Edge Villa - terrace dining table with benches and a lidded bronze vessel.jpg", "resort": "Alila Ubud", "space": "Forest Edge Villa", "description": "The Forest Edge Villa terrace is furnished like an outdoor dining room, a massive slab top timber table with heavy bench seats on a timber deck, centred by a large lidded bronze toned vessel. Timber railings and round plaster columns frame the forest canopy at eye level, so meals are taken inside the treetops. It is the strongest pure furniture image in the Alila Ubud set.", "src": "images/Alila Ubud/0468 - Alila Ubud - Forest Edge Villa - terrace dining table with benches and a lidded bronze vessel.jpg", "source": "https://www.hyatt.com/alila-hotels-and-resorts/en-US/dpsau-alila-ubud/rooms", "dimensions": "2560x1440", "size": 693786}, {"number": "0469", "file": "0469 - Mandarin Oriental Desaru Coast - The Resort - aerial view of planted roof suites, lawns and the forested coast.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "The Resort", "description": "Aerial view of Kerry Hill's modern kampung spread along the Johor coast, long lawns and planted green roofs stepping down through rainforest to the South China Sea. The suites sit in loose village clusters rather than a single block, their planted roofs continuing the landscape over the buildings, with the beach and its line of umbrellas at the shore. It is the clearest record of the resort's planning idea, architecture as landscape.", "src": "images/Mandarin Oriental Desaru Coast/0469 - Mandarin Oriental Desaru Coast - The Resort - aerial view of planted roof suites, lawns and the forested coast.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/gallery", "dimensions": "2560x1440", "size": 1170654}, {"number": "0470", "file": "0470 - Mandarin Oriental Desaru Coast - Junior Suite - suite exterior with private plunge pool, daybed and louvred facade.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Junior Suite", "description": "A standalone Junior Suite seen from its garden, the facade a screen of yellow balau timber louvres under a deep overhang. A private plunge pool runs along the terrace with a circular woven daybed at its end, and sliding glass walls open the bedroom directly to the water. Hand selected stone, pale render and dense planting keep the building quiet against the rainforest, the kampung idea rebuilt in modern materials.", "src": "images/Mandarin Oriental Desaru Coast/0470 - Mandarin Oriental Desaru Coast - Junior Suite - suite exterior with private plunge pool, daybed and louvred facade.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay", "dimensions": "2560x1440", "size": 1257264}, {"number": "0471", "file": "0471 - Mandarin Oriental Desaru Coast - Junior Suite - courtyard plunge pool with daybed against a mosaic tiled wall.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Junior Suite", "description": "The suite courtyard is arranged around its plunge pool like a village well court, a long daybed with a bolster cushion set against a wall of small mosaic tiles in sand and stone tones. Timber framed glass doors slide fully open so the bedroom, with its timber desk and armchair visible inside, becomes part of the courtyard. Yellow balau, mosaic and water do all the decorative work.", "src": "images/Mandarin Oriental Desaru Coast/0471 - Mandarin Oriental Desaru Coast - Junior Suite - courtyard plunge pool with daybed against a mosaic tiled wall.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay/rainforest-junior-suite", "dimensions": "2560x1440", "size": 784806}, {"number": "0472", "file": "0472 - Mandarin Oriental Desaru Coast - Junior Suite - bathroom with freestanding tub, wicker rocking chair and mosaic wall.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Junior Suite", "description": "Bathroom opening directly onto the courtyard plunge pool, a sculptural freestanding oval tub in pale stone set before the same mosaic tile wall used outside. A woven wicker rocking chair with a slatted timber frame stands on the stone floor beside a small side table, and through the glass the bedroom's timber panelling continues the material story. Bathing, sitting and swimming share one continuous space.", "src": "images/Mandarin Oriental Desaru Coast/0472 - Mandarin Oriental Desaru Coast - Junior Suite - bathroom with freestanding tub, wicker rocking chair and mosaic wall.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay/rainforest-junior-suite", "dimensions": "2560x1440", "size": 640815}, {"number": "0473", "file": "0473 - Mandarin Oriental Desaru Coast - Rainforest Junior Suite - bedroom and sitting area with sofa, round table and planted wall.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Rainforest Junior Suite", "description": "Rainforest Junior Suite interior with the bed dressed in white and backed by a wall of green planting and patterned tile. A low sofa with teal and batik patterned cushions and a round timber side table make a sitting corner inside the room, and warm timber floors and louvred screens hold the palette to wood, white and green. The rainforest is not a view here, it is part of the room's fabric.", "src": "images/Mandarin Oriental Desaru Coast/0473 - Mandarin Oriental Desaru Coast - Rainforest Junior Suite - bedroom and sitting area with sofa, round table and planted wall.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay/rainforest-junior-suite", "dimensions": "2560x1440", "size": 580461}, {"number": "0474", "file": "0474 - Mandarin Oriental Desaru Coast - Ocean Junior Suite - living area with daybed and table facing the sea through louvred glass.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Ocean Junior Suite", "description": "Ocean Junior Suite living area facing the South China Sea through full height glass screened by timber louvres. A long upholstered daybed with white and patterned cushions and a round timber table are arranged for the view, with the lawn and beach beyond the glass. The furniture is deliberately low and horizontal so nothing competes with the horizon, Kerry Hill's restraint at its most complete.", "src": "images/Mandarin Oriental Desaru Coast/0474 - Mandarin Oriental Desaru Coast - Ocean Junior Suite - living area with daybed and table facing the sea through louvred glass.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay/ocean-junior-suite", "dimensions": "2560x1440", "size": 750970}, {"number": "0475", "file": "0475 - Mandarin Oriental Desaru Coast - Junior Suite - veranda dining table and armchairs beside louvred timber screens.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Junior Suite", "description": "Veranda set for private dining, a square timber table with four armchairs in woven cane and pale cushions, placed beside full height louvred timber screens. A small courtyard tree grows through the deck and the bedroom opens behind glass, so dinner is served in a room that is half garden. The chairs' cane backs and batik cushions carry the Malaysian craft layer of the design.", "src": "images/Mandarin Oriental Desaru Coast/0475 - Mandarin Oriental Desaru Coast - Junior Suite - veranda dining table and armchairs beside louvred timber screens.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay", "dimensions": "2560x1440", "size": 794786}, {"number": "0476", "file": "0476 - Mandarin Oriental Desaru Coast - Ocean Grand Suite - study corner with timber shelving and a framed batik artwork.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Ocean Grand Suite", "description": "Study corner in the Ocean Grand Suite, the only suite whose living spaces carry a curated art programme. Pale timber shelving with books and ceramics stands beside a timber desk and chairs, and the wall is dominated by a large framed batik artwork in indigo, rust and gold, a radiant star motif drawn from Malaysian textile tradition. It is the resort's clearest statement that local art, not imported decor, furnishes these rooms.", "src": "images/Mandarin Oriental Desaru Coast/0476 - Mandarin Oriental Desaru Coast - Ocean Grand Suite - study corner with timber shelving and a framed batik artwork.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/gallery", "dimensions": "2560x1440", "size": 929737}, {"number": "0477", "file": "0477 - Mandarin Oriental Desaru Coast - Four Bedroom Pool Villa - aerial view of the villa and its long private pool in the forest.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Four Bedroom Pool Villa", "description": "Aerial view of the Four Bedroom Pool Villa, the resort's single private residence, a long low pavilion in a forest clearing with a lap length private pool running beside it and lawns opening toward the sea. From above, the villa reads as one more kampung cluster, planted roofs and timber screens folded into the canopy, at 1,500 square metres the largest expression of the resort's design language.", "src": "images/Mandarin Oriental Desaru Coast/0477 - Mandarin Oriental Desaru Coast - Four Bedroom Pool Villa - aerial view of the villa and its long private pool in the forest.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/gallery", "dimensions": "2560x1440", "size": 1244968}, {"number": "0478", "file": "0478 - Mandarin Oriental Desaru Coast - Four Bedroom Pool Villa - two storey louvred facade above the long private pool.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Four Bedroom Pool Villa", "description": "The Four Bedroom Pool Villa from its pool, two storeys of yellow balau louvre screens behind a deep terrace, the long private pool lined with timber loungers. The split level facade is a study in screening, every opening shaded and layered, so the big house stays private and cool. Stone, timber and water are the whole palette, used at residential scale.", "src": "images/Mandarin Oriental Desaru Coast/0478 - Mandarin Oriental Desaru Coast - Four Bedroom Pool Villa - two storey louvred facade above the long private pool.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/stay", "dimensions": "2560x1440", "size": 1116922}, {"number": "0479", "file": "0479 - Mandarin Oriental Desaru Coast - Main Pool - main pool with canvas shade canopies and timber loungers.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Main Pool", "description": "The resort's main pool is a long rectangle of still water flanked by timber loungers under stretched canvas shade canopies on slender posts. Behind the deck the low timber buildings of the resort sit inside dense forest, so the pool reads as a clearing in the rainforest rather than a resort centrepiece. Furniture is limited to loungers, side tables and shade, all in timber and canvas.", "src": "images/Mandarin Oriental Desaru Coast/0479 - Mandarin Oriental Desaru Coast - Main Pool - main pool with canvas shade canopies and timber loungers.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/wellness/pools-and-beach", "dimensions": "2560x1440", "size": 1232359}, {"number": "0480", "file": "0480 - Mandarin Oriental Desaru Coast - Ember Beach Club - pool terrace with white daybeds, umbrellas and the timber clubhouse.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Ember Beach Club", "description": "Ember Beach Club pool terrace, white upholstered daybeds and timber loungers arranged under big white umbrellas on pale stone paving, the clubhouse behind in full height glass and warm timber. A central daybed platform sits at the pool's edge like a piece of furniture in the water. The beach club takes the suites' language, timber, white fabric, shade, and relaxes it for the shore.", "src": "images/Mandarin Oriental Desaru Coast/0480 - Mandarin Oriental Desaru Coast - Ember Beach Club - pool terrace with white daybeds, umbrellas and the timber clubhouse.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi", "dimensions": "2560x1440", "size": 807487}, {"number": "0481", "file": "0481 - Mandarin Oriental Desaru Coast - Ember Beach Club - restaurant interior with woven rattan pendants and a long bar counter.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Ember Beach Club", "description": "Ember Beach Club restaurant interior, a long room of timber columns and full height glass where rows of set tables run toward the sea light. Woven rattan pendant lamps hang in a line over the space, and a long bar counter with dark stools anchors the inner wall. The rattan, cane seated chairs and warm timber give the beach club a craft layer that matches the suites, casual in form, exact in execution.", "src": "images/Mandarin Oriental Desaru Coast/0481 - Mandarin Oriental Desaru Coast - Ember Beach Club - restaurant interior with woven rattan pendants and a long bar counter.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/gallery", "dimensions": "2560x1440", "size": 825238}, {"number": "0482", "file": "0482 - Mandarin Oriental Desaru Coast - Ambara Restaurant - dining room with dark timber tables and armchairs with yellow cushions.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Ambara Restaurant", "description": "Ambara, the resort's signature restaurant, is a dark, calm dining room of polished timber floors, square set tables and armchairs with woven backs and mustard yellow cushions. Louvred screens filter the daylight at the windows and a green apple sits on each table as the single colour accent. The room's formality is a counterpoint to the open beach club, Malaysian and Mediterranean cooking served in a proper dining room.", "src": "images/Mandarin Oriental Desaru Coast/0482 - Mandarin Oriental Desaru Coast - Ambara Restaurant - dining room with dark timber tables and armchairs with yellow cushions.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/dine/ambara-restaurant", "dimensions": "2560x1440", "size": 615437}, {"number": "0483", "file": "0483 - Mandarin Oriental Desaru Coast - Dusky Monkey Bar - bar lounge with timber armchairs and garden views.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Dusky Monkey Bar", "description": "Dusky Monkey Bar lounge, timber framed armchairs with pale cushions grouped around low tables on a dark floor, the room open through glass to the garden. Slatted timber chairs and a long banquette continue the resort's furniture vocabulary into the evening, and the planting presses close on every side. It is a bar furnished like a veranda, made for Straits inspired cocktails at dusk.", "src": "images/Mandarin Oriental Desaru Coast/0483 - Mandarin Oriental Desaru Coast - Dusky Monkey Bar - bar lounge with timber armchairs and garden views.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/dine/dusky-monkey-bar", "dimensions": "2560x1440", "size": 674106}, {"number": "0484", "file": "0484 - Mandarin Oriental Desaru Coast - The Spa - treatment detail with a brass singing bowl on a batik textile runner.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "The Spa", "description": "Spa treatment detail, a brass singing bowl resting on a blue batik patterned textile runner laid over the treatment bed, with soft garden green beyond the window. The image captures the spa's method in miniature, Malaysian textile craft and simple ritual objects rather than machinery, set inside the resort's quiet palette of timber, stone and cloth.", "src": "images/Mandarin Oriental Desaru Coast/0484 - Mandarin Oriental Desaru Coast - The Spa - treatment detail with a brass singing bowl on a batik textile runner.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/wellness/the-spa", "dimensions": "2560x1440", "size": 420663}, {"number": "0485", "file": "0485 - Mandarin Oriental Desaru Coast - Private Beach Dining - candlelit table for two with timber chairs on the beach at dusk.jpg", "resort": "Mandarin Oriental Desaru Coast", "space": "Private Beach Dining", "description": "Private beach dining at dusk, a timber table for two set on the sand with woven lanterns, candles and wine glasses, framed by two timber armchairs with batik patterned cushions. The sea and the darkening hedge of coastal planting close the scene. The resort's furniture vocabulary travels well, the same chairs and textiles used indoors read as a private dining room on the shore.", "src": "images/Mandarin Oriental Desaru Coast/0485 - Mandarin Oriental Desaru Coast - Private Beach Dining - candlelit table for two with timber chairs on the beach at dusk.jpg", "source": "https://www.mandarinoriental.com/en/desaru-coast/kota-tinggi/wellness/pools-and-beach", "dimensions": "2560x1707", "size": 825550}, {"number": "0486", "file": "0486 - Cheval Blanc Seychelles - The Resort - aerial view over Anse Intendance at sunset.jpg", "resort": "Cheval Blanc Seychelles", "space": "The Resort", "description": "Aerial view at sunset over Anse Intendance, the Creole roofed villas scattered through 22 hectares of jungle between the granite hills and the silver sand. From above, Jean-Michel Gathy's planning reads clearly, no block taller than the canopy, every villa turned to the sea or the green, the Main Lodge at the centre of the bay. It is the establishing record of a resort designed to disappear into its landscape.", "src": "images/Cheval Blanc Seychelles/0486 - Cheval Blanc Seychelles - The Resort - aerial view over Anse Intendance at sunset.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/", "dimensions": "1920x2560", "size": 1314047}, {"number": "0487", "file": "0487 - Cheval Blanc Seychelles - Main Pool - pool edge merging with the beach and sea.jpg", "resort": "Cheval Blanc Seychelles", "space": "Main Pool", "description": "The main pool is a freeform sheet of water held just above the beach, its edge dissolving into the sand and the Indian Ocean beyond. Palms lean over the water and the Main Lodge sits behind, so the pool works as the resort's central room, furnished by landscape rather than objects. One swimmer underlines the scale, this is a pool sized to the bay it faces.", "src": "images/Cheval Blanc Seychelles/0487 - Cheval Blanc Seychelles - Main Pool - pool edge merging with the beach and sea.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/wellness", "dimensions": "2560x1438", "size": 978895}, {"number": "0488", "file": "0488 - Cheval Blanc Seychelles - Beach Villa - living room with pitched ceiling and striped textile artwork.jpg", "resort": "Cheval Blanc Seychelles", "space": "Beach Villa", "description": "Beach Villa living room under a high pitched Creole ceiling, the whole room opening through folding glass to the private pool in the foreground. A woven rocking chair, low sofas with pale cushions and sculptural side tables furnish the space in sand and white, and the far wall carries the villa's commissioned textile artwork by Joel Andrianomearisoa, vertical bands of blue, green and black that give every villa its own colour key.", "src": "images/Cheval Blanc Seychelles/0488 - Cheval Blanc Seychelles - Beach Villa - living room with pitched ceiling and striped textile artwork.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/beach-villa", "dimensions": "2560x1706", "size": 656593}, {"number": "0489", "file": "0489 - Cheval Blanc Seychelles - Beach Villa - bathroom with porcelain shell framed mirrors.jpg", "resort": "Cheval Blanc Seychelles", "space": "Beach Villa", "description": "Beach Villa bathroom with a long double vanity in pale stone and two mirrors framed in porcelain shell, the Maison's signature Seychelles detail, shells reworked as ornament. Vertical light sconces flank the mirrors, a freestanding tub sits in the foreground, and sliding doors open the room to a private garden terrace with loungers, so the bathroom is planned as a second living space.", "src": "images/Cheval Blanc Seychelles/0489 - Cheval Blanc Seychelles - Beach Villa - bathroom with porcelain shell framed mirrors.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/beach-villa", "dimensions": "2560x1706", "size": 800758}, {"number": "0490", "file": "0490 - Cheval Blanc Seychelles - Jungle Hill Villa - sitting corner with sculptural side tables and lamp.jpg", "resort": "Cheval Blanc Seychelles", "space": "Jungle Hill Villa", "description": "Sitting corner of a Jungle Hill Villa, a low white sofa with sea coloured cushions against a plain plaster wall, lit by a table lamp with a timber stem. The furniture is the story, a sculptural grey side table like a pebble with a hole through it, a round timber coffee table, pieces chosen as objects rather than suites. Against the jungle outside, the interior stays almost monastic in its calm.", "src": "images/Cheval Blanc Seychelles/0490 - Cheval Blanc Seychelles - Jungle Hill Villa - sitting corner with sculptural side tables and lamp.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/jungle-hill-villa", "dimensions": "1920x2560", "size": 671000}, {"number": "0491", "file": "0491 - Cheval Blanc Seychelles - Jungle Hill Villa - private pool seen from the bedroom with beanbag loungers.jpg", "resort": "Cheval Blanc Seychelles", "space": "Jungle Hill Villa", "description": "The Jungle Hill Villa's private pool seen from the bedroom through linen curtains, a guest floating at the edge where the water meets the jungle canopy. White beanbag loungers and a small stone side table sit on the timber deck, the villa's whole outdoor furniture set reduced to three soft forms. The pool hangs in the green at canopy height, private enough that the jungle itself is the enclosure.", "src": "images/Cheval Blanc Seychelles/0491 - Cheval Blanc Seychelles - Jungle Hill Villa - private pool seen from the bedroom with beanbag loungers.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/jungle-hill-villa", "dimensions": "1920x2560", "size": 1336829}, {"number": "0492", "file": "0492 - Cheval Blanc Seychelles - Panorama Hill Villa - living room with sofa and sea view.jpg", "resort": "Cheval Blanc Seychelles", "space": "Panorama Hill Villa", "description": "Panorama Hill Villa living room, a long white sofa with turquoise and blue cushions, a woven leather strap chair and round timber tables, all turned to the sea through full height glass. A ceiling fan turns under the slatted timber ceiling and a dining table for two sits by the window wall. The palette is white, pale timber and sea colours, the view doing the decorating.", "src": "images/Cheval Blanc Seychelles/0492 - Cheval Blanc Seychelles - Panorama Hill Villa - living room with sofa and sea view.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/panorama-hill-villa", "dimensions": "2560x1706", "size": 639239}, {"number": "0493", "file": "0493 - Cheval Blanc Seychelles - Panorama Hill Villa - bedroom with woven screen wall and terrace.jpg", "resort": "Cheval Blanc Seychelles", "space": "Panorama Hill Villa", "description": "Panorama Hill Villa bedroom with the television set into a wall of woven openwork screen, the Maison's modern reading of Creole lattice. The bed faces the terrace, where white beanbag loungers and sculptural tables wait under the deep overhang, and the sea fills the glass beyond. Woven texture, white linen and pale timber run from the bedroom straight out to the deck furniture.", "src": "images/Cheval Blanc Seychelles/0493 - Cheval Blanc Seychelles - Panorama Hill Villa - bedroom with woven screen wall and terrace.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/panorama-hill-villa", "dimensions": "2560x1706", "size": 861036}, {"number": "0494", "file": "0494 - Cheval Blanc Seychelles - Horizon Villa - private pool deck with beanbag loungers above the bay.jpg", "resort": "Cheval Blanc Seychelles", "space": "Horizon Villa", "description": "Horizon Villa pool deck high above Anse Intendance, a long infinity pool running along the timber deck with white beanbag loungers and an umbrella at its edge, the bay and its green headland spread below. The villa sits at the top of the Maison's hillside, and its outdoor room is furnished as simply as the hill villas, soft white forms on timber, everything else is view.", "src": "images/Cheval Blanc Seychelles/0494 - Cheval Blanc Seychelles - Horizon Villa - private pool deck with beanbag loungers above the bay.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/horizon-villa-2", "dimensions": "2560x1707", "size": 803639}, {"number": "0495", "file": "0495 - Cheval Blanc Seychelles - Horizon Villa - bedroom opening through glass to the pool and sea.jpg", "resort": "Cheval Blanc Seychelles", "space": "Horizon Villa", "description": "Horizon Villa bedroom behind a wall of glass, the bed in white linen with a single blue cushion, the private pool and its loungers a step beyond the sliding doors and the sea beyond that. The room is planned as a viewing platform, minimal furniture, pale floors, nothing between the sleeper and the horizon the villa is named for.", "src": "images/Cheval Blanc Seychelles/0495 - Cheval Blanc Seychelles - Horizon Villa - bedroom opening through glass to the pool and sea.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/rooms-and-suites/horizon-villa-2", "dimensions": "2560x1707", "size": 575356}, {"number": "0496", "file": "0496 - Cheval Blanc Seychelles - Le White - dining terrace with rattan chairs facing the sea.jpg", "resort": "Cheval Blanc Seychelles", "space": "Le White", "description": "Le White, the Maison's all day restaurant in the Main Lodge, its terrace set with timber tables and woven rattan chairs behind glass screens, palms and the beach a few steps beyond. Andrianomearisoa's pastel illustrations run across the restaurant's walls and ceramics inside, while out here the furniture stays natural, cane, timber and white, against the blue of the bay.", "src": "images/Cheval Blanc Seychelles/0496 - Cheval Blanc Seychelles - Le White - dining terrace with rattan chairs facing the sea.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/restaurants-and-bars/le-white-restaurant-seychelles", "dimensions": "2560x1707", "size": 1083756}, {"number": "0497", "file": "0497 - Cheval Blanc Seychelles - Le 1947 - dining room with white and orange chairs and pendant lights.jpg", "resort": "Cheval Blanc Seychelles", "space": "Le 1947", "description": "Le 1947, the signature French gastronomic restaurant, is a tall, calm dining room of round marble topped tables, white shell chairs with burnt orange cushions and clusters of globe pendant lights on black stems. Sculptural white partitions curve between tables and louvred screens line the walls, a room that quotes the Maison's Parisian flagship in tropical materials, opened only two evenings a week.", "src": "images/Cheval Blanc Seychelles/0497 - Cheval Blanc Seychelles - Le 1947 - dining room with white and orange chairs and pendant lights.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/restaurants-and-bars/le-1947-seychelles", "dimensions": "2560x1920", "size": 739059}, {"number": "0498", "file": "0498 - Cheval Blanc Seychelles - Vivamento - bar with green mosaic tile wall and white armchairs.jpg", "resort": "Cheval Blanc Seychelles", "space": "Vivamento", "description": "Vivamento's bar, a long counter backed by a wall of green and white mosaic tiles in an abstract pattern, white upholstered armchairs and small round tables in front. The Italian restaurant sits by the pool in the Main Lodge, its dramatic spiral staircase and this tiled bar as its two set pieces, the ceramics on its tables designed by French ceramicist Maximilien Pellet.", "src": "images/Cheval Blanc Seychelles/0498 - Cheval Blanc Seychelles - Vivamento - bar with green mosaic tile wall and white armchairs.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/restaurants-and-bars/vivamento-seychelles", "dimensions": "1920x2560", "size": 700024}, {"number": "0499", "file": "0499 - Cheval Blanc Seychelles - Mizumi - lakeside deck dining with orange chairs.jpg", "resort": "Cheval Blanc Seychelles", "space": "Mizumi", "description": "Mizumi, the Japanese restaurant in a Creole house by the resort's lotus lake, serves dinner on a timber deck over the water, a round table set with woven rattan chairs with orange cushions and lanterns at the deck edge. The lake and jungle close around the deck after dark, making this the Maison's most atmospheric outdoor dining room.", "src": "images/Cheval Blanc Seychelles/0499 - Cheval Blanc Seychelles - Mizumi - lakeside deck dining with orange chairs.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/restaurants-and-bars/mizumi-seychelles", "dimensions": "2560x1706", "size": 1137727}, {"number": "0500", "file": "0500 - Cheval Blanc Seychelles - Sula Beach Club - terrace table with woven chairs under the pergola.jpg", "resort": "Cheval Blanc Seychelles", "space": "Sula Beach Club", "description": "Sula beach club terrace on the sand at Anse Intendance, a timber table and woven chairs set under a slatted pergola, the sea framed between palm trunks. The beach club serves Mediterranean plates with a Creole twist, toes in the sand, and its furniture is the resort's vocabulary at its most relaxed, timber, weave and shade.", "src": "images/Cheval Blanc Seychelles/0500 - Cheval Blanc Seychelles - Sula Beach Club - terrace table with woven chairs under the pergola.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/restaurants-and-bars/sula-seychelles", "dimensions": "1920x2560", "size": 1482858}, {"number": "0501", "file": "0501 - Cheval Blanc Seychelles - Cheval Blanc Spa - treatment room with stone stools and sea view.jpg", "resort": "Cheval Blanc Seychelles", "space": "Cheval Blanc Spa", "description": "A treatment room at the Cheval Blanc Spa by Guerlain, the first Guerlain spa in the Seychelles, its bed dressed in white facing glass walls that open to a granite boulder, palms and the sea. Stone stools and a sculptural side table furnish the room, and the eight treatment suites are wedged between the granite boulders on the hillside, built around rock and view rather than decoration.", "src": "images/Cheval Blanc Seychelles/0501 - Cheval Blanc Seychelles - Cheval Blanc Spa - treatment room with stone stools and sea view.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/wellness/chevalblanc-spa", "dimensions": "2560x1706", "size": 869948}, {"number": "0502", "file": "0502 - Cheval Blanc Seychelles - Villa Art Programme - textile artwork detail by Joel Andrianomearisoa.jpg", "resort": "Cheval Blanc Seychelles", "space": "Villa Art Programme", "description": "Detail of a commissioned textile artwork by Joel Andrianomearisoa, the Malagasy artist who made a unique work for every one of the 52 villas, this one titled Un souffle du temps sur la melodie de nos songes. Hundreds of fine strands in blues, greens and earth tones hang like a waterfall of thread, setting each villa's accent colours and giving the Maison's interiors their single strong note of art.", "src": "images/Cheval Blanc Seychelles/0502 - Cheval Blanc Seychelles - Villa Art Programme - textile artwork detail by Joel Andrianomearisoa.jpg", "source": "https://www.chevalblanc.com/en/maison/seychelles/experiences/art-and-design-seychelles", "dimensions": "1707x2560", "size": 881123}];
